CREATE OR REPLACE FUNCTION authorization_private.calendar_event_allowed_uat_v1(p_event_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select exists(
    select 1
    from public.workforce_calendar_events_v2 event
    where event.id=p_event_id
      and authorization_private.calendar_payload_allowed_uat_v1(
        event.location_id,
        coalesce((select jsonb_agg(jsonb_build_object('roleId',demand.role_id))
          from public.workforce_event_demand_v2 demand where demand.event_id=event.id),'[]'::jsonb),
        coalesce((select jsonb_agg(jsonb_build_object('roleId',hot.role_id))
          from public.workforce_hot_day_limits_v2 hot where hot.event_id=event.id),'[]'::jsonb)
      )
  );
$function$;

CREATE OR REPLACE FUNCTION authorization_private.calendar_payload_allowed_uat_v1(p_location_id uuid, p_demands jsonb, p_hot_limits jsonb)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  with role_ids as (
    select nullif(item->>'roleId','')::uuid role_id
    from jsonb_array_elements(coalesce(p_demands,'[]'::jsonb)||coalesce(p_hot_limits,'[]'::jsonb)) item
  )
  select public.has_app_role('OWNER') or public.has_app_role('ADMIN')
    or public.matrix_v2_scope_allows_resource_for_app_role_uat_v1(
      'LOCATION_MANAGER',null,p_location_id,null
    )
    or (
      exists(select 1 from role_ids where role_id is not null)
      and not exists(
        select 1 from role_ids
        where role_id is null or not public.matrix_v2_scope_allows_resource_for_app_role_uat_v1(
          'ROLE_MANAGER',role_id,p_location_id,null
        )
      )
    );
$function$;

CREATE OR REPLACE FUNCTION authorization_private.enter_resource_scope_uat_v1()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  perform set_config('szafunek.resource_scope_actor',auth.uid()::text,true);
end;
$function$;

CREATE OR REPLACE FUNCTION authorization_private.matrix_v2_visible_employee_ids_uat_v1()
 RETURNS TABLE(employee_id uuid)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select employee.id
  from public.employees employee
  where public.matrix_v2_can_manage_employee(employee.id)
$function$;

CREATE OR REPLACE FUNCTION public.application_access_bulk_apply_uat_v1(p_rows jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_row jsonb;
  v_count integer:=0;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  if not (public.has_app_role('OWNER') or public.has_app_role('ADMIN')) then
    raise exception 'FORBIDDEN';
  end if;
  if jsonb_typeof(p_rows)<>'array' then raise exception 'ACCESS_ROWS_MUST_BE_ARRAY'; end if;
  if jsonb_array_length(p_rows)<1 or jsonb_array_length(p_rows)>1000 then
    raise exception 'ACCESS_ROWS_COUNT_OUT_OF_RANGE';
  end if;

  for v_row in select value from jsonb_array_elements(p_rows) loop
    perform public.application_access_save_uat_v1(
      v_row->>'email',
      v_row->>'appRole',
      nullif(v_row->>'roleId','')::uuid,
      nullif(v_row->>'locationId','')::uuid,
      coalesce((v_row->>'active')::boolean,true)
    );
    v_count:=v_count+1;
  end loop;
  return jsonb_build_object('applied',v_count);
end;
$function$;

CREATE OR REPLACE FUNCTION public.application_access_directory_uat_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_matrix uuid;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  if not (public.has_app_role('OWNER') or public.has_app_role('ADMIN')) then
    raise exception 'FORBIDDEN';
  end if;
  select mv.id into v_matrix from public.matrix_versions mv
    where mv.schema_version>=2 and mv.status in ('DRAFT','ACTIVE')
    order by (mv.status='DRAFT') desc,mv.version desc limit 1;
  return jsonb_build_object(
    'entries',coalesce((select jsonb_agg(jsonb_build_object(
      'id',d.id,'email',d.email,'appRole',d.app_role,'active',d.active,
      'authUserId',d.auth_user_id,
      'status',case when d.auth_user_id is null then 'PENDING' else 'ACTIVE' end,
      'roleLogicalId',d.role_logical_id,'roleName',r.name,
      'locationLogicalId',d.location_logical_id,'locationName',l.name
    ) order by lower(d.email),d.app_role::text)
    from public.application_access_directory_v1 d
    left join public.matrix_roles_v2 r on r.matrix_version_id=v_matrix and r.logical_id=d.role_logical_id
    left join public.matrix_locations_v2 l on l.matrix_version_id=v_matrix and l.logical_id=d.location_logical_id),'[]'::jsonb),
    'roles',coalesce((select jsonb_agg(jsonb_build_object(
      'rowId',r.id,'logicalId',r.logical_id,'name',r.name,'code',r.code
    ) order by r.sort_order,r.name) from public.matrix_roles_v2 r
      where r.matrix_version_id=v_matrix and r.active),'[]'::jsonb),
    'locations',coalesce((select jsonb_agg(jsonb_build_object(
      'rowId',l.id,'logicalId',l.logical_id,'name',l.name,'code',l.code
    ) order by l.sort_order,l.name) from public.matrix_locations_v2 l
      where l.matrix_version_id=v_matrix and l.active),'[]'::jsonb)
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.application_access_materialize_uat_v1(p_email text, p_auth_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_entry record;
begin
  for v_entry in
    select * from public.application_access_directory_v1 d
    where lower(d.email)=lower(trim(p_email)) and d.active
  loop
    update public.application_access_directory_v1
      set auth_user_id=p_auth_user_id,updated_at=now()
      where id=v_entry.id;

    insert into public.matrix_scope_grants_v2(
      auth_user_id,app_role,role_logical_id,location_logical_id,active,created_by
    ) values(
      p_auth_user_id,v_entry.app_role,v_entry.role_logical_id,
      v_entry.location_logical_id,true,v_entry.created_by
    ) on conflict(auth_user_id,app_role,role_logical_id,location_logical_id,duty_logical_id)
      do update set active=true,updated_at=now();

    if v_entry.app_role in ('OWNER','ADMIN','HR_FINANCE','VERIFIER','EMPLOYEE') then
      insert into public.user_permissions(auth_user_id,app_role,scope_role,scope_location)
      values(p_auth_user_id,v_entry.app_role,null,null)
      on conflict do nothing;
    end if;
  end loop;

  if exists(
    select 1 from public.application_access_directory_v1 d
    where lower(d.email)=lower(trim(p_email)) and d.active and d.app_role='EMPLOYEE'
  ) then
    update public.employees e set auth_user_id=p_auth_user_id,updated_at=now()
    where lower(coalesce(e.email,''))=lower(trim(p_email))
      and (e.auth_user_id is null or e.auth_user_id=p_auth_user_id);
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION public.application_access_save_uat_v1(p_email text, p_app_role text, p_role_id uuid DEFAULT NULL::uuid, p_location_id uuid DEFAULT NULL::uuid, p_active boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid(); v_email text:=lower(trim(p_email));
  v_role public.app_role; v_role_logical uuid; v_location_logical uuid;
  v_auth uuid; v_id uuid;
begin
  if v_actor is null then raise exception 'AUTH_REQUIRED'; end if;
  if not (public.has_app_role('OWNER') or public.has_app_role('ADMIN')) then
    raise exception 'FORBIDDEN';
  end if;
  if v_email !~ '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$' then
    raise exception 'INVALID_ACCESS_EMAIL';
  end if;
  begin v_role:=upper(trim(p_app_role))::public.app_role;
  exception when others then raise exception 'INVALID_APP_ROLE'; end;

  if p_role_id is not null then
    select r.logical_id into v_role_logical from public.matrix_roles_v2 r where r.id=p_role_id;
  end if;
  if p_location_id is not null then
    select l.logical_id into v_location_logical from public.matrix_locations_v2 l where l.id=p_location_id;
  end if;
  if v_role='ROLE_MANAGER' and v_role_logical is null then raise exception 'ROLE_SCOPE_REQUIRED'; end if;
  if v_role='LOCATION_MANAGER' and v_location_logical is null then raise exception 'LOCATION_SCOPE_REQUIRED'; end if;
  if v_role not in ('ROLE_MANAGER','LOCATION_MANAGER') then
    v_role_logical:=null;v_location_logical:=null;
  elsif v_role='ROLE_MANAGER' then v_location_logical:=null;
  elsif v_role='LOCATION_MANAGER' then v_role_logical:=null;
  end if;

  select u.id into v_auth from auth.users u where lower(u.email)=v_email limit 1;
  insert into public.application_access_directory_v1(
    email,app_role,role_logical_id,location_logical_id,auth_user_id,active,created_by
  ) values(v_email,v_role,v_role_logical,v_location_logical,v_auth,p_active,v_actor)
  on conflict(email,app_role,role_logical_id,location_logical_id)
  do update set auth_user_id=excluded.auth_user_id,active=excluded.active,
    updated_at=now()
  returning id into v_id;

  if v_auth is not null then
    if p_active then
      perform public.application_access_materialize_uat_v1(v_email,v_auth);
    else
      delete from public.matrix_scope_grants_v2 g
        where g.auth_user_id=v_auth and g.app_role=v_role
          and g.role_logical_id is not distinct from v_role_logical
          and g.location_logical_id is not distinct from v_location_logical;
      if v_role in ('OWNER','ADMIN','HR_FINANCE','VERIFIER','EMPLOYEE') then
        if v_role='OWNER' and v_auth=v_actor then raise exception 'CANNOT_REMOVE_OWN_OWNER_ACCESS'; end if;
        delete from public.user_permissions p where p.auth_user_id=v_auth and p.app_role=v_role;
      end if;
    end if;
  end if;
  return jsonb_build_object('id',v_id,'email',v_email,'appRole',v_role,
    'active',p_active,'status',case when v_auth is null then 'PENDING' else 'ACTIVE' end);
end;
$function$;

CREATE OR REPLACE FUNCTION public.application_finance_visibility_current_uat_v1()
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid(); v_visibility text;
begin
  if v_actor is null then raise exception 'AUTH_REQUIRED'; end if;
  select p.visibility into v_visibility
  from public.application_finance_visibility_policy_v1 p
  where p.app_role in (
    select up.app_role from public.user_permissions up where up.auth_user_id=v_actor
    union
    select grant_row.app_role from public.matrix_scope_grants_v2 grant_row where grant_row.auth_user_id=v_actor and grant_row.active
  )
  order by case p.visibility when 'FULL' then 4 when 'AGGREGATE' then 3 when 'BUDGET_ONLY' then 2 else 1 end desc
  limit 1;
  return coalesce(v_visibility,'NONE');
end;
$function$;

CREATE OR REPLACE FUNCTION public.application_finance_visibility_policy_uat_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  if not public.has_app_role('OWNER') then raise exception 'ACCESS_POLICY_VIEW_FORBIDDEN'; end if;
  return jsonb_build_object('levels',jsonb_build_array('NONE','BUDGET_ONLY','AGGREGATE','FULL'),'policies',coalesce((select jsonb_agg(jsonb_build_object('appRole',p.app_role::text,'visibility',p.visibility,'updatedAt',p.updated_at) order by p.app_role::text) from public.application_finance_visibility_policy_v1 p),'[]'::jsonb));
end;
$function$;

CREATE OR REPLACE FUNCTION public.application_finance_visibility_save_uat_v1(p_app_role text, p_visibility text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid(); v_role public.app_role; v_visibility text:=upper(trim(coalesce(p_visibility,'')));
begin
  if v_actor is null then raise exception 'AUTH_REQUIRED'; end if;
  if not public.has_app_role('OWNER') then raise exception 'ACCESS_POLICY_EDIT_FORBIDDEN'; end if;
  begin v_role:=upper(trim(coalesce(p_app_role,'')))::public.app_role;
  exception when invalid_text_representation then raise exception 'INVALID_APPLICATION_ROLE'; end;
  if v_visibility not in ('NONE','BUDGET_ONLY','AGGREGATE','FULL') then raise exception 'INVALID_FINANCE_VISIBILITY'; end if;
  insert into public.application_finance_visibility_policy_v1(app_role,visibility,updated_by,updated_at)
  values(v_role,v_visibility,v_actor,now())
  on conflict(app_role) do update set visibility=excluded.visibility,updated_by=v_actor,updated_at=now();
  insert into public.audit_log(actor_id,entity_type,entity_id,action,new_data)
  values(v_actor,'application_finance_visibility_policy_v1',v_role::text,'VISIBILITY_CHANGED',jsonb_build_object('visibility',v_visibility));
  return jsonb_build_object('appRole',v_role::text,'visibility',v_visibility);
end;
$function$;

CREATE OR REPLACE FUNCTION public.assemble_role_plans(p_month date, p_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare new_plan uuid; new_version integer; sec_count integer; ass_count integer; begin
 if not(public.has_app_role('OWNER') or public.has_app_role('ADMIN')) then raise exception 'FORBIDDEN'; end if;
 select count(*) into sec_count from role_plan_sections rp
 where rp.month=date_trunc('month',p_month)::date and rp.status='APPROVED'
   and rp.version=(select max(x.version) from role_plan_sections x where x.month=rp.month and x.role_id=rp.role_id);
 if sec_count=0 then raise exception 'NO_APPROVED_ROLE_PLANS'; end if;
 select coalesce(max(version),0)+1 into new_version from plans where month=date_trunc('month',p_month)::date;
 insert into plans(month,name,scenario_code,optimization_mode,staffing_level,status,version,created_by)
 values(date_trunc('month',p_month)::date,coalesce(nullif(trim(p_name),''),'Grafik operacyjny'),
   'MERGED','ROLE_PLANS','APPROVED','DRAFT',new_version,auth.uid()) returning id into new_plan;
 insert into shifts(plan_id,location_id,shift_date,shift_code,starts_at,ends_at,status)
 select distinct new_plan,s.location_id,s.shift_date,s.shift_code,s.starts_at,s.ends_at,'PLANNED'
 from role_plan_sections rp join role_plan_assignments rpa on rpa.role_plan_section_id=rp.id
 join assignments a on a.id=rpa.assignment_id join shifts s on s.id=a.shift_id
 where rp.month=date_trunc('month',p_month)::date and rp.status='APPROVED'
   and rp.version=(select max(x.version) from role_plan_sections x where x.month=rp.month and x.role_id=rp.role_id);
 insert into assignments(shift_id,employee_id,assigned_role,assigned_capability,assignment_type,cost,locked,explanation)
 select ns.id,a.employee_id,a.assigned_role,a.assigned_capability,a.assignment_type,a.cost,a.locked,
   a.explanation||jsonb_build_object('source','ROLE_PLAN','sourceAssignment',a.id)
 from role_plan_sections rp join role_plan_assignments rpa on rpa.role_plan_section_id=rp.id
 join assignments a on a.id=rpa.assignment_id join shifts os on os.id=a.shift_id
 join shifts ns on ns.plan_id=new_plan and ns.location_id=os.location_id and ns.shift_date=os.shift_date
   and ns.shift_code=os.shift_code and ns.starts_at=os.starts_at and ns.ends_at=os.ends_at
 where rp.month=date_trunc('month',p_month)::date and rp.status='APPROVED'
   and rp.version=(select max(x.version) from role_plan_sections x where x.month=rp.month and x.role_id=rp.role_id)
 on conflict do nothing;
 get diagnostics ass_count=row_count;
 update plans set status='READY',generated_at=now(),total_cost=(select coalesce(sum(cost),0) from assignments a join shifts s on s.id=a.shift_id where s.plan_id=new_plan) where id=new_plan;
 insert into composite_schedules(month,matrix_version_id,version,name,status,section_ids,created_by)
 select date_trunc('month',p_month)::date,(select id from matrix_versions where status='ACTIVE' order by version desc limit 1),
   coalesce((select max(version)+1 from composite_schedules where month=date_trunc('month',p_month)::date),1),p_name,'READY',
   array_agg(id),auth.uid() from role_plan_sections rp where rp.month=date_trunc('month',p_month)::date and rp.status='APPROVED'
   and rp.version=(select max(x.version) from role_plan_sections x where x.month=rp.month and x.role_id=rp.role_id);
 return jsonb_build_object('planId',new_plan,'sections',sec_count,'assignments',ass_count,'version',new_version);
end $function$;

CREATE OR REPLACE FUNCTION public.attendance_clock(p_action text, p_location text, p_latitude numeric DEFAULT NULL::numeric, p_longitude numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare e employees; l locations; out_id uuid; last_type text; begin
 select * into e from employees where auth_user_id=auth.uid() and active;
 if e.id is null then raise exception 'EMPLOYEE_ACCOUNT_NOT_LINKED'; end if;
 select * into l from locations where code::text=p_location and active;
 if l.id is null then raise exception 'LOCATION_NOT_FOUND'; end if;
 if not exists(select 1 from employee_locations el where el.employee_id=e.id and el.location_id=l.id and (el.standard_allowed or el.overtime_allowed or el.home_location)) then raise exception 'LOCATION_NOT_ALLOWED'; end if;
 select event_type::text into last_type from attendance_events where employee_id=e.id order by occurred_at desc limit 1;
 if p_action='CHECK_IN' and last_type='CHECK_IN' then raise exception 'ALREADY_CLOCKED_IN'; end if;
 if p_action='CHECK_OUT' and coalesce(last_type,'')<>'CHECK_IN' then raise exception 'NOT_CLOCKED_IN'; end if;
 if p_action not in ('CHECK_IN','CHECK_OUT') then raise exception 'INVALID_ACTION'; end if;
 insert into attendance_events(employee_id,location_id,event_type,verification_method,latitude,longitude,created_by)
 values(e.id,l.id,p_action::attendance_event_type,'GEOLOCATION',p_latitude,p_longitude,auth.uid()) returning id into out_id;
 return jsonb_build_object('id',out_id,'action',p_action,'occurredAt',now(),'location',l.name);
end $function$;

CREATE OR REPLACE FUNCTION public.availability_exception_review_before_phase1_uat_v1(p_review_id uuid, p_decision text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid(); v_review public.availability_exception_reviews_v2%rowtype;
  v_decision text:=upper(trim(coalesce(p_decision,''))); v_constraint uuid;
begin
  if v_actor is null then raise exception 'AUTH_REQUIRED'; end if;
  if not public.can_manage_plans() then raise exception 'FORBIDDEN'; end if;
  if v_decision not in ('APPROVE','REJECT') then raise exception 'INVALID_REVIEW_DECISION'; end if;
  if length(trim(coalesce(p_reason,'')))<3 then raise exception 'REVIEW_REASON_REQUIRED'; end if;
  select * into v_review from public.availability_exception_reviews_v2
  where id=p_review_id for update;
  if v_review.id is null then raise exception 'REVIEW_NOT_FOUND'; end if;
  if v_review.status<>'PENDING' then raise exception 'REVIEW_ALREADY_RESOLVED'; end if;
  if v_decision='APPROVE' then
    v_constraint:=gen_random_uuid();
    insert into public.employee_time_constraints_v2(
      id,employee_id,constraint_kind,time_range,source,source_record_key,
      priority,editable_by_employee,status,note,created_by
    ) values(v_constraint,v_review.employee_id,'UNAVAILABLE',v_review.requested_range,
      'HOT_DAY_APPROVED','hot-day-review:'||v_review.id::text,100,false,'ACTIVE',
      v_review.note,v_actor);
  end if;
  update public.availability_exception_reviews_v2 set
    status=case when v_decision='APPROVE' then 'APPROVED' else 'REJECTED' end,
    reviewed_by=v_actor,reviewed_at=now(),review_reason=trim(p_reason),
    constraint_id=v_constraint where id=v_review.id;
  insert into public.audit_log(actor_id,entity_type,entity_id,action,new_data)
  values(v_actor,'availability_exception_review_v2',v_review.id::text,v_decision,
    jsonb_build_object('employeeId',v_review.employee_id,'date',v_review.work_date,
      'roleId',v_review.role_id,'reason',trim(p_reason),'constraintId',v_constraint));
  insert into public.notifications(recipient_id,title,body)
  select employee.auth_user_id,'Decyzja dotycząca niedostępności',
    case when v_decision='APPROVE' then 'Niedostępność została zaakceptowana.'
      else 'Niedostępność nie została zaakceptowana: '||trim(p_reason) end
  from public.employees employee where employee.id=v_review.employee_id
    and employee.auth_user_id is not null;
  return jsonb_build_object('id',v_review.id,'status',
    case when v_decision='APPROVE' then 'APPROVED' else 'REJECTED' end,
    'constraintId',v_constraint);
end;
$function$;

CREATE OR REPLACE FUNCTION public.availability_exception_review_uat_v2(p_review_id uuid, p_decision text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_review public.availability_exception_reviews_v2%rowtype;
begin
  select * into v_review from public.availability_exception_reviews_v2 where id=p_review_id;
  if v_review.id is null then raise exception 'REVIEW_NOT_FOUND'; end if;
  if not public.matrix_v2_can_manage_resource_uat_v1(v_review.role_id,null,v_review.employee_id)
    then raise exception 'RESOURCE_SCOPE_FORBIDDEN'; end if;
  perform authorization_private.enter_resource_scope_uat_v1();
  return public.availability_exception_review_before_phase1_uat_v1(p_review_id,p_decision,p_reason);
end;
$function$;

CREATE OR REPLACE FUNCTION public.budget_update(p_month date, p_amount numeric, p_warning_percent integer, p_hard_limit boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ begin
 if not(public.has_app_role('OWNER') or public.has_app_role('ADMIN') or public.has_app_role('HR_FINANCE')) then raise exception 'FORBIDDEN'; end if;
 insert into monthly_budgets(month,amount,warning_percent,hard_limit,updated_by,updated_at) values(date_trunc('month',p_month)::date,p_amount,p_warning_percent,p_hard_limit,auth.uid(),now())
 on conflict(month) do update set amount=excluded.amount,warning_percent=excluded.warning_percent,hard_limit=excluded.hard_limit,updated_by=auth.uid(),updated_at=now();
end $function$;

CREATE OR REPLACE FUNCTION public.can_manage_plans()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select auth.uid() is not null and (
    public.has_app_role('OWNER') or public.has_app_role('ADMIN')
    or current_setting('szafunek.resource_scope_actor',true)=auth.uid()::text
  );
$function$;

CREATE OR REPLACE FUNCTION public.can_view_assignment(p_employee_id uuid, p_role public.employee_role, p_location public.location_code)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select public.has_app_role('OWNER') or public.has_app_role('ADMIN')
    or exists (select 1 from public.employees e where e.id=p_employee_id and e.auth_user_id=auth.uid())
    or exists (select 1 from public.user_permissions up where up.auth_user_id=auth.uid()
      and up.app_role='ROLE_MANAGER' and (up.scope_role is null or up.scope_role=p_role))
    or exists (select 1 from public.user_permissions up where up.auth_user_id=auth.uid()
      and up.app_role='LOCATION_MANAGER' and (up.scope_location is null or up.scope_location=p_location));
$function$;

CREATE OR REPLACE FUNCTION public.claim_demo_owner()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  current_user_id uuid := auth.uid();
  employee_id uuid;
begin
  if current_user_id is null then
    raise exception 'AUTH_REQUIRED';
  end if;

  if exists (
    select 1 from public.user_permissions
    where auth_user_id = current_user_id
  ) then
    return jsonb_build_object('claimed', false, 'reason', 'ALREADY_ASSIGNED');
  end if;

  if exists (
    select 1 from public.user_permissions where app_role = 'OWNER'
  ) then
    return jsonb_build_object('claimed', false, 'reason', 'OWNER_EXISTS');
  end if;

  insert into public.user_permissions (auth_user_id, app_role)
  values (current_user_id, 'OWNER');

  select id into employee_id
  from public.employees
  where employee_no = 'GP-001' and auth_user_id is null;

  if employee_id is not null then
    update public.employees
    set auth_user_id = current_user_id, updated_at = now()
    where id = employee_id;
  end if;

  return jsonb_build_object('claimed', true, 'role', 'OWNER', 'employee_no', 'GP-001');
end;
$function$;

CREATE OR REPLACE FUNCTION public.complete_workspace(p_month date DEFAULT CURRENT_DATE)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_payload jsonb;
  v_visibility text:=public.application_finance_visibility_current_uat_v1();
  v_employee jsonb;
  v_employees jsonb:='[]'::jsonb;
  v_budget jsonb;
begin
  v_payload:=public.complete_workspace_before_b4f101_uat_v1(p_month);
  if v_visibility='FULL' then return v_payload; end if;
  for v_employee in select value from jsonb_array_elements(coalesce(v_payload->'employees','[]'::jsonb)) loop
    v_employees:=v_employees||jsonb_build_array(v_employee-'finance');
  end loop;
  v_payload:=jsonb_set(v_payload,'{employees}',v_employees,true);
  if v_visibility='AGGREGATE' then return v_payload; end if;
  if v_visibility='BUDGET_ONLY' then
    v_budget:=v_payload->'budget';
    v_payload:=jsonb_set(v_payload,'{budget}',jsonb_build_object(
      'configured',v_budget is not null and v_budget<>'{}'::jsonb,
      'hardLimit',case when v_budget is null or v_budget='{}'::jsonb then null else v_budget->'hard_limit' end
    ),true);
    return v_payload;
  end if;
  return v_payload-'budget';
end;
$function$;

CREATE OR REPLACE FUNCTION public.complete_workspace_before_b4f101_uat_v1(p_month date DEFAULT CURRENT_DATE)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
with target_month as (select date_trunc('month',p_month)::date as target_date),
active_matrix as (select * from matrix_versions where status='ACTIVE' order by version desc limit 1),
draft_matrix as (select * from matrix_versions where status='DRAFT' order by version desc limit 1),
chosen_plan as (
  select p.* from plans p,target_month t where p.month=t.target_date
  order by case p.status when 'PUBLISHED' then 1 when 'READY' then 2 else 3 end,p.version desc limit 1
)
select jsonb_build_object(
 'counts',jsonb_build_object(
   'employees',(select count(*) from employees where active),
   'archivedEmployees',(select count(*) from employees where not active),
   'roleManagers',(select count(distinct employee_id) from employee_capabilities where capability='ROLE_MANAGER' and active),
   'locations',(select count(*) from locations where active)
 ),
 'employees',coalesce((select jsonb_agg(jsonb_build_object(
   'id',e.id,'employeeNo',e.employee_no,'firstName',e.first_name,'lastName',e.last_name,'email',e.email,
   'primaryRole',e.primary_role,'nominalMinutes',e.monthly_nominal_minutes,'maxWeeklyMinutes',e.max_weekly_minutes,
   'maxMonthlyMinutes',e.max_monthly_minutes,'preferredShift',e.preferred_shift,'active',e.active,
   'archivedAt',e.archived_at,'archiveReason',e.archive_reason,
   'locations',coalesce((select jsonb_agg(jsonb_build_object('code',l.code,'name',l.name,'home',el.home_location,'standard',el.standard_allowed,'overtime',el.overtime_allowed) order by l.name) from employee_locations el join locations l on l.id=el.location_id where el.employee_id=e.id),'[]'::jsonb),
   'capabilities',coalesce((select jsonb_agg(jsonb_build_object('id',ec.id,'capability',ec.capability,'role',ec.scope_role,'location',ec.scope_location) order by ec.capability) from employee_capabilities ec where ec.employee_id=e.id and ec.active),'[]'::jsonb),
   'hr',case when public.has_app_role('OWNER') or public.has_app_role('ADMIN') or public.has_app_role('HR_FINANCE') then (select to_jsonb(h)-'employee_id' from employee_hr_profiles h where h.employee_id=e.id) else null end,
   'finance',case when public.has_app_role('OWNER') or public.has_app_role('ADMIN') or public.has_app_role('HR_FINANCE') then jsonb_build_object('hourlyRate',e.hourly_rate) else null end
 ) order by e.active desc,e.employee_no) from employees e where
   public.has_app_role('OWNER') or public.has_app_role('ADMIN') or public.has_app_role('HR_FINANCE')
   or public.has_app_role('ROLE_MANAGER') or public.has_app_role('LOCATION_MANAGER') or e.auth_user_id=auth.uid()),'[]'::jsonb),
 'activeMatrix',(select to_jsonb(a) from active_matrix a),
 'draftMatrix',(select to_jsonb(d) from draft_matrix d),
 'roles',coalesce((select jsonb_agg(to_jsonb(r) order by r.sort_order) from matrix_roles r where r.matrix_version_id=coalesce((select id from draft_matrix),(select id from active_matrix))),'[]'::jsonb),
 'functions',coalesce((select jsonb_agg(to_jsonb(f) order by f.name) from matrix_functions f where f.matrix_version_id=coalesce((select id from draft_matrix),(select id from active_matrix))),'[]'::jsonb),
 'locations',coalesce((select jsonb_agg(to_jsonb(l) order by l.name) from matrix_locations l where l.matrix_version_id=coalesce((select id from draft_matrix),(select id from active_matrix))),'[]'::jsonb),
 'shifts',coalesce((select jsonb_agg(to_jsonb(s) order by s.sort_order,s.name) from matrix_shift_templates s where s.matrix_version_id=coalesce((select id from draft_matrix),(select id from active_matrix))),'[]'::jsonb),
 'demand',coalesce((select jsonb_agg(to_jsonb(d)) from matrix_demand d join matrix_shift_templates s on s.id=d.shift_template_id where s.matrix_version_id=coalesce((select id from draft_matrix),(select id from active_matrix))),'[]'::jsonb),
 'sections',coalesce((select jsonb_agg(jsonb_build_object(
   'id',rp.id,'roleId',rp.role_id,'roleCode',r.code,'roleName',r.name,'version',rp.version,'status',rp.status,'name',rp.name,
   'createdAt',rp.created_at,'updatedAt',rp.updated_at,'planId',rp.legacy_plan_id,
   'assignmentCount',(select count(*) from role_plan_assignments ra where ra.role_plan_section_id=rp.id),
   'issueCount',(select count(*) from plan_issues pi where pi.plan_id=rp.legacy_plan_id and pi.role::text=r.code and pi.resolved_at is null)
 ) order by r.sort_order,rp.version desc) from role_plan_sections rp join matrix_roles r on r.id=rp.role_id,target_month t where rp.month=t.target_date),'[]'::jsonb),
 'plan',(select to_jsonb(p) from chosen_plan p),
 'budget',coalesce((select to_jsonb(b) from monthly_budgets b,target_month t where b.month=t.target_date),'{}'::jsonb),
 'preferences',coalesce((select jsonb_agg(to_jsonb(ep) order by ep.valid_from desc) from employee_preferences ep where ep.valid_to >= (select target_date from target_month)),'[]'::jsonb),
 'integrationRuns',coalesce((select jsonb_agg(to_jsonb(ir) order by ir.created_at desc) from integration_runs ir limit 20),'[]'::jsonb),
 'timeRecords',coalesce((select jsonb_agg(to_jsonb(tr) order by tr.work_date desc) from time_records tr,target_month t where date_trunc('month',tr.work_date)::date=t.target_date),'[]'::jsonb)
);
$function$;

CREATE OR REPLACE FUNCTION public.create_operational_event(p_location public.location_code, p_event_type text, p_title text, p_description text, p_starts_at timestamp with time zone, p_ends_at timestamp with time zone, p_expected_guests integer DEFAULT NULL::integer, p_status public.event_status DEFAULT 'DRAFT'::public.event_status, p_demand jsonb DEFAULT '[]'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_event_id uuid;
  v_location_id uuid;
  v_item jsonb;
begin
  if not public.can_manage_plans() then raise exception 'FORBIDDEN'; end if;
  if p_ends_at <= p_starts_at then raise exception 'INVALID_EVENT_TIME'; end if;

  select id into v_location_id from public.locations where code = p_location and active;
  if v_location_id is null then raise exception 'LOCATION_NOT_FOUND'; end if;

  insert into public.operational_events(
    location_id, event_type, title, description, starts_at, ends_at,
    expected_guests, status, created_by
  ) values (
    v_location_id, p_event_type, p_title, nullif(p_description,''), p_starts_at, p_ends_at,
    p_expected_guests, p_status, auth.uid()
  ) returning id into v_event_id;

  for v_item in select * from jsonb_array_elements(coalesce(p_demand, '[]'::jsonb))
  loop
    insert into public.event_demand_changes(
      event_id, role, shift_code, additional_count, required_capability
    ) values (
      v_event_id,
      (v_item->>'role')::public.employee_role,
      nullif(v_item->>'shift_code',''),
      greatest(0, coalesce((v_item->>'additional_count')::integer, 0)),
      nullif(v_item->>'required_capability','')
    );
  end loop;

  update public.plans
  set status = 'STALE'
  where month = date_trunc('month', p_starts_at at time zone 'Europe/Warsaw')::date
    and status in ('READY','PUBLISHED');

  insert into public.audit_log(actor_id, entity_type, entity_id, action, new_data)
  values (auth.uid(), 'operational_event', v_event_id::text, 'CREATE',
    jsonb_build_object('title',p_title,'type',p_event_type,'status',p_status));
  return v_event_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.create_role_plan_section(p_month date, p_role_id uuid, p_name text, p_scenario text DEFAULT 'BASE'::text, p_mode text DEFAULT 'BALANCED'::text, p_staffing text DEFAULT 'OPTIMAL'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid; v_version integer; v_mv uuid; begin
 if not public.can_manage_plans() then raise exception 'FORBIDDEN'; end if;
 select matrix_version_id into v_mv from matrix_roles where id=p_role_id and active;
 if v_mv is null then raise exception 'ROLE_NOT_FOUND'; end if;
 if not (public.has_app_role('OWNER') or public.has_app_role('ADMIN') or exists(select 1 from user_permissions up join matrix_roles r on r.code=up.scope_role::text where up.auth_user_id=auth.uid() and up.app_role='ROLE_MANAGER' and r.id=p_role_id)) then raise exception 'ROLE_SCOPE_FORBIDDEN'; end if;
 select coalesce(max(version),0)+1 into v_version from role_plan_sections where month=date_trunc('month',p_month)::date and role_id=p_role_id;
 insert into role_plan_sections(month,matrix_version_id,role_id,version,name,scenario_code,optimization_mode,staffing_level,created_by)
 values(date_trunc('month',p_month)::date,v_mv,p_role_id,v_version,p_name,p_scenario,p_mode,p_staffing,auth.uid()) returning id into v_id;
 return v_id;
end $function$;

CREATE OR REPLACE FUNCTION public.current_user_access()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select jsonb_build_object(
    'auth_user_id', auth.uid(),
    'roles', coalesce((
      select jsonb_agg(jsonb_build_object(
        'app_role', up.app_role,
        'scope_role', up.scope_role,
        'scope_location', up.scope_location
      ))
      from public.user_permissions up
      where up.auth_user_id = auth.uid()
    ), '[]'::jsonb),
    'employee', (
      select jsonb_build_object(
        'id', e.id,
        'employee_no', e.employee_no,
        'first_name', e.first_name,
        'last_name', e.last_name,
        'primary_role', e.primary_role
      )
      from public.employees e
      where e.auth_user_id = auth.uid()
      limit 1
    )
  );
$function$;

CREATE OR REPLACE FUNCTION public.current_user_access_v2()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_user uuid:=auth.uid(); v_email text; v_roles jsonb; v_employee jsonb;
begin
  if v_user is null then raise exception 'AUTH_REQUIRED'; end if;
  select lower(u.email) into v_email from auth.users u where u.id=v_user;
  if v_email is not null then
    perform public.application_access_materialize_uat_v1(v_email,v_user);
  end if;

  select coalesce(jsonb_agg(item order by item->>'app_role'),'[]'::jsonb)
  into v_roles from (
    select distinct jsonb_build_object(
      'app_role',x.app_role::text,
      'scope_role',x.scope_role,
      'scope_location',x.scope_location,
      'role_logical_id',x.role_logical_id,
      'location_logical_id',x.location_logical_id
    ) item
    from (
      select p.app_role,p.scope_role::text scope_role,p.scope_location::text scope_location,
        null::uuid role_logical_id,null::uuid location_logical_id
      from public.user_permissions p where p.auth_user_id=v_user
      union all
      select g.app_role,r.code,l.code,g.role_logical_id,g.location_logical_id
      from public.matrix_scope_grants_v2 g
      left join lateral (
        select mr.code from public.matrix_roles_v2 mr
        join public.matrix_versions mv on mv.id=mr.matrix_version_id
        where mr.logical_id=g.role_logical_id and mv.status in ('DRAFT','ACTIVE')
        order by (mv.status='DRAFT') desc,mv.version desc limit 1
      ) r on true
      left join lateral (
        select ml.code from public.matrix_locations_v2 ml
        join public.matrix_versions mv on mv.id=ml.matrix_version_id
        where ml.logical_id=g.location_logical_id and mv.status in ('DRAFT','ACTIVE')
        order by (mv.status='DRAFT') desc,mv.version desc limit 1
      ) l on true
      where g.auth_user_id=v_user and g.active
    ) x
  ) roles;

  select jsonb_build_object(
    'id',e.id,'employee_no',e.employee_no,'first_name',e.first_name,
    'last_name',e.last_name,'primary_role',e.primary_role
  ) into v_employee from public.employees e where e.auth_user_id=v_user limit 1;

  return jsonb_build_object(
    'auth_user_id',v_user,'email',v_email,'roles',v_roles,'employee',v_employee
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.emergency_assign(p_shift_id uuid, p_employee_id uuid, p_role public.employee_role, p_notify boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_shift public.shifts;
  v_employee public.employees;
  v_minutes integer;
  v_assignment_id uuid;
  v_assigned integer;
begin
  if not public.can_manage_plans() then raise exception 'FORBIDDEN'; end if;
  select * into v_shift from public.shifts where id=p_shift_id;
  if v_shift.id is null then raise exception 'SHIFT_NOT_FOUND'; end if;
  select * into v_employee from public.employees where id=p_employee_id and active;
  if v_employee.id is null then raise exception 'EMPLOYEE_NOT_FOUND'; end if;
  if v_employee.primary_role<>p_role then raise exception 'ROLE_MISMATCH'; end if;
  if not exists(select 1 from public.employee_locations el
    where el.employee_id=p_employee_id and el.location_id=v_shift.location_id
      and (el.standard_allowed or el.overtime_allowed)) then
    raise exception 'LOCATION_NOT_ALLOWED';
  end if;
  if exists(select 1 from public.assignments a join public.shifts s on s.id=a.shift_id
    where a.employee_id=p_employee_id and s.plan_id=v_shift.plan_id
      and tstzrange(s.starts_at,s.ends_at,'[)') &&
        tstzrange(v_shift.starts_at,v_shift.ends_at,'[)')) then
    raise exception 'SHIFT_OVERLAP';
  end if;

  v_minutes:=public.shift_minutes(v_shift.starts_at,v_shift.ends_at);
  insert into public.assignments(
    shift_id,employee_id,assigned_role,assignment_type,cost,locked,explanation
  ) values (
    p_shift_id,p_employee_id,p_role,'EMERGENCY',
    round(v_employee.hourly_rate*v_minutes/60,2),true,
    jsonb_build_object('engine','MANUAL','reason','EMERGENCY_ASSIGNMENT','notify',p_notify)
  ) returning id into v_assignment_id;

  select count(*) into v_assigned from public.assignments
  where shift_id=p_shift_id and assigned_role=p_role;
  update public.plan_issues set resolved_at=now()
  where plan_id=v_shift.plan_id and shift_id=p_shift_id and role=p_role
    and issue_type='SHORTAGE' and required_count<=v_assigned and resolved_at is null;

  if p_notify and v_employee.auth_user_id is not null then
    insert into public.notifications(recipient_id,channel,title,body)
    values(v_employee.auth_user_id,'IN_APP','Awaryjna zmiana',
      'Dodano Cię do zmiany '||v_shift.shift_code||' dnia '||v_shift.shift_date);
  end if;
  insert into public.audit_log(actor_id,entity_type,entity_id,action,new_data)
  values(auth.uid(),'assignment',v_assignment_id::text,'EMERGENCY_ASSIGN',
    jsonb_build_object('shift_id',p_shift_id,'employee_id',p_employee_id,'notify',p_notify));
  return jsonb_build_object('assignment_id',v_assignment_id,'status','ASSIGNED','notified',
    (p_notify and v_employee.auth_user_id is not null));
end;
$function$;

CREATE OR REPLACE FUNCTION public.employee_archive(p_employee_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ begin
 if not(public.has_app_role('OWNER') or public.has_app_role('ADMIN') or public.has_app_role('HR_FINANCE')) then raise exception 'FORBIDDEN'; end if;
 update employees set active=false,archived_at=now(),archived_by=auth.uid(),archive_reason=nullif(trim(p_reason),'') where id=p_employee_id;
 if not found then raise exception 'EMPLOYEE_NOT_FOUND'; end if;
 insert into audit_log(actor_id,entity_type,entity_id,action,new_data) values(auth.uid(),'employee',p_employee_id::text,'ARCHIVE',jsonb_build_object('reason',p_reason));
end $function$;

CREATE OR REPLACE FUNCTION public.employee_availability_bulk_save_v2(p_from date, p_to date, p_kind text, p_all_day boolean DEFAULT true, p_local_start time without time zone DEFAULT NULL::time without time zone, p_local_end time without time zone DEFAULT NULL::time without time zone, p_preferred_location_id uuid DEFAULT NULL::uuid, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_employee_id uuid;
  v_kind text := upper(trim(coalesce(p_kind,'')));
  v_timezone text;
  v_day date;
  v_start timestamptz;
  v_end timestamptz;
  v_count integer := 0;
  v_source_key text;
  v_location_logical_id uuid;
  v_preference public.employee_preferences%rowtype;
  v_constraint public.employee_time_constraints_v2%rowtype;
begin
  if v_actor is null then raise exception 'AUTH_REQUIRED'; end if;
  select employee.id into v_employee_id
  from public.employees employee
  where employee.auth_user_id=v_actor and employee.active
    and employee.archived_at is null
  order by employee.created_at limit 1;
  if v_employee_id is null then raise exception 'EMPLOYEE_PROFILE_REQUIRED'; end if;
  if p_from is null or p_to is null or p_to<p_from or p_to-p_from>62 then
    raise exception 'INVALID_DATE_RANGE';
  end if;
  if v_kind not in ('AVAILABLE','PREFER_NOT_TO_WORK','CANNOT_WORK') then
    raise exception 'INVALID_AVAILABILITY_KIND';
  end if;
  if not coalesce(p_all_day,false)
    and (p_local_start is null or p_local_end is null or p_local_end=p_local_start) then
    raise exception 'HOURS_REQUIRED';
  end if;

  select nullif(version.settings->>'timezone','') into v_timezone
  from public.matrix_versions version
  where version.status in ('ACTIVE','DRAFT')
    and (version.effective_from is null or version.effective_from<=p_to)
    and (version.effective_to is null or version.effective_to>=p_from)
  order by (version.status='ACTIVE') desc,version.version desc limit 1;
  if v_timezone is null then raise exception 'MATRIX_TIMEZONE_REQUIRED'; end if;

  if p_preferred_location_id is not null then
    select location.logical_id into v_location_logical_id
    from public.matrix_locations_v2 location
    join public.matrix_versions version on version.id=location.matrix_version_id
    where location.id=p_preferred_location_id and location.active
      and version.status in ('ACTIVE','DRAFT')
    order by (version.status='ACTIVE') desc,version.version desc limit 1;
    if v_location_logical_id is null then
      raise exception 'PREFERRED_LOCATION_NOT_FOUND';
    end if;
  end if;

  for v_day in select generate_series(p_from,p_to,interval '1 day')::date loop
    v_start := v_day::timestamp at time zone v_timezone;
    v_end := (v_day+1)::timestamp at time zone v_timezone;

    -- A day has one employee-controlled effective state. Protected HR/manager
    -- entries are deliberately excluded and remain authoritative.
    for v_preference in
      select preference.* from public.employee_preferences preference
      where preference.employee_id=v_employee_id
        and preference.status='ACTIVE'
        and preference.source='GRAFIK_PRO'
        and preference.editable_by_employee
        and preference.preference_type in ('OTHER','PREFERRED_LOCATION')
        and preference.valid_from<=v_day and preference.valid_to>=v_day
      for update
    loop
      update public.employee_preferences set status='CANCELLED'
      where id=v_preference.id;
      if v_preference.valid_from<v_day then
        insert into public.employee_preferences(
          employee_id,valid_from,valid_to,preference_type,preference_value,
          source,editable_by_employee,status
        ) values(
          v_preference.employee_id,v_preference.valid_from,v_day-1,
          v_preference.preference_type,v_preference.preference_value,
          v_preference.source,v_preference.editable_by_employee,'ACTIVE'
        );
      end if;
      if v_preference.valid_to>v_day then
        insert into public.employee_preferences(
          employee_id,valid_from,valid_to,preference_type,preference_value,
          source,editable_by_employee,status
        ) values(
          v_preference.employee_id,v_day+1,v_preference.valid_to,
          v_preference.preference_type,v_preference.preference_value,
          v_preference.source,v_preference.editable_by_employee,'ACTIVE'
        );
      end if;
    end loop;

    for v_constraint in
      select constraint_row.* from public.employee_time_constraints_v2 constraint_row
      where constraint_row.employee_id=v_employee_id
        and constraint_row.status='ACTIVE'
        and constraint_row.source='GRAFIK_PRO'
        and constraint_row.editable_by_employee
        and constraint_row.time_range && tstzrange(v_start,v_end,'[)')
      for update
    loop
      update public.employee_time_constraints_v2
      set status='REVOKED',revoked_at=now(),updated_at=now()
      where id=v_constraint.id;
      if lower(v_constraint.time_range)<v_start then
        insert into public.employee_time_constraints_v2(
          employee_id,constraint_kind,time_range,location_logical_id,source,
          source_record_key,priority,editable_by_employee,status,note,created_by
        ) values(
          v_employee_id,v_constraint.constraint_kind,
          tstzrange(lower(v_constraint.time_range),v_start,'[)'),
          v_constraint.location_logical_id,'GRAFIK_PRO',
          'self-split:left:'||gen_random_uuid()::text,v_constraint.priority,
          true,'ACTIVE',v_constraint.note,v_actor
        );
      end if;
      if upper(v_constraint.time_range)>v_end then
        insert into public.employee_time_constraints_v2(
          employee_id,constraint_kind,time_range,location_logical_id,source,
          source_record_key,priority,editable_by_employee,status,note,created_by
        ) values(
          v_employee_id,v_constraint.constraint_kind,
          tstzrange(v_end,upper(v_constraint.time_range),'[)'),
          v_constraint.location_logical_id,'GRAFIK_PRO',
          'self-split:right:'||gen_random_uuid()::text,v_constraint.priority,
          true,'ACTIVE',v_constraint.note,v_actor
        );
      end if;
    end loop;

    -- An all-day AVAILABLE entry without metadata is the baseline state and
    -- therefore needs no row. This keeps the calendar and solver consistent:
    -- green by default, with only exceptions persisted.
    if v_kind='PREFER_NOT_TO_WORK' then
      insert into public.employee_preferences(
        employee_id,valid_from,valid_to,preference_type,preference_value,
        source,editable_by_employee,status
      ) values(
        v_employee_id,v_day,v_day,'OTHER',jsonb_strip_nulls(jsonb_build_object(
          'kind','DAY_OFF','strength','SOFT','note',nullif(trim(p_note),''))),
        'GRAFIK_PRO',true,'ACTIVE'
      );
    elsif v_kind='CANNOT_WORK' or not coalesce(p_all_day,false) then
      if not coalesce(p_all_day,false) then
        v_start := (v_day+p_local_start)::timestamp at time zone v_timezone;
        v_end := case when p_local_end>p_local_start
          then (v_day+p_local_end)::timestamp at time zone v_timezone
          else (v_day+1+p_local_end)::timestamp at time zone v_timezone end;
      end if;
      v_source_key := 'self-day:'||v_employee_id::text||':'||v_kind||':'
        ||v_start::text||':'||v_end::text;
      insert into public.employee_time_constraints_v2(
        employee_id,constraint_kind,time_range,location_logical_id,source,
        source_record_key,priority,editable_by_employee,status,note,created_by
      ) values(
        v_employee_id,
        case when v_kind='AVAILABLE' then 'AVAILABLE_WINDOW' else 'UNAVAILABLE' end,
        tstzrange(v_start,v_end,'[)'),v_location_logical_id,'GRAFIK_PRO',
        v_source_key,100,true,'ACTIVE',nullif(trim(p_note),''),v_actor
      ) on conflict (source,source_record_key)
        where source_record_key is not null
        do update set status='ACTIVE',revoked_at=null,updated_at=now(),
          note=excluded.note,location_logical_id=excluded.location_logical_id;
    end if;

    if p_preferred_location_id is not null then
      insert into public.employee_preferences(
        employee_id,valid_from,valid_to,preference_type,preference_value,
        source,editable_by_employee,status
      ) values(
        v_employee_id,v_day,v_day,'PREFERRED_LOCATION',
        jsonb_build_object('locationId',p_preferred_location_id),
        'GRAFIK_PRO',true,'ACTIVE'
      );
    end if;
    v_count := v_count+1;
  end loop;

  insert into public.audit_log(actor_id,entity_type,entity_id,action,new_data)
  values(v_actor,'employee_availability_v2',v_employee_id::text,'SET_DAYS',
    jsonb_build_object('from',p_from,'to',p_to,'kind',v_kind,
      'allDay',p_all_day,'days',v_count,
      'preferredLocationId',p_preferred_location_id));
  return jsonb_build_object('employeeId',v_employee_id,'savedDays',v_count,
    'kind',v_kind);
end;
$function$;

CREATE OR REPLACE FUNCTION public.employee_availability_days_save_uat_v3(p_dates date[], p_kind text, p_all_day boolean DEFAULT true, p_local_start time without time zone DEFAULT NULL::time without time zone, p_local_end time without time zone DEFAULT NULL::time without time zone, p_preferred_location_id uuid DEFAULT NULL::uuid, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid:=auth.uid(); v_employee uuid; v_day date; v_kind text;
  v_matrix uuid; v_timezone text; v_role uuid; v_event uuid; v_limit integer;
  v_current integer; v_pending integer:=0; v_saved integer:=0;
  v_start timestamptz; v_end timestamptz; v_result jsonb;
begin
  if v_actor is null then raise exception 'AUTH_REQUIRED'; end if;
  v_kind:=upper(trim(coalesce(p_kind,'')));
  if v_kind not in ('AVAILABLE','PREFER_NOT_TO_WORK','CANNOT_WORK')
    then raise exception 'INVALID_AVAILABILITY_KIND'; end if;
  if coalesce(cardinality(p_dates),0)=0 or cardinality(p_dates)>63
    then raise exception 'INVALID_DATE_SELECTION'; end if;
  select employee.id into v_employee from public.employees employee
  where employee.auth_user_id=v_actor and employee.active
    and employee.archived_at is null order by employee.created_at limit 1;
  if v_employee is null then raise exception 'EMPLOYEE_PROFILE_REQUIRED'; end if;

  foreach v_day in array p_dates loop
    if v_day<current_date then raise exception 'AVAILABILITY_DATE_IN_PAST'; end if;
    select matrix.id,coalesce(matrix.settings->>'timezone','Europe/Warsaw')
    into v_matrix,v_timezone from public.matrix_versions matrix
    where matrix.status='ACTIVE' and matrix.schema_version>=2
      and matrix.effective_from<=v_day
      and (matrix.effective_to is null or matrix.effective_to>=v_day)
    order by matrix.effective_from desc,matrix.version desc limit 1;
    if v_matrix is null then raise exception 'MATRIX_V2_FOR_MONTH_NOT_FOUND'; end if;

    -- Selecting green/soft cancels a pending hard request for that day first.
    if v_kind<>'CANNOT_WORK' then
      update public.availability_exception_reviews_v2 set status='CANCELLED',
        reviewed_by=v_actor,reviewed_at=now(),review_reason='Zmiana przez pracownika'
      where employee_id=v_employee and work_date=v_day and status='PENDING';
    end if;

    v_role:=null; v_event:=null; v_limit:=null;
    if v_kind='CANNOT_WORK' then
      select role_grant.role_id,event.id,hot.maximum_hard_unavailable
      into v_role,v_event,v_limit
      from public.matrix_employee_roles_v2 role_grant
      join public.workforce_hot_day_limits_v2 hot
        on hot.matrix_version_id=role_grant.matrix_version_id
        and hot.role_id=role_grant.role_id
      join public.workforce_calendar_events_v2 event on event.id=hot.event_id
        and event.status='ACTIVE' and event.event_kind='HOT_DAY'
        and event.event_date=v_day
      where role_grant.matrix_version_id=v_matrix
        and role_grant.employee_id=v_employee and role_grant.active
        and (role_grant.valid_from is null or role_grant.valid_from<=v_day)
        and (role_grant.valid_to is null or role_grant.valid_to>=v_day)
      order by role_grant.is_primary desc,hot.maximum_hard_unavailable limit 1;
    end if;
    if v_event is not null then
      select count(distinct constraint_row.employee_id)::integer into v_current
      from public.employee_time_constraints_v2 constraint_row
      join public.matrix_employee_roles_v2 role_grant
        on role_grant.matrix_version_id=v_matrix
        and role_grant.employee_id=constraint_row.employee_id
        and role_grant.role_id=v_role and role_grant.active
      where constraint_row.status='ACTIVE'
        and constraint_row.constraint_kind in ('UNAVAILABLE','LEAVE','SICKNESS')
        and constraint_row.time_range && tstzrange(
          v_day::timestamp at time zone v_timezone,
          (v_day+1)::timestamp at time zone v_timezone,'[)');
      if coalesce(v_current,0)>=v_limit then
        v_start:=case when coalesce(p_all_day,true)
          then v_day::timestamp at time zone v_timezone
          else (v_day+p_local_start)::timestamp at time zone v_timezone end;
        v_end:=case when coalesce(p_all_day,true)
          then (v_day+1)::timestamp at time zone v_timezone
          when p_local_end>p_local_start
            then (v_day+p_local_end)::timestamp at time zone v_timezone
          else (v_day+1+p_local_end)::timestamp at time zone v_timezone end;
        insert into public.availability_exception_reviews_v2(
          employee_id,matrix_version_id,hot_day_event_id,role_id,work_date,
          requested_range,note,requested_by
        ) values(v_employee,v_matrix,v_event,v_role,v_day,
          tstzrange(v_start,v_end,'[)'),nullif(trim(p_note),''),v_actor)
        on conflict(employee_id,work_date,role_id) where status='PENDING'
        do update set requested_range=excluded.requested_range,note=excluded.note,
          requested_at=now();
        v_pending:=v_pending+1;
        insert into public.notifications(recipient_id,title,body)
        select distinct recipient.auth_user_id,'HOT DAY: prośba o niedostępność',
          'Pracownik zgłosił twardą niedostępność na '||v_day::text||
          '. Limit dla roli został osiągnięty.'
        from (
          select grant_row.auth_user_id from public.matrix_scope_grants_v2 grant_row
          join public.matrix_roles_v2 role on role.logical_id=grant_row.role_logical_id
          where grant_row.active and grant_row.app_role='ROLE_MANAGER'
            and role.id=v_role
          union
          select permission.auth_user_id from public.user_permissions permission
          where permission.app_role in ('OWNER','ADMIN')
        ) recipient
        where recipient.auth_user_id is not null;
        continue;
      end if;
    end if;
    v_result:=public.employee_availability_bulk_save_v2(
      v_day,v_day,v_kind,p_all_day,p_local_start,p_local_end,
      p_preferred_location_id,p_note);
    v_saved:=v_saved+coalesce((v_result->>'savedDays')::integer,0);
  end loop;
  insert into public.audit_log(actor_id,entity_type,entity_id,action,new_data)
  values(v_actor,'employee_availability_v2',v_employee::text,'SET_DAYS_REVIEW_AWARE',
    jsonb_build_object('dates',to_jsonb(p_dates),'kind',v_kind,
      'savedDays',v_saved,'pendingReviewDays',v_pending));
  return jsonb_build_object('employeeId',v_employee,'savedDays',v_saved,
    'pendingReviewDays',v_pending,'kind',v_kind);
end;
$function$;

CREATE OR REPLACE FUNCTION public.employee_availability_publication_conflicts_uat_v1(p_employee_id uuid, p_dates date[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid();
begin
  if v_actor is null then raise exception 'AUTH_REQUIRED'; end if;
  if not exists(select 1 from public.employees employee
      where employee.id=p_employee_id and employee.auth_user_id=v_actor)
     and not exists(select 1 from public.user_permissions permission
      where permission.auth_user_id=v_actor and permission.app_role in ('OWNER','ADMIN')) then
    perform solver_private.assert_uat_master_persona_v2();
  end if;
  return coalesce((
    select jsonb_agg(distinct jsonb_build_object(
      'scheduleId',schedule.id,'scheduleName',schedule.name,
      'publishedAt',schedule.published_at,'date',shift.shift_date,
      'shiftName',template.name,'locationName',location.name,'roleName',role.name,
      'startsAt',shift.starts_at,'endsAt',shift.ends_at
    ))
    from public.published_role_schedules_v2 schedule
    join public.plan_assignments_v2 assignment on assignment.variant_id=schedule.variant_id and assignment.employee_id=p_employee_id
    join public.plan_shifts_v2 shift on shift.id=assignment.shift_id
    join public.matrix_shift_templates_v2 template on template.id=shift.shift_template_id
    join public.matrix_locations_v2 location on location.id=shift.location_id
    join public.matrix_roles_v2 role on role.id=assignment.role_id
    where schedule.status='PUBLISHED' and shift.shift_date=any(p_dates)
  ),'[]'::jsonb);
end;
$function$;

CREATE OR REPLACE FUNCTION public.employee_availability_publication_conflicts_uat_v2(p_employee_id uuid, p_dates date[], p_all_day boolean DEFAULT true, p_local_start time without time zone DEFAULT NULL::time without time zone, p_local_end time without time zone DEFAULT NULL::time without time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid();
begin
  if v_actor is null then raise exception 'AUTH_REQUIRED'; end if;
  if coalesce(cardinality(p_dates),0)=0 then raise exception 'INVALID_DATE_SELECTION'; end if;
  if not coalesce(p_all_day,true) and (
    p_local_start is null or p_local_end is null or p_local_start=p_local_end
  ) then raise exception 'INVALID_LOCAL_TIME_RANGE'; end if;
  if not exists(select 1 from public.employees employee
      where employee.id=p_employee_id and employee.auth_user_id=v_actor)
     and not exists(select 1 from public.user_permissions permission
      where permission.auth_user_id=v_actor and permission.app_role in ('OWNER','ADMIN')) then
    perform solver_private.assert_uat_master_persona_v2();
  end if;
  return coalesce((
    select jsonb_agg(distinct jsonb_build_object(
      'scheduleId',schedule.id,'scheduleName',schedule.name,
      'publishedAt',schedule.published_at,'date',shift.shift_date,
      'shiftName',template.name,'locationName',location.name,'roleName',role.name,
      'startsAt',shift.starts_at,'endsAt',shift.ends_at
    ))
    from public.published_role_schedules_v2 schedule
    join public.plan_assignments_v2 assignment on assignment.variant_id=schedule.variant_id
      and assignment.employee_id=p_employee_id
    join public.plan_shifts_v2 shift on shift.id=assignment.shift_id
    join public.matrix_shift_templates_v2 template on template.id=shift.shift_template_id
    join public.matrix_locations_v2 location on location.id=shift.location_id
    join public.matrix_roles_v2 role on role.id=assignment.role_id
    where schedule.status='PUBLISHED' and shift.shift_date=any(p_dates)
      and (coalesce(p_all_day,true) or tstzrange(shift.starts_at,shift.ends_at,'[)') &&
        tstzrange(
          (shift.shift_date+p_local_start)::timestamp at time zone location.timezone,
          (shift.shift_date+p_local_end
            +case when p_local_end<=p_local_start then interval '1 day' else interval '0 day' end
          )::timestamp at time zone location.timezone,
          '[)'
        )
      )
  ),'[]'::jsonb);
end;
$function$;

CREATE OR REPLACE FUNCTION public.employee_availability_save_month(p_month date, p_entries jsonb, p_default_remaining_available boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare e uuid; d date; item jsonb; saved integer:=0; defaulted integer:=0; begin
  select id into e from employees where auth_user_id=auth.uid() and active limit 1;
  if e is null then raise exception 'EMPLOYEE_ACCOUNT_NOT_LINKED'; end if;
  if date_trunc('month',p_month)::date<>p_month then raise exception 'MONTH_REQUIRED'; end if;
  for item in select value from jsonb_array_elements(coalesce(p_entries,'[]'::jsonb)) loop
    d:=(item->>'date')::date;
    if date_trunc('month',d)::date<>p_month then raise exception 'DATE_OUTSIDE_MONTH'; end if;
    insert into employee_availability(employee_id,work_date,available,note,source,updated_by,updated_at)
    values(e,d,(item->>'status')='AVAILABLE',nullif(item->>'note',''),'GRAFIK_PRO',auth.uid(),now())
    on conflict(employee_id,work_date) do update set available=excluded.available,note=excluded.note,
      source='GRAFIK_PRO',updated_by=auth.uid(),updated_at=now();
    saved:=saved+1;
  end loop;
  if p_default_remaining_available then
    insert into employee_availability(employee_id,work_date,available,source,updated_by,updated_at)
    select e,g::date,true,'GRAFIK_PRO',auth.uid(),now()
    from generate_series(p_month,(p_month+interval '1 month-1 day')::date,interval '1 day') g
    where not exists(select 1 from employee_availability a where a.employee_id=e and a.work_date=g::date)
    on conflict(employee_id,work_date) do nothing;
    get diagnostics defaulted=row_count;
  end if;
  return jsonb_build_object('saved',saved,'defaultedAvailable',defaulted);
end $function$;

CREATE OR REPLACE FUNCTION public.employee_pay_rate_save_v2(p_id uuid, p_employee_id uuid, p_valid_from date, p_valid_to date, p_base_rate_minor bigint, p_currency text DEFAULT NULL::text, p_contract_type text DEFAULT NULL::text, p_active boolean DEFAULT true)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_id uuid;
  v_currency text;
  v_employment_start date;
  v_employment_end date;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  if not (public.has_app_role('OWNER') or public.has_app_role('ADMIN')
      or public.has_app_role('HR_FINANCE')) then
    raise exception 'FORBIDDEN';
  end if;
  perform pg_advisory_xact_lock(hashtext('matrix-v2-lifecycle'));
  if not exists(select 1 from public.employees e where e.id=p_employee_id) then
    raise exception 'EMPLOYEE_NOT_FOUND';
  end if;
  if p_valid_from is null or (p_valid_to is not null and p_valid_to<p_valid_from)
      or p_base_rate_minor is null or p_base_rate_minor<0 then
    raise exception 'INVALID_PAY_RATE';
  end if;
  if p_id is not null and not exists(
    select 1 from public.employee_pay_rates_v2 rate
    where rate.id=p_id and rate.employee_id=p_employee_id
  ) then raise exception 'PAY_RATE_NOT_FOUND'; end if;

  select profile.employment_start,profile.employment_end
  into v_employment_start,v_employment_end
  from public.matrix_employee_profiles_v2 profile
  join public.matrix_versions version on version.id=profile.matrix_version_id
  where profile.employee_id=p_employee_id
  order by (version.status='DRAFT') desc,version.version desc limit 1;
  if v_employment_start is not null and p_valid_from<v_employment_start then
    raise exception 'PAY_RATE_BEFORE_EMPLOYMENT';
  end if;
  if v_employment_end is not null
    and (p_valid_from>v_employment_end
      or p_valid_to is null or p_valid_to>v_employment_end) then
    raise exception 'PAY_RATE_OUTSIDE_EMPLOYMENT';
  end if;

  select upper(mv.settings->>'currency') into v_currency
  from public.matrix_versions mv
  where mv.status in ('DRAFT','ACTIVE') and mv.schema_version>=2
  order by (mv.status='DRAFT') desc,mv.version desc limit 1;
  v_currency:=coalesce(nullif(upper(trim(p_currency)),''),v_currency);
  if not public.matrix_v2_is_iso_4217_currency(v_currency) then
    raise exception 'INVALID_CURRENCY';
  end if;
  if coalesce(p_active,true) and exists(
    select 1 from public.employee_pay_rates_v2 x
    where x.employee_id=p_employee_id and x.active and x.id is distinct from p_id
      and daterange(x.valid_from,case when x.valid_to is null then null else x.valid_to+1 end,'[)')
        && daterange(p_valid_from,case when p_valid_to is null then null else p_valid_to+1 end,'[)')
  ) then raise exception 'OVERLAPPING_ACTIVE_PAY_RATE'; end if;

  if p_id is null then
    insert into public.employee_pay_rates_v2(
      employee_id,valid_from,valid_to,base_rate_minor,currency,contract_type,
      active,created_by,updated_by
    ) values(
      p_employee_id,p_valid_from,p_valid_to,p_base_rate_minor,v_currency,
      nullif(trim(p_contract_type),''),coalesce(p_active,true),auth.uid(),auth.uid()
    ) returning id into v_id;
  else
    update public.employee_pay_rates_v2 set employee_id=p_employee_id,
      valid_from=p_valid_from,valid_to=p_valid_to,base_rate_minor=p_base_rate_minor,
      currency=v_currency,contract_type=nullif(trim(p_contract_type),''),
      active=coalesce(p_active,true),updated_by=auth.uid(),updated_at=now()
    where id=p_id and employee_id=p_employee_id returning id into v_id;
    if v_id is null then raise exception 'PAY_RATE_NOT_FOUND'; end if;
  end if;

  insert into public.audit_log(actor_id,entity_type,entity_id,action,new_data)
  values(auth.uid(),'employee_pay_rate_v2',v_id::text,'UPSERT',jsonb_build_object(
    'employeeId',p_employee_id,'validFrom',p_valid_from,'validTo',p_valid_to,
    'currency',v_currency,'active',coalesce(p_active,true)));
  return v_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.employee_portal_workspace(p_month date DEFAULT CURRENT_DATE)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
with me as(select * from employees where auth_user_id=auth.uid() and active limit 1),
published as(select id from plans where month=date_trunc('month',p_month)::date and status='PUBLISHED' order by version desc limit 1)
select jsonb_build_object(
 'employee',(select jsonb_build_object('id',m.id,'employeeNo',m.employee_no,'firstName',m.first_name,'lastName',m.last_name,'primaryRole',m.primary_role,
   'locations',coalesce((select jsonb_agg(jsonb_build_object('code',l.code,'name',l.name)) from employee_locations el join locations l on l.id=el.location_id where el.employee_id=m.id and (el.standard_allowed or el.overtime_allowed or el.home_location)),'[]'::jsonb)) from me m),
 'preferences',coalesce((select jsonb_agg(to_jsonb(ep) order by ep.valid_from desc) from employee_preferences ep join me on me.id=ep.employee_id),'[]'::jsonb),
 'availability',coalesce((select jsonb_agg(jsonb_build_object('date',av.work_date,'status',case when av.available then 'AVAILABLE' else 'UNAVAILABLE' end,'source',av.source,'note',av.note) order by av.work_date) from employee_availability av join me on me.id=av.employee_id where date_trunc('month',av.work_date)::date=date_trunc('month',p_month)::date),'[]'::jsonb),
 'availabilityHistory',coalesce((select jsonb_agg(jsonb_build_object('date',h.work_date,'from',h.old_available,'to',h.new_available,'source',h.source,'changedAt',h.changed_at) order by h.changed_at desc) from employee_availability_history h join me on me.id=h.employee_id limit 100),'[]'::jsonb),
 'assignments',coalesce((select jsonb_agg(jsonb_build_object('id',a.id,'shiftId',s.id,'date',s.shift_date,'startsAt',s.starts_at,'endsAt',s.ends_at,'shiftCode',s.shift_code,'location',l.name,'locationCode',l.code,'role',a.assigned_role,'capability',a.assigned_capability,
   'coworkers',coalesce((select jsonb_agg(jsonb_build_object('name',ce.first_name||' '||ce.last_name,'role',ca.assigned_role,'capability',ca.assigned_capability) order by ce.last_name) from assignments ca join employees ce on ce.id=ca.employee_id where ca.shift_id=s.id and ca.employee_id<>a.employee_id),'[]'::jsonb)) order by s.starts_at)
   from assignments a join shifts s on s.id=a.shift_id join published p on p.id=s.plan_id join locations l on l.id=s.location_id join me on me.id=a.employee_id),'[]'::jsonb),
 'attendance',coalesce((select jsonb_agg(jsonb_build_object('id',ae.id,'action',ae.event_type,'occurredAt',ae.occurred_at,'location',l.name) order by ae.occurred_at desc)
   from attendance_events ae join locations l on l.id=ae.location_id join me on me.id=ae.employee_id where ae.occurred_at>=date_trunc('month',p_month)),'[]'::jsonb)
);
$function$;

CREATE OR REPLACE FUNCTION public.employee_request_review_uat_v1(p_request_id uuid, p_decision text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid:=auth.uid();
  v_request public.employee_requests_v1%rowtype;
  v_decision text:=upper(trim(coalesce(p_decision,'')));
  v_constraint uuid;
  v_status text;
  v_employee_user uuid;
begin
  if v_actor is null then raise exception 'AUTH_REQUIRED'; end if;
  select * into v_request from public.employee_requests_v1 request_row
  where request_row.id=p_request_id for update;
  if v_request.id is null then raise exception 'EMPLOYEE_REQUEST_NOT_FOUND'; end if;
  select employee.auth_user_id into v_employee_user from public.employees employee
  where employee.id=v_request.employee_id;
  if v_employee_user=v_actor or not public.matrix_v2_can_manage_employee(v_request.employee_id) then
    raise exception 'FORBIDDEN';
  end if;
  if v_request.request_type='SICKNESS' then
    if v_request.status<>'APPLIED' then raise exception 'REQUEST_ALREADY_RESOLVED'; end if;
    if v_decision<>'ACKNOWLEDGE' then raise exception 'SICKNESS_CANNOT_BE_REJECTED'; end if;
    v_status:='ACKNOWLEDGED';
  else
    if v_request.status<>'PENDING' then raise exception 'REQUEST_ALREADY_RESOLVED'; end if;
    if v_decision not in ('APPROVE','REJECT') then raise exception 'INVALID_REVIEW_DECISION'; end if;
    if v_decision='REJECT' and length(trim(coalesce(p_reason,'')))<3 then
      raise exception 'REVIEW_REASON_REQUIRED';
    end if;
    v_status:=case when v_decision='APPROVE' then 'APPROVED' else 'REJECTED' end;
    if v_request.request_type='LEAVE' and v_decision='APPROVE' then
      v_constraint:=gen_random_uuid();
      insert into public.employee_time_constraints_v2(
        id,employee_id,constraint_kind,time_range,source,source_record_key,
        priority,editable_by_employee,status,note,created_by
      ) values(v_constraint,v_request.employee_id,'LEAVE',v_request.requested_range,
        'EMPLOYEE_LEAVE_REQUEST','employee-request:'||v_request.id::text,500,false,
        'ACTIVE',v_request.note,v_actor);
    elsif v_request.request_type='HARD_UNAVAILABLE' then
      if v_request.legacy_review_id is null then raise exception 'HARD_REVIEW_NOT_FOUND'; end if;
      if v_decision='APPROVE' then
        v_constraint:=gen_random_uuid();
        insert into public.employee_time_constraints_v2(
          id,employee_id,constraint_kind,time_range,source,source_record_key,
          priority,editable_by_employee,status,note,created_by
        ) values(v_constraint,v_request.employee_id,'UNAVAILABLE',v_request.requested_range,
          'HOT_DAY_APPROVED','hot-day-review:'||v_request.legacy_review_id::text,100,false,
          'ACTIVE',v_request.note,v_actor);
      end if;
      update public.availability_exception_reviews_v2 set
        status=case when v_decision='APPROVE' then 'APPROVED' else 'REJECTED' end,
        reviewed_by=v_actor,reviewed_at=now(),review_reason=coalesce(nullif(trim(p_reason),''),'Decyzja lidera'),
        constraint_id=v_constraint
      where id=v_request.legacy_review_id and status='PENDING';
      if not found then raise exception 'HARD_REVIEW_ALREADY_RESOLVED'; end if;
    end if;
  end if;
  update public.employee_requests_v1 set status=v_status,reviewed_by=v_actor,
    reviewed_at=now(),review_reason=nullif(trim(p_reason),''),
    constraint_id=coalesce(v_constraint,constraint_id),updated_at=now()
  where id=v_request.id;
  update public.notifications set resolved_at=now(),resolution=v_status
  where context_type='EMPLOYEE_REQUEST'
    and context_id=v_request.id::text and resolved_at is null;
  if v_employee_user is not null then
    insert into public.notifications(
      recipient_id,title,body,kind,context_type,context_id,action_route,action_required
    ) values(v_employee_user,
      case when v_request.request_type='SICKNESS' then 'L4 przyjęte do wiadomości'
        else 'Decyzja dotycząca nieobecności' end,
      case when v_request.request_type='SICKNESS' then 'Lider potwierdził odbiór zgłoszenia L4.'
        when v_status='APPROVED' then 'Twoja nieobecność została zaakceptowana.'
        else 'Twoja prośba nie została zaakceptowana: '||coalesce(nullif(trim(p_reason),''),'bez dodatkowego uzasadnienia') end,
      'DECISION','EMPLOYEE_REQUEST',v_request.id::text,
      '/my-schedule?month='||to_char(v_request.date_from,'YYYY-MM'),false);
  end if;
  insert into public.audit_log(actor_id,entity_type,entity_id,action,new_data)
  values(v_actor,'employee_request_v1',v_request.id::text,v_decision,jsonb_build_object(
    'employeeId',v_request.employee_id,'requestType',v_request.request_type,
    'status',v_status,'reason',nullif(trim(p_reason),''),'constraintId',v_constraint));
  return jsonb_build_object('id',v_request.id,'status',v_status,'constraintId',v_constraint);
end;
$function$;

CREATE OR REPLACE FUNCTION public.employee_request_submit_uat_v1(p_request_type text, p_dates date[], p_all_day boolean DEFAULT true, p_local_start time without time zone DEFAULT NULL::time without time zone, p_local_end time without time zone DEFAULT NULL::time without time zone, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid:=auth.uid();
  v_employee uuid;
  v_type text:=upper(trim(coalesce(p_request_type,'')));
  v_first date;
  v_last date;
  v_day date;
  v_timezone text;
  v_start timestamptz;
  v_end timestamptz;
  v_id uuid;
  v_constraint uuid;
  v_legacy uuid;
  v_result jsonb;
  v_saved integer:=0;
  v_pending integer:=0;
  v_request_ids jsonb:='[]'::jsonb;
begin
  if v_actor is null then raise exception 'AUTH_REQUIRED'; end if;
  if v_type not in ('LEAVE','SICKNESS','HARD_UNAVAILABLE') then
    raise exception 'INVALID_EMPLOYEE_REQUEST_TYPE';
  end if;
  if coalesce(cardinality(p_dates),0)=0 or cardinality(p_dates)>63 then
    raise exception 'INVALID_DATE_SELECTION';
  end if;
  select min(day_value),max(day_value) into v_first,v_last
  from unnest(p_dates) day_value;
  if (select count(distinct day_value) from unnest(p_dates) day_value)<>cardinality(p_dates) then
    raise exception 'DUPLICATE_DATES';
  end if;
  if v_type in ('LEAVE','HARD_UNAVAILABLE') and v_first<current_date then
    raise exception 'ABSENCE_DATE_IN_PAST';
  end if;
  if v_type in ('LEAVE','SICKNESS') and cardinality(p_dates)<>(v_last-v_first+1) then
    raise exception 'REQUEST_RANGE_MUST_BE_CONTIGUOUS';
  end if;
  if not coalesce(p_all_day,true) and (
    p_local_start is null or p_local_end is null or p_local_start=p_local_end
  ) then raise exception 'INVALID_LOCAL_TIME_RANGE'; end if;
  select employee.id into v_employee from public.employees employee
  where employee.auth_user_id=v_actor and employee.active
    and employee.archived_at is null order by employee.created_at limit 1;
  if v_employee is null then raise exception 'EMPLOYEE_PROFILE_REQUIRED'; end if;

  if v_type in ('LEAVE','SICKNESS') then
    select coalesce(matrix_row.settings->>'timezone','Europe/Warsaw') into v_timezone
    from public.matrix_versions matrix_row
    where matrix_row.status='ACTIVE' and matrix_row.schema_version>=2
      and matrix_row.effective_from<=v_first
      and (matrix_row.effective_to is null or matrix_row.effective_to>=v_first)
    order by matrix_row.effective_from desc,matrix_row.version desc limit 1;
    if v_timezone is null then raise exception 'MATRIX_V2_FOR_MONTH_NOT_FOUND'; end if;
    v_start:=case when coalesce(p_all_day,true)
      then v_first::timestamp at time zone v_timezone
      else (v_first+p_local_start)::timestamp at time zone v_timezone end;
    v_end:=case when coalesce(p_all_day,true)
      then (v_last+1)::timestamp at time zone v_timezone
      when p_local_end>p_local_start
        then (v_last+p_local_end)::timestamp at time zone v_timezone
      else (v_last+1+p_local_end)::timestamp at time zone v_timezone end;
    v_id:=gen_random_uuid();
    if v_type='SICKNESS' then
      v_constraint:=gen_random_uuid();
      insert into public.employee_time_constraints_v2(
        id,employee_id,constraint_kind,time_range,source,source_record_key,
        priority,editable_by_employee,status,note,created_by
      ) values(v_constraint,v_employee,'SICKNESS',tstzrange(v_start,v_end,'[)'),
        'EMPLOYEE_SICKNESS','employee-request:'||v_id::text,500,false,'ACTIVE',
        nullif(trim(p_note),''),v_actor);
    end if;
    insert into public.employee_requests_v1(
      id,employee_id,requested_by,request_type,date_from,date_to,requested_range,
      status,requires_decision,note,constraint_id
    ) values(v_id,v_employee,v_actor,v_type,v_first,v_last,tstzrange(v_start,v_end,'[)'),
      case when v_type='LEAVE' then 'PENDING' else 'APPLIED' end,true,
      nullif(trim(p_note),''),v_constraint);
    insert into public.notifications(
      recipient_id,title,body,kind,context_type,context_id,action_route,action_required
    ) select recipient.auth_user_id,
      case when v_type='LEAVE' then 'Nowy wniosek urlopowy' else 'Zgłoszone L4' end,
      case when v_type='LEAVE'
        then 'Pracownik prosi o urlop '||v_first::text||'–'||v_last::text||'. Otwórz sprawę i podejmij decyzję.'
        else 'Pracownik zgłosił L4 '||v_first::text||'–'||v_last::text||'. Nie można go odrzucić — potwierdź odbiór i zorganizuj zastępstwo.' end,
      'ACTION_REQUIRED','EMPLOYEE_REQUEST',v_id::text,'/profile?tab=inbox',true
    from public.personal_request_manager_recipients_uat_v1(v_employee) recipient;
    v_request_ids:=jsonb_build_array(v_id);
    v_saved:=1;
  else
    foreach v_day in array p_dates loop
      v_result:=public.employee_availability_days_save_uat_v3(
        array[v_day],'CANNOT_WORK',p_all_day,p_local_start,p_local_end,null,p_note);
      select coalesce(matrix_row.settings->>'timezone','Europe/Warsaw') into v_timezone
      from public.matrix_versions matrix_row
      where matrix_row.status='ACTIVE' and matrix_row.schema_version>=2
        and matrix_row.effective_from<=v_day
        and (matrix_row.effective_to is null or matrix_row.effective_to>=v_day)
      order by matrix_row.effective_from desc,matrix_row.version desc limit 1;
      v_start:=case when coalesce(p_all_day,true)
        then v_day::timestamp at time zone v_timezone
        else (v_day+p_local_start)::timestamp at time zone v_timezone end;
      v_end:=case when coalesce(p_all_day,true)
        then (v_day+1)::timestamp at time zone v_timezone
        when p_local_end>p_local_start
          then (v_day+p_local_end)::timestamp at time zone v_timezone
        else (v_day+1+p_local_end)::timestamp at time zone v_timezone end;
      v_id:=gen_random_uuid();v_constraint:=null;v_legacy:=null;
      if coalesce((v_result->>'pendingReviewDays')::integer,0)>0 then
        select review.id into v_legacy from public.availability_exception_reviews_v2 review
        where review.employee_id=v_employee and review.work_date=v_day
          and review.status='PENDING' order by review.requested_at desc limit 1;
      else
        select constraint_row.id into v_constraint
        from public.employee_time_constraints_v2 constraint_row
        where constraint_row.employee_id=v_employee and constraint_row.status='ACTIVE'
          and constraint_row.constraint_kind='UNAVAILABLE'
          and constraint_row.source='GRAFIK_PRO'
          and constraint_row.time_range && tstzrange(v_start,v_end,'[)')
        order by constraint_row.created_at desc limit 1;
      end if;
      insert into public.employee_requests_v1(
        id,employee_id,requested_by,request_type,date_from,date_to,requested_range,
        status,requires_decision,note,constraint_id,legacy_review_id
      ) values(v_id,v_employee,v_actor,v_type,v_day,v_day,tstzrange(v_start,v_end,'[)'),
        case when v_legacy is null then 'AUTO_APPLIED' else 'PENDING' end,
        v_legacy is not null,nullif(trim(p_note),''),v_constraint,v_legacy);
      if v_legacy is not null then
        delete from public.notifications notification
        where notification.title='HOT DAY: prośba o niedostępność'
          and notification.body='Pracownik zgłosił twardą niedostępność na '||v_day::text||'. Limit dla roli został osiągnięty.'
          and notification.created_at>=transaction_timestamp();
        insert into public.notifications(
          recipient_id,title,body,kind,context_type,context_id,action_route,action_required
        ) select recipient.auth_user_id,'Limit nieobecności przekroczony',
          'Twarda nieobecność na '||v_day::text||' przekracza limit. Otwórz sprawę i podejmij decyzję.',
          'ACTION_REQUIRED','EMPLOYEE_REQUEST',v_id::text,'/profile?tab=inbox',true
        from public.personal_request_manager_recipients_uat_v1(v_employee) recipient;
        v_pending:=v_pending+1;
      else
        v_saved:=v_saved+1;
      end if;
      v_request_ids:=v_request_ids||jsonb_build_array(v_id);
    end loop;
  end if;
  insert into public.audit_log(actor_id,entity_type,entity_id,action,new_data)
  values(v_actor,'employee_request_v1',v_employee::text,'SUBMIT',jsonb_build_object(
    'requestType',v_type,'dates',to_jsonb(p_dates),'requestIds',v_request_ids,
    'saved',v_saved,'pending',v_pending));
  return jsonb_build_object('requestType',v_type,'requestIds',v_request_ids,
    'saved',v_saved,'pending',v_pending);
end;
$function$;

CREATE OR REPLACE FUNCTION public.employee_request_submit_uat_v2(p_request_type text, p_dates date[], p_all_day boolean DEFAULT true, p_local_start time without time zone DEFAULT NULL::time without time zone, p_local_end time without time zone DEFAULT NULL::time without time zone, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_day date;
  v_result jsonb;
  v_request_ids jsonb:='[]'::jsonb;
  v_saved integer:=0;
  v_pending integer:=0;
begin
  if coalesce(cardinality(p_dates),0)=0 or cardinality(p_dates)>63 then
    raise exception 'INVALID_DATE_SELECTION';
  end if;
  if coalesce(p_all_day,true) or cardinality(p_dates)=1
    or upper(trim(coalesce(p_request_type,'')))='HARD_UNAVAILABLE' then
    return public.employee_request_submit_uat_v1(
      p_request_type,p_dates,p_all_day,p_local_start,p_local_end,p_note
    );
  end if;
  foreach v_day in array p_dates loop
    v_result:=public.employee_request_submit_uat_v1(
      p_request_type,array[v_day],false,p_local_start,p_local_end,p_note
    );
    v_request_ids:=v_request_ids||coalesce(v_result->'requestIds','[]'::jsonb);
    v_saved:=v_saved+coalesce((v_result->>'saved')::integer,0);
    v_pending:=v_pending+coalesce((v_result->>'pending')::integer,0);
  end loop;
  return jsonb_build_object(
    'requestType',upper(trim(coalesce(p_request_type,''))),
    'requestIds',v_request_ids,'saved',v_saved,'pending',v_pending
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.employee_restore(p_employee_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ begin
 if not(public.has_app_role('OWNER') or public.has_app_role('ADMIN') or public.has_app_role('HR_FINANCE')) then raise exception 'FORBIDDEN'; end if;
 update employees set active=true,archived_at=null,archived_by=null,archive_reason=null,employment_end=null where id=p_employee_id;
 if not found then raise exception 'EMPLOYEE_NOT_FOUND'; end if;
 insert into audit_log(actor_id,entity_type,entity_id,action) values(auth.uid(),'employee',p_employee_id::text,'RESTORE');
end $function$;

CREATE OR REPLACE FUNCTION public.employee_shift_preferences_save_self_v2(p_month date, p_preferences jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_employee uuid;
  v_month date:=date_trunc('month',p_month)::date;
  v_period text;
  v_level text;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  if p_month is null or jsonb_typeof(p_preferences)<>'object' then
    raise exception 'INVALID_SHIFT_PERIOD_PREFERENCES';
  end if;
  select employee.id into v_employee from public.employees employee
  where employee.auth_user_id=auth.uid() and employee.active
    and employee.archived_at is null order by employee.id limit 1 for update;
  if v_employee is null then raise exception 'EMPLOYEE_NOT_FOUND'; end if;
  update public.employee_preferences preference set status='CANCELLED'
  where preference.employee_id=v_employee and preference.status='ACTIVE'
    and preference.source='GRAFIK_PRO'
    and preference.preference_type='PREFERRED_SHIFT'
    and preference.valid_from<v_month+interval '1 month'
    and preference.valid_to>=v_month;
  foreach v_period in array array['MORNING','MIDDLE','EVENING'] loop
    v_level:=upper(coalesce(p_preferences->>v_period,'NEUTRAL'));
    if v_level not in ('PREFERRED','NEUTRAL','AVOIDED') then
      raise exception 'INVALID_EMPLOYEE_SHIFT_PREFERENCE_LEVEL';
    end if;
    insert into public.employee_preferences(
      employee_id,valid_from,valid_to,preference_type,preference_value,
      source,editable_by_employee,status
    ) values(
      v_employee,v_month,(v_month+interval '1 month - 1 day')::date,
      'PREFERRED_SHIFT',jsonb_build_object('period',v_period,'level',v_level),
      'GRAFIK_PRO',true,'ACTIVE'
    );
  end loop;
  insert into public.audit_log(actor_id,entity_type,entity_id,action,new_data)
  values(auth.uid(),'employee_shift_preferences_v2',v_employee::text,'UPSERT',
    jsonb_build_object('month',v_month,'preferences',p_preferences));
  return jsonb_build_object('saved',3,'month',v_month);
end;
$function$;

CREATE OR REPLACE FUNCTION public.employee_shift_preferences_self_v2(p_month date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_employee uuid;
  v_matrix uuid;
  v_month date:=date_trunc('month',p_month)::date;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  if p_month is null then raise exception 'MONTH_REQUIRED'; end if;
  select employee.id into v_employee from public.employees employee
  where employee.auth_user_id=auth.uid() and employee.active
    and employee.archived_at is null order by employee.id limit 1;
  if v_employee is null then raise exception 'EMPLOYEE_NOT_FOUND'; end if;
  select matrix.id into v_matrix from public.matrix_versions matrix
  where matrix.status in ('ACTIVE','ARCHIVED') and matrix.schema_version>=2
    and solver_private.matrix_covers_planning_month_uat_v1(matrix.effective_from,v_month)
  order by matrix.effective_from desc,matrix.version desc limit 1;
  if v_matrix is null then raise exception 'MATRIX_V2_FOR_MONTH_NOT_FOUND'; end if;
  return jsonb_build_object(
    'employeeId',v_employee,'month',v_month,
    'employee',jsonb_build_object(
      'MORNING',coalesce((select upper(p.preference_value->>'level')
        from public.employee_preferences p where p.employee_id=v_employee
          and p.status='ACTIVE' and p.source='GRAFIK_PRO'
          and p.preference_type='PREFERRED_SHIFT'
          and upper(p.preference_value->>'period')='MORNING'
          and p.valid_from<v_month+interval '1 month' and p.valid_to>=v_month
        order by p.created_at desc limit 1),'NEUTRAL'),
      'MIDDLE',coalesce((select upper(p.preference_value->>'level')
        from public.employee_preferences p where p.employee_id=v_employee
          and p.status='ACTIVE' and p.source='GRAFIK_PRO'
          and p.preference_type='PREFERRED_SHIFT'
          and upper(p.preference_value->>'period')='MIDDLE'
          and p.valid_from<v_month+interval '1 month' and p.valid_to>=v_month
        order by p.created_at desc limit 1),'NEUTRAL'),
      'EVENING',coalesce((select upper(p.preference_value->>'level')
        from public.employee_preferences p where p.employee_id=v_employee
          and p.status='ACTIVE' and p.source='GRAFIK_PRO'
          and p.preference_type='PREFERRED_SHIFT'
          and upper(p.preference_value->>'period')='EVENING'
          and p.valid_from<v_month+interval '1 month' and p.valid_to>=v_month
        order by p.created_at desc limit 1),'NEUTRAL')
    ),
    'effective',coalesce(solver_private.alpha16_shift_rules_v2(
      v_employee,v_matrix,v_month
    )->'periods','{}'::jsonb),
    'managerOverrides',coalesce((select jsonb_object_agg(
      upper(p.preference_value->>'period'),upper(p.preference_value->>'level')
    ) from public.employee_preferences p
      where p.employee_id=v_employee and p.status='ACTIVE'
        and p.source='MANAGER' and p.preference_type='PREFERRED_SHIFT'
        and p.preference_value->>'matrixVersionId'=v_matrix::text
        and p.valid_from<v_month+interval '1 month' and p.valid_to>=v_month
    ),'{}'::jsonb)
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.employee_time_constraint_revoke_v2(p_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_row public.employee_time_constraints_v2%rowtype;
  v_self boolean;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  select * into v_row from public.employee_time_constraints_v2 x
  where x.id=p_id for update;
  if v_row.id is null then raise exception 'TIME_CONSTRAINT_NOT_FOUND'; end if;
  if v_row.status<>'ACTIVE' then return v_row.id; end if;
  if not public.matrix_v2_can_manage_employee(v_row.employee_id) then
    raise exception 'FORBIDDEN';
  end if;
  select exists(select 1 from public.employees e
    where e.id=v_row.employee_id and e.auth_user_id=auth.uid()) into v_self;
  if v_self and (v_row.source<>'GRAFIK_PRO' or not v_row.editable_by_employee) then
    raise exception 'PROTECTED_TIME_CONSTRAINT';
  end if;
  update public.employee_time_constraints_v2 set status='REVOKED',
    revoked_at=now(),updated_at=now() where id=v_row.id;
  insert into public.audit_log(actor_id,entity_type,entity_id,action,new_data)
  values(auth.uid(),'employee_time_constraint_v2',v_row.id::text,'REVOKE',
    jsonb_build_object('employeeId',v_row.employee_id,'kind',v_row.constraint_kind));
  return v_row.id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.employee_time_constraint_save_v2(p_id uuid, p_employee_id uuid, p_kind text, p_starts_at timestamp with time zone, p_ends_at timestamp with time zone, p_note text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_kind text:=upper(trim(p_kind));
  v_old public.employee_time_constraints_v2%rowtype;
  v_id uuid;
  v_self boolean;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  if not exists(select 1 from public.employees e where e.id=p_employee_id) then
    raise exception 'EMPLOYEE_NOT_FOUND';
  end if;
  if not public.matrix_v2_can_manage_employee(p_employee_id) then
    raise exception 'FORBIDDEN';
  end if;
  select exists(select 1 from public.employees e
    where e.id=p_employee_id and e.auth_user_id=auth.uid()) into v_self;
  if v_kind not in ('AVAILABLE_WINDOW','UNAVAILABLE','LEAVE','SICKNESS') then
    raise exception 'INVALID_TIME_CONSTRAINT_KIND';
  end if;
  if v_self and v_kind not in ('AVAILABLE_WINDOW','UNAVAILABLE') then
    raise exception 'EMPLOYEE_CANNOT_CREATE_PROTECTED_ABSENCE';
  end if;
  if p_starts_at is null or p_ends_at is null or p_ends_at<=p_starts_at then
    raise exception 'INVALID_TIME_RANGE';
  end if;

  if p_id is not null then
    select * into v_old from public.employee_time_constraints_v2 x
    where x.id=p_id for update;
    if v_old.id is null then raise exception 'TIME_CONSTRAINT_NOT_FOUND'; end if;
    if v_old.employee_id<>p_employee_id then raise exception 'EMPLOYEE_MISMATCH'; end if;
    if v_old.status<>'ACTIVE' then raise exception 'TIME_CONSTRAINT_NOT_ACTIVE'; end if;
    if v_self and (v_old.source<>'GRAFIK_PRO' or not v_old.editable_by_employee) then
      raise exception 'PROTECTED_TIME_CONSTRAINT';
    end if;
    update public.employee_time_constraints_v2 set status='REVOKED',
      revoked_at=now(),updated_at=now() where id=v_old.id;
  end if;

  insert into public.employee_time_constraints_v2(
    employee_id,constraint_kind,time_range,source,priority,editable_by_employee,
    status,note,supersedes_id,created_by
  ) values(
    p_employee_id,v_kind,tstzrange(p_starts_at,p_ends_at,'[)'),
    case when v_self then 'GRAFIK_PRO' else 'MANAGER' end,
    case when v_self then 100 else 300 end,v_self,'ACTIVE',nullif(trim(p_note),''),
    v_old.id,auth.uid()
  ) returning id into v_id;

  insert into public.audit_log(actor_id,entity_type,entity_id,action,new_data)
  values(auth.uid(),'employee_time_constraint_v2',v_id::text,
    case when p_id is null then 'CREATE' else 'SUPERSEDE' end,
    jsonb_build_object('employeeId',p_employee_id,'kind',v_kind,
      'startsAt',p_starts_at,'endsAt',p_ends_at,'supersedesId',v_old.id));
  return v_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.employee_time_constraints_self_v2(p_month date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_month date:=date_trunc('month',p_month)::date;
  v_employee_id uuid;
  v_matrix uuid;
  v_timezone text;
  v_default_available boolean;
  v_period_start timestamptz;
  v_period_end timestamptz;
  v_constraints jsonb;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  if p_month is null then raise exception 'MONTH_REQUIRED'; end if;
  select employee.id into v_employee_id
  from public.employees employee
  where employee.auth_user_id=auth.uid() and employee.active
    and employee.archived_at is null
  order by employee.id limit 1;
  if v_employee_id is null then raise exception 'EMPLOYEE_NOT_FOUND'; end if;
  select matrix.id,nullif(matrix.settings->>'timezone',''),
    coalesce((matrix.settings->>'missingAvailabilityMeansAvailable')::boolean,true)
  into v_matrix,v_timezone,v_default_available
  from public.matrix_versions matrix
  where matrix.status in ('ACTIVE','ARCHIVED') and matrix.schema_version>=2
    and solver_private.matrix_covers_planning_month_uat_v1(matrix.effective_from,v_month)
    and coalesce(matrix.content_hash,'') ~ '^[0-9a-f]{64}$'
    and coalesce(matrix.workforce_hash,'') ~ '^[0-9a-f]{64}$'
  order by matrix.effective_from desc,matrix.version desc limit 1;
  if v_timezone is null then raise exception 'MATRIX_V2_FOR_MONTH_NOT_FOUND'; end if;
  v_period_start:=v_month::timestamp at time zone v_timezone;
  v_period_end:=(v_month+interval '1 month')::timestamp at time zone v_timezone;

  with entries as (
    select constraint_row.id,constraint_row.constraint_kind kind,
      lower(constraint_row.time_range) starts_at,
      upper(constraint_row.time_range) ends_at,
      constraint_row.source,
      constraint_row.source='GRAFIK_PRO'
        and constraint_row.editable_by_employee editable,
      constraint_row.note,
      (select location.id from public.matrix_locations_v2 location
        where location.matrix_version_id=v_matrix
          and location.logical_id=constraint_row.location_logical_id
        order by location.active desc,location.sort_order limit 1) preferred_location_id
    from public.employee_time_constraints_v2 constraint_row
    where constraint_row.employee_id=v_employee_id
      and constraint_row.status='ACTIVE'
      and constraint_row.time_range
        && tstzrange(v_period_start,v_period_end,'[)')
    union all
    select preference.id,
      case when preference.preference_type='OTHER'
        then 'PREFER_NOT_TO_WORK' else 'PREFERRED_LOCATION' end,
      preference.valid_from::timestamp at time zone v_timezone,
      (preference.valid_to+1)::timestamp at time zone v_timezone,
      preference.source,
      preference.source='GRAFIK_PRO' and preference.editable_by_employee,
      nullif(preference.preference_value->>'note',''),
      case when preference.preference_type='PREFERRED_LOCATION'
        and preference.preference_value->>'locationId'
          ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
        then (preference.preference_value->>'locationId')::uuid else null end
    from public.employee_preferences preference
    where preference.employee_id=v_employee_id
      and preference.status='ACTIVE'
      and preference.valid_from<v_month+interval '1 month'
      and preference.valid_to>=v_month
      and (preference.preference_type='PREFERRED_LOCATION'
        or (preference.preference_type='OTHER'
          and preference.preference_value->>'kind'='DAY_OFF'
          and preference.preference_value->>'strength'='SOFT'))
  )
  select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
    'id',entry.id,'kind',entry.kind,'startsAt',entry.starts_at,
    'endsAt',entry.ends_at,'source',entry.source,
    'editable',entry.editable,'note',entry.note,
    'preferredLocationId',entry.preferred_location_id
  )) order by entry.starts_at,entry.ends_at,entry.id),'[]'::jsonb)
  into v_constraints from entries entry;
  return jsonb_build_object(
    'employeeId',v_employee_id,'timezone',v_timezone,
    'defaultAvailable',v_default_available,
    'constraints',v_constraints
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.employee_update(p_employee_id uuid, p_data jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ begin
 if not(public.has_app_role('OWNER') or public.has_app_role('ADMIN') or public.has_app_role('HR_FINANCE')) then raise exception 'FORBIDDEN'; end if;
 update employees set
   first_name=coalesce(nullif(trim(p_data->>'firstName'),''),first_name),last_name=coalesce(nullif(trim(p_data->>'lastName'),''),last_name),
   email=coalesce(nullif(trim(p_data->>'email'),''),email),primary_role=coalesce(nullif(p_data->>'primaryRole','')::employee_role,primary_role),
   monthly_nominal_minutes=coalesce((p_data->>'nominalMinutes')::integer,monthly_nominal_minutes),max_weekly_minutes=coalesce((p_data->>'maxWeeklyMinutes')::integer,max_weekly_minutes),
   max_monthly_minutes=coalesce((p_data->>'maxMonthlyMinutes')::integer,max_monthly_minutes),preferred_shift=coalesce(nullif(p_data->>'preferredShift',''),preferred_shift),
   hourly_rate=case when public.has_app_role('OWNER') or public.has_app_role('HR_FINANCE') then coalesce((p_data->>'hourlyRate')::numeric,hourly_rate) else hourly_rate end,
   updated_at=now() where id=p_employee_id;
 insert into employee_hr_profiles(employee_id,contract_type,employment_fraction,leave_days,hr_note,updated_by,updated_at)
 values(p_employee_id,coalesce(nullif(p_data->>'contractType',''),'UMOWA_O_PRACE'),coalesce((p_data->>'employmentFraction')::numeric,1),coalesce((p_data->>'leaveDays')::integer,0),nullif(p_data->>'hrNote',''),auth.uid(),now())
 on conflict(employee_id) do update set contract_type=excluded.contract_type,employment_fraction=excluded.employment_fraction,leave_days=excluded.leave_days,hr_note=excluded.hr_note,updated_by=auth.uid(),updated_at=now();
 insert into audit_log(actor_id,entity_type,entity_id,action,new_data) values(auth.uid(),'employee',p_employee_id::text,'UPDATE',p_data-'hourlyRate');
end $function$;

CREATE OR REPLACE FUNCTION public.employee_weekly_work_patterns_replace_before_phase1_uat_v1(p_employee_id uuid, p_valid_from date, p_valid_to date, p_patterns jsonb, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid:=auth.uid();
  v_reason text:=trim(coalesce(p_reason,''));
  v_item jsonb;
  v_count integer:=0;
  v_revision integer;
  v_supersedes_id uuid;
begin
  if not public.can_manage_plans() then raise exception 'FORBIDDEN'; end if;
  if v_actor is null then raise exception 'AUTH_REQUIRED'; end if;
  if length(v_reason)<3 then raise exception 'WORK_PATTERN_REASON_REQUIRED'; end if;
  if p_valid_to is not null and p_valid_to<p_valid_from then raise exception 'WORK_PATTERN_PERIOD_INVALID'; end if;
  if jsonb_typeof(coalesce(p_patterns,'[]'::jsonb))<>'array' then raise exception 'WORK_PATTERNS_ARRAY_REQUIRED'; end if;

  perform pg_advisory_xact_lock(hashtextextended('weekly-pattern:'||p_employee_id::text,0));
  select coalesce(max(revision),0)+1 into v_revision
  from public.employee_weekly_work_patterns_v2 where employee_id=p_employee_id;
  update public.employee_weekly_work_patterns_v2 set active=false,revoked_at=now()
  where employee_id=p_employee_id and active
    and daterange(valid_from,coalesce(valid_to,'infinity'::date),'[]') && daterange(p_valid_from,coalesce(p_valid_to,'infinity'::date),'[]');

  for v_item in select value from jsonb_array_elements(coalesce(p_patterns,'[]'::jsonb)) loop
    if coalesce((v_item->>'weekday')::integer,0) not between 1 and 7 then raise exception 'WORK_PATTERN_WEEKDAY_INVALID'; end if;
    if nullif(v_item->>'localStart','') is null or nullif(v_item->>'localEnd','') is null then raise exception 'WORK_PATTERN_TIME_REQUIRED'; end if;
    if upper(coalesce(v_item->>'enforcement','')) not in ('HARD','PREFERENCE') then raise exception 'WORK_PATTERN_ENFORCEMENT_INVALID'; end if;
    select p.id into v_supersedes_id
    from public.employee_weekly_work_patterns_v2 p
    where p.employee_id=p_employee_id and p.revision<v_revision
      and p.weekday=(v_item->>'weekday')::smallint
      and p.local_start=(v_item->>'localStart')::time
      and p.local_end=(v_item->>'localEnd')::time
      and p.role_id is not distinct from nullif(v_item->>'roleId','')::uuid
      and p.location_id is not distinct from nullif(v_item->>'locationId','')::uuid
      and p.enforcement=upper(v_item->>'enforcement')
    order by p.revision desc,p.created_at desc limit 1;
    insert into public.employee_weekly_work_patterns_v2(employee_id,weekday,local_start,local_end,role_id,location_id,enforcement,valid_from,valid_to,revision,supersedes_id,reason,created_by)
    values(p_employee_id,(v_item->>'weekday')::smallint,(v_item->>'localStart')::time,(v_item->>'localEnd')::time,
      nullif(v_item->>'roleId','')::uuid,nullif(v_item->>'locationId','')::uuid,upper(v_item->>'enforcement'),p_valid_from,p_valid_to,v_revision,v_supersedes_id,v_reason,v_actor);
    v_count:=v_count+1;
  end loop;
  insert into public.audit_log(actor_id,entity_type,entity_id,action,new_data)
  values(v_actor,'employee_weekly_work_pattern_v2',p_employee_id::text,'REPLACE',jsonb_build_object('validFrom',p_valid_from,'validTo',p_valid_to,'count',v_count,'reason',v_reason));
  return jsonb_build_object('employeeId',p_employee_id,'count',v_count,'revision',v_revision,'validFrom',p_valid_from,'validTo',p_valid_to);
end;
$function$;

CREATE OR REPLACE FUNCTION public.employee_weekly_work_patterns_replace_uat_v1(p_employee_id uuid, p_valid_from date, p_valid_to date, p_patterns jsonb, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not public.matrix_v2_can_manage_resource_uat_v1(null,null,p_employee_id)
    then raise exception 'RESOURCE_SCOPE_FORBIDDEN'; end if;
  if exists(
    select 1
    from jsonb_array_elements(coalesce(p_patterns,'[]'::jsonb)) pattern
    where (nullif(pattern->>'roleId','') is not null or nullif(pattern->>'locationId','') is not null)
      and not public.matrix_v2_can_manage_resource_uat_v1(
        nullif(pattern->>'roleId','')::uuid,
        nullif(pattern->>'locationId','')::uuid,
        p_employee_id
      )
  ) then raise exception 'WORK_PATTERN_RESOURCE_SCOPE_FORBIDDEN'; end if;
  perform authorization_private.enter_resource_scope_uat_v1();
  return public.employee_weekly_work_patterns_replace_before_phase1_uat_v1(
    p_employee_id,p_valid_from,p_valid_to,p_patterns,p_reason
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.employee_weekly_work_patterns_workspace_uat_v1(p_employee_id uuid, p_on_date date DEFAULT CURRENT_DATE)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not (public.can_manage_plans() or public.matrix_v2_can_manage_employee(p_employee_id)) then raise exception 'FORBIDDEN'; end if;
  return jsonb_build_object(
      'employeeId',p_employee_id,
      'onDate',p_on_date,
      'canEdit',public.can_manage_plans(),
      'patterns',coalesce((select jsonb_agg(jsonb_build_object(
        'id',p.id,'weekday',p.weekday,'localStart',p.local_start,'localEnd',p.local_end,
        'roleId',p.role_id,'locationId',p.location_id,'enforcement',p.enforcement,
        'validFrom',p.valid_from,'validTo',p.valid_to,'revision',p.revision,
        'reason',p.reason,'active',p.active
      ) order by p.weekday,p.local_start,p.created_at)
      from public.employee_weekly_work_patterns_v2 p
      where p.employee_id=p_employee_id and p.active
        and p.valid_from<=p_on_date and (p.valid_to is null or p.valid_to>=p_on_date)),'[]'::jsonb)
    );
end;
$function$;

CREATE OR REPLACE FUNCTION public.employer_cost_component_save_uat_v1(p_logical_id uuid, p_code text, p_name text, p_calculation_method text, p_value bigint, p_contract_type text, p_valid_from date, p_valid_to date, p_active boolean, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_actor uuid:=auth.uid();v_previous public.employer_cost_components_v2%rowtype;v_id uuid:=gen_random_uuid();v_logical uuid:=coalesce(p_logical_id,gen_random_uuid());v_revision integer:=1;
begin
  if not (public.has_app_role('OWNER') or public.has_app_role('ADMIN')) then raise exception 'FORBIDDEN'; end if;
  if p_calculation_method not in ('PERCENT_BASE','PER_HOUR','FIXED_PER_SHIFT') then raise exception 'INVALID_CALCULATION_METHOD'; end if;
  if p_value<0 or length(trim(coalesce(p_reason,'')))<5 then raise exception 'VALUE_AND_REASON_REQUIRED'; end if;
  select * into v_previous from public.employer_cost_components_v2 where logical_id=v_logical and active for update;
  if v_previous.id is not null then
    v_revision:=v_previous.revision+1;
    update public.employer_cost_components_v2 set active=false where id=v_previous.id;
  end if;
  insert into public.employer_cost_components_v2(id,logical_id,revision,supersedes_id,code,name,calculation_method,
    percent_basis_points,rate_minor_per_hour,amount_minor,contract_type,valid_from,valid_to,active,reason,created_by)
  values(v_id,v_logical,v_revision,v_previous.id,upper(trim(p_code)),trim(p_name),p_calculation_method,
    case when p_calculation_method='PERCENT_BASE' then p_value::integer end,
    case when p_calculation_method='PER_HOUR' then p_value end,
    case when p_calculation_method='FIXED_PER_SHIFT' then p_value end,
    nullif(trim(coalesce(p_contract_type,'')),''),p_valid_from,p_valid_to,p_active,trim(p_reason),v_actor);
  insert into public.audit_log(actor_id,entity_type,entity_id,action,new_data) values(v_actor,'employer_cost_component_v2',v_id::text,'VERSION_SAVED',jsonb_build_object('logicalId',v_logical,'revision',v_revision));
  return v_id;
end $function$;

CREATE OR REPLACE FUNCTION public.employer_cost_workspace_before_b4f101_uat_v1(p_month date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_month date:=date_trunc('month',p_month)::date;v_end date:=(date_trunc('month',p_month)+interval '1 month - 1 day')::date;
begin
  if not (public.has_app_role('OWNER') or public.has_app_role('ADMIN') or public.has_app_role('HR_FINANCE') or public.has_app_role('ROLE_MANAGER') or public.has_app_role('LOCATION_MANAGER')) then raise exception 'FORBIDDEN'; end if;
  return jsonb_build_object('month',v_month,'components',coalesce((select jsonb_agg(jsonb_build_object(
    'id',c.id,'logicalId',c.logical_id,'revision',c.revision,'code',c.code,'name',c.name,
    'calculationMethod',c.calculation_method,'percentBasisPoints',c.percent_basis_points,
    'rateMinorPerHour',c.rate_minor_per_hour,'amountMinor',c.amount_minor,'contractType',c.contract_type,
    'validFrom',c.valid_from,'validTo',c.valid_to,'active',c.active,'reason',c.reason
  ) order by c.code,c.revision desc) from public.employer_cost_components_v2 c
    where c.active and c.valid_from<=v_end and coalesce(c.valid_to,'infinity'::date)>=v_month),'[]'::jsonb));
end $function$;

CREATE OR REPLACE FUNCTION public.employer_cost_workspace_uat_v1(p_month date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_visibility text:=public.application_finance_visibility_current_uat_v1();
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  if not (public.has_app_role('OWNER') or public.has_app_role('ADMIN') or public.has_app_role('HR_FINANCE')
    or public.has_app_role('ROLE_MANAGER') or public.has_app_role('LOCATION_MANAGER')) then raise exception 'FORBIDDEN'; end if;
  if v_visibility<>'FULL' then
    return jsonb_build_object('month',date_trunc('month',p_month)::date,
      'components','[]'::jsonb,'financeVisibility',v_visibility);
  end if;
  return public.employer_cost_workspace_before_b4f101_uat_v1(p_month)
    ||jsonb_build_object('financeVisibility',v_visibility);
end;
$function$;

CREATE OR REPLACE FUNCTION public.generate_plan(p_month date, p_name text, p_scenario_code text DEFAULT 'BASE'::text, p_optimization_mode text DEFAULT 'BALANCED'::text, p_staffing_level text DEFAULT 'OPTIMAL'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_plan_id uuid;
  v_day date;
  v_last_day date;
  v_shift record;
  v_rule record;
  v_candidate record;
  v_shift_id uuid;
  v_shift_start timestamptz;
  v_shift_end timestamptz;
  v_location_code public.location_code;
  v_location_id uuid;
  v_shift_code text;
  v_required integer;
  v_assigned integer;
  v_minutes integer;
  v_multiplier numeric := (case upper(p_staffing_level)
    when 'MINIMAL' then 0.85 when 'FULL' then 1.10 else 1 end)
    * (case upper(p_scenario_code)
      when 'EVENT' then 1.05 when 'SAVINGS' then 0.90 else 1 end);
  v_cost numeric := 0;
  v_budget numeric;
  v_issue_count integer;
  v_assignment_count integer;
  v_version integer;
begin
  if not public.can_manage_plans() then raise exception 'FORBIDDEN'; end if;
  p_month := date_trunc('month', p_month)::date;
  v_last_day := (p_month + interval '1 month - 1 day')::date;
  select coalesce(max(version),0)+1 into v_version from public.plans where month=p_month;

  insert into public.plans(
    month,name,scenario_code,optimization_mode,staffing_level,status,version,created_by
  ) values (
    p_month,coalesce(nullif(trim(p_name),''),'Plan '||to_char(p_month,'YYYY-MM')),
    upper(p_scenario_code),upper(p_optimization_mode),upper(p_staffing_level),
    'GENERATING',v_version,auth.uid()
  ) returning id into v_plan_id;

  v_day := p_month;
  while v_day <= v_last_day loop
    for v_shift in
      select sd.*, l.code location_code,
        (v_day + sd.start_time) at time zone l.timezone starts_at_calc,
        ((v_day + case when sd.ends_next_day then 1 else 0 end) + sd.end_time)
          at time zone l.timezone ends_at_calc
      from public.shift_definitions sd
      join public.locations l on l.id=sd.location_id
      where sd.active and l.active and sd.day_of_week=extract(dow from v_day)::integer
        and not exists (
          select 1 from public.operational_events oe
          where oe.location_id=l.id and oe.status='CONFIRMED' and oe.event_type='CLOSURE'
            and (oe.starts_at at time zone l.timezone)::date=v_day
        )
      order by l.code, sd.start_time
    loop
      v_location_code := v_shift.location_code;
      v_location_id := v_shift.location_id;
      v_shift_code := v_shift.code;
      insert into public.shifts(
        plan_id,location_id,shift_date,shift_code,starts_at,ends_at,source_event_id
      ) values (
        v_plan_id,v_shift.location_id,v_day,v_shift.code,
        coalesce((
          select edc.custom_start from public.event_demand_changes edc
          join public.operational_events oe on oe.id=edc.event_id
          where oe.location_id=v_shift.location_id and oe.status='CONFIRMED'
            and (oe.starts_at at time zone 'Europe/Warsaw')::date=v_day
            and (edc.shift_code is null or edc.shift_code=v_shift.code)
            and edc.custom_start is not null limit 1
        ),v_shift.starts_at_calc),
        coalesce((
          select edc.custom_end from public.event_demand_changes edc
          join public.operational_events oe on oe.id=edc.event_id
          where oe.location_id=v_shift.location_id and oe.status='CONFIRMED'
            and (oe.starts_at at time zone 'Europe/Warsaw')::date=v_day
            and (edc.shift_code is null or edc.shift_code=v_shift.code)
            and edc.custom_end is not null limit 1
        ),v_shift.ends_at_calc),
        (select oe.id from public.operational_events oe
          where oe.location_id=v_shift.location_id and oe.status='CONFIRMED'
            and (oe.starts_at at time zone 'Europe/Warsaw')::date=v_day limit 1)
      ) returning id,starts_at,ends_at into v_shift_id,v_shift_start,v_shift_end;

      v_minutes := public.shift_minutes(v_shift_start,v_shift_end);

      -- Najpierw kompetencje twarde; osoba z kompetencją jednocześnie pokrywa podstawową rolę.
      for v_rule in
        select dr.role, dr.required_capability,
          greatest(0,dr.required_count)::integer required_count
        from public.demand_rules dr
        where dr.shift_definition_id in (
          select id from public.shift_definitions
          where location_id=v_location_id and code=v_shift_code
            and day_of_week=extract(dow from v_day)::integer
        ) and dr.scenario_code in ('BASE',upper(p_scenario_code))
          and dr.required_capability is not null
        order by dr.role
      loop
        v_required := v_rule.required_count;
        v_assigned := 0;
        for v_candidate in
          select e.*, el.home_location,
            coalesce((select sum(public.shift_minutes(s.starts_at,s.ends_at))
              from public.assignments a join public.shifts s on s.id=a.shift_id
              where a.employee_id=e.id and s.plan_id=v_plan_id),0) assigned_minutes
          from public.employees e
          join public.employee_locations el on el.employee_id=e.id
            and el.location_id=v_location_id
            and (el.standard_allowed or el.overtime_allowed)
          where e.active and e.primary_role=v_rule.role
            and exists (select 1 from public.employee_capabilities ec
              where ec.employee_id=e.id and ec.active and ec.capability=v_rule.required_capability
                and (ec.scope_role is null or ec.scope_role=v_rule.role)
                and (ec.scope_location is null or ec.scope_location=v_location_code))
            and not exists (select 1 from public.employee_availability av
              where av.employee_id=e.id and av.work_date=v_day and not av.available)
            and not exists (select 1 from public.assignments ax join public.shifts sx on sx.id=ax.shift_id
              where ax.employee_id=e.id and sx.plan_id=v_plan_id
                and tstzrange(sx.starts_at,sx.ends_at,'[)') && tstzrange(v_shift_start,v_shift_end,'[)'))
            and coalesce((select sum(public.shift_minutes(s.starts_at,s.ends_at))
              from public.assignments a join public.shifts s on s.id=a.shift_id
              where a.employee_id=e.id and s.plan_id=v_plan_id),0)+v_minutes
              <= coalesce(e.max_monthly_minutes,round(e.monthly_nominal_minutes*1.25))
            and coalesce((select sum(public.shift_minutes(s.starts_at,s.ends_at))
              from public.assignments a join public.shifts s on s.id=a.shift_id
              where a.employee_id=e.id and s.plan_id=v_plan_id
                and date_trunc('week',s.shift_date::timestamp)=date_trunc('week',v_day::timestamp)),0)+v_minutes
              <= e.max_weekly_minutes
            and not exists (select 1 from public.assignments ar join public.shifts sr on sr.id=ar.shift_id
              where ar.employee_id=e.id and sr.plan_id=v_plan_id
                and tstzrange(sr.starts_at-interval '11 hours',sr.ends_at+interval '11 hours','[)')
                  && tstzrange(v_shift_start,v_shift_end,'[)'))
          order by
            case when upper(p_optimization_mode)='MIN_COST' then e.hourly_rate else 0 end,
            coalesce((select sum(public.shift_minutes(s.starts_at,s.ends_at))
              from public.assignments a join public.shifts s on s.id=a.shift_id
              where a.employee_id=e.id and s.plan_id=v_plan_id),0)::numeric
              / greatest(e.monthly_nominal_minutes,1),
            el.home_location desc, e.employee_no
          limit v_required
        loop
          insert into public.assignments(
            shift_id,employee_id,assigned_role,assigned_capability,cost,explanation
          ) values (
            v_shift_id,v_candidate.id,v_rule.role,v_rule.required_capability,
            round(v_candidate.hourly_rate*v_minutes/60,2),
            jsonb_build_object('engine','ALPHA_5','reason','HARD_CAPABILITY','score_minutes',v_candidate.assigned_minutes)
          );
          v_assigned := v_assigned+1;
        end loop;
        if v_assigned < v_required then
          insert into public.plan_issues(plan_id,shift_id,issue_type,severity,role,capability,required_count,assigned_count,message)
          values(v_plan_id,v_shift_id,'CAPABILITY_MISSING','CRITICAL',v_rule.role,v_rule.required_capability,
            v_required,v_assigned,'Brak wymaganej kompetencji '||v_rule.required_capability);
        end if;
      end loop;

      -- Następnie uzupełnienie liczebności każdej roli.
      for v_rule in
        select dr.role,
          greatest(0,ceil((dr.required_count + coalesce((
            select sum(edc.additional_count)
            from public.event_demand_changes edc
            join public.operational_events oe on oe.id=edc.event_id
            where oe.location_id=v_location_id and oe.status='CONFIRMED'
              and (oe.starts_at at time zone 'Europe/Warsaw')::date=v_day
              and edc.role=dr.role
              and (edc.shift_code is null or edc.shift_code=v_shift_code)
              and edc.required_capability is null
          ),0))*v_multiplier))::integer required_count
        from public.demand_rules dr
        where dr.shift_definition_id in (
          select id from public.shift_definitions
          where location_id=v_location_id and code=v_shift_code
            and day_of_week=extract(dow from v_day)::integer
        ) and dr.scenario_code in ('BASE',upper(p_scenario_code))
          and dr.required_capability is null
        order by dr.role
      loop
        select count(*) into v_assigned from public.assignments
          where shift_id=v_shift_id and assigned_role=v_rule.role;
        v_required := greatest(0,v_rule.required_count-v_assigned);
        for v_candidate in
          select e.*, el.home_location,
            coalesce((select sum(public.shift_minutes(s.starts_at,s.ends_at))
              from public.assignments a join public.shifts s on s.id=a.shift_id
              where a.employee_id=e.id and s.plan_id=v_plan_id),0) assigned_minutes
          from public.employees e
          join public.employee_locations el on el.employee_id=e.id
            and el.location_id=v_location_id
            and (el.standard_allowed or el.overtime_allowed)
          where e.active and e.primary_role=v_rule.role
            and not exists (select 1 from public.employee_availability av
              where av.employee_id=e.id and av.work_date=v_day and not av.available)
            and not exists (select 1 from public.assignments ax join public.shifts sx on sx.id=ax.shift_id
              where ax.employee_id=e.id and sx.plan_id=v_plan_id
                and tstzrange(sx.starts_at,sx.ends_at,'[)') && tstzrange(v_shift_start,v_shift_end,'[)'))
            and coalesce((select sum(public.shift_minutes(s.starts_at,s.ends_at))
              from public.assignments a join public.shifts s on s.id=a.shift_id
              where a.employee_id=e.id and s.plan_id=v_plan_id),0)+v_minutes
              <= coalesce(e.max_monthly_minutes,round(e.monthly_nominal_minutes*1.25))
            and coalesce((select sum(public.shift_minutes(s.starts_at,s.ends_at))
              from public.assignments a join public.shifts s on s.id=a.shift_id
              where a.employee_id=e.id and s.plan_id=v_plan_id
                and date_trunc('week',s.shift_date::timestamp)=date_trunc('week',v_day::timestamp)),0)+v_minutes
              <= e.max_weekly_minutes
            and not exists (select 1 from public.assignments ar join public.shifts sr on sr.id=ar.shift_id
              where ar.employee_id=e.id and sr.plan_id=v_plan_id
                and tstzrange(sr.starts_at-interval '11 hours',sr.ends_at+interval '11 hours','[)')
                  && tstzrange(v_shift_start,v_shift_end,'[)'))
          order by
            case when upper(p_optimization_mode)='MIN_COST' then e.hourly_rate else 0 end,
            case when e.preferred_shift=v_shift_code then 0 else 1 end,
            coalesce((select sum(public.shift_minutes(s.starts_at,s.ends_at))
              from public.assignments a join public.shifts s on s.id=a.shift_id
              where a.employee_id=e.id and s.plan_id=v_plan_id),0)::numeric
              / greatest(e.monthly_nominal_minutes,1),
            el.home_location desc, e.employee_no
          limit v_required
        loop
          insert into public.assignments(shift_id,employee_id,assigned_role,cost,explanation)
          values(v_shift_id,v_candidate.id,v_rule.role,
            round(v_candidate.hourly_rate*v_minutes/60,2),
            jsonb_build_object('engine','ALPHA_5','reason','BALANCED_LOAD','score_minutes',v_candidate.assigned_minutes));
          v_assigned := v_assigned+1;
        end loop;
        if v_assigned < v_rule.required_count then
          insert into public.plan_issues(plan_id,shift_id,issue_type,severity,role,required_count,assigned_count,message)
          values(v_plan_id,v_shift_id,'SHORTAGE',
            case when v_assigned=0 then 'CRITICAL' else 'WARNING' end,
            v_rule.role,v_rule.required_count,v_assigned,
            'Brak '||(v_rule.required_count-v_assigned)||' os. dla roli '||v_rule.role::text);
        end if;
      end loop;
    end loop;
    v_day := v_day+1;
  end loop;

  select coalesce(sum(cost),0),count(*) into v_cost,v_assignment_count
  from public.assignments a join public.shifts s on s.id=a.shift_id where s.plan_id=v_plan_id;
  select amount into v_budget from public.monthly_budgets where month=p_month;
  if v_budget is not null and v_cost>v_budget then
    insert into public.plan_issues(plan_id,issue_type,severity,message)
    values(v_plan_id,'BUDGET_EXCEEDED','CRITICAL',
      'Koszt planu '||round(v_cost,2)||' przekracza budżet '||round(v_budget,2));
  end if;
  select count(*) into v_issue_count from public.plan_issues where plan_id=v_plan_id;

  update public.plans set status='READY',total_cost=v_cost,generated_at=now(),
    score=greatest(0,100-v_issue_count*2)
  where id=v_plan_id;

  insert into public.audit_log(actor_id,entity_type,entity_id,action,new_data)
  values(auth.uid(),'plan',v_plan_id::text,'GENERATE',
    jsonb_build_object('assignments',v_assignment_count,'issues',v_issue_count,'cost',v_cost));
  return jsonb_build_object(
    'plan_id',v_plan_id,'status','READY','assignments',v_assignment_count,
    'issues',v_issue_count,'total_cost',v_cost
  );
exception when others then
  if v_plan_id is not null then
    update public.plans set status='FAILED' where id=v_plan_id;
  end if;
  raise;
end;
$function$;

CREATE OR REPLACE FUNCTION public.generate_role_plan(p_month date, p_role_id uuid, p_name text, p_scenario text DEFAULT 'BASE'::text, p_mode text DEFAULT 'BALANCED'::text, p_staffing text DEFAULT 'OPTIMAL'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare generated jsonb; v_plan_id uuid; section_id uuid; role_code text; cnt integer; begin
 if not public.can_manage_plans() then raise exception 'FORBIDDEN'; end if;
 select code into role_code from matrix_roles where id=p_role_id and active;
 if role_code is null then raise exception 'ROLE_NOT_FOUND'; end if;
 generated:=public.generate_plan(p_month,'Źródło roli '||role_code||' • '||coalesce(p_name,''),p_scenario,p_mode,p_staffing);
 v_plan_id:=(generated->>'plan_id')::uuid;
 section_id:=public.create_role_plan_section(p_month,p_role_id,p_name,p_scenario,p_mode,p_staffing);
 update role_plan_sections set legacy_plan_id=v_plan_id,status='READY',updated_at=now() where id=section_id;
 insert into role_plan_assignments(role_plan_section_id,assignment_id)
 select section_id,a.id from assignments a join shifts s on s.id=a.shift_id
 where s.plan_id=v_plan_id and a.assigned_role::text=role_code;
 get diagnostics cnt=row_count;
 -- Kluczowa izolacja: źródło roli nigdy nie trafia do Centrum dowodzenia.
 update plans set status='ARCHIVED' where id=v_plan_id;
 return jsonb_build_object('sectionId',section_id,'assignments',cnt,
   'issues',(select count(*) from plan_issues pi where pi.plan_id=v_plan_id and pi.role::text=role_code));
exception when others then
 if v_plan_id is not null then update plans set status='FAILED' where id=v_plan_id; end if;
 raise;
end $function$;

CREATE OR REPLACE FUNCTION public.has_app_role(required_role public.app_role)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (
    select 1 from public.user_permissions
    where auth_user_id = auth.uid() and app_role = required_role
  );
$function$;

CREATE OR REPLACE FUNCTION public.kadromierz_export(p_month date)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
with chosen as (select id from plans where month=date_trunc('month',p_month)::date and status='PUBLISHED' order by version desc limit 1)
select coalesce(jsonb_agg(jsonb_build_object('numer_pracownika',e.employee_no,'pracownik',e.first_name||' '||e.last_name,'data',s.shift_date,'lokal',l.code,'zmiana',s.shift_code,'od',s.starts_at,'do',s.ends_at,'rola',a.assigned_role,'funkcja',a.assigned_capability) order by s.shift_date,e.employee_no),'[]'::jsonb)
from assignments a join shifts s on s.id=a.shift_id join chosen c on c.id=s.plan_id join employees e on e.id=a.employee_id join locations l on l.id=s.location_id where public.can_manage_plans();
$function$;

CREATE OR REPLACE FUNCTION public.kadromierz_import_preferences(p_file_name text, p_rows jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare row jsonb; e_id uuid; imported integer:=0; skipped integer:=0; run_id uuid; from_day date; to_day date; typ text; begin
 if not public.can_manage_plans() then raise exception 'FORBIDDEN'; end if;
 insert into integration_runs(integration,direction,entity_type,status,file_name,executed_by) values('KADROMIERZ','IMPORT','DOSTEPNOSC_I_PREFERENCJE','RUNNING',p_file_name,auth.uid()) returning id into run_id;
 for row in select value from jsonb_array_elements(coalesce(p_rows,'[]'::jsonb)) loop
   select id into e_id from employees where employee_no=coalesce(row->>'employee_no',row->>'numer_pracownika');
   from_day:=coalesce(row->>'date',row->>'data')::date; to_day:=coalesce(row->>'date_to',row->>'data_do',row->>'date',row->>'data')::date; typ:=upper(coalesce(nullif(row->>'type',''),'LEAVE'));
   if e_id is null or from_day is null then skipped:=skipped+1; continue; end if;
   insert into employee_preferences(employee_id,valid_from,valid_to,preference_type,preference_value,source,status)
   values(e_id,from_day,to_day,typ,jsonb_build_object('note',coalesce(row->>'note',row->>'uwagi','')),'KADROMIERZ','ACTIVE');
   if typ in ('UNAVAILABLE','LEAVE','SICKNESS') then
     insert into employee_availability(employee_id,work_date,available,note,source,updated_by,updated_at)
     select e_id,g::date,false,coalesce(row->>'note',row->>'uwagi',''),'KADROMIERZ',auth.uid(),now() from generate_series(from_day,to_day,interval '1 day') g
     on conflict(employee_id,work_date) do update set available=false,note=excluded.note,source='KADROMIERZ',updated_by=auth.uid(),updated_at=now();
   end if;
   imported:=imported+1;
 end loop;
 update integration_runs set status=case when skipped=0 then 'SUCCESS' else 'PARTIAL' end,summary=jsonb_build_object('imported',imported,'skipped',skipped,'unavailabilityApplied',true) where id=run_id;
 return jsonb_build_object('imported',imported,'skipped',skipped,'runId',run_id);
end $function$;

CREATE OR REPLACE FUNCTION public.log_availability_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if tg_op='INSERT' or old.available is distinct from new.available or old.note is distinct from new.note then
    insert into employee_availability_history(employee_id,work_date,old_available,new_available,source,note,changed_by)
    values(new.employee_id,new.work_date,case when tg_op='INSERT' then null else old.available end,new.available,new.source,new.note,coalesce(new.updated_by,auth.uid()));
  end if;
  return new;
end $function$;

CREATE OR REPLACE FUNCTION public.manager_standby_month_uat_v2(p_month date, p_scope_role_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  if not public.can_manage_plans() then raise exception 'FORBIDDEN'; end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'id',standby.id,
      'date',standby.standby_date,
      'tier',standby.tier,
      'status',standby.status,
      'roleId',standby.role_id,
      'roleName',role.name,
      'employeeId',standby.employee_id,
      'employeeNo',employee.employee_no,
      'employeeName',concat_ws(' ',employee.first_name,employee.last_name),
      'sourceType',case when standby.source_role_schedule_id is null then 'COMPANY' else 'ROLE' end,
      'activatedShiftId',standby.activated_shift_id
    ) order by standby.standby_date,role.name,standby.tier)
    from public.published_standby_assignments_v2 standby
    join public.matrix_roles_v2 role on role.id=standby.role_id
    join public.employees employee on employee.id=standby.employee_id
    where standby.month=date_trunc('month',p_month)::date
      and (p_scope_role_id is null or standby.role_id=p_scope_role_id)
      and standby.status in ('PLANNED','ACTIVATED','DECLINED')
  ),'[]'::jsonb);
end;
$function$;

CREATE OR REPLACE FUNCTION public.manager_standby_month_uat_v3(p_month date, p_scope_role_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  if not public.can_manage_plans() then raise exception 'FORBIDDEN'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object(
    'id',standby.id,'date',standby.standby_date,'tier',standby.tier,'status',standby.status,
    'roleId',standby.role_id,'roleName',coalesce(standby.standby_group_name,role.name),
    'groupCode',standby.standby_group_code,'groupName',standby.standby_group_name,
    'eligibleRoleIds',to_jsonb(coalesce(standby.eligible_role_ids,array[standby.role_id])),
    'eligibleRoleNames',coalesce((select jsonb_agg(group_role.name order by group_role.sort_order,group_role.name)
      from public.matrix_roles_v2 group_role where group_role.id=any(coalesce(standby.eligible_role_ids,array[standby.role_id]))),'[]'::jsonb),
    'employeeId',standby.employee_id,'employeeNo',employee.employee_no,
    'employeeName',concat_ws(' ',employee.first_name,employee.last_name),
    'sourceType',case when standby.source_role_schedule_id is null then 'COMPANY' else 'ROLE' end,
    'activatedShiftId',standby.activated_shift_id
  ) order by standby.standby_date,coalesce(standby.standby_group_name,role.name),standby.tier)
  from public.published_standby_assignments_v2 standby
  join public.matrix_roles_v2 role on role.id=standby.role_id
  join public.employees employee on employee.id=standby.employee_id
  where standby.month=date_trunc('month',p_month)::date and standby.status in ('PLANNED','ACTIVATED','DECLINED')
    and (p_scope_role_id is null or standby.role_id=p_scope_role_id
      or p_scope_role_id=any(coalesce(standby.eligible_role_ids,'{}'::uuid[]))
      or standby.standby_category_code=(select category.code from public.matrix_roles_v2 scope_role
        join public.matrix_role_categories_v2 category on category.id=scope_role.category_id where scope_role.id=p_scope_role_id)
    )),'[]'::jsonb);
end;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_create_draft(p_name text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare a matrix_versions; n uuid; v integer; begin
 if not(public.has_app_role('OWNER') or public.has_app_role('ADMIN')) then raise exception 'FORBIDDEN'; end if;
 select * into a from matrix_versions where status='ACTIVE' order by version desc limit 1;
 if exists(select 1 from matrix_versions where status='DRAFT') then return (select id from matrix_versions where status='DRAFT' order by version desc limit 1); end if;
 select coalesce(max(version),0)+1 into v from matrix_versions;
 insert into matrix_versions(version,name,status,effective_from,settings,created_by) values(v,coalesce(nullif(trim(p_name),''),'Matrix v'||v),'DRAFT',a.effective_from,a.settings,auth.uid()) returning id into n;
  insert into matrix_roles(matrix_version_id,code,name,color,sort_order,active) select n,code,name,color,sort_order,active from matrix_roles where matrix_version_id=a.id;
  insert into matrix_locations(matrix_version_id,code,name,active) select n,code,name,active from matrix_locations where matrix_version_id=a.id;
  insert into matrix_functions(matrix_version_id,code,name,description,active) select n,code,name,description,active from matrix_functions where matrix_version_id=a.id;
  insert into matrix_shift_templates(matrix_version_id,location_id,code,name,starts_at,ends_at,day_mask,sort_order,active)
  select n,nl.id,s.code,s.name,s.starts_at,s.ends_at,s.day_mask,s.sort_order,s.active
  from matrix_shift_templates s join matrix_locations ol on ol.id=s.location_id
  join matrix_locations nl on nl.matrix_version_id=n and nl.code=ol.code where s.matrix_version_id=a.id;
  insert into matrix_role_functions(role_id,function_id,assignment_mode)
  select nr.id,nf.id,rf.assignment_mode from matrix_role_functions rf
  join matrix_roles orr on orr.id=rf.role_id join matrix_functions ofn on ofn.id=rf.function_id
  join matrix_roles nr on nr.matrix_version_id=n and nr.code=orr.code
  join matrix_functions nf on nf.matrix_version_id=n and nf.code=ofn.code;
  insert into matrix_demand(shift_template_id,role_id,function_id,scenario_code,required_count)
  select ns.id,nr.id,nf.id,md.scenario_code,md.required_count from matrix_demand md
  join matrix_shift_templates os on os.id=md.shift_template_id join matrix_locations ol on ol.id=os.location_id
  join matrix_roles orr on orr.id=md.role_id left join matrix_functions ofn on ofn.id=md.function_id
  join matrix_locations nl on nl.matrix_version_id=n and nl.code=ol.code
  join matrix_shift_templates ns on ns.matrix_version_id=n and ns.location_id=nl.id and ns.code=os.code
  join matrix_roles nr on nr.matrix_version_id=n and nr.code=orr.code
  left join matrix_functions nf on nf.matrix_version_id=n and nf.code=ofn.code;
 return n;
end $function$;

CREATE OR REPLACE FUNCTION public.matrix_import_apply(p_file_name text, p_payload jsonb, p_requested_permissions jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare d uuid; row jsonb; loc uuid; sh uuid; ro uuid; imported_roles int:=0; imported_shifts int:=0; imported_demand int:=0; run_id uuid; begin
 if not(public.has_app_role('OWNER') or public.has_app_role('ADMIN')) then raise exception 'FORBIDDEN'; end if;
 d:=matrix_create_draft('Import z pliku '||p_file_name);
 for row in select value from jsonb_array_elements(coalesce(p_payload->'locations','[]'::jsonb)) loop
   insert into matrix_locations(matrix_version_id,code,name,active)
   values(d,upper(trim(row->>'KOD')),trim(row->>'NAZWA'),upper(coalesce(row->>'AKTYWNA','TAK'))<>'NIE')
   on conflict(matrix_version_id,code) do update set name=excluded.name,active=excluded.active;
 end loop;
 for row in select value from jsonb_array_elements(coalesce(p_payload->'roles','[]'::jsonb)) loop
   insert into matrix_roles(matrix_version_id,code,name,color,active)
   values(d,upper(trim(row->>'KOD')),trim(row->>'NAZWA'),coalesce(nullif(row->>'KOLOR',''),'#7257d8'),upper(coalesce(row->>'AKTYWNA','TAK'))<>'NIE')
   on conflict(matrix_version_id,code) do update set name=excluded.name,color=excluded.color,active=excluded.active;
   imported_roles:=imported_roles+1;
 end loop;
 for row in select value from jsonb_array_elements(coalesce(p_payload->'functions','[]'::jsonb)) loop
   insert into matrix_functions(matrix_version_id,code,name,description,active)
   values(d,upper(trim(row->>'KOD')),trim(row->>'NAZWA'),nullif(row->>'OPIS',''),upper(coalesce(row->>'AKTYWNA','TAK'))<>'NIE')
   on conflict(matrix_version_id,code) do update set name=excluded.name,description=excluded.description,active=excluded.active;
 end loop;
 for row in select value from jsonb_array_elements(coalesce(p_payload->'scenarios','[]'::jsonb)) loop
   insert into matrix_scenarios(matrix_version_id,code,name,active)
   values(d,upper(trim(row->>'KOD')),trim(row->>'NAZWA'),upper(coalesce(row->>'AKTYWNY','TAK'))<>'NIE')
   on conflict(matrix_version_id,code) do update set name=excluded.name,active=excluded.active;
 end loop;
 for row in select value from jsonb_array_elements(coalesce(p_payload->'shifts','[]'::jsonb)) loop
   select id into loc from matrix_locations where matrix_version_id=d and code=upper(trim(row->>'LOKAL'));
   if loc is null then raise exception 'IMPORT_UNKNOWN_LOCATION: %',row->>'LOKAL'; end if;
   insert into matrix_shift_templates(matrix_version_id,location_id,code,name,starts_at,ends_at,day_mask,active)
   values(d,loc,upper(trim(row->>'KOD')),trim(row->>'NAZWA'),(row->>'OD')::time,(row->>'DO')::time,string_to_array(row->>'DNI',',')::smallint[],upper(coalesce(row->>'AKTYWNA','TAK'))<>'NIE')
   on conflict(matrix_version_id,location_id,code) do update set name=excluded.name,starts_at=excluded.starts_at,ends_at=excluded.ends_at,day_mask=excluded.day_mask,active=excluded.active;
   imported_shifts:=imported_shifts+1;
 end loop;
 for row in select value from jsonb_array_elements(coalesce(p_payload->'demand','[]'::jsonb)) loop
   select ml.id into loc from matrix_locations ml where ml.matrix_version_id=d and ml.code=upper(trim(row->>'LOKAL'));
   select ms.id into sh from matrix_shift_templates ms where ms.matrix_version_id=d and ms.location_id=loc and ms.code=upper(trim(row->>'ZMIANA'));
   select mr.id into ro from matrix_roles mr where mr.matrix_version_id=d and mr.code=upper(trim(row->>'ROLA'));
   if sh is null or ro is null then raise exception 'IMPORT_UNKNOWN_SHIFT_OR_ROLE'; end if;
   insert into matrix_demand(shift_template_id,role_id,scenario_code,required_count)
   values(sh,ro,upper(coalesce(nullif(row->>'SCENARIUSZ',''),'BASE')),greatest((row->>'WYMAGANE')::integer,0))
   on conflict(shift_template_id,role_id,function_id,scenario_code) do update set required_count=excluded.required_count;
   imported_demand:=imported_demand+1;
 end loop;
 insert into matrix_import_runs(file_name,matrix_version_id,status,summary,requested_permissions,created_by)
 values(p_file_name,d,'IMPORTED',jsonb_build_object('roles',imported_roles,'shifts',imported_shifts,'demand',imported_demand),coalesce(p_requested_permissions,'[]'::jsonb),auth.uid()) returning id into run_id;
 insert into audit_log(actor_id,entity_type,entity_id,action,new_data) values(auth.uid(),'matrix_import',run_id::text,'IMPORT',jsonb_build_object('permissionsApplied',false));
 return jsonb_build_object('draftId',d,'roles',imported_roles,'shifts',imported_shifts,'demand',imported_demand,'permissionsApplied',false);
end $function$;

CREATE OR REPLACE FUNCTION public.matrix_publish_draft(p_effective_from date)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ declare d matrix_versions; begin
 if not(public.has_app_role('OWNER') or public.has_app_role('ADMIN')) then raise exception 'FORBIDDEN'; end if;
 select * into d from matrix_versions where status='DRAFT' order by version desc limit 1 for update;
 if d.id is null then raise exception 'NO_DRAFT'; end if;
 update matrix_versions set status='ARCHIVED',effective_to=p_effective_from-1 where status='ACTIVE';
 update matrix_versions set status='ACTIVE',effective_from=p_effective_from,activated_at=now() where id=d.id;
 return d.id;
end $function$;

CREATE OR REPLACE FUNCTION public.matrix_register_import(p_file_name text, p_summary jsonb, p_requested_permissions jsonb DEFAULT '[]'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare out_id uuid; draft_id uuid; begin
 if not(public.has_app_role('OWNER') or public.has_app_role('ADMIN')) then raise exception 'FORBIDDEN'; end if;
 draft_id:=matrix_create_draft('Import z pliku '||p_file_name);
 insert into matrix_import_runs(file_name,matrix_version_id,status,summary,requested_permissions,created_by)
 values(p_file_name,draft_id,'VALIDATED',coalesce(p_summary,'{}'::jsonb),coalesce(p_requested_permissions,'[]'::jsonb),auth.uid()) returning id into out_id;
 return out_id;
end $function$;

CREATE OR REPLACE FUNCTION public.matrix_save_demand(p_shift_id uuid, p_role_id uuid, p_required integer, p_scenario text DEFAULT 'BASE'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare d uuid; out_id uuid; begin
 if not(public.has_app_role('OWNER') or public.has_app_role('ADMIN')) then raise exception 'FORBIDDEN'; end if;
 select id into d from matrix_versions where status='DRAFT' order by version desc limit 1;
 if d is null then raise exception 'NO_DRAFT'; end if;
 if not exists(select 1 from matrix_shift_templates where id=p_shift_id and matrix_version_id=d) then raise exception 'SHIFT_NOT_IN_DRAFT'; end if;
 if not exists(select 1 from matrix_roles where id=p_role_id and matrix_version_id=d) then raise exception 'ROLE_NOT_IN_DRAFT'; end if;
 update matrix_demand set required_count=greatest(p_required,0)
 where shift_template_id=p_shift_id and role_id=p_role_id and function_id is null and scenario_code=p_scenario
 returning id into out_id;
 if out_id is null then
   insert into matrix_demand(shift_template_id,role_id,scenario_code,required_count)
   values(p_shift_id,p_role_id,p_scenario,greatest(p_required,0)) returning id into out_id;
 end if;
 return out_id;
end $function$;

CREATE OR REPLACE FUNCTION public.matrix_save_item(p_kind text, p_id uuid, p_data jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare d uuid; out_id uuid; begin
 if not(public.has_app_role('OWNER') or public.has_app_role('ADMIN')) then raise exception 'FORBIDDEN'; end if;
 d:=matrix_create_draft(null);
 if p_kind='ROLE' then
   if p_id is null then insert into matrix_roles(matrix_version_id,code,name,color,sort_order) values(d,upper(p_data->>'code'),p_data->>'name',coalesce(p_data->>'color','#7257d8'),coalesce((p_data->>'sortOrder')::integer,99)) returning id into out_id;
   else update matrix_roles set code=upper(coalesce(nullif(p_data->>'code',''),code)),name=coalesce(nullif(p_data->>'name',''),name),color=coalesce(nullif(p_data->>'color',''),color),active=coalesce((p_data->>'active')::boolean,active) where id=p_id and matrix_version_id=d returning id into out_id; end if;
 elsif p_kind='FUNCTION' then
   if p_id is null then insert into matrix_functions(matrix_version_id,code,name,description) values(d,upper(p_data->>'code'),p_data->>'name',p_data->>'description') returning id into out_id;
   else update matrix_functions set code=upper(coalesce(nullif(p_data->>'code',''),code)),name=coalesce(nullif(p_data->>'name',''),name),description=coalesce(p_data->>'description',description),active=coalesce((p_data->>'active')::boolean,active) where id=p_id and matrix_version_id=d returning id into out_id; end if;
 elsif p_kind='LOCATION' then
   if p_id is null then insert into matrix_locations(matrix_version_id,code,name) values(d,upper(p_data->>'code'),p_data->>'name') returning id into out_id;
   else update matrix_locations set code=upper(coalesce(nullif(p_data->>'code',''),code)),name=coalesce(nullif(p_data->>'name',''),name),active=coalesce((p_data->>'active')::boolean,active) where id=p_id and matrix_version_id=d returning id into out_id; end if;
 else raise exception 'INVALID_KIND'; end if;
 if out_id is null then raise exception 'ITEM_NOT_IN_DRAFT'; end if; return out_id;
end $function$;

CREATE OR REPLACE FUNCTION public.matrix_save_shift(p_id uuid, p_data jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare d uuid; out_id uuid; loc uuid; begin
 if not(public.has_app_role('OWNER') or public.has_app_role('ADMIN')) then raise exception 'FORBIDDEN'; end if;
 d:=matrix_create_draft(null);
 loc:=(p_data->>'locationId')::uuid;
 if not exists(select 1 from matrix_locations where id=loc and matrix_version_id=d) then raise exception 'LOCATION_NOT_IN_DRAFT'; end if;
 if p_id is null then
   insert into matrix_shift_templates(matrix_version_id,location_id,code,name,starts_at,ends_at,day_mask,sort_order,active)
   values(d,loc,upper(p_data->>'code'),p_data->>'name',(p_data->>'startsAt')::time,(p_data->>'endsAt')::time,
     string_to_array(p_data->>'days',',')::smallint[],coalesce((p_data->>'sortOrder')::integer,99),true) returning id into out_id;
 else
   update matrix_shift_templates set location_id=loc,code=upper(coalesce(nullif(p_data->>'code',''),code)),
     name=coalesce(nullif(p_data->>'name',''),name),starts_at=coalesce((p_data->>'startsAt')::time,starts_at),
     ends_at=coalesce((p_data->>'endsAt')::time,ends_at),day_mask=coalesce(string_to_array(nullif(p_data->>'days',''),',')::smallint[],day_mask),
     active=coalesce((p_data->>'active')::boolean,active)
   where id=p_id and matrix_version_id=d returning id into out_id;
 end if;
 if out_id is null then raise exception 'ITEM_NOT_IN_DRAFT'; end if;
 return out_id;
end $function$;

CREATE OR REPLACE FUNCTION public.matrix_scope_grant_save_v2(p_id uuid, p_auth_user_id uuid, p_app_role public.app_role, p_role_id uuid DEFAULT NULL::uuid, p_location_id uuid DEFAULT NULL::uuid, p_duty_id uuid DEFAULT NULL::uuid, p_active boolean DEFAULT true)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_id uuid;
  v_role_logical uuid;
  v_location_logical uuid;
  v_duty_logical uuid;
begin
  if not (public.has_app_role('OWNER') or public.has_app_role('ADMIN')) then
    raise exception 'FORBIDDEN';
  end if;
  if p_auth_user_id is null then raise exception 'AUTH_USER_REQUIRED'; end if;
  if p_role_id is not null then
    select r.logical_id into v_role_logical from public.matrix_roles_v2 r where r.id=p_role_id;
    if v_role_logical is null then raise exception 'ROLE_NOT_FOUND'; end if;
  end if;
  if p_location_id is not null then
    select l.logical_id into v_location_logical from public.matrix_locations_v2 l where l.id=p_location_id;
    if v_location_logical is null then raise exception 'LOCATION_NOT_FOUND'; end if;
  end if;
  if p_duty_id is not null then
    select d.logical_id into v_duty_logical from public.matrix_duties_v2 d where d.id=p_duty_id;
    if v_duty_logical is null then raise exception 'DUTY_NOT_FOUND'; end if;
  end if;

  if p_id is null then
    insert into public.matrix_scope_grants_v2(
      auth_user_id,app_role,role_logical_id,location_logical_id,duty_logical_id,
      active,created_by
    ) values(
      p_auth_user_id,p_app_role,v_role_logical,v_location_logical,v_duty_logical,
      coalesce(p_active,true),auth.uid()
    ) on conflict(auth_user_id,app_role,role_logical_id,location_logical_id,duty_logical_id)
      do update set active=excluded.active,updated_at=now()
    returning id into v_id;
  else
    update public.matrix_scope_grants_v2 set auth_user_id=p_auth_user_id,
      app_role=p_app_role,role_logical_id=v_role_logical,
      location_logical_id=v_location_logical,duty_logical_id=v_duty_logical,
      active=coalesce(p_active,true),updated_at=now()
    where id=p_id returning id into v_id;
    if v_id is null then raise exception 'SCOPE_GRANT_NOT_FOUND'; end if;
  end if;

  insert into public.audit_log(actor_id,entity_type,entity_id,action,new_data)
  values(auth.uid(),'matrix_scope_grant_v2',v_id::text,'UPSERT',jsonb_build_object(
    'authUserId',p_auth_user_id,'appRole',p_app_role,
    'roleLogicalId',v_role_logical,'locationLogicalId',v_location_logical,
    'dutyLogicalId',v_duty_logical,'active',coalesce(p_active,true)));
  return v_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_shift_color_preserve_on_clone_uat_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_source_color text;
begin
  select source_row.color into v_source_color
  from public.matrix_shift_templates_v2 source_row
  where source_row.logical_id=new.logical_id
  order by source_row.updated_at desc,source_row.created_at desc,source_row.id desc
  limit 1;
  if v_source_color is not null then new.color:=v_source_color; end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_admin_save(p_kind text, p_id uuid, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_result jsonb;v_tiers integer;
begin
  if upper(trim(p_kind))='MATRIX_SETTINGS' then
    if coalesce(p_data->>'standbyTiersPerRoleDay','') !~ '^[0-2]$' then
      raise exception 'INVALID_STANDBY_TIERS';
    end if;
    v_tiers:=(p_data->>'standbyTiersPerRoleDay')::integer;
  end if;
  v_result:=public.matrix_v2_admin_save_before_standby_setting(p_kind,p_id,p_data);
  if upper(trim(p_kind))='MATRIX_SETTINGS' then
    update public.matrix_versions
    set settings=jsonb_set(coalesce(settings,'{}'::jsonb),'{standbyTiersPerRoleDay}',to_jsonb(v_tiers),true)
    where id=(v_result->>'id')::uuid;
  end if;
  return v_result;
end;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_admin_save_alpha16(p_kind text, p_id uuid, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_result jsonb;
  v_color text;
begin
  v_result:=public.matrix_v2_admin_save_before_b4f118(p_kind,p_id,p_data);
  if upper(trim(p_kind))='SHIFT' and coalesce(trim(p_data->>'color'),'')<>'' then
    v_color:=upper(trim(p_data->>'color'));
    if v_color !~ '^#[0-9A-F]{6}$' then raise exception 'INVALID_SHIFT_COLOR'; end if;
    update public.matrix_shift_templates_v2
    set color=v_color,updated_at=now()
    where id=(v_result->>'id')::uuid;
  end if;
  return v_result;
end;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_admin_save_before_b4f118(p_kind text, p_id uuid, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_mode text:=upper(coalesce(nullif(trim(p_data->>'assignmentMode'),''),'OPTIONAL'));
  v_minimum_text text:=coalesce(nullif(trim(p_data->>'minimumCount'),''),'0');
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  if not (public.has_app_role('OWNER') or public.has_app_role('ADMIN')) then
    raise exception 'FORBIDDEN';
  end if;
  if upper(trim(p_kind))='ROLE_DUTY' and (
    v_mode not in ('OPTIONAL','EXTRA')
    or v_minimum_text !~ '^\d+$'
    or case when v_minimum_text ~ '^\d+$' then v_minimum_text::integer else 1 end<>0
    or lower(coalesce(p_data->>'shiftObligation','false')) in ('true','t','1','yes')
    or nullif(trim(p_data->>'shiftPeriod'),'') is not null
  ) then
    raise exception 'ROLE_DUTY_COMPETENCY_ONLY_USE_EXACT_SHIFT_STAFFING';
  end if;
  return public.matrix_v2_admin_save_before_mx_k10(
    p_kind,p_id,
    case when upper(trim(p_kind))='ROLE_DUTY' then
      p_data||jsonb_build_object(
        'assignmentMode',case when v_mode='EXTRA' then 'EXTRA' else 'OPTIONAL' end,
        'minimumCount',0,'shiftObligation',false,'shiftPeriod',null
      )
    else p_data end
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_admin_save_before_categories_uat_v1(p_kind text, p_id uuid, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_kind text:=upper(trim(p_kind));
  v_result jsonb;
  v_id uuid;
  v_period text;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  if not (public.has_app_role('OWNER') or public.has_app_role('ADMIN')) then
    raise exception 'FORBIDDEN';
  end if;
  v_result:=public.matrix_v2_admin_save(v_kind,p_id,p_data);
  v_id:=(v_result->>'id')::uuid;
  if v_kind='SHIFT' then
    v_period:=upper(coalesce(p_data->>'shiftPeriod','MIDDLE'));
    if v_period not in ('MORNING','MIDDLE','EVENING') then
      raise exception 'INVALID_SHIFT_PERIOD';
    end if;
    update public.matrix_shift_templates_v2 set shift_period=v_period,
      updated_at=now() where id=v_id;
  elsif v_kind='ROLE_DUTY' then
    v_period:=nullif(upper(p_data->>'shiftPeriod'),'');
    if coalesce((p_data->>'shiftObligation')::boolean,false)
      and v_period not in ('MORNING','MIDDLE','EVENING') then
      raise exception 'SHIFT_PERIOD_REQUIRED';
    end if;
    update public.matrix_role_duties_v2 set
      shift_obligation=coalesce((p_data->>'shiftObligation')::boolean,false),
      shift_period=case when coalesce((p_data->>'shiftObligation')::boolean,false)
        then v_period else null end
    where id=v_id;
  end if;
  return v_result;
end;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_admin_save_before_mx_k10(p_kind text, p_id uuid, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_payload jsonb:=coalesce(p_data,'{}'::jsonb);
  v_groups jsonb:='[]'::jsonb;
  v_group jsonb;
  v_matrix uuid;
  v_category uuid;
  v_result jsonb;
begin
  if upper(trim(p_kind))='MATRIX_SETTINGS' then
    v_groups:=coalesce(v_payload->'standbyGroups','[]'::jsonb);
    if jsonb_typeof(v_groups)<>'array' then raise exception 'INVALID_STANDBY_GROUPS'; end if;
    select id into v_matrix from public.matrix_versions
    where status='DRAFT' and schema_version>=2 order by version desc limit 1;
    if v_matrix is null then raise exception 'MATRIX_V2_DRAFT_NOT_FOUND'; end if;
    if exists(
      select 1 from jsonb_array_elements(v_groups) item
      where coalesce(item.value->>'code','') !~ '^[A-Za-z0-9_\-]{1,80}$'
        or length(trim(coalesce(item.value->>'name',''))) < 1
        or coalesce(item.value->>'categoryCode','') = ''
        or jsonb_typeof(coalesce(item.value->'roleCodes','null'::jsonb)) <> 'array'
        or jsonb_array_length(coalesce(item.value->'roleCodes','[]'::jsonb)) = 0
        or coalesce(item.value->>'tiers','') !~ '^[12]$'
    ) then raise exception 'INVALID_STANDBY_GROUP'; end if;
    for v_group in select value from jsonb_array_elements(v_groups) loop
      select category.id into v_category from public.matrix_role_categories_v2 category
      where category.matrix_version_id=v_matrix and category.active
        and upper(category.code)=upper(v_group->>'categoryCode');
      if v_category is null then raise exception 'STANDBY_GROUP_CATEGORY_NOT_FOUND:%',v_group->>'categoryCode'; end if;
      if exists(
        select 1 from jsonb_array_elements_text(v_group->'roleCodes') role_code
        where not exists(select 1 from public.matrix_roles_v2 role_row
          where role_row.matrix_version_id=v_matrix and role_row.active
            and role_row.category_id=v_category and upper(role_row.code)=upper(role_code.value))
      ) then raise exception 'STANDBY_GROUP_ROLE_NOT_FOUND_OR_WRONG_CATEGORY:%',v_group->>'code'; end if;
    end loop;
    if exists(
      select upper(role_code.value)
      from jsonb_array_elements(v_groups) item
      cross join lateral jsonb_array_elements_text(item.value->'roleCodes') role_code
      group by upper(role_code.value) having count(*)>1
    ) then raise exception 'STANDBY_ROLE_USED_IN_MULTIPLE_GROUPS'; end if;
    v_payload:=v_payload||jsonb_build_object('standbyTiersPerRoleDay',0,'standbyGroups',v_groups);
  end if;
  v_result:=public.matrix_v2_admin_save_before_standby_groups_uat_v1(p_kind,p_id,v_payload);
  if upper(trim(p_kind))='MATRIX_SETTINGS' then
    update public.matrix_versions set settings=jsonb_set(
      jsonb_set(coalesce(settings,'{}'::jsonb),'{standbyTiersPerRoleDay}','0'::jsonb,true),
      '{standbyGroups}',v_groups,true
    ) where id=(v_result->>'id')::uuid;
  end if;
  return v_result;
end;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_admin_save_before_standby_groups_uat_v1(p_kind text, p_id uuid, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_result jsonb;
  v_id uuid;
  v_matrix uuid;
  v_category uuid;
  v_category_code text;
  v_payload jsonb:=coalesce(p_data,'{}'::jsonb);
  v_mode text;
  v_priority integer;
begin
  if upper(trim(p_kind))='ROLE' then
    select id into v_matrix from public.matrix_versions
    where status='DRAFT' and schema_version>=2 order by version desc limit 1;
    if v_matrix is null then raise exception 'MATRIX_V2_DRAFT_NOT_FOUND'; end if;

    if pg_catalog.pg_input_is_valid(coalesce(v_payload->>'categoryId',''),'uuid') then
      v_category:=(v_payload->>'categoryId')::uuid;
    end if;
    v_category_code:=upper(trim(coalesce(nullif(v_payload->>'categoryCode',''),v_payload->>'code','')));
    if v_category is null then
      select id into v_category from public.matrix_role_categories_v2
      where matrix_version_id=v_matrix and code=v_category_code and active
      order by sort_order,id limit 1;
    end if;
    if v_category is null or not exists(
      select 1 from public.matrix_role_categories_v2
      where id=v_category and matrix_version_id=v_matrix and active
    ) then
      raise exception 'ROLE_CATEGORY_NOT_FOUND|%|%',coalesce(v_payload->>'code',''),v_category_code;
    end if;
    v_payload:=v_payload||jsonb_build_object('categoryId',v_category);
  end if;

  v_result:=public.matrix_v2_admin_save_before_categories_uat_v1(p_kind,p_id,v_payload);
  v_id:=(v_result->>'id')::uuid;

  if upper(trim(p_kind))='ROLE' then
    update public.matrix_roles_v2 set category_id=v_category,updated_at=now() where id=v_id;
  elsif upper(trim(p_kind))='EMPLOYEE_ROLE' then
    v_mode:=case upper(coalesce(nullif(v_payload->>'assignmentMode',''),'STANDARD'))
      when 'BACKUP' then 'BACKUP' else 'STANDARD' end;
    v_priority:=greatest(1,least(999,coalesce(nullif(v_payload->>'backupPriority','')::integer,100)));
    update public.matrix_employee_roles_v2 set
      assignment_mode=case when is_primary then 'STANDARD' else v_mode end,
      backup_priority=v_priority,updated_by=auth.uid(),updated_at=now()
    where id=v_id;
  end if;
  return v_result;
end;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_admin_save_before_standby_setting(p_kind text, p_id uuid, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_kind text:=upper(trim(p_kind));
  v_matrix uuid;
  v_id uuid;
  v_logical uuid;
  v_ref1 uuid;
  v_ref2 uuid;
  v_ref3 uuid;
  v_ref4 uuid;
begin
  if not (public.has_app_role('OWNER') or public.has_app_role('ADMIN')) then
    raise exception 'FORBIDDEN';
  end if;
  if p_data is null or jsonb_typeof(p_data)<>'object' then
    raise exception 'OBJECT_PAYLOAD_REQUIRED';
  end if;
  v_matrix:=public.matrix_v2_create_draft(null);

  if v_kind='MATRIX_SETTINGS' then
    if not public.matrix_v2_is_iso_4217_currency(
      upper(trim(coalesce(p_data->>'currency','')))
    ) then
      raise exception 'INVALID_MATRIX_CURRENCY';
    end if;
    if nullif(p_data->>'timezone','') is null or not exists(
      select 1 from pg_catalog.pg_timezone_names tz
      where tz.name=p_data->>'timezone'
    ) then raise exception 'INVALID_MATRIX_TIMEZONE'; end if;
    if coalesce(p_data->>'minimumRestMinutes','') !~ '^[0-9]+$'
      or (p_data->>'minimumRestMinutes')::integer<0
      or coalesce(p_data->>'maximumShiftsPerDay','') !~ '^[0-9]+$'
      or (p_data->>'maximumShiftsPerDay')::integer not between 1 and 24
      or jsonb_typeof(p_data->'missingAvailabilityMeansAvailable')<>'boolean'
      or jsonb_typeof(p_data->'requireOptimal')<>'boolean' then
      raise exception 'INVALID_MATRIX_LIMITS';
    end if;
    update public.matrix_versions mv set settings=coalesce(mv.settings,'{}'::jsonb)
      ||jsonb_build_object(
        'currency',upper(trim(p_data->>'currency')),
        'timezone',p_data->>'timezone',
        'minimumRestMinutes',(p_data->>'minimumRestMinutes')::integer,
        'maximumShiftsPerDay',(p_data->>'maximumShiftsPerDay')::integer,
        'missingAvailabilityMeansAvailable',
          (p_data->>'missingAvailabilityMeansAvailable')::boolean,
        'requireOptimal',(p_data->>'requireOptimal')::boolean
      )
    where mv.id=v_matrix
    returning mv.id into v_id;

  elsif v_kind='ROLE' then
    if p_id is not null then
      select r.logical_id into v_logical from public.matrix_roles_v2 r where r.id=p_id;
      select r.id into v_id from public.matrix_roles_v2 r
        where r.matrix_version_id=v_matrix and r.logical_id=v_logical;
    end if;
    if v_id is null then
      insert into public.matrix_roles_v2(
        matrix_version_id,logical_id,code,name,color,sort_order,active
      ) values(
        v_matrix,gen_random_uuid(),upper(trim(p_data->>'code')),trim(p_data->>'name'),
        coalesce(nullif(p_data->>'color',''),'#7257d8'),
        coalesce((p_data->>'sortOrder')::integer,0),
        coalesce((p_data->>'active')::boolean,true)
      ) returning id into v_id;
    else
      update public.matrix_roles_v2 set
        code=upper(coalesce(nullif(trim(p_data->>'code'),''),code)),
        name=coalesce(nullif(trim(p_data->>'name'),''),name),
        color=coalesce(nullif(p_data->>'color',''),color),
        sort_order=coalesce((p_data->>'sortOrder')::integer,sort_order),
        active=coalesce((p_data->>'active')::boolean,active),updated_at=now()
      where id=v_id and matrix_version_id=v_matrix;
    end if;

  elsif v_kind='LOCATION' then
    if nullif(p_data->>'timezone','') is not null and not exists(
      select 1 from pg_catalog.pg_timezone_names tz
      where tz.name=p_data->>'timezone'
    ) then raise exception 'INVALID_LOCATION_TIMEZONE'; end if;
    if p_id is not null then
      select l.logical_id into v_logical from public.matrix_locations_v2 l where l.id=p_id;
      select l.id into v_id from public.matrix_locations_v2 l
        where l.matrix_version_id=v_matrix and l.logical_id=v_logical;
    end if;
    if v_id is null then
      insert into public.matrix_locations_v2(
        matrix_version_id,logical_id,code,name,timezone,sort_order,active
      ) values(
        v_matrix,gen_random_uuid(),upper(trim(p_data->>'code')),trim(p_data->>'name'),
        coalesce(
          nullif(p_data->>'timezone',''),
          (select nullif(mv.settings->>'timezone','')
            from public.matrix_versions mv where mv.id=v_matrix)
        ),
        coalesce((p_data->>'sortOrder')::integer,0),
        coalesce((p_data->>'active')::boolean,true)
      ) returning id into v_id;
    else
      update public.matrix_locations_v2 set
        code=upper(coalesce(nullif(trim(p_data->>'code'),''),code)),
        name=coalesce(nullif(trim(p_data->>'name'),''),name),
        timezone=coalesce(nullif(p_data->>'timezone',''),timezone),
        sort_order=coalesce((p_data->>'sortOrder')::integer,sort_order),
        active=coalesce((p_data->>'active')::boolean,active),updated_at=now()
      where id=v_id and matrix_version_id=v_matrix;
    end if;

  elsif v_kind='DUTY' then
    if p_id is not null then
      select d.logical_id into v_logical from public.matrix_duties_v2 d where d.id=p_id;
      select d.id into v_id from public.matrix_duties_v2 d
        where d.matrix_version_id=v_matrix and d.logical_id=v_logical;
    end if;
    if v_id is null then
      insert into public.matrix_duties_v2(
        matrix_version_id,logical_id,code,name,description,color,sort_order,active
      ) values(
        v_matrix,gen_random_uuid(),upper(trim(p_data->>'code')),trim(p_data->>'name'),
        nullif(p_data->>'description',''),coalesce(nullif(p_data->>'color',''),'#4a8d78'),
        coalesce((p_data->>'sortOrder')::integer,0),
        coalesce((p_data->>'active')::boolean,true)
      ) returning id into v_id;
    else
      update public.matrix_duties_v2 set
        code=upper(coalesce(nullif(trim(p_data->>'code'),''),code)),
        name=coalesce(nullif(trim(p_data->>'name'),''),name),
        description=case when p_data ? 'description' then nullif(p_data->>'description','') else description end,
        color=coalesce(nullif(p_data->>'color',''),color),
        sort_order=coalesce((p_data->>'sortOrder')::integer,sort_order),
        active=coalesce((p_data->>'active')::boolean,active),updated_at=now()
      where id=v_id and matrix_version_id=v_matrix;
    end if;

  elsif v_kind='SHIFT' then
    if nullif(p_data->>'locationId','') is not null then
      select target.id into v_ref1
      from public.matrix_locations_v2 source
      join public.matrix_locations_v2 target
        on target.matrix_version_id=v_matrix and target.logical_id=source.logical_id
      where source.id=(p_data->>'locationId')::uuid;
    elsif p_id is not null then
      select target.id into v_ref1
      from public.matrix_shift_templates_v2 source_shift
      join public.matrix_locations_v2 source on source.id=source_shift.location_id
      join public.matrix_locations_v2 target
        on target.matrix_version_id=v_matrix and target.logical_id=source.logical_id
      where source_shift.id=p_id;
    end if;
    if v_ref1 is null then raise exception 'LOCATION_NOT_IN_MATRIX_V2'; end if;
    if p_id is not null then
      select s.logical_id into v_logical from public.matrix_shift_templates_v2 s where s.id=p_id;
      select s.id into v_id from public.matrix_shift_templates_v2 s
        where s.matrix_version_id=v_matrix and s.logical_id=v_logical;
    end if;
    if v_id is null then
      insert into public.matrix_shift_templates_v2(
        matrix_version_id,logical_id,location_id,code,name,starts_at,ends_at,
        ends_next_day,day_mask,sort_order,active
      ) values(
        v_matrix,gen_random_uuid(),v_ref1,upper(trim(p_data->>'code')),trim(p_data->>'name'),
        (p_data->>'startsAt')::time,(p_data->>'endsAt')::time,
        coalesce((p_data->>'endsNextDay')::boolean,
          (p_data->>'endsAt')::time<=(p_data->>'startsAt')::time),
        case when p_data ? 'days' then
          array(select value::smallint from jsonb_array_elements_text(p_data->'days'))
          else array[1,2,3,4,5,6,7]::smallint[] end,
        coalesce((p_data->>'sortOrder')::integer,0),
        coalesce((p_data->>'active')::boolean,true)
      ) returning id into v_id;
    else
      update public.matrix_shift_templates_v2 set
        location_id=v_ref1,
        code=upper(coalesce(nullif(trim(p_data->>'code'),''),code)),
        name=coalesce(nullif(trim(p_data->>'name'),''),name),
        starts_at=coalesce((p_data->>'startsAt')::time,starts_at),
        ends_at=coalesce((p_data->>'endsAt')::time,ends_at),
        ends_next_day=coalesce((p_data->>'endsNextDay')::boolean,ends_next_day),
        day_mask=case when p_data ? 'days' then
          array(select value::smallint from jsonb_array_elements_text(p_data->'days'))
          else day_mask end,
        sort_order=coalesce((p_data->>'sortOrder')::integer,sort_order),
        active=coalesce((p_data->>'active')::boolean,active),updated_at=now()
      where id=v_id and matrix_version_id=v_matrix;
    end if;

  elsif v_kind='ROLE_DUTY' then
    select target.id into v_ref1 from public.matrix_roles_v2 source
    join public.matrix_roles_v2 target
      on target.matrix_version_id=v_matrix and target.logical_id=source.logical_id
    where source.id=(p_data->>'roleId')::uuid;
    select target.id into v_ref2 from public.matrix_duties_v2 source
    join public.matrix_duties_v2 target
      on target.matrix_version_id=v_matrix and target.logical_id=source.logical_id
    where source.id=(p_data->>'dutyId')::uuid;
    if v_ref1 is null or v_ref2 is null then raise exception 'ROLE_OR_DUTY_NOT_IN_MATRIX_V2'; end if;
    insert into public.matrix_role_duties_v2(
      id,matrix_version_id,role_id,duty_id,assignment_mode,minimum_count,active
    ) values(
      gen_random_uuid(),v_matrix,v_ref1,v_ref2,
      coalesce(nullif(upper(p_data->>'assignmentMode'),''),'OPTIONAL'),
      coalesce((p_data->>'minimumCount')::integer,0),
      coalesce((p_data->>'active')::boolean,true)
    ) on conflict(matrix_version_id,role_id,duty_id) do update set
      assignment_mode=excluded.assignment_mode,minimum_count=excluded.minimum_count,
      active=excluded.active
    returning id into v_id;

  elsif v_kind='SCENARIO' then
    if p_id is not null then
      select s.logical_id into v_logical from public.matrix_scenarios_v2 s where s.id=p_id;
      select s.id into v_id from public.matrix_scenarios_v2 s
        where s.matrix_version_id=v_matrix and s.logical_id=v_logical;
    end if;
    v_ref1:=null;
    if p_data ? 'parentScenarioId' then
      if nullif(p_data->>'parentScenarioId','') is not null then
        select target.id into v_ref1 from public.matrix_scenarios_v2 source
        join public.matrix_scenarios_v2 target
          on target.matrix_version_id=v_matrix and target.logical_id=source.logical_id
        where source.id=(p_data->>'parentScenarioId')::uuid;
        if v_ref1 is null then raise exception 'PARENT_SCENARIO_NOT_IN_MATRIX_V2'; end if;
      end if;
    elsif v_id is not null then
      select s.parent_scenario_id into v_ref1 from public.matrix_scenarios_v2 s
      where s.id=v_id;
    end if;
    if coalesce((p_data->>'isDefault')::boolean,false) then
      update public.matrix_scenarios_v2 set is_default=false,updated_at=now()
      where matrix_version_id=v_matrix and is_default;
    end if;
    if v_id is null then
      insert into public.matrix_scenarios_v2(
        matrix_version_id,logical_id,parent_scenario_id,code,name,description,color,
        is_default,active,sort_order,valid_from,valid_to,settings_overrides
      ) values(
        v_matrix,gen_random_uuid(),v_ref1,upper(trim(p_data->>'code')),trim(p_data->>'name'),
        nullif(p_data->>'description',''),coalesce(nullif(p_data->>'color',''),'#7457e8'),
        coalesce((p_data->>'isDefault')::boolean,false),
        coalesce((p_data->>'active')::boolean,true),
        coalesce((p_data->>'sortOrder')::integer,0),
        nullif(p_data->>'validFrom','')::date,nullif(p_data->>'validTo','')::date,
        coalesce(p_data->'settingsOverrides','{}'::jsonb)
      ) returning id into v_id;
    else
      update public.matrix_scenarios_v2 set
        parent_scenario_id=v_ref1,
        code=upper(coalesce(nullif(trim(p_data->>'code'),''),code)),
        name=coalesce(nullif(trim(p_data->>'name'),''),name),
        description=case when p_data ? 'description' then nullif(p_data->>'description','') else description end,
        color=coalesce(nullif(p_data->>'color',''),color),
        is_default=coalesce((p_data->>'isDefault')::boolean,is_default),
        active=coalesce((p_data->>'active')::boolean,active),
        sort_order=coalesce((p_data->>'sortOrder')::integer,sort_order),
        valid_from=case when p_data ? 'validFrom' then nullif(p_data->>'validFrom','')::date else valid_from end,
        valid_to=case when p_data ? 'validTo' then nullif(p_data->>'validTo','')::date else valid_to end,
        settings_overrides=coalesce(p_data->'settingsOverrides',settings_overrides),updated_at=now()
      where id=v_id and matrix_version_id=v_matrix;
    end if;

  elsif v_kind='STAFFING_RULE' then
    select target.id into v_ref1 from public.matrix_scenarios_v2 source
    join public.matrix_scenarios_v2 target
      on target.matrix_version_id=v_matrix and target.logical_id=source.logical_id
    where source.id=(p_data->>'scenarioId')::uuid;
    select target.id into v_ref2 from public.matrix_shift_templates_v2 source
    join public.matrix_shift_templates_v2 target
      on target.matrix_version_id=v_matrix and target.logical_id=source.logical_id
    where source.id=(p_data->>'shiftTemplateId')::uuid;
    select target.id into v_ref3 from public.matrix_roles_v2 source
    join public.matrix_roles_v2 target
      on target.matrix_version_id=v_matrix and target.logical_id=source.logical_id
    where source.id=(p_data->>'roleId')::uuid;
    v_ref4:=null;
    if nullif(p_data->>'dutyId','') is not null then
      select target.id into v_ref4 from public.matrix_duties_v2 source
      join public.matrix_duties_v2 target
        on target.matrix_version_id=v_matrix and target.logical_id=source.logical_id
      where source.id=(p_data->>'dutyId')::uuid;
    end if;
    if v_ref1 is null or v_ref2 is null or v_ref3 is null then
      raise exception 'STAFFING_SCOPE_NOT_IN_MATRIX_V2';
    end if;
    insert into public.matrix_staffing_rules_v2(
      id,matrix_version_id,scenario_id,shift_template_id,role_id,duty_id,
      operation,count_value,multiplier_basis_points,active,source_metadata
    ) values(
      gen_random_uuid(),v_matrix,v_ref1,v_ref2,v_ref3,v_ref4,
      upper(p_data->>'operation'),nullif(p_data->>'countValue','')::integer,
      nullif(p_data->>'multiplierBasisPoints','')::integer,
      coalesce((p_data->>'active')::boolean,true),
      coalesce(p_data->'sourceMetadata','{}'::jsonb)
    ) on conflict(scenario_id,shift_template_id,role_id,duty_id) do update set
      operation=excluded.operation,count_value=excluded.count_value,
      multiplier_basis_points=excluded.multiplier_basis_points,
      active=excluded.active,source_metadata=excluded.source_metadata,updated_at=now()
    returning id into v_id;

  elsif v_kind='STRATEGY' then
    if p_id is not null then
      select s.logical_id into v_logical from public.matrix_strategies_v2 s where s.id=p_id;
      select s.id into v_id from public.matrix_strategies_v2 s
        where s.matrix_version_id=v_matrix and s.logical_id=v_logical;
    end if;
    if v_id is null then
      insert into public.matrix_strategies_v2(
        matrix_version_id,logical_id,code,name,description,solver_code,solver_options,
        sort_order,active
      ) values(
        v_matrix,gen_random_uuid(),upper(trim(p_data->>'code')),trim(p_data->>'name'),
        nullif(p_data->>'description',''),coalesce(nullif(p_data->>'solverCode',''),'CP_SAT'),
        coalesce(p_data->'solverOptions','{}'::jsonb),
        coalesce((p_data->>'sortOrder')::integer,0),
        coalesce((p_data->>'active')::boolean,true)
      ) returning id into v_id;
    else
      update public.matrix_strategies_v2 set
        code=upper(coalesce(nullif(trim(p_data->>'code'),''),code)),
        name=coalesce(nullif(trim(p_data->>'name'),''),name),
        description=case when p_data ? 'description' then nullif(p_data->>'description','') else description end,
        solver_code=coalesce(nullif(p_data->>'solverCode',''),solver_code),
        solver_options=coalesce(p_data->'solverOptions',solver_options),
        sort_order=coalesce((p_data->>'sortOrder')::integer,sort_order),
        active=coalesce((p_data->>'active')::boolean,active),updated_at=now()
      where id=v_id and matrix_version_id=v_matrix;
    end if;

  elsif v_kind='OBJECTIVE' then
    select target.id into v_ref1 from public.matrix_strategies_v2 source
    join public.matrix_strategies_v2 target
      on target.matrix_version_id=v_matrix and target.logical_id=source.logical_id
    where source.id=(p_data->>'strategyId')::uuid;
    if v_ref1 is null then raise exception 'STRATEGY_NOT_IN_MATRIX_V2'; end if;
    insert into public.matrix_strategy_objectives_v2(
      id,matrix_version_id,strategy_id,tier,sort_order,metric_code,direction,
      weight,tolerance,parameters,active
    ) values(
      gen_random_uuid(),v_matrix,v_ref1,(p_data->>'tier')::smallint,
      coalesce((p_data->>'sortOrder')::integer,0),upper(trim(p_data->>'metricCode')),
      coalesce(nullif(upper(p_data->>'direction'),''),'MINIMIZE'),
      coalesce((p_data->>'weight')::bigint,1),coalesce((p_data->>'tolerance')::bigint,0),
      coalesce(p_data->'parameters','{}'::jsonb),coalesce((p_data->>'active')::boolean,true)
    ) on conflict(strategy_id,tier,metric_code) do update set
      sort_order=excluded.sort_order,direction=excluded.direction,weight=excluded.weight,
      tolerance=excluded.tolerance,parameters=excluded.parameters,active=excluded.active
    returning id into v_id;

  elsif v_kind='SCENARIO_STRATEGY' then
    select target.id into v_ref1 from public.matrix_scenarios_v2 source
    join public.matrix_scenarios_v2 target
      on target.matrix_version_id=v_matrix and target.logical_id=source.logical_id
    where source.id=(p_data->>'scenarioId')::uuid;
    select target.id into v_ref2 from public.matrix_strategies_v2 source
    join public.matrix_strategies_v2 target
      on target.matrix_version_id=v_matrix and target.logical_id=source.logical_id
    where source.id=(p_data->>'strategyId')::uuid;
    if v_ref1 is null or v_ref2 is null then raise exception 'SCENARIO_OR_STRATEGY_NOT_IN_MATRIX_V2'; end if;
    insert into public.matrix_scenario_strategies_v2(
      id,matrix_version_id,scenario_id,strategy_id,sort_order,active,
      objective_overrides,solver_overrides
    ) values(
      gen_random_uuid(),v_matrix,v_ref1,v_ref2,
      coalesce((p_data->>'sortOrder')::integer,0),
      coalesce((p_data->>'active')::boolean,true),
      coalesce(p_data->'objectiveOverrides','{}'::jsonb),
      coalesce(p_data->'solverOverrides','{}'::jsonb)
    ) on conflict(scenario_id,strategy_id) do update set
      sort_order=excluded.sort_order,active=excluded.active,
      objective_overrides=excluded.objective_overrides,
      solver_overrides=excluded.solver_overrides
    returning id into v_id;

  elsif v_kind='PAY_RULE' then
    if p_id is not null then
      select p.logical_id into v_logical from public.matrix_pay_rules_v2 p where p.id=p_id;
      select p.id into v_id from public.matrix_pay_rules_v2 p
        where p.matrix_version_id=v_matrix and p.logical_id=v_logical;
    end if;
    if v_id is null then
      insert into public.matrix_pay_rules_v2(
        matrix_version_id,logical_id,code,name,description,calculation_method,
        amount_minor,rate_minor_per_hour,percent_basis_points,multiplier_basis_points,
        threshold_minutes,currency,priority,stacking_group,stacking_mode,day_mask,
        local_start,local_end,ends_next_day,valid_from,valid_to,condition_expression,
        formula_expression,active
      ) values(
        v_matrix,gen_random_uuid(),upper(trim(p_data->>'code')),trim(p_data->>'name'),
        nullif(p_data->>'description',''),upper(p_data->>'calculationMethod'),
        nullif(p_data->>'amountMinor','')::bigint,
        nullif(p_data->>'rateMinorPerHour','')::bigint,
        nullif(p_data->>'percentBasisPoints','')::integer,
        nullif(p_data->>'multiplierBasisPoints','')::integer,
        nullif(p_data->>'thresholdMinutes','')::integer,
        coalesce(
          nullif(upper(p_data->>'currency'),''),
          (select upper(mv.settings->>'currency')
            from public.matrix_versions mv where mv.id=v_matrix)
        ),
        coalesce((p_data->>'priority')::integer,100),nullif(p_data->>'stackingGroup',''),
        coalesce(nullif(upper(p_data->>'stackingMode'),''),'STACK'),
        case when p_data ? 'days' then array(select value::smallint from jsonb_array_elements_text(p_data->'days'))
          else array[1,2,3,4,5,6,7]::smallint[] end,
        nullif(p_data->>'localStart','')::time,nullif(p_data->>'localEnd','')::time,
        coalesce((p_data->>'endsNextDay')::boolean,false),
        nullif(p_data->>'validFrom','')::date,nullif(p_data->>'validTo','')::date,
        coalesce(p_data->'conditionExpression','{}'::jsonb),
        coalesce(p_data->'formulaExpression','{}'::jsonb),
        coalesce((p_data->>'active')::boolean,true)
      ) returning id into v_id;
    else
      update public.matrix_pay_rules_v2 set
        code=upper(coalesce(nullif(trim(p_data->>'code'),''),code)),
        name=coalesce(nullif(trim(p_data->>'name'),''),name),
        description=case when p_data ? 'description' then nullif(p_data->>'description','') else description end,
        calculation_method=coalesce(nullif(upper(p_data->>'calculationMethod'),''),calculation_method),
        amount_minor=case when p_data ? 'amountMinor' then nullif(p_data->>'amountMinor','')::bigint else amount_minor end,
        rate_minor_per_hour=case when p_data ? 'rateMinorPerHour' then nullif(p_data->>'rateMinorPerHour','')::bigint else rate_minor_per_hour end,
        percent_basis_points=case when p_data ? 'percentBasisPoints' then nullif(p_data->>'percentBasisPoints','')::integer else percent_basis_points end,
        multiplier_basis_points=case when p_data ? 'multiplierBasisPoints' then nullif(p_data->>'multiplierBasisPoints','')::integer else multiplier_basis_points end,
        threshold_minutes=case when p_data ? 'thresholdMinutes' then nullif(p_data->>'thresholdMinutes','')::integer else threshold_minutes end,
        currency=coalesce(nullif(upper(p_data->>'currency'),''),currency),
        priority=coalesce((p_data->>'priority')::integer,priority),
        stacking_group=case when p_data ? 'stackingGroup' then nullif(p_data->>'stackingGroup','') else stacking_group end,
        stacking_mode=coalesce(nullif(upper(p_data->>'stackingMode'),''),stacking_mode),
        day_mask=case when p_data ? 'days' then array(select value::smallint from jsonb_array_elements_text(p_data->'days')) else day_mask end,
        local_start=case when p_data ? 'localStart' then nullif(p_data->>'localStart','')::time else local_start end,
        local_end=case when p_data ? 'localEnd' then nullif(p_data->>'localEnd','')::time else local_end end,
        ends_next_day=coalesce((p_data->>'endsNextDay')::boolean,ends_next_day),
        valid_from=case when p_data ? 'validFrom' then nullif(p_data->>'validFrom','')::date else valid_from end,
        valid_to=case when p_data ? 'validTo' then nullif(p_data->>'validTo','')::date else valid_to end,
        condition_expression=coalesce(p_data->'conditionExpression',condition_expression),
        formula_expression=coalesce(p_data->'formulaExpression',formula_expression),
        active=coalesce((p_data->>'active')::boolean,active),updated_at=now()
      where id=v_id and matrix_version_id=v_matrix;
    end if;

    if p_data ? 'roleIds' then
      delete from public.matrix_pay_rule_roles_v2 where pay_rule_id=v_id;
      insert into public.matrix_pay_rule_roles_v2(matrix_version_id,pay_rule_id,role_id)
      select distinct v_matrix,v_id,target.id
      from jsonb_array_elements_text(p_data->'roleIds') x(value)
      join public.matrix_roles_v2 source on source.id=x.value::uuid
      join public.matrix_roles_v2 target
        on target.matrix_version_id=v_matrix and target.logical_id=source.logical_id;
    end if;
    if p_data ? 'dutyIds' then
      delete from public.matrix_pay_rule_duties_v2 where pay_rule_id=v_id;
      insert into public.matrix_pay_rule_duties_v2(matrix_version_id,pay_rule_id,duty_id)
      select distinct v_matrix,v_id,target.id
      from jsonb_array_elements_text(p_data->'dutyIds') x(value)
      join public.matrix_duties_v2 source on source.id=x.value::uuid
      join public.matrix_duties_v2 target
        on target.matrix_version_id=v_matrix and target.logical_id=source.logical_id;
    end if;
    if p_data ? 'locationIds' then
      delete from public.matrix_pay_rule_locations_v2 where pay_rule_id=v_id;
      insert into public.matrix_pay_rule_locations_v2(matrix_version_id,pay_rule_id,location_id)
      select distinct v_matrix,v_id,target.id
      from jsonb_array_elements_text(p_data->'locationIds') x(value)
      join public.matrix_locations_v2 source on source.id=x.value::uuid
      join public.matrix_locations_v2 target
        on target.matrix_version_id=v_matrix and target.logical_id=source.logical_id;
    end if;
    if p_data ? 'shiftIds' then
      delete from public.matrix_pay_rule_shifts_v2 where pay_rule_id=v_id;
      insert into public.matrix_pay_rule_shifts_v2(matrix_version_id,pay_rule_id,shift_template_id)
      select distinct v_matrix,v_id,target.id
      from jsonb_array_elements_text(p_data->'shiftIds') x(value)
      join public.matrix_shift_templates_v2 source on source.id=x.value::uuid
      join public.matrix_shift_templates_v2 target
        on target.matrix_version_id=v_matrix and target.logical_id=source.logical_id;
    end if;

  elsif v_kind='SCENARIO_PAY_RULE' then
    select target.id into v_ref1 from public.matrix_scenarios_v2 source
    join public.matrix_scenarios_v2 target
      on target.matrix_version_id=v_matrix and target.logical_id=source.logical_id
    where source.id=(p_data->>'scenarioId')::uuid;
    select target.id into v_ref2 from public.matrix_pay_rules_v2 source
    join public.matrix_pay_rules_v2 target
      on target.matrix_version_id=v_matrix and target.logical_id=source.logical_id
    where source.id=(p_data->>'payRuleId')::uuid;
    if v_ref1 is null or v_ref2 is null then
      raise exception 'SCENARIO_OR_PAY_RULE_NOT_IN_MATRIX_V2';
    end if;
    insert into public.matrix_scenario_pay_rule_overrides_v2(
      id,matrix_version_id,scenario_id,pay_rule_id,enabled,amount_minor,
      rate_minor_per_hour,percent_basis_points,multiplier_basis_points,formula_expression
    ) values(
      gen_random_uuid(),v_matrix,v_ref1,v_ref2,
      coalesce((p_data->>'enabled')::boolean,true),
      nullif(p_data->>'amountMinor','')::bigint,
      nullif(p_data->>'rateMinorPerHour','')::bigint,
      nullif(p_data->>'percentBasisPoints','')::integer,
      nullif(p_data->>'multiplierBasisPoints','')::integer,
      case when p_data ? 'formulaExpression' then p_data->'formulaExpression' else null end
    ) on conflict(scenario_id,pay_rule_id) do update set
      enabled=excluded.enabled,amount_minor=excluded.amount_minor,
      rate_minor_per_hour=excluded.rate_minor_per_hour,
      percent_basis_points=excluded.percent_basis_points,
      multiplier_basis_points=excluded.multiplier_basis_points,
      formula_expression=excluded.formula_expression
    returning id into v_id;

  elsif v_kind='SCENARIO_BUDGET' then
    select target.id into v_ref1 from public.matrix_scenarios_v2 source
    join public.matrix_scenarios_v2 target
      on target.matrix_version_id=v_matrix and target.logical_id=source.logical_id
    where source.id=(p_data->>'scenarioId')::uuid;
    if v_ref1 is null then raise exception 'SCENARIO_NOT_IN_MATRIX_V2'; end if;
    v_ref2:=null; v_ref3:=null; v_ref4:=null;
    if nullif(p_data->>'locationId','') is not null then
      select target.id into v_ref2 from public.matrix_locations_v2 source
      join public.matrix_locations_v2 target
        on target.matrix_version_id=v_matrix and target.logical_id=source.logical_id
      where source.id=(p_data->>'locationId')::uuid;
      if v_ref2 is null then raise exception 'LOCATION_NOT_IN_MATRIX_V2'; end if;
    end if;
    if nullif(p_data->>'roleId','') is not null then
      select target.id into v_ref3 from public.matrix_roles_v2 source
      join public.matrix_roles_v2 target
        on target.matrix_version_id=v_matrix and target.logical_id=source.logical_id
      where source.id=(p_data->>'roleId')::uuid;
      if v_ref3 is null then raise exception 'ROLE_NOT_IN_MATRIX_V2'; end if;
    end if;
    if nullif(p_data->>'dutyId','') is not null then
      select target.id into v_ref4 from public.matrix_duties_v2 source
      join public.matrix_duties_v2 target
        on target.matrix_version_id=v_matrix and target.logical_id=source.logical_id
      where source.id=(p_data->>'dutyId')::uuid;
      if v_ref4 is null then raise exception 'DUTY_NOT_IN_MATRIX_V2'; end if;
    end if;
    insert into public.matrix_scenario_budgets_v2(
      id,matrix_version_id,scenario_id,budget_month,location_id,role_id,duty_id,
      operation,amount_minor,multiplier_basis_points,currency,hard_limit,
      warning_percent,source_metadata
    ) values(
      gen_random_uuid(),v_matrix,v_ref1,
      nullif(p_data->>'budgetMonth','')::date,v_ref2,v_ref3,v_ref4,
      coalesce(nullif(upper(p_data->>'operation'),''),'SET'),
      nullif(p_data->>'amountMinor','')::bigint,
      nullif(p_data->>'multiplierBasisPoints','')::integer,
      coalesce(
        nullif(upper(p_data->>'currency'),''),
        (select upper(mv.settings->>'currency')
          from public.matrix_versions mv where mv.id=v_matrix)
      ),
      nullif(p_data->>'hardLimit','')::boolean,
      nullif(p_data->>'warningPercent','')::integer,
      coalesce(p_data->'sourceMetadata','{}'::jsonb)
    ) on conflict(scenario_id,budget_month,location_id,role_id,duty_id) do update set
      operation=excluded.operation,amount_minor=excluded.amount_minor,
      multiplier_basis_points=excluded.multiplier_basis_points,
      currency=excluded.currency,hard_limit=excluded.hard_limit,
      warning_percent=excluded.warning_percent,
      source_metadata=excluded.source_metadata,updated_at=now()
    returning id into v_id;

  elsif v_kind='EMPLOYEE_ROLE' then
    select target.id into v_ref1 from public.matrix_roles_v2 source
    join public.matrix_roles_v2 target
      on target.matrix_version_id=v_matrix and target.logical_id=source.logical_id
    where source.id=(p_data->>'roleId')::uuid;
    if v_ref1 is null then raise exception 'ROLE_NOT_IN_MATRIX_V2'; end if;
    if coalesce((p_data->>'isPrimary')::boolean,false) then
      update public.matrix_employee_roles_v2 set is_primary=false
      where matrix_version_id=v_matrix and employee_id=(p_data->>'employeeId')::uuid and is_primary;
    end if;
    insert into public.matrix_employee_roles_v2(
      id,matrix_version_id,employee_id,role_id,is_primary,can_lead,active,valid_from,valid_to
    ) values(
      gen_random_uuid(),v_matrix,(p_data->>'employeeId')::uuid,v_ref1,
      coalesce((p_data->>'isPrimary')::boolean,false),
      coalesce((p_data->>'canLead')::boolean,false),
      coalesce((p_data->>'active')::boolean,true),
      nullif(p_data->>'validFrom','')::date,nullif(p_data->>'validTo','')::date
    ) on conflict(matrix_version_id,employee_id,role_id) do update set
      is_primary=excluded.is_primary,can_lead=excluded.can_lead,active=excluded.active,
      valid_from=excluded.valid_from,valid_to=excluded.valid_to
    returning id into v_id;

  elsif v_kind='EMPLOYEE_LOCATION' then
    select target.id into v_ref1 from public.matrix_locations_v2 source
    join public.matrix_locations_v2 target
      on target.matrix_version_id=v_matrix and target.logical_id=source.logical_id
    where source.id=(p_data->>'locationId')::uuid;
    if v_ref1 is null then raise exception 'LOCATION_NOT_IN_MATRIX_V2'; end if;
    insert into public.matrix_employee_locations_v2(
      id,matrix_version_id,employee_id,location_id,standard_allowed,overtime_allowed,
      home_location,active,valid_from,valid_to
    ) values(
      gen_random_uuid(),v_matrix,(p_data->>'employeeId')::uuid,v_ref1,
      coalesce((p_data->>'standardAllowed')::boolean,false),
      coalesce((p_data->>'overtimeAllowed')::boolean,false),
      coalesce((p_data->>'homeLocation')::boolean,false),
      coalesce((p_data->>'active')::boolean,true),
      nullif(p_data->>'validFrom','')::date,nullif(p_data->>'validTo','')::date
    ) on conflict(matrix_version_id,employee_id,location_id) do update set
      standard_allowed=excluded.standard_allowed,overtime_allowed=excluded.overtime_allowed,
      home_location=excluded.home_location,active=excluded.active,
      valid_from=excluded.valid_from,valid_to=excluded.valid_to
    returning id into v_id;

  elsif v_kind='EMPLOYEE_DUTY' then
    select target.id into v_ref1 from public.matrix_duties_v2 source
    join public.matrix_duties_v2 target
      on target.matrix_version_id=v_matrix and target.logical_id=source.logical_id
    where source.id=(p_data->>'dutyId')::uuid;
    if v_ref1 is null then raise exception 'DUTY_NOT_IN_MATRIX_V2'; end if;
    v_ref2:=null; v_ref3:=null;
    if nullif(p_data->>'roleId','') is not null then
      select target.id into v_ref2 from public.matrix_roles_v2 source
      join public.matrix_roles_v2 target
        on target.matrix_version_id=v_matrix and target.logical_id=source.logical_id
      where source.id=(p_data->>'roleId')::uuid;
      if v_ref2 is null then raise exception 'ROLE_NOT_IN_MATRIX_V2'; end if;
    end if;
    if nullif(p_data->>'locationId','') is not null then
      select target.id into v_ref3 from public.matrix_locations_v2 source
      join public.matrix_locations_v2 target
        on target.matrix_version_id=v_matrix and target.logical_id=source.logical_id
      where source.id=(p_data->>'locationId')::uuid;
      if v_ref3 is null then raise exception 'LOCATION_NOT_IN_MATRIX_V2'; end if;
    end if;
    insert into public.matrix_employee_duties_v2(
      id,matrix_version_id,employee_id,duty_id,role_id,location_id,active,
      valid_from,valid_to,source
    ) values(
      gen_random_uuid(),v_matrix,(p_data->>'employeeId')::uuid,v_ref1,
      v_ref2,v_ref3,coalesce((p_data->>'active')::boolean,true),
      nullif(p_data->>'validFrom','')::date,nullif(p_data->>'validTo','')::date,'MATRIX_V2_ADMIN'
    ) on conflict(matrix_version_id,employee_id,duty_id,role_id,location_id) do update set
      active=excluded.active,valid_from=excluded.valid_from,valid_to=excluded.valid_to,
      source=excluded.source
    returning id into v_id;

  else
    raise exception 'UNSUPPORTED_MATRIX_V2_KIND: %',v_kind;
  end if;

  insert into public.audit_log(actor_id,entity_type,entity_id,action,new_data)
  values(auth.uid(),'matrix_v2_'||lower(v_kind),v_id::text,'UPSERT',
    jsonb_build_object('matrixVersionId',v_matrix,'data',
      case when v_kind in ('PAY_RULE','SCENARIO_PAY_RULE','SCENARIO_BUDGET') then
        p_data-array['amountMinor','rateMinorPerHour','percentBasisPoints',
          'multiplierBasisPoints','formulaExpression']
      else p_data end));
  return jsonb_build_object('id',v_id,'kind',v_kind,'matrixVersionId',v_matrix);
end;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_can_manage_employee(p_employee_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select auth.uid() is not null and (
    public.has_app_role('OWNER') or public.has_app_role('ADMIN')
    or public.has_app_role('HR_FINANCE')
    or exists(
      select 1 from public.employees employee
      where employee.id=p_employee_id and employee.auth_user_id=auth.uid()
    )
    or public.matrix_v2_scope_allows_resource_for_app_role_uat_v1(
      'ROLE_MANAGER',null,null,p_employee_id
    )
    or public.matrix_v2_scope_allows_resource_for_app_role_uat_v1(
      'LOCATION_MANAGER',null,null,p_employee_id
    )
  );
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_can_manage_legacy_assignment_uat_v1(p_assignment_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_role_code text;
  v_employee_id uuid;
  v_location_id uuid;
begin
  if auth.uid() is null or p_assignment_id is null then return false; end if;

  select assignment.assigned_role::text,assignment.employee_id,shift.location_id
  into v_role_code,v_employee_id,v_location_id
  from public.assignments assignment
  join public.shifts shift on shift.id=assignment.shift_id
  where assignment.id=p_assignment_id;

  if v_role_code is null or v_employee_id is null or v_location_id is null then
    return false;
  end if;

  return public.matrix_v2_can_manage_legacy_resource_uat_v1(
    v_role_code,v_location_id,v_employee_id
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_can_manage_legacy_plan_issue_uat_v1(p_issue_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_role_code text;
  v_location_id uuid;
begin
  if auth.uid() is null or p_issue_id is null then return false; end if;

  select issue.role::text,shift.location_id
  into v_role_code,v_location_id
  from public.plan_issues issue
  join public.shifts shift on shift.id=issue.shift_id
  where issue.id=p_issue_id;

  if v_role_code is null or v_location_id is null then return false; end if;

  return public.matrix_v2_can_manage_legacy_resource_uat_v1(
    v_role_code,v_location_id,null
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_can_manage_legacy_resource_uat_v1(p_role_code text DEFAULT NULL::text, p_legacy_location_id uuid DEFAULT NULL::uuid, p_employee_id uuid DEFAULT NULL::uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_matrix_id uuid;
  v_match_count integer;
  v_role_id uuid;
  v_location_id uuid;
begin
  if auth.uid() is null then return false; end if;

  select count(*),(array_agg(matrix.id))[1] into v_match_count,v_matrix_id
  from public.matrix_versions matrix
  where matrix.status='ACTIVE';
  if v_match_count<>1 then return false; end if;

  if nullif(trim(coalesce(p_role_code,'')),'') is not null then
    select count(*),(array_agg(role.id))[1] into v_match_count,v_role_id
    from public.matrix_roles_v2 role
    where role.matrix_version_id=v_matrix_id and role.active
      and upper(role.code)=upper(trim(p_role_code));
    if v_match_count<>1 then return false; end if;
  end if;

  if p_legacy_location_id is not null then
    select count(*),(array_agg(matrix_location.id))[1] into v_match_count,v_location_id
    from public.locations legacy_location
    join public.matrix_locations_v2 matrix_location
      on upper(matrix_location.code::text)=upper(legacy_location.code::text)
    where legacy_location.id=p_legacy_location_id
      and matrix_location.matrix_version_id=v_matrix_id
      and matrix_location.active;
    if v_match_count<>1 then return false; end if;
  end if;

  return public.matrix_v2_can_manage_resource_uat_v1(
    v_role_id,v_location_id,p_employee_id
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_can_manage_resource_uat_v1(p_role_id uuid DEFAULT NULL::uuid, p_location_id uuid DEFAULT NULL::uuid, p_employee_id uuid DEFAULT NULL::uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select auth.uid() is not null and (
    public.has_app_role('OWNER') or public.has_app_role('ADMIN')
    or public.matrix_v2_scope_allows_resource_for_app_role_uat_v1(
      'ROLE_MANAGER',p_role_id,p_location_id,p_employee_id
    )
    or public.matrix_v2_scope_allows_resource_for_app_role_uat_v1(
      'LOCATION_MANAGER',p_role_id,p_location_id,p_employee_id
    )
  );
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_compare_versions_uat_v2(p_left_version_id uuid, p_right_version_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_left jsonb;
  v_right jsonb;
  v_sections jsonb;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  if not (public.has_app_role('OWNER') or public.has_app_role('ADMIN')) then
    raise exception 'FORBIDDEN';
  end if;
  if p_left_version_id is null or p_right_version_id is null
    or p_left_version_id=p_right_version_id then
    raise exception 'TWO_DIFFERENT_MATRIX_VERSIONS_REQUIRED';
  end if;
  v_left:=public.matrix_v2_content_document(p_left_version_id);
  v_right:=public.matrix_v2_content_document(p_right_version_id);
  if v_left is null or v_right is null then raise exception 'MATRIX_V2_NOT_FOUND'; end if;
  v_left:=v_left||jsonb_build_object('employeeProfiles',coalesce((
    select jsonb_agg(to_jsonb(profile)-array[
      'id','matrix_version_id','created_at','updated_at','created_by','updated_by'
    ] order by profile.employee_no)
    from public.matrix_employee_profiles_v2 profile
    where profile.matrix_version_id=p_left_version_id
  ),'[]'::jsonb));
  v_right:=v_right||jsonb_build_object('employeeProfiles',coalesce((
    select jsonb_agg(to_jsonb(profile)-array[
      'id','matrix_version_id','created_at','updated_at','created_by','updated_by'
    ] order by profile.employee_no)
    from public.matrix_employee_profiles_v2 profile
    where profile.matrix_version_id=p_right_version_id
  ),'[]'::jsonb));

  select jsonb_agg(jsonb_build_object(
    'key',section.key,'label',section.label,
    'leftCount',jsonb_array_length(coalesce(v_left->section.key,'[]'::jsonb)),
    'rightCount',jsonb_array_length(coalesce(v_right->section.key,'[]'::jsonb)),
    'changed',(v_left->section.key) is distinct from (v_right->section.key)
  ) order by section.ordinal)
  into v_sections
  from (values
    (1,'roles','Role'),(2,'locations','Lokale'),(3,'duties','Obowiązki'),
    (4,'shifts','Zmiany'),(5,'roleDuties','Powiązania ról i obowiązków'),
    (6,'staffingRules','Wymagana obsada'),(7,'scenarios','Scenariusze'),
    (8,'strategies','Warianty biznesowe'),(9,'objectives','Priorytety wariantów'),
    (10,'employeeProfiles','Profile i limity pracowników'),
    (11,'employeeRoles','Role pracowników'),(12,'employeeLocations','Lokale pracowników'),
    (13,'employeeDuties','Kompetencje pracowników'),(14,'payRules','Reguły płacowe'),
    (15,'scenarioBudgets','Budżety')
  ) section(ordinal,key,label);
  return jsonb_build_object(
    'leftVersionId',p_left_version_id,'rightVersionId',p_right_version_id,
    'settingsChanged',(v_left->'settings') is distinct from (v_right->'settings'),
    'sections',v_sections
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_content_document(p_matrix_version_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select jsonb_build_object(
    'settings',mv.settings,
    'roles',coalesce((select jsonb_agg(
      to_jsonb(x)-array['id','matrix_version_id','created_at','updated_at'] order by x.logical_id)
      from public.matrix_roles_v2 x where x.matrix_version_id=mv.id),'[]'::jsonb),
    'locations',coalesce((select jsonb_agg(
      to_jsonb(x)-array['id','matrix_version_id','created_at','updated_at'] order by x.logical_id)
      from public.matrix_locations_v2 x where x.matrix_version_id=mv.id),'[]'::jsonb),
    'duties',coalesce((select jsonb_agg(
      to_jsonb(x)-array['id','matrix_version_id','created_at','updated_at'] order by x.logical_id)
      from public.matrix_duties_v2 x where x.matrix_version_id=mv.id),'[]'::jsonb),
    'shifts',coalesce((select jsonb_agg(
      (to_jsonb(x)-array['id','matrix_version_id','location_id','created_at','updated_at'])
        ||jsonb_build_object('locationLogicalId',l.logical_id) order by x.logical_id)
      from public.matrix_shift_templates_v2 x
      join public.matrix_locations_v2 l on l.id=x.location_id
      where x.matrix_version_id=mv.id),'[]'::jsonb),
    'roleDuties',coalesce((select jsonb_agg(
      (to_jsonb(x)-array['id','matrix_version_id','role_id','duty_id','created_at'])
        ||jsonb_build_object('roleLogicalId',r.logical_id,'dutyLogicalId',d.logical_id)
        order by r.logical_id,d.logical_id)
      from public.matrix_role_duties_v2 x
      join public.matrix_roles_v2 r on r.id=x.role_id
      join public.matrix_duties_v2 d on d.id=x.duty_id
      where x.matrix_version_id=mv.id),'[]'::jsonb),
    'scenarios',coalesce((select jsonb_agg(
      (to_jsonb(x)-array['id','matrix_version_id','parent_scenario_id','created_at','updated_at'])
        ||jsonb_build_object('parentLogicalId',p.logical_id) order by x.logical_id)
      from public.matrix_scenarios_v2 x
      left join public.matrix_scenarios_v2 p on p.id=x.parent_scenario_id
      where x.matrix_version_id=mv.id),'[]'::jsonb),
    'staffingRules',coalesce((select jsonb_agg(
      (to_jsonb(x)-array['id','matrix_version_id','scenario_id','shift_template_id',
        'role_id','duty_id','created_at','updated_at'])
        ||jsonb_build_object('scenarioLogicalId',sc.logical_id,
          'shiftLogicalId',sh.logical_id,'roleLogicalId',r.logical_id,
          'dutyLogicalId',d.logical_id)
        order by sc.logical_id,sh.logical_id,r.logical_id,d.logical_id)
      from public.matrix_staffing_rules_v2 x
      join public.matrix_scenarios_v2 sc on sc.id=x.scenario_id
      join public.matrix_shift_templates_v2 sh on sh.id=x.shift_template_id
      join public.matrix_roles_v2 r on r.id=x.role_id
      left join public.matrix_duties_v2 d on d.id=x.duty_id
      where x.matrix_version_id=mv.id),'[]'::jsonb),
    'strategies',coalesce((select jsonb_agg(
      to_jsonb(x)-array['id','matrix_version_id','legacy_optimizer_profile_id',
        'created_at','updated_at'] order by x.logical_id)
      from public.matrix_strategies_v2 x where x.matrix_version_id=mv.id),'[]'::jsonb),
    'objectives',coalesce((select jsonb_agg(
      (to_jsonb(x)-array['id','matrix_version_id','strategy_id','created_at'])
        ||jsonb_build_object('strategyLogicalId',s.logical_id)
        order by s.logical_id,x.tier,x.sort_order,x.metric_code)
      from public.matrix_strategy_objectives_v2 x
      join public.matrix_strategies_v2 s on s.id=x.strategy_id
      where x.matrix_version_id=mv.id),'[]'::jsonb),
    'scenarioStrategies',coalesce((select jsonb_agg(
      (to_jsonb(x)-array['id','matrix_version_id','scenario_id','strategy_id','created_at'])
        ||jsonb_build_object('scenarioLogicalId',sc.logical_id,
          'strategyLogicalId',st.logical_id)
        order by sc.logical_id,x.sort_order,st.logical_id)
      from public.matrix_scenario_strategies_v2 x
      join public.matrix_scenarios_v2 sc on sc.id=x.scenario_id
      join public.matrix_strategies_v2 st on st.id=x.strategy_id
      where x.matrix_version_id=mv.id),'[]'::jsonb),
    'employeeRoles',coalesce((select jsonb_agg(
      (to_jsonb(x)-array['id','matrix_version_id','role_id','created_at'])
        ||jsonb_build_object('roleLogicalId',r.logical_id)
        order by x.employee_id,r.logical_id)
      from public.matrix_employee_roles_v2 x
      join public.matrix_roles_v2 r on r.id=x.role_id
      where x.matrix_version_id=mv.id),'[]'::jsonb),
    'employeeLocations',coalesce((select jsonb_agg(
      (to_jsonb(x)-array['id','matrix_version_id','location_id','created_at'])
        ||jsonb_build_object('locationLogicalId',l.logical_id)
        order by x.employee_id,l.logical_id)
      from public.matrix_employee_locations_v2 x
      join public.matrix_locations_v2 l on l.id=x.location_id
      where x.matrix_version_id=mv.id),'[]'::jsonb),
    'employeeDuties',coalesce((select jsonb_agg(
      (to_jsonb(x)-array['id','matrix_version_id','duty_id','role_id','location_id','created_at'])
        ||jsonb_build_object('dutyLogicalId',d.logical_id,
          'roleLogicalId',r.logical_id,'locationLogicalId',l.logical_id)
        order by x.employee_id,d.logical_id,r.logical_id,l.logical_id)
      from public.matrix_employee_duties_v2 x
      join public.matrix_duties_v2 d on d.id=x.duty_id
      left join public.matrix_roles_v2 r on r.id=x.role_id
      left join public.matrix_locations_v2 l on l.id=x.location_id
      where x.matrix_version_id=mv.id),'[]'::jsonb),
    'payRules',coalesce((select jsonb_agg(
      to_jsonb(x)-array['id','matrix_version_id','created_at','updated_at']
        order by x.logical_id)
      from public.matrix_pay_rules_v2 x where x.matrix_version_id=mv.id),'[]'::jsonb),
    'payRuleRoles',coalesce((select jsonb_agg(jsonb_build_object(
        'payRuleLogicalId',p.logical_id,'roleLogicalId',r.logical_id)
        order by p.logical_id,r.logical_id)
      from public.matrix_pay_rule_roles_v2 x
      join public.matrix_pay_rules_v2 p on p.id=x.pay_rule_id
      join public.matrix_roles_v2 r on r.id=x.role_id
      where x.matrix_version_id=mv.id),'[]'::jsonb),
    'payRuleDuties',coalesce((select jsonb_agg(jsonb_build_object(
        'payRuleLogicalId',p.logical_id,'dutyLogicalId',d.logical_id,'matchMode',x.match_mode)
        order by p.logical_id,d.logical_id)
      from public.matrix_pay_rule_duties_v2 x
      join public.matrix_pay_rules_v2 p on p.id=x.pay_rule_id
      join public.matrix_duties_v2 d on d.id=x.duty_id
      where x.matrix_version_id=mv.id),'[]'::jsonb),
    'payRuleLocations',coalesce((select jsonb_agg(jsonb_build_object(
        'payRuleLogicalId',p.logical_id,'locationLogicalId',l.logical_id)
        order by p.logical_id,l.logical_id)
      from public.matrix_pay_rule_locations_v2 x
      join public.matrix_pay_rules_v2 p on p.id=x.pay_rule_id
      join public.matrix_locations_v2 l on l.id=x.location_id
      where x.matrix_version_id=mv.id),'[]'::jsonb),
    'payRuleShifts',coalesce((select jsonb_agg(jsonb_build_object(
        'payRuleLogicalId',p.logical_id,'shiftLogicalId',s.logical_id)
        order by p.logical_id,s.logical_id)
      from public.matrix_pay_rule_shifts_v2 x
      join public.matrix_pay_rules_v2 p on p.id=x.pay_rule_id
      join public.matrix_shift_templates_v2 s on s.id=x.shift_template_id
      where x.matrix_version_id=mv.id),'[]'::jsonb),
    'scenarioPayRuleOverrides',coalesce((select jsonb_agg(
      (to_jsonb(x)-array['id','matrix_version_id','scenario_id','pay_rule_id','created_at'])
        ||jsonb_build_object('scenarioLogicalId',sc.logical_id,
          'payRuleLogicalId',p.logical_id) order by sc.logical_id,p.logical_id)
      from public.matrix_scenario_pay_rule_overrides_v2 x
      join public.matrix_scenarios_v2 sc on sc.id=x.scenario_id
      join public.matrix_pay_rules_v2 p on p.id=x.pay_rule_id
      where x.matrix_version_id=mv.id),'[]'::jsonb),
    'scenarioBudgets',coalesce((select jsonb_agg(
      (to_jsonb(x)-array['id','matrix_version_id','scenario_id','location_id','role_id',
        'duty_id','created_at','updated_at'])
        ||jsonb_build_object('scenarioLogicalId',sc.logical_id,
          'locationLogicalId',l.logical_id,'roleLogicalId',r.logical_id,
          'dutyLogicalId',d.logical_id)
        order by sc.logical_id,x.budget_month,l.logical_id,r.logical_id,d.logical_id)
      from public.matrix_scenario_budgets_v2 x
      join public.matrix_scenarios_v2 sc on sc.id=x.scenario_id
      left join public.matrix_locations_v2 l on l.id=x.location_id
      left join public.matrix_roles_v2 r on r.id=x.role_id
      left join public.matrix_duties_v2 d on d.id=x.duty_id
      where x.matrix_version_id=mv.id),'[]'::jsonb)
  )
  from public.matrix_versions mv where mv.id=p_matrix_version_id;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_create_draft(p_name text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_active public.matrix_versions%rowtype;
  v_draft_id uuid;
  v_version integer;
begin
  if not (public.has_app_role('OWNER') or public.has_app_role('ADMIN')) then
    raise exception 'FORBIDDEN';
  end if;
  perform pg_advisory_xact_lock(hashtext('matrix-v2-lifecycle'));

  select mv.id into v_draft_id
  from public.matrix_versions mv
  where mv.status='DRAFT' and mv.schema_version>=2
  order by mv.version desc limit 1;
  if v_draft_id is not null then return v_draft_id; end if;

  select * into v_active from public.matrix_versions mv
  where mv.status='ACTIVE' and mv.schema_version>=2
  order by mv.version desc limit 1;
  select coalesce(max(mv.version),0)+1 into v_version from public.matrix_versions mv;

  insert into public.matrix_versions(
    version,name,status,effective_from,settings,created_by,schema_version,base_version_id
  ) values(
    v_version,coalesce(nullif(trim(p_name),''),'Matrix v2 v'||v_version),'DRAFT',
    coalesce(v_active.effective_from,current_date),
    coalesce(v_active.settings,'{}'::jsonb),auth.uid(),2,v_active.id
  ) returning id into v_draft_id;

  if v_active.id is null then return v_draft_id; end if;

  -- Keep the last legacy-compatible projection beside Matrix v2. Until the
  -- feature flag leaves ALPHA15 this prevents publishing a v2 draft from
  -- activating a Matrix version with empty legacy tables.
  insert into public.matrix_roles(matrix_version_id,code,name,color,sort_order,active)
  select v_draft_id,r.code,r.name,r.color,r.sort_order,r.active
  from public.matrix_roles r where r.matrix_version_id=v_active.id;

  insert into public.matrix_locations(matrix_version_id,code,name,active)
  select v_draft_id,l.code,l.name,l.active
  from public.matrix_locations l where l.matrix_version_id=v_active.id;

  insert into public.matrix_functions(matrix_version_id,code,name,description,active)
  select v_draft_id,f.code,f.name,f.description,f.active
  from public.matrix_functions f where f.matrix_version_id=v_active.id;

  insert into public.matrix_shift_templates(
    matrix_version_id,location_id,code,name,starts_at,ends_at,day_mask,sort_order,active
  )
  select v_draft_id,nl.id,s.code,s.name,s.starts_at,s.ends_at,s.day_mask,
    s.sort_order,s.active
  from public.matrix_shift_templates s
  join public.matrix_locations old_location on old_location.id=s.location_id
  join public.matrix_locations nl
    on nl.matrix_version_id=v_draft_id and nl.code=old_location.code
  where s.matrix_version_id=v_active.id;

  insert into public.matrix_role_functions(role_id,function_id,assignment_mode)
  select nr.id,nf.id,rf.assignment_mode
  from public.matrix_role_functions rf
  join public.matrix_roles old_role on old_role.id=rf.role_id
  join public.matrix_functions old_function on old_function.id=rf.function_id
  join public.matrix_roles nr
    on nr.matrix_version_id=v_draft_id and nr.code=old_role.code
  join public.matrix_functions nf
    on nf.matrix_version_id=v_draft_id and nf.code=old_function.code
  where old_role.matrix_version_id=v_active.id
    and old_function.matrix_version_id=v_active.id;

  insert into public.matrix_demand(
    shift_template_id,role_id,function_id,scenario_code,required_count
  )
  select nsh.id,nr.id,nf.id,d.scenario_code,d.required_count
  from public.matrix_demand d
  join public.matrix_shift_templates old_shift on old_shift.id=d.shift_template_id
  join public.matrix_locations old_location on old_location.id=old_shift.location_id
  join public.matrix_roles old_role on old_role.id=d.role_id
  left join public.matrix_functions old_function on old_function.id=d.function_id
  join public.matrix_locations nl
    on nl.matrix_version_id=v_draft_id and nl.code=old_location.code
  join public.matrix_shift_templates nsh
    on nsh.matrix_version_id=v_draft_id and nsh.location_id=nl.id and nsh.code=old_shift.code
  join public.matrix_roles nr
    on nr.matrix_version_id=v_draft_id and nr.code=old_role.code
  left join public.matrix_functions nf
    on nf.matrix_version_id=v_draft_id and nf.code=old_function.code
  where old_shift.matrix_version_id=v_active.id
    and old_role.matrix_version_id=v_active.id
    and (old_function.id is null
      or old_function.matrix_version_id=v_active.id);

  insert into public.matrix_employee_roles(
    matrix_version_id,employee_id,role_id,is_primary,can_lead
  )
  select v_draft_id,er.employee_id,nr.id,er.is_primary,er.can_lead
  from public.matrix_employee_roles er
  join public.matrix_roles old_role on old_role.id=er.role_id
  join public.matrix_roles nr
    on nr.matrix_version_id=v_draft_id and nr.code=old_role.code
  where er.matrix_version_id=v_active.id;

  insert into public.matrix_scenarios(
    matrix_version_id,code,name,description,color,active,sort_order
  )
  select v_draft_id,s.code,s.name,s.description,s.color,s.active,s.sort_order
  from public.matrix_scenarios s where s.matrix_version_id=v_active.id;

  insert into public.optimizer_profiles(
    matrix_version_id,code,name,weights,population_size,generations,elite_count,
    mutation_rate,alternatives_count,active
  )
  select v_draft_id,p.code,p.name,p.weights,p.population_size,p.generations,
    p.elite_count,p.mutation_rate,p.alternatives_count,p.active
  from public.optimizer_profiles p where p.matrix_version_id=v_active.id;

  insert into public.matrix_roles_v2(
    id,matrix_version_id,logical_id,code,name,color,sort_order,active
  ) select gen_random_uuid(),v_draft_id,r.logical_id,r.code,r.name,r.color,r.sort_order,r.active
    from public.matrix_roles_v2 r where r.matrix_version_id=v_active.id;

  insert into public.matrix_locations_v2(
    id,matrix_version_id,logical_id,code,name,timezone,sort_order,active
  ) select gen_random_uuid(),v_draft_id,l.logical_id,l.code,l.name,l.timezone,l.sort_order,l.active
    from public.matrix_locations_v2 l where l.matrix_version_id=v_active.id;

  insert into public.matrix_duties_v2(
    id,matrix_version_id,logical_id,code,name,description,color,sort_order,active
  ) select gen_random_uuid(),v_draft_id,d.logical_id,d.code,d.name,d.description,d.color,d.sort_order,d.active
    from public.matrix_duties_v2 d where d.matrix_version_id=v_active.id;

  insert into public.matrix_shift_templates_v2(
    id,matrix_version_id,logical_id,location_id,code,name,starts_at,ends_at,
    ends_next_day,day_mask,sort_order,active
  )
  select gen_random_uuid(),v_draft_id,s.logical_id,nl.id,s.code,s.name,s.starts_at,s.ends_at,
    s.ends_next_day,s.day_mask,s.sort_order,s.active
  from public.matrix_shift_templates_v2 s
  join public.matrix_locations_v2 ol on ol.id=s.location_id
  join public.matrix_locations_v2 nl
    on nl.matrix_version_id=v_draft_id and nl.logical_id=ol.logical_id
  where s.matrix_version_id=v_active.id;

  insert into public.matrix_role_duties_v2(
    id,matrix_version_id,role_id,duty_id,assignment_mode,minimum_count,active
  )
  select gen_random_uuid(),v_draft_id,nr.id,nd.id,rd.assignment_mode,
    rd.minimum_count,rd.active
  from public.matrix_role_duties_v2 rd
  join public.matrix_roles_v2 orole on orole.id=rd.role_id
  join public.matrix_duties_v2 od on od.id=rd.duty_id
  join public.matrix_roles_v2 nr
    on nr.matrix_version_id=v_draft_id and nr.logical_id=orole.logical_id
  join public.matrix_duties_v2 nd
    on nd.matrix_version_id=v_draft_id and nd.logical_id=od.logical_id
  where rd.matrix_version_id=v_active.id;

  insert into public.matrix_scenarios_v2(
    id,matrix_version_id,logical_id,code,name,description,color,is_default,active,
    sort_order,valid_from,valid_to,settings_overrides
  )
  select gen_random_uuid(),v_draft_id,s.logical_id,s.code,s.name,s.description,s.color,
    s.is_default,s.active,s.sort_order,s.valid_from,s.valid_to,s.settings_overrides
  from public.matrix_scenarios_v2 s where s.matrix_version_id=v_active.id;

  update public.matrix_scenarios_v2 child
  set parent_scenario_id=np.id
  from public.matrix_scenarios_v2 old_child
  join public.matrix_scenarios_v2 old_parent on old_parent.id=old_child.parent_scenario_id
  join public.matrix_scenarios_v2 np
    on np.matrix_version_id=v_draft_id and np.logical_id=old_parent.logical_id
  where child.matrix_version_id=v_draft_id
    and child.logical_id=old_child.logical_id
    and old_child.matrix_version_id=v_active.id;

  insert into public.matrix_staffing_rules_v2(
    id,matrix_version_id,scenario_id,shift_template_id,role_id,duty_id,
    operation,count_value,multiplier_basis_points,active,source_metadata
  )
  select gen_random_uuid(),v_draft_id,nsc.id,nsh.id,nr.id,nd.id,sr.operation,
    sr.count_value,sr.multiplier_basis_points,sr.active,sr.source_metadata
  from public.matrix_staffing_rules_v2 sr
  join public.matrix_scenarios_v2 osc on osc.id=sr.scenario_id
  join public.matrix_shift_templates_v2 osh on osh.id=sr.shift_template_id
  join public.matrix_roles_v2 orole on orole.id=sr.role_id
  left join public.matrix_duties_v2 od on od.id=sr.duty_id
  join public.matrix_scenarios_v2 nsc
    on nsc.matrix_version_id=v_draft_id and nsc.logical_id=osc.logical_id
  join public.matrix_shift_templates_v2 nsh
    on nsh.matrix_version_id=v_draft_id and nsh.logical_id=osh.logical_id
  join public.matrix_roles_v2 nr
    on nr.matrix_version_id=v_draft_id and nr.logical_id=orole.logical_id
  left join public.matrix_duties_v2 nd
    on nd.matrix_version_id=v_draft_id and nd.logical_id=od.logical_id
  where sr.matrix_version_id=v_active.id;

  insert into public.matrix_strategies_v2(
    id,matrix_version_id,logical_id,code,name,description,solver_code,solver_options,
    legacy_weights,sort_order,active
  )
  select gen_random_uuid(),v_draft_id,s.logical_id,s.code,s.name,s.description,
    s.solver_code,s.solver_options-array[
      'legacyPopulationSize','legacyGenerations','legacyMutationRate'
    ],s.legacy_weights,s.sort_order,s.active
  from public.matrix_strategies_v2 s where s.matrix_version_id=v_active.id;

  insert into public.matrix_strategy_objectives_v2(
    id,matrix_version_id,strategy_id,tier,sort_order,metric_code,direction,
    weight,tolerance,parameters,active
  )
  select gen_random_uuid(),v_draft_id,ns.id,o.tier,o.sort_order,o.metric_code,
    o.direction,o.weight,o.tolerance,o.parameters,o.active
  from public.matrix_strategy_objectives_v2 o
  join public.matrix_strategies_v2 os on os.id=o.strategy_id
  join public.matrix_strategies_v2 ns
    on ns.matrix_version_id=v_draft_id and ns.logical_id=os.logical_id
  where o.matrix_version_id=v_active.id;

  insert into public.matrix_scenario_strategies_v2(
    id,matrix_version_id,scenario_id,strategy_id,sort_order,active,
    objective_overrides,solver_overrides
  )
  select gen_random_uuid(),v_draft_id,nsc.id,nst.id,ss.sort_order,ss.active,
    ss.objective_overrides,ss.solver_overrides
  from public.matrix_scenario_strategies_v2 ss
  join public.matrix_scenarios_v2 osc on osc.id=ss.scenario_id
  join public.matrix_strategies_v2 ost on ost.id=ss.strategy_id
  join public.matrix_scenarios_v2 nsc
    on nsc.matrix_version_id=v_draft_id and nsc.logical_id=osc.logical_id
  join public.matrix_strategies_v2 nst
    on nst.matrix_version_id=v_draft_id and nst.logical_id=ost.logical_id
  where ss.matrix_version_id=v_active.id;

  insert into public.matrix_employee_roles_v2(
    id,matrix_version_id,employee_id,role_id,is_primary,can_lead,active,valid_from,valid_to
  )
  select gen_random_uuid(),v_draft_id,er.employee_id,nr.id,er.is_primary,er.can_lead,
    er.active,er.valid_from,er.valid_to
  from public.matrix_employee_roles_v2 er
  join public.matrix_roles_v2 old_role on old_role.id=er.role_id
  join public.matrix_roles_v2 nr
    on nr.matrix_version_id=v_draft_id and nr.logical_id=old_role.logical_id
  where er.matrix_version_id=v_active.id;

  insert into public.matrix_employee_locations_v2(
    id,matrix_version_id,employee_id,location_id,standard_allowed,overtime_allowed,
    home_location,active,valid_from,valid_to
  )
  select gen_random_uuid(),v_draft_id,el.employee_id,nl.id,el.standard_allowed,
    el.overtime_allowed,el.home_location,el.active,el.valid_from,el.valid_to
  from public.matrix_employee_locations_v2 el
  join public.matrix_locations_v2 old_location on old_location.id=el.location_id
  join public.matrix_locations_v2 nl
    on nl.matrix_version_id=v_draft_id and nl.logical_id=old_location.logical_id
  where el.matrix_version_id=v_active.id;

  insert into public.matrix_employee_duties_v2(
    id,matrix_version_id,employee_id,duty_id,role_id,location_id,active,
    valid_from,valid_to,source
  )
  select gen_random_uuid(),v_draft_id,ed.employee_id,nd.id,nr.id,nl.id,ed.active,
    ed.valid_from,ed.valid_to,ed.source
  from public.matrix_employee_duties_v2 ed
  join public.matrix_duties_v2 old_duty on old_duty.id=ed.duty_id
  left join public.matrix_roles_v2 old_role on old_role.id=ed.role_id
  left join public.matrix_locations_v2 old_location on old_location.id=ed.location_id
  join public.matrix_duties_v2 nd
    on nd.matrix_version_id=v_draft_id and nd.logical_id=old_duty.logical_id
  left join public.matrix_roles_v2 nr
    on nr.matrix_version_id=v_draft_id and nr.logical_id=old_role.logical_id
  left join public.matrix_locations_v2 nl
    on nl.matrix_version_id=v_draft_id and nl.logical_id=old_location.logical_id
  where ed.matrix_version_id=v_active.id;

  insert into public.matrix_pay_rules_v2(
    id,matrix_version_id,logical_id,code,name,description,calculation_method,
    amount_minor,rate_minor_per_hour,percent_basis_points,multiplier_basis_points,
    threshold_minutes,currency,priority,stacking_group,stacking_mode,day_mask,
    local_start,local_end,ends_next_day,valid_from,valid_to,condition_expression,
    formula_expression,active
  )
  select gen_random_uuid(),v_draft_id,p.logical_id,p.code,p.name,p.description,
    p.calculation_method,p.amount_minor,p.rate_minor_per_hour,p.percent_basis_points,
    p.multiplier_basis_points,p.threshold_minutes,p.currency,p.priority,p.stacking_group,
    p.stacking_mode,p.day_mask,p.local_start,p.local_end,p.ends_next_day,p.valid_from,
    p.valid_to,p.condition_expression,p.formula_expression,p.active
  from public.matrix_pay_rules_v2 p where p.matrix_version_id=v_active.id;

  insert into public.matrix_pay_rule_roles_v2(matrix_version_id,pay_rule_id,role_id)
  select v_draft_id,np.id,nr.id
  from public.matrix_pay_rule_roles_v2 x
  join public.matrix_pay_rules_v2 op on op.id=x.pay_rule_id
  join public.matrix_roles_v2 old_role on old_role.id=x.role_id
  join public.matrix_pay_rules_v2 np
    on np.matrix_version_id=v_draft_id and np.logical_id=op.logical_id
  join public.matrix_roles_v2 nr
    on nr.matrix_version_id=v_draft_id and nr.logical_id=old_role.logical_id
  where x.matrix_version_id=v_active.id;

  insert into public.matrix_pay_rule_duties_v2(matrix_version_id,pay_rule_id,duty_id,match_mode)
  select v_draft_id,np.id,nd.id,x.match_mode
  from public.matrix_pay_rule_duties_v2 x
  join public.matrix_pay_rules_v2 op on op.id=x.pay_rule_id
  join public.matrix_duties_v2 old_duty on old_duty.id=x.duty_id
  join public.matrix_pay_rules_v2 np
    on np.matrix_version_id=v_draft_id and np.logical_id=op.logical_id
  join public.matrix_duties_v2 nd
    on nd.matrix_version_id=v_draft_id and nd.logical_id=old_duty.logical_id
  where x.matrix_version_id=v_active.id;

  insert into public.matrix_pay_rule_locations_v2(matrix_version_id,pay_rule_id,location_id)
  select v_draft_id,np.id,nl.id
  from public.matrix_pay_rule_locations_v2 x
  join public.matrix_pay_rules_v2 op on op.id=x.pay_rule_id
  join public.matrix_locations_v2 old_location on old_location.id=x.location_id
  join public.matrix_pay_rules_v2 np
    on np.matrix_version_id=v_draft_id and np.logical_id=op.logical_id
  join public.matrix_locations_v2 nl
    on nl.matrix_version_id=v_draft_id and nl.logical_id=old_location.logical_id
  where x.matrix_version_id=v_active.id;

  insert into public.matrix_pay_rule_shifts_v2(matrix_version_id,pay_rule_id,shift_template_id)
  select v_draft_id,np.id,nsh.id
  from public.matrix_pay_rule_shifts_v2 x
  join public.matrix_pay_rules_v2 op on op.id=x.pay_rule_id
  join public.matrix_shift_templates_v2 old_shift on old_shift.id=x.shift_template_id
  join public.matrix_pay_rules_v2 np
    on np.matrix_version_id=v_draft_id and np.logical_id=op.logical_id
  join public.matrix_shift_templates_v2 nsh
    on nsh.matrix_version_id=v_draft_id and nsh.logical_id=old_shift.logical_id
  where x.matrix_version_id=v_active.id;

  insert into public.matrix_scenario_pay_rule_overrides_v2(
    id,matrix_version_id,scenario_id,pay_rule_id,enabled,amount_minor,
    rate_minor_per_hour,percent_basis_points,multiplier_basis_points,formula_expression
  )
  select gen_random_uuid(),v_draft_id,nsc.id,np.id,x.enabled,x.amount_minor,
    x.rate_minor_per_hour,x.percent_basis_points,x.multiplier_basis_points,x.formula_expression
  from public.matrix_scenario_pay_rule_overrides_v2 x
  join public.matrix_scenarios_v2 osc on osc.id=x.scenario_id
  join public.matrix_pay_rules_v2 op on op.id=x.pay_rule_id
  join public.matrix_scenarios_v2 nsc
    on nsc.matrix_version_id=v_draft_id and nsc.logical_id=osc.logical_id
  join public.matrix_pay_rules_v2 np
    on np.matrix_version_id=v_draft_id and np.logical_id=op.logical_id
  where x.matrix_version_id=v_active.id;

  insert into public.matrix_scenario_budgets_v2(
    id,matrix_version_id,scenario_id,budget_month,location_id,role_id,duty_id,
    operation,amount_minor,multiplier_basis_points,currency,hard_limit,
    warning_percent,source_metadata
  )
  select gen_random_uuid(),v_draft_id,nsc.id,b.budget_month,nl.id,nr.id,nd.id,
    b.operation,b.amount_minor,b.multiplier_basis_points,b.currency,b.hard_limit,
    b.warning_percent,b.source_metadata
  from public.matrix_scenario_budgets_v2 b
  join public.matrix_scenarios_v2 osc on osc.id=b.scenario_id
  left join public.matrix_locations_v2 ol on ol.id=b.location_id
  left join public.matrix_roles_v2 orole on orole.id=b.role_id
  left join public.matrix_duties_v2 od on od.id=b.duty_id
  join public.matrix_scenarios_v2 nsc
    on nsc.matrix_version_id=v_draft_id and nsc.logical_id=osc.logical_id
  left join public.matrix_locations_v2 nl
    on nl.matrix_version_id=v_draft_id and nl.logical_id=ol.logical_id
  left join public.matrix_roles_v2 nr
    on nr.matrix_version_id=v_draft_id and nr.logical_id=orole.logical_id
  left join public.matrix_duties_v2 nd
    on nd.matrix_version_id=v_draft_id and nd.logical_id=od.logical_id
  where b.matrix_version_id=v_active.id;

  return v_draft_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_discard_current_draft_uat_v2()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_draft public.matrix_versions%rowtype;
  v_active uuid;
  v_draft_count integer;
  v_active_count integer;
  v_decision text;
  v_ensured jsonb;
  v_ad_hoc_reconnected integer:=0;
  v_ad_hoc_removed integer:=0;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  if not (public.has_app_role('OWNER') or public.has_app_role('ADMIN')) then
    raise exception 'FORBIDDEN';
  end if;

  perform pg_advisory_xact_lock(hashtext('matrix-v2-lifecycle'));

  select count(*)::integer into v_draft_count
  from public.matrix_versions where status='DRAFT';
  select count(*)::integer into v_active_count
  from public.matrix_versions where status='ACTIVE';
  v_decision:=solver_private.matrix_v2_discard_decision_uat_v1(
    v_draft_count,v_active_count
  );

  if v_decision='MULTIPLE_DRAFTS' then
    raise exception 'MULTIPLE_MATRIX_DRAFTS_FOUND';
  end if;

  select * into v_draft
  from public.matrix_versions
  where status='DRAFT'
  order by version desc
  limit 1
  for update;

  select id into v_active
  from public.matrix_versions
  where status='ACTIVE'
  order by effective_from desc nulls last,version desc
  limit 1;

  if v_decision='ENSURE_FIRST_RUN' then
    v_ensured:=public.matrix_v2_ensure_first_run_uat_v1();
    return jsonb_build_object(
      'discarded',null,'alreadyDiscarded',true,
      'ensuredFirstRun',true,
      'activeMatrixVersionId',null,
      'draftMatrixVersionId',v_ensured->>'matrixVersionId'
    );
  end if;

  if v_decision='NOOP_ACTIVE' then
    return jsonb_build_object(
      'discarded',null,'alreadyDiscarded',true,
      'ensuredFirstRun',false,'activeMatrixVersionId',v_active
    );
  end if;

  if v_decision='PRESERVE_ONLY_DRAFT' then
    insert into public.audit_log(actor_id,entity_type,entity_id,action,old_data)
    values(auth.uid(),'matrix_version',v_draft.id::text,
      'B4F171_PRESERVE_ONLY_DRAFT',jsonb_build_object(
        'version',v_draft.version,'name',v_draft.name,
        'reason','NO_ACTIVE_CONFIGURATION'
      ));
    return jsonb_build_object(
      'discarded',null,'alreadyDiscarded',false,
      'preservedOnlyDraft',true,'ensuredFirstRun',false,
      'activeMatrixVersionId',null,'draftMatrixVersionId',v_draft.id
    );
  end if;

  if exists(
    select 1 from public.optimization_runs_v2 r
    where r.matrix_version_id=v_draft.id
  ) then
    raise exception 'DRAFT_ALREADY_USED_BY_GENERATOR';
  end if;

  insert into public.audit_log(actor_id,entity_type,entity_id,action,old_data)
  values(
    auth.uid(),'matrix_version',v_draft.id::text,'DISCARD_DRAFT',
    jsonb_build_object('version',v_draft.version,'name',v_draft.name)
  );

  update public.recovery_ad_hoc_pool_v2 pool
  set role_id=active_role.id,updated_at=now()
  from public.matrix_roles_v2 draft_role
  join public.matrix_roles_v2 active_role
    on active_role.matrix_version_id=v_active
   and active_role.logical_id=draft_role.logical_id
  where pool.role_id=draft_role.id
    and draft_role.matrix_version_id=v_draft.id;
  get diagnostics v_ad_hoc_reconnected=row_count;

  delete from public.recovery_ad_hoc_pool_v2 pool
  using public.matrix_roles_v2 draft_role
  where pool.role_id=draft_role.id
    and draft_role.matrix_version_id=v_draft.id;
  get diagnostics v_ad_hoc_removed=row_count;

  delete from public.matrix_versions where id=v_draft.id;

  if not exists(
    select 1 from public.matrix_versions mv
    where mv.status in ('DRAFT','ACTIVE')
  ) then
    raise exception 'B4F171_USABLE_MATRIX_REQUIRED_AFTER_DISCARD';
  end if;

  return jsonb_build_object(
    'discarded',v_draft.id,'alreadyDiscarded',false,
    'preservedOnlyDraft',false,'ensuredFirstRun',false,
    'activeMatrixVersionId',v_active,
    'adHocRowsReconnected',v_ad_hoc_reconnected,
    'adHocRowsRemoved',v_ad_hoc_removed
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_discard_draft_uat_v1(p_matrix_version_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_draft public.matrix_versions%rowtype;
  v_active uuid;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  if not (public.has_app_role('OWNER') or public.has_app_role('ADMIN')) then
    raise exception 'FORBIDDEN';
  end if;
  perform pg_advisory_xact_lock(hashtext('matrix-v2-lifecycle'));
  select * into v_draft from public.matrix_versions
    where id=p_matrix_version_id for update;
  if v_draft.id is null then raise exception 'MATRIX_VERSION_NOT_FOUND'; end if;
  if v_draft.status<>'DRAFT' then raise exception 'ONLY_DRAFT_CAN_BE_DISCARDED'; end if;
  if exists(select 1 from public.optimization_runs_v2 r where r.matrix_version_id=v_draft.id) then
    raise exception 'DRAFT_ALREADY_USED_BY_GENERATOR';
  end if;

  insert into public.audit_log(actor_id,entity_type,entity_id,action,old_data)
  values(auth.uid(),'matrix_version',v_draft.id::text,'DISCARD_DRAFT',
    jsonb_build_object('version',v_draft.version,'name',v_draft.name));
  delete from public.matrix_versions where id=v_draft.id;
  select id into v_active from public.matrix_versions
    where status='ACTIVE' order by effective_from desc nulls last,version desc limit 1;
  return jsonb_build_object('discarded',v_draft.id,'activeMatrixVersionId',v_active);
end;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_duty_archive_preview_uat_v2(p_duty_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_matrix uuid;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  if not (public.has_app_role('OWNER') or public.has_app_role('ADMIN')) then
    raise exception 'FORBIDDEN';
  end if;
  select duty.matrix_version_id into v_matrix
  from public.matrix_duties_v2 duty where duty.id=p_duty_id;
  if v_matrix is null then raise exception 'DUTY_NOT_FOUND'; end if;
  return jsonb_build_object(
    'dutyId',p_duty_id,
    'roleDuties',(select count(*) from public.matrix_role_duties_v2 link
      where link.matrix_version_id=v_matrix and link.duty_id=p_duty_id and link.active),
    'employeeDuties',(select count(*) from public.matrix_employee_duties_v2 link
      where link.matrix_version_id=v_matrix and link.duty_id=p_duty_id and link.active),
    'staffingRules',(select count(*) from public.matrix_staffing_rules_v2 rule
      where rule.matrix_version_id=v_matrix and rule.duty_id=p_duty_id and rule.active),
    'payRules',(select count(*) from public.matrix_pay_rule_duties_v2 link
      where link.matrix_version_id=v_matrix and link.duty_id=p_duty_id)
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_duty_archive_uat_v2(p_duty_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_duty public.matrix_duties_v2%rowtype;
  v_role_duties integer:=0; v_employee_duties integer:=0;
  v_staffing_rules integer:=0; v_pay_rules integer:=0;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  if not (public.has_app_role('OWNER') or public.has_app_role('ADMIN')) then
    raise exception 'FORBIDDEN';
  end if;
  if length(trim(coalesce(p_reason,'')))<5 then raise exception 'ARCHIVE_REASON_REQUIRED'; end if;
  perform pg_advisory_xact_lock(hashtext('matrix-v2-lifecycle'));
  select duty.* into v_duty from public.matrix_duties_v2 duty
  join public.matrix_versions version on version.id=duty.matrix_version_id
  where duty.id=p_duty_id and version.status='DRAFT' for update of duty;
  if v_duty.id is null then raise exception 'DRAFT_DUTY_NOT_FOUND'; end if;
  if not v_duty.active then raise exception 'DUTY_ALREADY_ARCHIVED'; end if;

  update public.matrix_role_duties_v2 set active=false
    where matrix_version_id=v_duty.matrix_version_id and duty_id=p_duty_id and active;
  get diagnostics v_role_duties=row_count;
  update public.matrix_employee_duties_v2 set active=false
    where matrix_version_id=v_duty.matrix_version_id and duty_id=p_duty_id and active;
  get diagnostics v_employee_duties=row_count;
  update public.matrix_staffing_rules_v2 set active=false
    where matrix_version_id=v_duty.matrix_version_id and duty_id=p_duty_id and active;
  get diagnostics v_staffing_rules=row_count;
  delete from public.matrix_pay_rule_duties_v2
    where matrix_version_id=v_duty.matrix_version_id and duty_id=p_duty_id;
  get diagnostics v_pay_rules=row_count;
  update public.matrix_duties_v2 set active=false where id=p_duty_id;

  insert into public.audit_log(actor_id,entity_type,entity_id,action,old_data,new_data)
  values(auth.uid(),'matrix_v2_duty',p_duty_id::text,'ARCHIVE_WITH_DEPENDENCIES',
    to_jsonb(v_duty),jsonb_build_object('active',false,'reason',trim(p_reason),
      'roleDutiesDeactivated',v_role_duties,'employeeDutiesDeactivated',v_employee_duties,
      'staffingRulesDeactivated',v_staffing_rules,'payRuleLinksRemoved',v_pay_rules));
  return jsonb_build_object('dutyId',p_duty_id,'archived',true,
    'roleDutiesDeactivated',v_role_duties,'employeeDutiesDeactivated',v_employee_duties,
    'staffingRulesDeactivated',v_staffing_rules,'payRuleLinksRemoved',v_pay_rules);
end;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_employee_archive_v2(p_employee_id uuid, p_reason text DEFAULT NULL::text, p_archive boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_matrix uuid;
  v_profile public.matrix_employee_profiles_v2%rowtype;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  if not (public.has_app_role('OWNER') or public.has_app_role('ADMIN')
    or public.has_app_role('HR_FINANCE')) then raise exception 'FORBIDDEN'; end if;
  perform pg_advisory_xact_lock(hashtext('matrix-v2-lifecycle'));
  if p_employee_id is null then raise exception 'EMPLOYEE_REQUIRED'; end if;
  select mv.id into v_matrix
  from public.matrix_versions mv
  where mv.status='DRAFT' and mv.schema_version>=2
  order by mv.version desc limit 1 for update;
  if v_matrix is null then raise exception 'NO_MATRIX_V2_DRAFT'; end if;
  select * into v_profile from public.matrix_employee_profiles_v2 p
  where p.matrix_version_id=v_matrix and p.employee_id=p_employee_id for update;
  if v_profile.id is null then raise exception 'MATRIX_EMPLOYEE_NOT_FOUND'; end if;

  update public.matrix_employee_profiles_v2 set
    active=not p_archive,
    archived_at=case when p_archive then now() else null end,
    archived_by=case when p_archive then auth.uid() else null end,
    archive_reason=case when p_archive then nullif(trim(p_reason),'') else null end,
    updated_by=auth.uid(),updated_at=now()
  where id=v_profile.id returning * into v_profile;

  insert into public.audit_log(actor_id,entity_type,entity_id,action,new_data)
  values(auth.uid(),'matrix_v2_employee',p_employee_id::text,
    case when p_archive then 'ARCHIVE' else 'RESTORE' end,
    jsonb_build_object('matrixVersionId',v_matrix,'reason',
      case when p_archive then nullif(trim(p_reason),'') else null end));
  return jsonb_build_object('id',p_employee_id,'active',v_profile.active,
    'matrixVersionId',v_matrix);
end;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_employee_directory_alpha16(p_month date DEFAULT CURRENT_DATE)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_directory jsonb;
  v_matrix uuid;
  v_month date:=date_trunc('month',coalesce(p_month,current_date))::date;
  v_employees jsonb;
begin
  v_directory:=public.matrix_v2_employee_directory_v2();
  v_matrix:=(v_directory->>'matrixVersionId')::uuid;
  select coalesce(jsonb_agg(
    employee.value || jsonb_build_object(
      'locationIds',coalesce((select jsonb_agg(location_grant.location_id::text
        order by location_grant.location_id::text)
        from public.matrix_employee_locations_v2 location_grant
        where location_grant.matrix_version_id=v_matrix
          and location_grant.employee_id=(employee.value->>'id')::uuid
          and location_grant.standard_allowed and location_grant.active
      ),'[]'::jsonb),
      'shiftPeriodPreferences',coalesce((select jsonb_object_agg(
        upper(preference.preference_value->>'period'),
        upper(preference.preference_value->>'level')
      ) from public.employee_preferences preference
        where preference.employee_id=(employee.value->>'id')::uuid
          and preference.preference_type='PREFERRED_SHIFT'
          and preference.source='MANAGER' and preference.status='ACTIVE'
          and preference.preference_value->>'matrixVersionId'=v_matrix::text
          and preference.valid_from<v_month+interval '1 month'
          and preference.valid_to>=v_month
      ),'{}'::jsonb)
    ) order by employee.ordinality
  ),'[]'::jsonb) into v_employees
  from jsonb_array_elements(coalesce(v_directory->'employees','[]'::jsonb))
    with ordinality employee(value,ordinality);
  return jsonb_set(v_directory,'{employees}',v_employees,true);
end;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_employee_directory_v2()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_matrix uuid;
  v_manage boolean;
  v_owner_admin boolean;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  v_owner_admin:=public.has_app_role('OWNER') or public.has_app_role('ADMIN');
  v_manage:=v_owner_admin or public.has_app_role('HR_FINANCE');
  if v_owner_admin then
    select mv.id into v_matrix from public.matrix_versions mv
    where mv.status='DRAFT' and mv.schema_version>=2
    order by mv.version desc limit 1;
  end if;
  if v_matrix is null then
    select mv.id into v_matrix from public.matrix_versions mv
    where mv.status='ACTIVE' and mv.schema_version>=2
    order by mv.version desc limit 1;
  end if;
  if v_matrix is null then raise exception 'MATRIX_V2_NOT_FOUND'; end if;

  return jsonb_build_object(
    'matrixVersionId',v_matrix,
    'workforceHash',(select mv.workforce_hash from public.matrix_versions mv
      where mv.id=v_matrix),
    'activeCount',(select count(*) from public.matrix_employee_profiles_v2 p
      where p.matrix_version_id=v_matrix and p.active),
    'archivedCount',(select count(*) from public.matrix_employee_profiles_v2 p
      where p.matrix_version_id=v_matrix and not p.active),
    'employees',coalesce((select jsonb_agg(jsonb_build_object(
      'id',p.employee_id,'profileId',p.id,'employeeNo',p.employee_no,
      'firstName',p.first_name,'lastName',p.last_name,
      'email',case when v_manage or e.auth_user_id=auth.uid() then p.email else null end,
      'active',p.active,'employmentStart',p.employment_start,
      'employmentEnd',p.employment_end,
      'nominalMonthlyMinutes',p.nominal_monthly_minutes,
      'maximumMonthlyMinutes',p.maximum_monthly_minutes,
      'maximumWeeklyMinutes',p.maximum_weekly_minutes,
      'maximumConsecutiveDays',p.maximum_consecutive_days,
      'minimumRestMinutes',p.minimum_rest_minutes,
      'onlyMorning',p.only_morning,'onlyEvening',p.only_evening,
      'noWeekends',p.no_weekends,'preferredShiftCode',p.preferred_shift_code,
      'archivedAt',p.archived_at,'archiveReason',p.archive_reason,
      'primaryRoleId',(select er.role_id from public.matrix_employee_roles_v2 er
        where er.matrix_version_id=v_matrix and er.employee_id=p.employee_id
          and er.is_primary and er.active order by er.created_at limit 1),
      'homeLocationId',(select el.location_id from public.matrix_employee_locations_v2 el
        where el.matrix_version_id=v_matrix and el.employee_id=p.employee_id
          and el.home_location and el.active order by el.created_at limit 1)
    ) order by p.active desc,p.last_name,p.first_name,p.employee_no)
    from public.matrix_employee_profiles_v2 p
    join public.employees e on e.id=p.employee_id
    where p.matrix_version_id=v_matrix
      and (v_manage or e.auth_user_id=auth.uid())),'[]'::jsonb)
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_employee_save_alpha16(p_employee_id uuid DEFAULT NULL::uuid, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_matrix uuid;
  v_employee uuid:=p_employee_id;
  v_result jsonb;
  v_payload jsonb:=coalesce(p_data,'{}'::jsonb);
  v_employee_no text;
  v_location uuid;
  v_period text;
  v_level text;
  v_month date:=date_trunc('month',coalesce(
    nullif(v_payload->>'preferenceMonth','')::date,current_date
  ))::date;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  if not (public.has_app_role('OWNER') or public.has_app_role('ADMIN')
    or public.has_app_role('HR_FINANCE')) then raise exception 'FORBIDDEN'; end if;
  perform pg_advisory_xact_lock(hashtext('matrix-v2-lifecycle'));
  select mv.id into v_matrix from public.matrix_versions mv
  where mv.status='DRAFT' and mv.schema_version>=2
  order by mv.version desc limit 1 for update;
  if v_matrix is null then raise exception 'NO_MATRIX_V2_DRAFT'; end if;

  if v_employee is null then
    v_employee_no:=public.matrix_v2_next_employee_no_v2();
    v_payload:=jsonb_set(v_payload,'{employeeNo}',to_jsonb(v_employee_no),true);
  else
    select profile.employee_no into v_employee_no
    from public.matrix_employee_profiles_v2 profile
    where profile.matrix_version_id=v_matrix and profile.employee_id=v_employee;
    v_payload:=jsonb_set(v_payload,'{employeeNo}',to_jsonb(v_employee_no),true);
  end if;
  -- The compatibility field is explicitly cleared. Standard locations below
  -- are the only location source used by the solver.
  v_payload:=jsonb_set(v_payload,'{homeLocationId}','null'::jsonb,true);
  v_result:=public.matrix_v2_employee_save_v2(v_employee,v_payload);
  v_employee:=(v_result->>'id')::uuid;

  if v_payload ? 'locationIds' then
    if jsonb_typeof(v_payload->'locationIds')<>'array'
      or jsonb_array_length(v_payload->'locationIds')=0 then
      raise exception 'ACTIVE_EMPLOYEE_REQUIRES_STANDARD_LOCATION';
    end if;
    update public.matrix_employee_locations_v2 location_grant
    set standard_allowed=false,home_location=false,active=false
    where location_grant.matrix_version_id=v_matrix
      and location_grant.employee_id=v_employee;
    for v_location in
      select distinct item.value::text::uuid
      from jsonb_array_elements_text(v_payload->'locationIds') item(value)
    loop
      if not exists(select 1 from public.matrix_locations_v2 location_row
        where location_row.id=v_location and location_row.matrix_version_id=v_matrix
          and location_row.active) then raise exception 'LOCATION_NOT_IN_MATRIX_V2'; end if;
      insert into public.matrix_employee_locations_v2(
        matrix_version_id,employee_id,location_id,standard_allowed,
        overtime_allowed,home_location,active
      ) values(v_matrix,v_employee,v_location,true,false,false,true)
      on conflict(matrix_version_id,employee_id,location_id) do update set
        standard_allowed=true,home_location=false,active=true;
    end loop;
  end if;

  if v_payload ? 'shiftPeriodPreferences' then
    if jsonb_typeof(v_payload->'shiftPeriodPreferences')<>'object' then
      raise exception 'INVALID_SHIFT_PERIOD_PREFERENCES';
    end if;
    update public.employee_preferences preference
    set status='CANCELLED'
    where preference.employee_id=v_employee
      and preference.preference_type='PREFERRED_SHIFT'
      and preference.source='MANAGER'
      and coalesce(preference.preference_value->>'matrixVersionId','')=v_matrix::text
      and preference.status='ACTIVE';
    foreach v_period in array array['MORNING','MIDDLE','EVENING'] loop
      v_level:=upper(coalesce(
        v_payload->'shiftPeriodPreferences'->>v_period,'INHERIT'
      ));
      if v_level not in ('INHERIT','PREFERRED','NEUTRAL','AVOIDED','BLOCKED') then
        raise exception 'INVALID_SHIFT_PREFERENCE_LEVEL';
      end if;
      if v_level<>'INHERIT' then
        insert into public.employee_preferences(
          employee_id,valid_from,valid_to,preference_type,preference_value,
          source,editable_by_employee,status
        ) values(
          v_employee,v_month,(v_month+interval '1 month - 1 day')::date,
          'PREFERRED_SHIFT',jsonb_build_object(
            'period',v_period,'level',v_level,'matrixVersionId',v_matrix
          ),'MANAGER',false,'ACTIVE'
        );
      end if;
    end loop;
    update public.matrix_employee_profiles_v2 profile set
      only_morning=false,only_evening=false,preferred_shift_code=null,
      updated_by=auth.uid(),updated_at=now()
    where profile.matrix_version_id=v_matrix and profile.employee_id=v_employee;
  end if;

  return v_result||jsonb_build_object('employeeNo',v_employee_no);
end;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_employee_save_uat_v3(p_employee_id uuid DEFAULT NULL::uuid, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_start date;
  v_end date;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  if not (public.has_app_role('OWNER') or public.has_app_role('ADMIN')
    or public.has_app_role('HR_FINANCE')) then raise exception 'FORBIDDEN'; end if;
  if nullif(p_data->>'employmentStart','') is not null
    and not pg_catalog.pg_input_is_valid(p_data->>'employmentStart','date') then
    raise exception 'INVALID_EMPLOYMENT_DATES';
  end if;
  if nullif(p_data->>'employmentEnd','') is not null
    and not pg_catalog.pg_input_is_valid(p_data->>'employmentEnd','date') then
    raise exception 'INVALID_EMPLOYMENT_DATES';
  end if;
  v_start:=nullif(p_data->>'employmentStart','')::date;
  v_end:=nullif(p_data->>'employmentEnd','')::date;
  if v_end is not null and (v_start is null or v_end<v_start) then
    raise exception 'INVALID_EMPLOYMENT_DATES';
  end if;
  if p_employee_id is not null and exists(
    select 1 from public.employee_pay_rates_v2 rate
    where rate.employee_id=p_employee_id and (
      (v_start is not null and rate.valid_from<v_start)
      or (v_end is not null and (
        rate.valid_from>v_end or rate.valid_to is null or rate.valid_to>v_end
      ))
    )
  ) then raise exception 'EMPLOYMENT_DATES_CONFLICT_PAY_RATES'; end if;
  return public.matrix_v2_employee_save_uat_v2(p_employee_id,p_data);
end;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_employee_save_uat_v4(p_employee_id uuid DEFAULT NULL::uuid, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_result jsonb;
  v_employee uuid;
  v_matrix uuid;
  v_stage text;
  v_overtime_policy text;
  v_contract text;
  v_fraction numeric;
  v_work_time_policy text;
  v_start date;
  v_end date;
begin
  if nullif(p_data->>'employmentStart','') is not null
    and not pg_catalog.pg_input_is_valid(p_data->>'employmentStart','date') then
    raise exception 'INVALID_EMPLOYMENT_DATES';
  end if;
  if nullif(p_data->>'employmentEnd','') is not null
    and not pg_catalog.pg_input_is_valid(p_data->>'employmentEnd','date') then
    raise exception 'INVALID_EMPLOYMENT_DATES';
  end if;
  v_start:=nullif(p_data->>'employmentStart','')::date;
  v_end:=nullif(p_data->>'employmentEnd','')::date;
  if v_end is not null and (v_start is null or v_end<v_start) then
    raise exception 'INVALID_EMPLOYMENT_DATES';
  end if;
  if p_employee_id is not null and exists(
    select 1 from public.employee_pay_rates_v2 rate
    where rate.employee_id=p_employee_id and (
      (v_start is not null and rate.valid_from<v_start)
      or (v_end is not null and (
        rate.valid_from>v_end or rate.valid_to is null or rate.valid_to>v_end
      ))
    )
  ) then raise exception 'EMPLOYMENT_DATES_CONFLICT_PAY_RATES'; end if;
  v_result := public.matrix_v2_employee_save_alpha16(p_employee_id, p_data);
  v_employee := (v_result->>'id')::uuid;
  select id into v_matrix from public.matrix_versions
    where status = 'DRAFT' and schema_version >= 2
    order by version desc limit 1;
  v_stage := case upper(coalesce(nullif(p_data->>'employmentStage',''),'REGULAR'))
    when 'PROBATION' then 'PROBATION'
    when 'NOTICE' then 'NOTICE'
    else 'REGULAR' end;
  v_overtime_policy := upper(coalesce(nullif(p_data->>'overtimePolicy',''),'NEVER'));
  if v_overtime_policy not in ('NEVER','APPROVAL_REQUIRED','ALLOWED') then
    raise exception 'INVALID_OVERTIME_POLICY';
  end if;
  if p_data ? 'contractType' then
    v_contract:=solver_private.normalize_contract_type_v2(p_data->>'contractType');
    v_fraction:=greatest(.01,least(1,coalesce(
      nullif(replace(p_data->>'employmentFraction',',','.'),'')::numeric,1
    )));
    insert into public.employee_hr_profiles(
      employee_id,contract_type,employment_fraction,updated_by,updated_at
    ) values(v_employee,v_contract,v_fraction,auth.uid(),now())
    on conflict(employee_id) do update set
      contract_type=excluded.contract_type,
      employment_fraction=excluded.employment_fraction,
      updated_by=auth.uid(),updated_at=now();
  end if;
  if p_data ? 'workTimePolicy' then
    v_work_time_policy:=case when upper(coalesce(p_data->>'workTimePolicy',''))='CUSTOM'
      then 'CUSTOM' else 'CONTRACT_DEFAULT' end;
  else
    select profile.work_time_policy into v_work_time_policy
    from public.matrix_employee_profiles_v2 profile
    where profile.employee_id=v_employee and profile.matrix_version_id=v_matrix;
    v_work_time_policy:=coalesce(v_work_time_policy,'CONTRACT_DEFAULT');
  end if;
  update public.matrix_employee_profiles_v2 set
    employment_stage = v_stage,
    probation_end = nullif(p_data->>'probationEnd','')::date,
    overtime_policy = v_overtime_policy,
    work_time_policy = v_work_time_policy,
    updated_by = auth.uid(),
    updated_at = now()
  where matrix_version_id = v_matrix and employee_id = v_employee;
  return v_result || jsonb_build_object(
    'employmentStage', v_stage,
    'probationEnd', nullif(p_data->>'probationEnd',''),
    'overtimePolicy', v_overtime_policy,
    'contractType',coalesce(v_contract,(select profile.contract_type
      from public.employee_hr_profiles profile where profile.employee_id=v_employee)),
    'workTimePolicy',v_work_time_policy
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_employee_save_v2(p_employee_id uuid DEFAULT NULL::uuid, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_matrix uuid;
  v_profile public.matrix_employee_profiles_v2%rowtype;
  v_employee_id uuid:=p_employee_id;
  v_employee_no text;
  v_first_name text;
  v_last_name text;
  v_email text;
  v_start date;
  v_end date;
  v_nominal integer;
  v_max_monthly integer;
  v_max_weekly integer;
  v_max_consecutive integer;
  v_minimum_rest integer;
  v_only_morning boolean;
  v_only_evening boolean;
  v_no_weekends boolean;
  v_preferred_shift text;
  v_primary_role uuid;
  v_home_location uuid;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  if not (public.has_app_role('OWNER') or public.has_app_role('ADMIN')
    or public.has_app_role('HR_FINANCE')) then raise exception 'FORBIDDEN'; end if;
  perform pg_advisory_xact_lock(hashtext('matrix-v2-lifecycle'));
  if p_data is null or jsonb_typeof(p_data)<>'object' then
    raise exception 'INVALID_EMPLOYEE_PAYLOAD';
  end if;

  select mv.id into v_matrix
  from public.matrix_versions mv
  where mv.status='DRAFT' and mv.schema_version>=2
  order by mv.version desc limit 1 for update;
  if v_matrix is null then raise exception 'NO_MATRIX_V2_DRAFT'; end if;

  if v_employee_id is not null then
    select * into v_profile
    from public.matrix_employee_profiles_v2 p
    where p.matrix_version_id=v_matrix and p.employee_id=v_employee_id
    for update;
    if v_profile.id is null then raise exception 'MATRIX_EMPLOYEE_NOT_FOUND'; end if;
  end if;

  v_employee_no:=coalesce(nullif(trim(p_data->>'employeeNo'),''),v_profile.employee_no);
  v_first_name:=coalesce(nullif(trim(p_data->>'firstName'),''),v_profile.first_name);
  v_last_name:=coalesce(nullif(trim(p_data->>'lastName'),''),v_profile.last_name);
  v_email:=case when p_data ? 'email'
    then nullif(lower(trim(p_data->>'email')),'') else v_profile.email end;
  v_start:=case when p_data ? 'employmentStart'
    then nullif(p_data->>'employmentStart','')::date else v_profile.employment_start end;
  v_end:=case when p_data ? 'employmentEnd'
    then nullif(p_data->>'employmentEnd','')::date else v_profile.employment_end end;
  v_nominal:=coalesce(nullif(p_data->>'nominalMonthlyMinutes','')::integer,
    v_profile.nominal_monthly_minutes);
  v_max_monthly:=coalesce(nullif(p_data->>'maximumMonthlyMinutes','')::integer,
    v_profile.maximum_monthly_minutes);
  v_max_weekly:=coalesce(nullif(p_data->>'maximumWeeklyMinutes','')::integer,
    v_profile.maximum_weekly_minutes);
  v_max_consecutive:=coalesce(
    nullif(p_data->>'maximumConsecutiveDays','')::integer,
    v_profile.maximum_consecutive_days
  );
  v_minimum_rest:=case when p_data ? 'minimumRestMinutes'
    then nullif(p_data->>'minimumRestMinutes','')::integer
    else v_profile.minimum_rest_minutes end;
  v_only_morning:=case when p_data ? 'onlyMorning'
    then (p_data->>'onlyMorning')::boolean else coalesce(v_profile.only_morning,false) end;
  v_only_evening:=case when p_data ? 'onlyEvening'
    then (p_data->>'onlyEvening')::boolean else coalesce(v_profile.only_evening,false) end;
  v_no_weekends:=case when p_data ? 'noWeekends'
    then (p_data->>'noWeekends')::boolean else coalesce(v_profile.no_weekends,false) end;
  v_preferred_shift:=case when p_data ? 'preferredShiftCode'
    then nullif(trim(p_data->>'preferredShiftCode'),'') else v_profile.preferred_shift_code end;
  v_primary_role:=nullif(p_data->>'primaryRoleId','')::uuid;
  v_home_location:=nullif(p_data->>'homeLocationId','')::uuid;

  if v_employee_no is null or v_first_name is null or v_last_name is null then
    raise exception 'EMPLOYEE_IDENTITY_REQUIRED';
  end if;
  if v_end is not null and v_start is not null and v_end<v_start then
    raise exception 'INVALID_EMPLOYMENT_DATES';
  end if;
  if v_nominal is null or v_max_monthly is null or v_max_weekly is null
    or v_max_consecutive is null
    or v_nominal not between 0 and 44640
    or v_max_monthly not between v_nominal and 44640
    or v_max_weekly not between 0 and 10080
    or v_max_consecutive not between 1 and 31
    or (v_minimum_rest is not null and v_minimum_rest not between 0 and 2880)
    or (v_only_morning and v_only_evening) then
    raise exception 'INVALID_EMPLOYEE_LIMITS';
  end if;
  if exists(select 1 from public.employees e
      where e.employee_no=v_employee_no and e.id is distinct from v_employee_id) then
    raise exception 'EMPLOYEE_NUMBER_ALREADY_EXISTS';
  end if;
  if v_email is not null and exists(select 1 from public.employees e
      where lower(e.email)=v_email and e.id is distinct from v_employee_id) then
    raise exception 'EMPLOYEE_EMAIL_ALREADY_EXISTS';
  end if;

  if v_employee_id is null then
    insert into public.employees(
      employee_no,first_name,last_name,email,primary_role,
      monthly_nominal_minutes,max_weekly_minutes,max_monthly_minutes,
      max_consecutive_days,minimum_rest_minutes,only_morning,only_evening,
      no_weekends,preferred_shift,active,employment_start,employment_end
    ) values(
      v_employee_no,v_first_name,v_last_name,v_email,null,
      v_nominal,v_max_weekly,v_max_monthly,v_max_consecutive,v_minimum_rest,
      v_only_morning,v_only_evening,v_no_weekends,v_preferred_shift,false,
      v_start,v_end
    ) returning id into v_employee_id;

    insert into public.matrix_employee_profiles_v2(
      matrix_version_id,employee_id,employee_no,first_name,last_name,email,
      active,employment_start,employment_end,nominal_monthly_minutes,
      maximum_monthly_minutes,maximum_weekly_minutes,maximum_consecutive_days,
      minimum_rest_minutes,only_morning,only_evening,no_weekends,
      preferred_shift_code,created_by,updated_by
    ) values(
      v_matrix,v_employee_id,v_employee_no,v_first_name,v_last_name,v_email,
      true,v_start,v_end,v_nominal,v_max_monthly,v_max_weekly,v_max_consecutive,
      v_minimum_rest,v_only_morning,v_only_evening,v_no_weekends,
      v_preferred_shift,auth.uid(),auth.uid()
    ) returning * into v_profile;
  else
    update public.matrix_employee_profiles_v2 set
      employee_no=v_employee_no,first_name=v_first_name,last_name=v_last_name,
      email=v_email,employment_start=v_start,employment_end=v_end,
      nominal_monthly_minutes=v_nominal,maximum_monthly_minutes=v_max_monthly,
      maximum_weekly_minutes=v_max_weekly,
      maximum_consecutive_days=v_max_consecutive,
      minimum_rest_minutes=v_minimum_rest,only_morning=v_only_morning,
      only_evening=v_only_evening,no_weekends=v_no_weekends,
      preferred_shift_code=v_preferred_shift,updated_by=auth.uid(),updated_at=now()
    where id=v_profile.id returning * into v_profile;
  end if;

  if p_data ? 'primaryRoleId' then
    update public.matrix_employee_roles_v2 set is_primary=false
    where matrix_version_id=v_matrix and employee_id=v_employee_id and is_primary;
    if v_primary_role is not null then
      if not exists(select 1 from public.matrix_roles_v2 r
          where r.id=v_primary_role and r.matrix_version_id=v_matrix and r.active) then
        raise exception 'ROLE_NOT_IN_MATRIX_V2';
      end if;
      insert into public.matrix_employee_roles_v2(
        matrix_version_id,employee_id,role_id,is_primary,can_lead,active
      ) values(v_matrix,v_employee_id,v_primary_role,true,false,true)
      on conflict(matrix_version_id,employee_id,role_id) do update set
        is_primary=true,active=true;
    end if;
  end if;

  if p_data ? 'homeLocationId' then
    update public.matrix_employee_locations_v2 set home_location=false
    where matrix_version_id=v_matrix and employee_id=v_employee_id and home_location;
    if v_home_location is not null then
      if not exists(select 1 from public.matrix_locations_v2 l
          where l.id=v_home_location and l.matrix_version_id=v_matrix and l.active) then
        raise exception 'LOCATION_NOT_IN_MATRIX_V2';
      end if;
      insert into public.matrix_employee_locations_v2(
        matrix_version_id,employee_id,location_id,standard_allowed,
        overtime_allowed,home_location,active
      ) values(v_matrix,v_employee_id,v_home_location,true,false,true,true)
      on conflict(matrix_version_id,employee_id,location_id) do update set
        standard_allowed=true,home_location=true,active=true;
    end if;
  end if;

  insert into public.audit_log(actor_id,entity_type,entity_id,action,new_data)
  values(auth.uid(),'matrix_v2_employee',v_employee_id::text,'UPSERT',
    jsonb_build_object('matrixVersionId',v_matrix,'employeeNo',v_employee_no,
      'active',v_profile.active,'employmentStart',v_start,'employmentEnd',v_end));
  return jsonb_build_object('id',v_employee_id,'profileId',v_profile.id,
    'matrixVersionId',v_matrix);
end;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_ensure_first_run_uat_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid:=auth.uid();
  v_matrix uuid;
begin
  if v_actor is null then raise exception 'AUTH_REQUIRED'; end if;
  if not (public.has_app_role('OWNER') or public.has_app_role('ADMIN')) then
    raise exception 'FORBIDDEN';
  end if;

  perform pg_advisory_xact_lock(hashtext('matrix-v2-lifecycle'));

  select mv.id into v_matrix
  from public.matrix_versions mv
  where mv.status in ('DRAFT','ACTIVE')
  order by (mv.status='DRAFT') desc,mv.version desc
  limit 1;

  if v_matrix is not null then
    return jsonb_build_object(
      'created',false,'matrixVersionId',v_matrix,'reason','USABLE_MATRIX_EXISTS'
    );
  end if;

  v_matrix:=solver_private.matrix_v2_create_safe_first_run_uat_v1(v_actor);
  return jsonb_build_object(
    'created',true,'matrixVersionId',v_matrix,'reason','SAFE_FIRST_RUN_CREATED'
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_finance_import_apply_uat_v1(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET statement_timeout TO '60s'
 SET lock_timeout TO '60s'
AS $function$
declare
  v_preview jsonb;
  v_row jsonb;
  v_rate_id uuid;
  v_applied integer:=0;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  if not (public.has_app_role('OWNER') or public.has_app_role('ADMIN')
    or public.has_app_role('HR_FINANCE')) then raise exception 'FORBIDDEN'; end if;
  perform pg_advisory_xact_lock(hashtext('matrix-v2-lifecycle'));
  v_preview:=public.matrix_v2_finance_import_preview_uat_v1(p_payload);
  if not coalesce((v_preview->>'valid')::boolean,false) then
    raise exception 'FINANCE_IMPORT_HAS_ERRORS';
  end if;

  -- Temporarily deactivate every changed existing row. This allows two
  -- adjacent periods to exchange dates without a transient overlap failure.
  update public.employee_pay_rates_v2 rate set active=false,updated_at=now(),updated_by=auth.uid()
  where rate.id in (
    select (value->>'rateId')::uuid from jsonb_array_elements(v_preview->'normalizedRows')
    where value->>'action' in ('UPDATE','DEACTIVATE')
      and nullif(value->>'rateId','') is not null
  );

  for v_row in select value from jsonb_array_elements(v_preview->'normalizedRows') loop
    if v_row->>'action'='UNCHANGED' then continue; end if;
    v_rate_id:=public.employee_pay_rate_save_v2(
      nullif(v_row->>'rateId','')::uuid,
      (v_row->>'employeeId')::uuid,
      (v_row->>'validFrom')::date,
      nullif(v_row->>'validTo','')::date,
      (v_row->>'baseRateMinor')::bigint,
      v_row->>'currency',v_row->>'contractType',(v_row->>'active')::boolean
    );
    v_applied:=v_applied+1;
  end loop;

  insert into public.audit_log(actor_id,entity_type,entity_id,action,new_data)
  values(auth.uid(),'matrix_v2_employee_finance',v_preview->>'matrixVersionId',
    'BULK_IMPORT',jsonb_build_object('rows',v_applied,
      'employees',v_preview#>>'{summary,employees}',
      'created',v_preview#>>'{summary,create}',
      'updated',v_preview#>>'{summary,update}',
      'deactivated',v_preview#>>'{summary,deactivate}'));
  return jsonb_build_object('appliedRows',v_applied,'summary',v_preview->'summary');
end;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_finance_import_preview_uat_v1(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
 SET statement_timeout TO '60s'
 SET lock_timeout TO '60s'
AS $function$
declare
  v_matrix public.matrix_versions%rowtype;
  v_currency text;
  v_rows jsonb:=coalesce(p_payload->'payRates','[]'::jsonb);
  v_row jsonb;
  v_other jsonb;
  v_errors jsonb:='[]'::jsonb;
  v_warnings jsonb:='[]'::jsonb;
  v_normalized jsonb:='[]'::jsonb;
  v_source_row integer;
  v_rate_id_text text;
  v_rate_id uuid;
  v_employee_no text;
  v_profile public.matrix_employee_profiles_v2%rowtype;
  v_existing public.employee_pay_rates_v2%rowtype;
  v_valid_from date;
  v_valid_to date;
  v_base_rate_text text;
  v_base_rate_minor bigint;
  v_row_currency text;
  v_contract_type text;
  v_active boolean;
  v_action text;
  v_employee_count integer:=0;
  v_create integer:=0;
  v_update integer:=0;
  v_deactivate integer:=0;
  v_unchanged integer:=0;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  if not (public.has_app_role('OWNER') or public.has_app_role('ADMIN')
    or public.has_app_role('HR_FINANCE')) then raise exception 'FORBIDDEN'; end if;
  if p_payload is null or jsonb_typeof(p_payload)<>'object'
    or jsonb_typeof(v_rows)<>'array' then raise exception 'INVALID_FINANCE_IMPORT_PAYLOAD'; end if;
  if jsonb_array_length(v_rows)=0 then raise exception 'FINANCE_IMPORT_EMPTY'; end if;
  if jsonb_array_length(v_rows)>1000 then raise exception 'FINANCE_IMPORT_TOO_LARGE'; end if;

  select matrix.* into v_matrix
  from public.matrix_versions matrix
  where matrix.status='DRAFT' and matrix.schema_version>=2
  order by matrix.version desc limit 1;
  if v_matrix.id is null then raise exception 'NO_MATRIX_V2_DRAFT'; end if;
  v_currency:=upper(trim(coalesce(v_matrix.settings->>'currency','')));

  for v_row in select value from jsonb_array_elements(v_rows) loop
    v_source_row:=case when pg_catalog.pg_input_is_valid(coalesce(v_row->>'sourceRow',''),'integer')
      then (v_row->>'sourceRow')::integer else 0 end;
    v_rate_id_text:=trim(coalesce(v_row->>'rateId',''));
    v_employee_no:=upper(trim(coalesce(v_row->>'employeeNo','')));
    v_valid_from:=case when pg_catalog.pg_input_is_valid(coalesce(v_row->>'validFrom',''),'date')
      then (v_row->>'validFrom')::date else null end;
    v_valid_to:=case when nullif(trim(coalesce(v_row->>'validTo','')),'') is null then null
      when pg_catalog.pg_input_is_valid(v_row->>'validTo','date') then (v_row->>'validTo')::date
      else null end;
    v_base_rate_text:=replace(trim(coalesce(v_row->>'baseRate','')),',','.');
    v_base_rate_minor:=case when v_base_rate_text~'^\d+(\.\d{1,2})?$'
      then round(v_base_rate_text::numeric*100)::bigint else null end;
    v_row_currency:=upper(trim(coalesce(v_row->>'currency','')));
    v_contract_type:=upper(trim(coalesce(v_row->>'contractType','')));
    v_active:=case lower(trim(coalesce(v_row->>'active','true')))
      when 'true' then true when 't' then true when '1' then true
      when 'yes' then true when 'on' then true
      when 'false' then false when 'f' then false when '0' then false
      when 'no' then false when 'off' then false
      else null end;
    v_rate_id:=case when pg_catalog.pg_input_is_valid(v_rate_id_text,'uuid')
      then v_rate_id_text::uuid else null end;

    select profile.* into v_profile
    from public.matrix_employee_profiles_v2 profile
    where profile.matrix_version_id=v_matrix.id and profile.active
      and upper(profile.employee_no)=v_employee_no
    limit 1;

    if v_source_row<2 then
      v_errors:=v_errors||jsonb_build_array(jsonb_build_object('sheet','Finanse pracowników','row',v_source_row,'code','INVALID_SOURCE_ROW','message','Nie udało się ustalić numeru wiersza. Pobierz świeży szablon i spróbuj ponownie.'));
    end if;
    if v_profile.employee_id is null then
      v_errors:=v_errors||jsonb_build_array(jsonb_build_object('sheet','Finanse pracowników','row',v_source_row,'code','EMPLOYEE_NOT_FOUND','message',format('Nie znaleziono aktywnego pracownika o numerze %s.',coalesce(nullif(v_employee_no,''),'—'))));
    end if;
    if v_valid_from is null then
      v_errors:=v_errors||jsonb_build_array(jsonb_build_object('sheet','Finanse pracowników','row',v_source_row,'code','INVALID_VALID_FROM','message','Podaj prawidłową datę w polu „Obowiązuje od”.'));
    end if;
    if nullif(trim(coalesce(v_row->>'validTo','')),'') is not null and v_valid_to is null then
      v_errors:=v_errors||jsonb_build_array(jsonb_build_object('sheet','Finanse pracowników','row',v_source_row,'code','INVALID_VALID_TO','message','Data „Obowiązuje do” ma nieprawidłowy format.'));
    elsif v_valid_from is not null and v_valid_to is not null and v_valid_to<v_valid_from then
      v_errors:=v_errors||jsonb_build_array(jsonb_build_object('sheet','Finanse pracowników','row',v_source_row,'code','INVALID_RATE_PERIOD','message','Koniec okresu stawki nie może być wcześniejszy niż jego początek.'));
    end if;
    if v_base_rate_minor is null or v_base_rate_minor<0 then
      v_errors:=v_errors||jsonb_build_array(jsonb_build_object('sheet','Finanse pracowników','row',v_source_row,'code','INVALID_BASE_RATE','message','Podaj nieujemną stawkę godzinową z dokładnością do dwóch miejsc po przecinku.'));
    end if;
    if v_row_currency<>v_currency then
      v_errors:=v_errors||jsonb_build_array(jsonb_build_object('sheet','Finanse pracowników','row',v_source_row,'code','INVALID_CURRENCY','message',format('Waluta musi być zgodna z konfiguracją firmy: %s.',v_currency)));
    end if;
    if v_contract_type not in ('UMOWA_O_PRACE','ZLECENIE','CZESC_ETATU','B2B','INNE') then
      v_errors:=v_errors||jsonb_build_array(jsonb_build_object('sheet','Finanse pracowników','row',v_source_row,'code','INVALID_CONTRACT_TYPE','message','Wybierz rodzaj umowy z arkusza „Słowniki”.'));
    end if;
    if v_active is null then
      v_errors:=v_errors||jsonb_build_array(jsonb_build_object('sheet','Finanse pracowników','row',v_source_row,'code','INVALID_ACTIVE_VALUE','message','Pole „Aktywna” musi mieć wartość TAK albo NIE.'));
    end if;
    if v_rate_id_text<>'' and v_rate_id is null then
      v_errors:=v_errors||jsonb_build_array(jsonb_build_object('sheet','Finanse pracowników','row',v_source_row,'code','INVALID_RATE_ID','message','ID stawki ma nieprawidłowy format. Nie zmieniaj identyfikatorów pobranych z szablonu.'));
    end if;
    if not v_active and v_rate_id is null then
      v_errors:=v_errors||jsonb_build_array(jsonb_build_object('sheet','Finanse pracowników','row',v_source_row,'code','NEW_INACTIVE_RATE','message','Nowy, nieaktywny wiersz nie ma skutku. Usuń go albo ustaw „Aktywna” na TAK.'));
    end if;

    select rate.* into v_existing from public.employee_pay_rates_v2 rate
    where rate.id=v_rate_id;
    if v_rate_id is not null and (v_existing.id is null
      or v_existing.employee_id is distinct from v_profile.employee_id) then
      v_errors:=v_errors||jsonb_build_array(jsonb_build_object('sheet','Finanse pracowników','row',v_source_row,'code','RATE_NOT_OWNED_BY_EMPLOYEE','message','ID stawki nie należy do wskazanego pracownika. Pobierz świeży plik i nie przenoś ID między osobami.'));
    end if;
    if v_profile.employee_id is not null and v_valid_from is not null and (
      (v_profile.employment_start is not null and v_valid_from<v_profile.employment_start)
      or (v_profile.employment_end is not null and (v_valid_from>v_profile.employment_end
        or v_valid_to is null or v_valid_to>v_profile.employment_end))
    ) then
      v_errors:=v_errors||jsonb_build_array(jsonb_build_object('sheet','Finanse pracowników','row',v_source_row,'code','RATE_OUTSIDE_EMPLOYMENT','message','Okres stawki wykracza poza daty zatrudnienia tej osoby.'));
    end if;

    if v_profile.employee_id is not null and v_valid_from is not null
      and v_base_rate_minor is not null and v_row_currency=v_currency
      and v_contract_type in ('UMOWA_O_PRACE','ZLECENIE','CZESC_ETATU','B2B','INNE')
      and v_active is not null
      and (v_rate_id is null or v_existing.id is not null) then
      v_action:=case
        when v_rate_id is null then 'CREATE'
        when not v_active and v_existing.active then 'DEACTIVATE'
        when not v_active and not v_existing.active then 'UNCHANGED'
        when v_existing.active=v_active and v_existing.valid_from=v_valid_from
          and v_existing.valid_to is not distinct from v_valid_to
          and v_existing.base_rate_minor=v_base_rate_minor
          and upper(v_existing.currency)=v_row_currency
          and upper(coalesce(v_existing.contract_type,''))=v_contract_type then 'UNCHANGED'
        else 'UPDATE' end;
      v_normalized:=v_normalized||jsonb_build_array(jsonb_build_object(
        'sourceRow',v_source_row,'rateId',coalesce(v_rate_id::text,''),
        'employeeId',v_profile.employee_id,'employeeNo',v_profile.employee_no,
        'employeeName',trim(concat(v_profile.first_name,' ',v_profile.last_name)),
        'validFrom',v_valid_from,'validTo',v_valid_to,
        'baseRateMinor',v_base_rate_minor,'currency',v_row_currency,
        'contractType',v_contract_type,'active',v_active,'action',v_action
      ));
    end if;
  end loop;

  for v_row in select value from jsonb_array_elements(v_normalized) loop
    if nullif(v_row->>'rateId','') is not null and exists(
      select 1 from jsonb_array_elements(v_normalized) duplicate
      where duplicate.value->>'rateId'=v_row->>'rateId'
        and (duplicate.value->>'sourceRow')::integer<>(v_row->>'sourceRow')::integer
    ) then
      v_errors:=v_errors||jsonb_build_array(jsonb_build_object('sheet','Finanse pracowników','row',(v_row->>'sourceRow')::integer,'code','DUPLICATE_RATE_ID','message','To samo ID stawki występuje w pliku więcej niż raz.'));
    end if;
    if (v_row->>'active')::boolean and exists(
      select 1 from jsonb_array_elements(v_normalized) other
      where other.value->>'employeeId'=v_row->>'employeeId'
        and (other.value->>'active')::boolean
        and (other.value->>'sourceRow')::integer<>(v_row->>'sourceRow')::integer
        and daterange((other.value->>'validFrom')::date,
          case when nullif(other.value->>'validTo','') is null then null else (other.value->>'validTo')::date+1 end,'[)')
          && daterange((v_row->>'validFrom')::date,
          case when nullif(v_row->>'validTo','') is null then null else (v_row->>'validTo')::date+1 end,'[)')
    ) then
      v_errors:=v_errors||jsonb_build_array(jsonb_build_object('sheet','Finanse pracowników','row',(v_row->>'sourceRow')::integer,'code','OVERLAPPING_IMPORTED_RATE','message','Ten okres nakłada się na inny aktywny okres tej samej osoby w pliku.'));
    end if;
    if (v_row->>'active')::boolean and exists(
      select 1 from public.employee_pay_rates_v2 rate
      where rate.employee_id=(v_row->>'employeeId')::uuid and rate.active
        and not exists(select 1 from jsonb_array_elements(v_normalized) supplied
          where nullif(supplied.value->>'rateId','')=rate.id::text)
        and daterange(rate.valid_from,case when rate.valid_to is null then null else rate.valid_to+1 end,'[)')
          && daterange((v_row->>'validFrom')::date,
          case when nullif(v_row->>'validTo','') is null then null else (v_row->>'validTo')::date+1 end,'[)')
    ) then
      v_errors:=v_errors||jsonb_build_array(jsonb_build_object('sheet','Finanse pracowników','row',(v_row->>'sourceRow')::integer,'code','OVERLAPPING_EXISTING_RATE','message','Ten okres nakłada się na istniejącą aktywną stawkę tej osoby, której nie ma w pliku. Pobierz świeży szablon.'));
    end if;
  end loop;

  select count(distinct value->>'employeeId'),
    count(*) filter(where value->>'action'='CREATE'),
    count(*) filter(where value->>'action'='UPDATE'),
    count(*) filter(where value->>'action'='DEACTIVATE'),
    count(*) filter(where value->>'action'='UNCHANGED')
  into v_employee_count,v_create,v_update,v_deactivate,v_unchanged
  from jsonb_array_elements(v_normalized);

  return jsonb_build_object(
    'valid',jsonb_array_length(v_errors)=0,'matrixVersionId',v_matrix.id,
    'errors',v_errors,'warnings',v_warnings,'normalizedRows',v_normalized,
    'summary',jsonb_build_object('rows',jsonb_array_length(v_rows),
      'employees',coalesce(v_employee_count,0),'create',coalesce(v_create,0),
      'update',coalesce(v_update,0),'deactivate',coalesce(v_deactivate,0),
      'unchanged',coalesce(v_unchanged,0))
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_finance_step_skip_uat_v2(p_employee_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_matrix uuid;
  v_employee_no text;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  if not (public.has_app_role('OWNER') or public.has_app_role('ADMIN')
    or public.has_app_role('HR_FINANCE')) then raise exception 'FORBIDDEN'; end if;
  select profile.matrix_version_id,profile.employee_no
  into v_matrix,v_employee_no
  from public.matrix_employee_profiles_v2 profile
  join public.matrix_versions version on version.id=profile.matrix_version_id
  where profile.employee_id=p_employee_id and version.status='DRAFT'
  order by version.version desc limit 1;
  if v_matrix is null then raise exception 'MATRIX_EMPLOYEE_NOT_FOUND'; end if;
  insert into public.audit_log(actor_id,entity_type,entity_id,action,new_data)
  values(auth.uid(),'matrix_v2_employee_finance',p_employee_id::text,
    'PAY_RATE_STEP_SKIPPED',jsonb_build_object(
      'matrixVersionId',v_matrix,'employeeNo',v_employee_no,
      'publicationRemainsBlocked',true
    ));
  return jsonb_build_object('employeeId',p_employee_id,'skipped',true);
end;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_full_import_apply_raw_uat_v1(p_payload jsonb, p_mode text DEFAULT 'UPDATE'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_configuration jsonb:=coalesce(p_payload->'configuration','{}'::jsonb);
  v_configuration_without_rates jsonb;
  v_finance jsonb:=coalesce(p_payload->'finance','{}'::jsonb);
  v_configuration_result jsonb;
  v_finance_result jsonb;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  if not (public.has_app_role('OWNER') or public.has_app_role('ADMIN')) then raise exception 'FORBIDDEN'; end if;
  perform pg_advisory_xact_lock(hashtext('matrix-v2-lifecycle'));
  v_configuration_without_rates:=jsonb_set(v_configuration,'{employees}',coalesce((
    select jsonb_agg(value-'baseRate') from jsonb_array_elements(coalesce(v_configuration->'employees','[]'::jsonb))
  ),'[]'::jsonb),true);
  perform solver_private.matrix_v2_full_import_phase_uat_v1(v_configuration,'PRE');
  v_configuration_result:=public.matrix_v2_import_apply_uat_v5(v_configuration_without_rates,p_mode);
  perform solver_private.matrix_v2_full_import_phase_uat_v1(v_configuration,'POST');
  v_finance_result:=public.matrix_v2_finance_import_apply_uat_v1(
    solver_private.matrix_v2_full_finance_payload_uat_v1(v_finance));
  return v_configuration_result||jsonb_build_object('finance',v_finance_result,'atomic',true,'scope','FULL_COMPANY');
exception when others then
  if sqlerrm like 'FULL_IMPORT_%' or sqlerrm like 'MATRIX_%' or sqlerrm like 'INVALID_%'
    or sqlerrm like 'EMPLOYEE_%' or sqlerrm like 'PAY_RATE_%' or sqlerrm like 'OVERLAPPING_%'
    or sqlerrm like 'FINANCE_%' then raise; end if;
  raise exception 'FULL_IMPORT_APPLY_FAILED|%|%|%',gen_random_uuid(),sqlstate,sqlerrm;
end;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_full_import_apply_uat_v1(p_payload jsonb, p_mode text DEFAULT 'UPDATE'::text)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
 SET statement_timeout TO '60s'
 SET lock_timeout TO '60s'
AS $function$
  select public.matrix_v2_full_import_apply_raw_uat_v1(
    jsonb_set(
      coalesce(p_payload,'{}'::jsonb),
      '{configuration}',
      solver_private.matrix_v2_full_import_configuration_uat_v2(coalesce(p_payload->'configuration','{}'::jsonb)),
      true
    ),
    p_mode
  )
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_full_import_preview_raw_uat_v1(p_payload jsonb, p_mode text DEFAULT 'UPDATE'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_configuration jsonb:=coalesce(p_payload->'configuration','{}'::jsonb);
  v_configuration_without_rates jsonb;
  v_finance jsonb:=coalesce(p_payload->'finance','{}'::jsonb);
  v_configuration_preview jsonb;
  v_finance_preview jsonb;
  v_result jsonb;
  v_extra integer;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  if not (public.has_app_role('OWNER') or public.has_app_role('ADMIN')) then raise exception 'FORBIDDEN'; end if;
  if jsonb_typeof(p_payload)<>'object' then raise exception 'INVALID_FULL_IMPORT_PAYLOAD'; end if;
  perform pg_advisory_xact_lock(hashtext('matrix-v2-lifecycle'));
  v_configuration_without_rates:=jsonb_set(v_configuration,'{employees}',coalesce((
    select jsonb_agg(value-'baseRate') from jsonb_array_elements(coalesce(v_configuration->'employees','[]'::jsonb))
  ),'[]'::jsonb),true);

  begin
    perform solver_private.matrix_v2_full_import_phase_uat_v1(v_configuration,'PRE');
    v_configuration_preview:=public.matrix_v2_import_preview_uat_v5(v_configuration_without_rates,p_mode);
    if coalesce((v_configuration_preview->>'valid')::boolean,false) then
      perform public.matrix_v2_import_apply_uat_v5(v_configuration_without_rates,p_mode);
      perform solver_private.matrix_v2_full_import_phase_uat_v1(v_configuration,'POST');
      v_finance_preview:=public.matrix_v2_finance_import_preview_uat_v1(
        solver_private.matrix_v2_full_finance_payload_uat_v1(v_finance));
    else
      v_finance_preview:=jsonb_build_object('valid',false,'errors','[]'::jsonb,'warnings','[]'::jsonb,
        'normalizedRows','[]'::jsonb,'summary',jsonb_build_object('rows',jsonb_array_length(coalesce(v_finance->'payRates','[]'::jsonb)),
          'employees',0,'create',0,'update',0,'deactivate',0,'unchanged',0));
    end if;

    v_configuration_preview:=jsonb_set(v_configuration_preview,'{warnings}',coalesce((
      select jsonb_agg(
        case when warning.value->>'code'='PAY_RATE_MISSING' then
          jsonb_set(warning.value,'{message}',to_jsonb('Brak stawki zablokuje późniejszą publikację konfiguracji firmy.'::text),true)
        else warning.value end
        order by warning.ordinality
      )
      from jsonb_array_elements(coalesce(v_configuration_preview->'warnings','[]'::jsonb))
        with ordinality warning(value,ordinality)
      where warning.value->>'code'<>'PAY_RATE_MISSING'
        or not exists(
          select 1
          from jsonb_array_elements(coalesce(v_configuration->'employees','[]'::jsonb))
            with ordinality employee(value,ordinality)
          join jsonb_array_elements(coalesce(v_finance->'payRates','[]'::jsonb)) rate(value)
            on upper(rate.value->>'employeeNo')=upper(employee.value->>'employeeNo')
          where pg_catalog.pg_input_is_valid(warning.value->>'row','integer')
            and employee.ordinality+1=(warning.value->>'row')::integer
            and nullif(rate.value->>'baseRate','') is not null
            and coalesce(nullif(rate.value->>'active','')::boolean,true)
        )
    ),'[]'::jsonb),true);

    v_extra:=jsonb_array_length(coalesce(v_configuration->'roles','[]'::jsonb))
      +jsonb_array_length(coalesce(v_configuration->'locations','[]'::jsonb))
      +jsonb_array_length(coalesce(v_configuration->'duties','[]'::jsonb))
      +jsonb_array_length(coalesce(v_configuration->'scenarios','[]'::jsonb))
      +jsonb_array_length(coalesce(v_configuration->'strategies','[]'::jsonb))
      +jsonb_array_length(coalesce(v_configuration->'strategyObjectives','[]'::jsonb))
      +jsonb_array_length(coalesce(v_configuration->'scenarioStrategies','[]'::jsonb))
      +jsonb_array_length(coalesce(v_configuration->'payRules','[]'::jsonb))
      +jsonb_array_length(coalesce(v_configuration->'scenarioPayRuleOverrides','[]'::jsonb))
      +jsonb_array_length(coalesce(v_configuration->'scenarioBudgets','[]'::jsonb))
      +jsonb_array_length(coalesce(v_configuration->'employeeRoles','[]'::jsonb))
      +jsonb_array_length(coalesce(v_configuration->'employeeLocationsDetailed','[]'::jsonb))
      +jsonb_array_length(coalesce(v_configuration->'employeeCapabilities','[]'::jsonb))
      +jsonb_array_length(coalesce(v_configuration->'timeConstraints','[]'::jsonb));
    v_result:=jsonb_build_object(
      'valid',coalesce((v_configuration_preview->>'valid')::boolean,false)
        and coalesce((v_finance_preview->>'valid')::boolean,false),
      'errors',coalesce(v_configuration_preview->'errors','[]'::jsonb)||coalesce(v_finance_preview->'errors','[]'::jsonb),
      'warnings',coalesce(v_configuration_preview->'warnings','[]'::jsonb)||coalesce(v_finance_preview->'warnings','[]'::jsonb),
      'configuration',v_configuration_preview,'finance',v_finance_preview,
      'summary',coalesce(v_configuration_preview->'summary','{}'::jsonb)||jsonb_build_object(
        'total',coalesce((v_configuration_preview#>>'{summary,total}')::integer,0)+v_extra,
        'financeRows',coalesce((v_finance_preview#>>'{summary,rows}')::integer,0),
        'financeEmployees',coalesce((v_finance_preview#>>'{summary,employees}')::integer,0),
        'financeChanges',coalesce((v_finance_preview#>>'{summary,create}')::integer,0)
          +coalesce((v_finance_preview#>>'{summary,update}')::integer,0)
          +coalesce((v_finance_preview#>>'{summary,deactivate}')::integer,0),
        'roles',jsonb_array_length(coalesce(v_configuration->'roles','[]'::jsonb)),
        'locations',jsonb_array_length(coalesce(v_configuration->'locations','[]'::jsonb)),
        'duties',jsonb_array_length(coalesce(v_configuration->'duties','[]'::jsonb)),
        'scenarios',jsonb_array_length(coalesce(v_configuration->'scenarios','[]'::jsonb)),
        'strategies',jsonb_array_length(coalesce(v_configuration->'strategies','[]'::jsonb)),
        'payRules',jsonb_array_length(coalesce(v_configuration->'payRules','[]'::jsonb)),
        'timeConstraints',jsonb_array_length(coalesce(v_configuration->'timeConstraints','[]'::jsonb))
      ));
    raise sqlstate 'GPF01' using message='FULL_IMPORT_DRY_RUN_COMPLETE';
  exception when sqlstate 'GPF01' then
    return v_result;
  end;
end;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_full_import_preview_uat_v1(p_payload jsonb, p_mode text DEFAULT 'UPDATE'::text)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
 SET statement_timeout TO '60s'
 SET lock_timeout TO '60s'
AS $function$
  select public.matrix_v2_full_import_preview_raw_uat_v1(
    jsonb_set(
      coalesce(p_payload,'{}'::jsonb),
      '{configuration}',
      solver_private.matrix_v2_full_import_configuration_uat_v2(coalesce(p_payload->'configuration','{}'::jsonb)),
      true
    ),
    p_mode
  )
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_has_any_manager_scope_uat_v1()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select auth.uid() is not null and (
    public.has_app_role('OWNER') or public.has_app_role('ADMIN')
    or exists(
      select 1 from public.matrix_scope_grants_v2 grant_row
      where grant_row.auth_user_id=auth.uid() and grant_row.active
        and (
          (grant_row.app_role='ROLE_MANAGER' and grant_row.role_logical_id is not null)
          or (grant_row.app_role='LOCATION_MANAGER' and grant_row.location_logical_id is not null)
        )
    )
  );
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_import_apply_alpha16(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_legacy_rows text;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  if not (public.has_app_role('OWNER') or public.has_app_role('ADMIN')) then
    raise exception 'FORBIDDEN';
  end if;
  select string_agg((legacy.ordinality+1)::text,',' order by legacy.ordinality)
  into v_legacy_rows
  from jsonb_array_elements(coalesce(p_payload->'roleDuties','[]'::jsonb))
    with ordinality legacy(value,ordinality)
  where solver_private.mx_k10_legacy_role_duty_payload_v1(legacy.value);
  if v_legacy_rows is not null then
    raise exception 'LEGACY_PERIOD_DEMAND_REJECTED rows=%: move required counts to exact shifts in OBSADA',v_legacy_rows;
  end if;
  return public.matrix_v2_import_apply_before_mx_k10(p_payload);
end;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_import_apply_before_mx_k10(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_preview jsonb;
  v_matrix uuid;
  v_row jsonb;
  v_location_ids jsonb;
  v_role uuid;
  v_location uuid;
  v_shift uuid;
  v_scenario uuid;
  v_duty uuid;
  v_existing uuid;
  v_result jsonb;
  v_employee uuid;
  v_rate_id uuid;
  v_currency text;
  v_effective date;
  v_applied integer:=0;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  if not (public.has_app_role('OWNER') or public.has_app_role('ADMIN')) then
    raise exception 'FORBIDDEN';
  end if;
  perform pg_advisory_xact_lock(hashtext('matrix-v2-lifecycle'));
  v_preview:=public.matrix_v2_import_preview_alpha16(p_payload);
  if not (v_preview->>'valid')::boolean then
    raise exception 'MATRIX_IMPORT_HAS_ERRORS:%',v_preview->'errors';
  end if;
  v_matrix:=(v_preview->>'matrixVersionId')::uuid;
  select upper(mv.settings->>'currency'),coalesce(mv.effective_from,current_date)
  into v_currency,v_effective from public.matrix_versions mv where mv.id=v_matrix;

  for v_row in select value from jsonb_array_elements(
    coalesce(p_payload->'employees','[]'::jsonb)
  ) loop
    select profile.employee_id into v_existing
    from public.matrix_employee_profiles_v2 profile
    where profile.matrix_version_id=v_matrix and (
      (nullif(trim(v_row->>'employeeNo'),'') is not null
        and upper(profile.employee_no)=upper(trim(v_row->>'employeeNo')))
      or (nullif(lower(trim(v_row->>'email')),'') is not null
        and lower(profile.email)=lower(trim(v_row->>'email')))
    ) order by profile.employee_id limit 1;
    select role_row.id into v_role from public.matrix_roles_v2 role_row
    where role_row.matrix_version_id=v_matrix and role_row.active
      and upper(role_row.code)=upper(v_row->>'primaryRoleCode');
    select coalesce(jsonb_agg(location_row.id order by location_row.sort_order,
      location_row.code),'[]'::jsonb) into v_location_ids
    from public.matrix_locations_v2 location_row
    join jsonb_array_elements_text(v_row->'locationCodes') code
      on upper(code.value)=upper(location_row.code)
    where location_row.matrix_version_id=v_matrix and location_row.active;
    v_result:=public.matrix_v2_employee_save_alpha16(v_existing,jsonb_build_object(
      'firstName',trim(v_row->>'firstName'),
      'lastName',trim(v_row->>'lastName'),
      'email',nullif(lower(trim(v_row->>'email')),''),
      'primaryRoleId',v_role,'locationIds',v_location_ids,
      'employmentStart',nullif(v_row->>'employmentStart',''),
      'employmentEnd',nullif(v_row->>'employmentEnd',''),
      'nominalMonthlyMinutes',round(coalesce(nullif(replace(v_row->>'nominalHours',',','.'),'')::numeric,168)*60),
      'maximumMonthlyMinutes',round(coalesce(nullif(replace(v_row->>'maximumMonthlyHours',',','.'),'')::numeric,210)*60),
      'maximumWeeklyMinutes',round(coalesce(nullif(replace(v_row->>'maximumWeeklyHours',',','.'),'')::numeric,40)*60),
      'maximumConsecutiveDays',coalesce(nullif(v_row->>'maximumConsecutiveDays','')::integer,6),
      'minimumRestMinutes',case when nullif(v_row->>'minimumRestHours','') is null
        then null else round(replace(v_row->>'minimumRestHours',',','.')::numeric*60) end,
      'preferenceMonth',coalesce(nullif(v_row->>'preferenceMonth','')::date,v_effective),
      'shiftPeriodPreferences',coalesce(v_row->'shiftPeriodPreferences','{}'::jsonb)
    ));
    v_employee:=(v_result->>'id')::uuid;
    if nullif(v_row->>'baseRate','') is not null then
      select rate.id into v_rate_id from public.employee_pay_rates_v2 rate
      where rate.employee_id=v_employee and rate.active
        and rate.valid_from<=v_effective
        and (rate.valid_to is null or rate.valid_to>=v_effective)
      order by rate.valid_from desc limit 1;
      perform public.employee_pay_rate_save_v2(
        v_rate_id,v_employee,v_effective,null,
        round(replace(v_row->>'baseRate',',','.')::numeric*100)::bigint,
        v_currency,nullif(v_row->>'contractType',''),true
      );
    end if;
    v_applied:=v_applied+1;
  end loop;

  for v_row in select value from jsonb_array_elements(
    coalesce(p_payload->'shifts','[]'::jsonb)
  ) loop
    select location_row.id into v_location from public.matrix_locations_v2 location_row
    where location_row.matrix_version_id=v_matrix and location_row.active
      and upper(location_row.code)=upper(v_row->>'locationCode');
    select shift_row.id into v_existing from public.matrix_shift_templates_v2 shift_row
    where shift_row.matrix_version_id=v_matrix and shift_row.location_id=v_location
      and upper(shift_row.code)=upper(v_row->>'code');
    perform public.matrix_v2_admin_save_alpha16('SHIFT',v_existing,jsonb_build_object(
      'locationId',v_location,'code',upper(v_row->>'code'),'name',trim(v_row->>'name'),
      'startsAt',v_row->>'startsAt','endsAt',v_row->>'endsAt',
      'endsNextDay',coalesce((v_row->>'endsNextDay')::boolean,false),
      'days',coalesce(v_row->'days','[1,2,3,4,5,6,7]'::jsonb),
      'sortOrder',coalesce(nullif(v_row->>'sortOrder','')::integer,0),
      'active',coalesce((v_row->>'active')::boolean,true),
      'shiftPeriod',upper(v_row->>'shiftPeriod')
    ));
    v_applied:=v_applied+1;
  end loop;

  for v_row in select value from jsonb_array_elements(
    coalesce(p_payload->'roleDuties','[]'::jsonb)
  ) loop
    select role_row.id into v_role from public.matrix_roles_v2 role_row
    where role_row.matrix_version_id=v_matrix
      and upper(role_row.code)=upper(v_row->>'roleCode');
    select duty_row.id into v_duty from public.matrix_duties_v2 duty_row
    where duty_row.matrix_version_id=v_matrix
      and upper(duty_row.code)=upper(v_row->>'dutyCode');
    select link.id into v_existing from public.matrix_role_duties_v2 link
    where link.matrix_version_id=v_matrix and link.role_id=v_role and link.duty_id=v_duty;
    perform public.matrix_v2_admin_save_alpha16('ROLE_DUTY',v_existing,jsonb_build_object(
      'roleId',v_role,'dutyId',v_duty,
      'assignmentMode',upper(coalesce(v_row->>'assignmentMode','OPTIONAL')),
      'minimumCount',coalesce(nullif(v_row->>'minimumCount','')::integer,0),
      'active',coalesce((v_row->>'active')::boolean,true),
      'shiftObligation',coalesce((v_row->>'shiftObligation')::boolean,false),
      'shiftPeriod',nullif(upper(v_row->>'shiftPeriod'),'')
    ));
    v_applied:=v_applied+1;
  end loop;

  for v_row in select value from jsonb_array_elements(
    coalesce(p_payload->'staffingRules','[]'::jsonb)
  ) loop
    select scenario.id into v_scenario from public.matrix_scenarios_v2 scenario
    where scenario.matrix_version_id=v_matrix
      and upper(scenario.code)=upper(v_row->>'scenarioCode');
    select role_row.id into v_role from public.matrix_roles_v2 role_row
    where role_row.matrix_version_id=v_matrix
      and upper(role_row.code)=upper(v_row->>'roleCode');
    select shift_row.id into v_shift from public.matrix_shift_templates_v2 shift_row
    join public.matrix_locations_v2 location_row on location_row.id=shift_row.location_id
    where shift_row.matrix_version_id=v_matrix
      and upper(shift_row.code)=upper(v_row->>'shiftCode')
      and (nullif(v_row->>'locationCode','') is null
        or upper(location_row.code)=upper(v_row->>'locationCode'))
    order by shift_row.id limit 1;
    v_duty:=null;
    if nullif(v_row->>'dutyCode','') is not null then
      select duty_row.id into v_duty from public.matrix_duties_v2 duty_row
      where duty_row.matrix_version_id=v_matrix
        and upper(duty_row.code)=upper(v_row->>'dutyCode');
    end if;
    select rule.id into v_existing from public.matrix_staffing_rules_v2 rule
    where rule.matrix_version_id=v_matrix and rule.scenario_id=v_scenario
      and rule.shift_template_id=v_shift and rule.role_id=v_role
      and rule.duty_id is not distinct from v_duty;
    perform public.matrix_v2_admin_save_alpha16('STAFFING_RULE',v_existing,
      jsonb_build_object(
        'scenarioId',v_scenario,'shiftTemplateId',v_shift,'roleId',v_role,
        'dutyId',v_duty,'operation',upper(coalesce(v_row->>'operation','SET')),
        'countValue',case when upper(coalesce(v_row->>'operation','SET')) in ('SET','ADD')
          then coalesce(nullif(v_row->>'countValue','')::integer,0) else null end,
        'multiplierBasisPoints',null,'active',coalesce((v_row->>'active')::boolean,true),
        'sourceMetadata',jsonb_build_object('source','EXCEL_ALPHA16')
      )
    );
    v_applied:=v_applied+1;
  end loop;

  insert into public.audit_log(actor_id,entity_type,entity_id,action,new_data)
  values(auth.uid(),'matrix_v2_import',v_matrix::text,'APPLY',jsonb_build_object(
    'appliedRows',v_applied,'summary',v_preview->'summary'
  ));
  return jsonb_build_object('appliedRows',v_applied,'summary',v_preview->'summary');
end;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_import_apply_uat_v2(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_result jsonb;
  v_matrix uuid;
  v_row jsonb;
  v_employee uuid;
  v_contract text;
  v_fraction numeric;
  v_duty uuid;
  v_role uuid;
  v_existing uuid;
begin
  if not (public.matrix_v2_import_preview_uat_v2(p_payload)->>'valid')::boolean then
    raise exception 'MATRIX_IMPORT_HAS_ERRORS';
  end if;
  v_result := public.matrix_v2_import_apply_alpha16(p_payload);
  select version.id into v_matrix from public.matrix_versions version
  where version.status='DRAFT' and version.schema_version>=2
  order by version.version desc limit 1;
  for v_row in select value from jsonb_array_elements(
    coalesce(p_payload->'employees','[]'::jsonb)
  ) loop
    select profile.employee_id into v_employee
    from public.matrix_employee_profiles_v2 profile
    where profile.matrix_version_id=v_matrix and (
      (nullif(trim(v_row->>'employeeNo'),'') is not null
        and upper(profile.employee_no)=upper(trim(v_row->>'employeeNo')))
      or (nullif(lower(trim(v_row->>'email')),'') is not null
        and lower(profile.email)=lower(trim(v_row->>'email')))
    ) order by profile.employee_id limit 1;
    if v_employee is null then
      raise exception 'IMPORTED_EMPLOYEE_NOT_FOUND|%|%|%',
        coalesce(v_row->>'employeeNo',''),coalesce(v_row->>'email',''),v_matrix;
    end if;
    v_contract := solver_private.normalize_contract_type_v2(v_row->>'contractType');
    v_fraction := greatest(.01,least(1,coalesce(
      nullif(replace(v_row->>'employmentFraction',',','.'),'')::numeric,1
    )));
    insert into public.employee_hr_profiles(
      employee_id,contract_type,employment_fraction,updated_by,updated_at
    ) values(v_employee,v_contract,v_fraction,auth.uid(),now())
    on conflict(employee_id) do update set
      contract_type=excluded.contract_type,
      employment_fraction=excluded.employment_fraction,
      updated_by=auth.uid(),updated_at=now();
    update public.matrix_employee_profiles_v2 profile set
      work_time_policy=case when upper(coalesce(v_row->>'workTimePolicy',''))='CUSTOM'
        then 'CUSTOM' else 'CONTRACT_DEFAULT' end,
      updated_by=auth.uid(),updated_at=now()
    where profile.matrix_version_id=v_matrix
      and profile.employee_id=v_employee;
  end loop;
  for v_row in select value from jsonb_array_elements(
    coalesce(p_payload->'employeeDuties','[]'::jsonb)
  ) loop
    select profile.employee_id into v_employee
    from public.matrix_employee_profiles_v2 profile
    where profile.matrix_version_id=v_matrix and (
      (nullif(trim(v_row->>'employeeNo'),'') is not null
        and upper(profile.employee_no)=upper(trim(v_row->>'employeeNo')))
      or (nullif(lower(trim(v_row->>'email')),'') is not null
        and lower(profile.email)=lower(trim(v_row->>'email')))
    ) order by profile.employee_id limit 1;
    select duty.id into v_duty from public.matrix_duties_v2 duty
    where duty.matrix_version_id=v_matrix
      and upper(duty.code)=upper(v_row->>'dutyCode');
    select role.id into v_role from public.matrix_roles_v2 role
    where role.matrix_version_id=v_matrix
      and upper(role.code)=upper(v_row->>'roleCode');
    select capability.id into v_existing
    from public.matrix_employee_duties_v2 capability
    where capability.matrix_version_id=v_matrix
      and capability.employee_id=v_employee and capability.duty_id=v_duty
      and capability.role_id is not distinct from v_role
      and capability.location_id is null;
    perform public.matrix_v2_admin_save_alpha16(
      'EMPLOYEE_DUTY',v_existing,jsonb_build_object(
        'employeeId',v_employee,'dutyId',v_duty,'roleId',v_role,
        'locationId',null,'active',coalesce((v_row->>'active')::boolean,true)
      )
    );
  end loop;
  return v_result;
end;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_import_apply_uat_v3(p_payload jsonb, p_mode text DEFAULT 'UPDATE'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_mode text:=upper(trim(coalesce(p_mode,'UPDATE')));
  v_preview jsonb;
  v_normalized jsonb;
  v_result jsonb;
  v_matrix uuid;
  v_apply_payload jsonb;
  v_profile public.matrix_employee_profiles_v2%rowtype;
  v_row jsonb;
  v_employee uuid;
  v_existing_rate public.employee_pay_rates_v2%rowtype;
  v_rate_start date;
  v_rate_end date;
  v_employment_end date;
  v_next_rate_start date;
  v_rate_amount bigint;
  v_effective date;
  v_currency text;
  v_archived integer:=0;
  v_location uuid;
  v_location_grant jsonb;
  v_profile_active boolean;
  v_desired_active boolean;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  if not (public.has_app_role('OWNER') or public.has_app_role('ADMIN')) then
    raise exception 'FORBIDDEN';
  end if;
  perform pg_advisory_xact_lock(hashtext('matrix-v2-lifecycle'));
  v_preview:=public.matrix_v2_import_preview_uat_v3(p_payload,v_mode);
  if not (v_preview->>'valid')::boolean then raise exception 'MATRIX_IMPORT_HAS_ERRORS'; end if;
  v_matrix:=(v_preview->>'matrixVersionId')::uuid;
  v_normalized:=solver_private.matrix_v2_import_normalize_uat_v3(p_payload,v_matrix);
  -- Rates are saved below with the later of the workbook month (when present),
  -- the Matrix effective date and the employee's start date.  The older
  -- importer used only the Matrix date and could create a rate before
  -- employment or in a technical draft month unrelated to the schedule.
  select coalesce(jsonb_agg(
    (source.value-'baseRate')||jsonb_build_object('baseRate','')
    order by source.ordinality
  ),'[]'::jsonb) into v_apply_payload
  from jsonb_array_elements(coalesce(v_normalized->'employees','[]'::jsonb))
    with ordinality source(value,ordinality);
  v_apply_payload:=jsonb_set(v_normalized,'{employees}',v_apply_payload,true);
  v_result:=public.matrix_v2_import_apply_uat_v2(v_apply_payload);
  select matrix.effective_from,upper(matrix.settings->>'currency')
  into v_effective,v_currency
  from public.matrix_versions matrix where matrix.id=v_matrix;

  -- The v2 importer predates the Apps Script columns that distinguish normal
  -- and overtime location access and therefore deliberately cannot persist
  -- them.  Apply those explicit grants, employee shift limits and active state
  -- only when the workbook actually contains the corresponding fields.
  for v_row in select value from jsonb_array_elements(
    coalesce(v_normalized->'employees','[]'::jsonb)
  ) loop
    select profile.employee_id,profile.active into v_employee,v_profile_active
    from public.matrix_employee_profiles_v2 profile
    where profile.matrix_version_id=v_matrix and (
      (nullif(trim(v_row->>'employeeNo'),'') is not null
        and upper(profile.employee_no)=upper(trim(v_row->>'employeeNo')))
      or (nullif(lower(trim(v_row->>'email')),'') is not null
        and lower(profile.email)=lower(trim(v_row->>'email')))
    ) order by profile.employee_id limit 1;
    if v_employee is null then
      raise exception 'IMPORTED_EMPLOYEE_NOT_FOUND|%|%',
        coalesce(v_row->>'employeeNo',''),coalesce(v_row->>'email','');
    end if;

    if v_row ? 'onlyMorning' or v_row ? 'onlyEvening' or v_row ? 'noWeekends' then
      update public.matrix_employee_profiles_v2 profile set
        only_morning=case when v_row ? 'onlyMorning'
          then (v_row->>'onlyMorning')::boolean else profile.only_morning end,
        only_evening=case when v_row ? 'onlyEvening'
          then (v_row->>'onlyEvening')::boolean else profile.only_evening end,
        no_weekends=case when v_row ? 'noWeekends'
          then (v_row->>'noWeekends')::boolean else profile.no_weekends end,
        updated_by=auth.uid(),updated_at=now()
      where profile.matrix_version_id=v_matrix and profile.employee_id=v_employee;
    end if;

    if v_row ? 'locationGrants' then
      update public.matrix_employee_locations_v2 location_grant set
        standard_allowed=false,overtime_allowed=false,home_location=false,active=false
      where location_grant.matrix_version_id=v_matrix
        and location_grant.employee_id=v_employee;
      for v_location_grant in select value from jsonb_array_elements(v_row->'locationGrants')
      loop
        select location_row.id into v_location
        from public.matrix_locations_v2 location_row
        where location_row.matrix_version_id=v_matrix and location_row.active
          and upper(location_row.code)=upper(v_location_grant->>'code');
        if v_location is null then raise exception 'LOCATION_NOT_IN_MATRIX_V2'; end if;
        insert into public.matrix_employee_locations_v2(
          matrix_version_id,employee_id,location_id,standard_allowed,
          overtime_allowed,home_location,active
        ) values(
          v_matrix,v_employee,v_location,
          coalesce((v_location_grant->>'standardAllowed')::boolean,false),
          coalesce((v_location_grant->>'overtimeAllowed')::boolean,false),
          coalesce((v_location_grant->>'homeLocation')::boolean,false),true
        ) on conflict(matrix_version_id,employee_id,location_id) do update set
          standard_allowed=excluded.standard_allowed,
          overtime_allowed=excluded.overtime_allowed,
          home_location=excluded.home_location,active=true;
      end loop;
    end if;

    -- When the workbook carries a duty dictionary, its employee columns are a
    -- complete statement for those duties: TAK activates the capability and a
    -- blank/NIE cell withdraws it.  Without this step an unchecked Excel cell
    -- could never remove an obsolete capability.
    if v_row ? 'dutyCodes' and jsonb_typeof(v_row->'dutyCodes')='array' then
      update public.matrix_employee_duties_v2 capability set
        active=false,updated_at=now()
      from public.matrix_duties_v2 duty
      where capability.matrix_version_id=v_matrix
        and capability.employee_id=v_employee
        and capability.duty_id=duty.id
        and duty.matrix_version_id=v_matrix
        and upper(duty.code) in (
          select upper(code.value)
          from jsonb_array_elements_text(v_row->'dutyCodes') code
        )
        and not exists(
          select 1
          from jsonb_array_elements(coalesce(v_normalized->'employeeDuties','[]'::jsonb)) imported
          where (
              (nullif(trim(v_row->>'employeeNo'),'') is not null
                and upper(coalesce(imported.value->>'employeeNo',''))=upper(trim(v_row->>'employeeNo')))
              or (nullif(lower(trim(v_row->>'email')),'') is not null
                and lower(coalesce(imported.value->>'email',''))=lower(trim(v_row->>'email')))
            )
            and upper(coalesce(imported.value->>'dutyCode',''))=upper(duty.code)
            and coalesce((imported.value->>'active')::boolean,true)
        );
    end if;

    if v_row ? 'active' then
      v_desired_active:=(v_row->>'active')::boolean;
      if v_desired_active is distinct from v_profile_active then
        perform public.matrix_v2_employee_archive_v2(
          v_employee,
          case when v_desired_active then null
            else 'Archiwizacja zgodna z polem AKTYWNY w imporcie Matrixa.' end,
          not v_desired_active
        );
      end if;
    end if;
  end loop;

  for v_row in select value from jsonb_array_elements(
    coalesce(v_normalized->'employees','[]'::jsonb)
  ) where nullif(value->>'baseRate','') is not null
  loop
    select profile.employee_id,greatest(
      coalesce(nullif(v_row->>'preferenceMonth','')::date,v_effective),
      coalesce(profile.employment_start,
        coalesce(nullif(v_row->>'preferenceMonth','')::date,v_effective))
    ),profile.employment_end into v_employee,v_rate_start,v_employment_end
    from public.matrix_employee_profiles_v2 profile
    where profile.matrix_version_id=v_matrix and (
      (nullif(trim(v_row->>'employeeNo'),'') is not null
        and upper(profile.employee_no)=upper(trim(v_row->>'employeeNo')))
      or (nullif(lower(trim(v_row->>'email')),'') is not null
        and lower(profile.email)=lower(trim(v_row->>'email')))
    ) order by profile.employee_id limit 1;
    if v_employee is null then
      raise exception 'IMPORTED_EMPLOYEE_NOT_FOUND|%|%',
        coalesce(v_row->>'employeeNo',''),coalesce(v_row->>'email','');
    end if;
    select min(rate.valid_from) into v_next_rate_start
    from public.employee_pay_rates_v2 rate
    where rate.employee_id=v_employee and rate.active
      and rate.valid_from>v_rate_start;
    v_rate_end:=case
      when v_next_rate_start is null then v_employment_end
      when v_employment_end is null then v_next_rate_start-1
      else least(v_employment_end,v_next_rate_start-1)
    end;
    select * into v_existing_rate
    from public.employee_pay_rates_v2 rate
    where rate.employee_id=v_employee and rate.active
      and rate.valid_from<=v_rate_start
      and (rate.valid_to is null or rate.valid_to>=v_rate_start)
    order by rate.valid_from desc,rate.id limit 1;
    v_rate_amount:=round(replace(v_row->>'baseRate',',','.')::numeric*100)::bigint;
    -- Re-importing an unchanged workbook is idempotent.  Do not split a rate
    -- period merely because the same amount and contract were supplied again.
    if v_existing_rate.id is not null
      and v_existing_rate.base_rate_minor=v_rate_amount
      and upper(coalesce(v_existing_rate.currency,''))=upper(coalesce(v_currency,''))
      and upper(coalesce(v_existing_rate.contract_type,''))=
        upper(coalesce(nullif(v_row->>'contractType',''),'')) then
      continue;
    end if;
    if v_existing_rate.id is not null and v_existing_rate.valid_from<v_rate_start then
      perform public.employee_pay_rate_save_v2(
        v_existing_rate.id,v_employee,v_existing_rate.valid_from,v_rate_start-1,
        v_existing_rate.base_rate_minor,v_existing_rate.currency,
        v_existing_rate.contract_type,v_existing_rate.active
      );
      v_existing_rate.id:=null;
    end if;
    perform public.employee_pay_rate_save_v2(
      v_existing_rate.id,v_employee,v_rate_start,v_rate_end,v_rate_amount,
      v_currency,nullif(v_row->>'contractType',''),true
    );
  end loop;

  if v_mode='REPLACE' then
    for v_profile in
      select profile.* from public.matrix_employee_profiles_v2 profile
      where profile.matrix_version_id=v_matrix and profile.active
        and not exists(
          select 1 from jsonb_array_elements(coalesce(v_normalized->'employees','[]'::jsonb)) imported
          where (nullif(trim(imported.value->>'employeeNo'),'') is not null
              and upper(profile.employee_no)=upper(trim(imported.value->>'employeeNo')))
            or (nullif(lower(trim(imported.value->>'email')),'') is not null
              and lower(profile.email)=lower(trim(imported.value->>'email')))
        )
      for update
    loop
      perform public.matrix_v2_employee_archive_v2(
        v_profile.employee_id,
        'Archiwizacja automatyczna: pracownik nie wystąpił w imporcie zastępującym bazę.',
        true
      );
      v_archived:=v_archived+1;
    end loop;
  end if;
  return v_result||jsonb_build_object('mode',v_mode,'archivedEmployees',v_archived);
end;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_import_apply_uat_v4(p_payload jsonb, p_mode text DEFAULT 'UPDATE'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if to_regprocedure('public.matrix_v2_import_preview_uat_v3(jsonb,text)') is null
    or to_regprocedure('public.matrix_v2_import_apply_uat_v3(jsonb,text)') is null then
    raise exception 'MATRIX_IMPORT_CONTRACT_INCOMPLETE';
  end if;
  return public.matrix_v2_import_apply_uat_v3(p_payload,p_mode);
exception when others then
  if sqlerrm like 'MATRIX_%' or sqlerrm like 'INVALID_%'
    or sqlerrm like 'EMPLOYEE_%' or sqlerrm like 'PAY_RATE_%'
    or sqlerrm like 'OVERLAPPING_%' then raise; end if;
  raise exception 'MATRIX_IMPORT_APPLY_FAILED|%|%|%',gen_random_uuid(),sqlstate,sqlerrm;
end;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_import_apply_uat_v5(p_payload jsonb, p_mode text DEFAULT 'UPDATE'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_result jsonb;
  v_matrix public.matrix_versions%rowtype;
  v_normalized jsonb;
  v_row jsonb;
  v_profile public.matrix_employee_profiles_v2%rowtype;
  v_rate public.employee_pay_rates_v2%rowtype;
  v_required_start date;
  v_rate_amount bigint;
  v_currency text;
  v_anchored integer:=0;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  if not (public.has_app_role('OWNER') or public.has_app_role('ADMIN')) then
    raise exception 'FORBIDDEN';
  end if;

  v_result:=public.matrix_v2_import_apply_uat_v4(p_payload,p_mode);

  select * into v_matrix
  from public.matrix_versions matrix
  where matrix.status='DRAFT' and matrix.schema_version>=2
  order by matrix.version desc limit 1;
  if v_matrix.id is null then raise exception 'NO_MATRIX_V2_DRAFT'; end if;

  v_normalized:=solver_private.matrix_v2_import_normalize_uat_v3(
    p_payload,v_matrix.id
  );
  v_currency:=upper(v_matrix.settings->>'currency');

  for v_row in
    select value from jsonb_array_elements(
      coalesce(v_normalized->'employees','[]'::jsonb)
    ) where nullif(value->>'baseRate','') is not null
  loop
    select profile.* into v_profile
    from public.matrix_employee_profiles_v2 profile
    where profile.matrix_version_id=v_matrix.id and (
      (nullif(trim(v_row->>'employeeNo'),'') is not null
        and upper(profile.employee_no)=upper(trim(v_row->>'employeeNo')))
      or (nullif(lower(trim(v_row->>'email')),'') is not null
        and lower(profile.email)=lower(trim(v_row->>'email')))
    ) order by profile.employee_id limit 1;
    if v_profile.employee_id is null then
      raise exception 'IMPORTED_EMPLOYEE_NOT_FOUND|%|%',
        coalesce(v_row->>'employeeNo',''),coalesce(v_row->>'email','');
    end if;

    v_required_start:=greatest(
      v_matrix.effective_from,
      coalesce(v_profile.employment_start,v_matrix.effective_from)
    );
    if v_profile.employment_end is not null
      and v_required_start>v_profile.employment_end then
      continue;
    end if;

    -- Existing historical coverage wins.  This only anchors the first rate of
    -- an employee created by the import; it never rewrites an established
    -- period or an intentional future pay change.
    if exists(
      select 1 from public.employee_pay_rates_v2 rate
      where rate.employee_id=v_profile.employee_id and rate.active
        and rate.valid_from<=v_required_start
        and (rate.valid_to is null or rate.valid_to>=v_required_start)
    ) then continue; end if;

    v_rate_amount:=round(replace(v_row->>'baseRate',',','.')::numeric*100)::bigint;
    select rate.* into v_rate
    from public.employee_pay_rates_v2 rate
    where rate.employee_id=v_profile.employee_id and rate.active
      and rate.valid_from>v_required_start
      and rate.base_rate_minor=v_rate_amount
      and upper(rate.currency)=v_currency
      and upper(coalesce(rate.contract_type,''))=
        upper(coalesce(nullif(v_row->>'contractType',''),''))
    order by rate.valid_from limit 1;
    if v_rate.id is null then
      raise exception 'IMPORTED_PAY_RATE_NOT_FOUND|%',v_profile.employee_no;
    end if;

    perform public.employee_pay_rate_save_v2(
      v_rate.id,v_profile.employee_id,v_required_start,v_rate.valid_to,
      v_rate.base_rate_minor,v_rate.currency,v_rate.contract_type,v_rate.active
    );
    v_anchored:=v_anchored+1;
  end loop;

  return v_result||jsonb_build_object('ratePeriodsAnchored',v_anchored);
exception when others then
  if sqlerrm like 'MATRIX_%' or sqlerrm like 'INVALID_%'
    or sqlerrm like 'EMPLOYEE_%' or sqlerrm like 'IMPORTED_%'
    or sqlerrm like 'PAY_RATE_%' or sqlerrm like 'OVERLAPPING_%' then raise; end if;
  raise exception 'MATRIX_IMPORT_APPLY_FAILED|%|%|%',
    gen_random_uuid(),sqlstate,sqlerrm;
end;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_import_preview_alpha16(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_result jsonb;
  v_legacy_errors jsonb;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  if not (public.has_app_role('OWNER') or public.has_app_role('ADMIN')) then
    raise exception 'FORBIDDEN';
  end if;
  v_result:=public.matrix_v2_import_preview_before_mx_k10(p_payload);
  select coalesce(jsonb_agg(jsonb_build_object(
    'sheet','ROLE-OBOWIĄZKI','row',legacy.ordinality+1,
    'column','Znaczenie / Minimum / Pora',
    'code','LEGACY_PERIOD_DEMAND_REJECTED',
    'message','Stary szeroki wymóg rola–obowiązek jest wycofany. W arkuszu Obsada wskaż dokładny Kod zmiany, Kod roli, opcjonalny Kod obowiązku i Liczbę osób.'
  ) order by legacy.ordinality),'[]'::jsonb)
  into v_legacy_errors
  from jsonb_array_elements(coalesce(p_payload->'roleDuties','[]'::jsonb))
    with ordinality legacy(value,ordinality)
  where solver_private.mx_k10_legacy_role_duty_payload_v1(legacy.value);

  if jsonb_array_length(v_legacy_errors)>0 then
    v_result:=jsonb_set(v_result,'{valid}','false'::jsonb,true);
    v_result:=jsonb_set(
      v_result,'{errors}',coalesce(v_result->'errors','[]'::jsonb)||v_legacy_errors,true
    );
  end if;
  return v_result;
end;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_import_preview_before_mx_k10(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_matrix uuid;
  v_errors jsonb:='[]'::jsonb;
  v_warnings jsonb:='[]'::jsonb;
  v_row jsonb;
  v_index integer;
  v_total integer:=0;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  if not (public.has_app_role('OWNER') or public.has_app_role('ADMIN')) then
    raise exception 'FORBIDDEN';
  end if;
  if p_payload is null or jsonb_typeof(p_payload)<>'object' then
    raise exception 'INVALID_MATRIX_IMPORT_PAYLOAD';
  end if;
  select mv.id into v_matrix from public.matrix_versions mv
  where mv.status='DRAFT' and mv.schema_version>=2
  order by mv.version desc limit 1;
  if v_matrix is null then raise exception 'NO_MATRIX_V2_DRAFT'; end if;
  if jsonb_typeof(coalesce(p_payload->'employees','[]'::jsonb))<>'array'
    or jsonb_typeof(coalesce(p_payload->'shifts','[]'::jsonb))<>'array'
    or jsonb_typeof(coalesce(p_payload->'staffingRules','[]'::jsonb))<>'array'
    or jsonb_typeof(coalesce(p_payload->'roleDuties','[]'::jsonb))<>'array' then
    raise exception 'INVALID_MATRIX_IMPORT_SECTIONS';
  end if;
  v_total:=jsonb_array_length(coalesce(p_payload->'employees','[]'::jsonb))
    +jsonb_array_length(coalesce(p_payload->'shifts','[]'::jsonb))
    +jsonb_array_length(coalesce(p_payload->'staffingRules','[]'::jsonb))
    +jsonb_array_length(coalesce(p_payload->'roleDuties','[]'::jsonb));
  if v_total=0 then
    v_errors:=v_errors||jsonb_build_array(jsonb_build_object(
      'sheet','PLIK','row',0,'code','EMPTY_IMPORT',
      'message','Plik nie zawiera obsługiwanych wierszy.'
    ));
  elsif v_total>5000 then
    v_errors:=v_errors||jsonb_build_array(jsonb_build_object(
      'sheet','PLIK','row',0,'code','IMPORT_TOO_LARGE',
      'message','Jednorazowy import może zawierać najwyżej 5000 wierszy.'
    ));
  end if;

  for v_row,v_index in
    select row.value,row.ordinality::integer
    from jsonb_array_elements(coalesce(p_payload->'employees','[]'::jsonb))
      with ordinality row(value,ordinality)
  loop
    if nullif(trim(v_row->>'firstName'),'') is null
      or nullif(trim(v_row->>'lastName'),'') is null then
      v_errors:=v_errors||jsonb_build_array(jsonb_build_object(
        'sheet','PRACOWNICY','row',v_index+1,'code','EMPLOYEE_NAME_REQUIRED',
        'message','Podaj imię i nazwisko.'
      ));
    end if;
    if nullif(trim(v_row->>'employeeNo'),'') is not null
      and not exists(select 1 from public.matrix_employee_profiles_v2 profile
        where profile.matrix_version_id=v_matrix
          and upper(profile.employee_no)=upper(trim(v_row->>'employeeNo'))) then
      v_errors:=v_errors||jsonb_build_array(jsonb_build_object(
        'sheet','PRACOWNICY','row',v_index+1,'code','EMPLOYEE_NUMBER_NOT_FOUND',
        'message','Podany numer nie istnieje. Dla nowej osoby pozostaw numer pusty — system nada go automatycznie.'
      ));
    end if;
    if nullif(lower(trim(v_row->>'email')),'') is not null
      and (select count(*) from jsonb_array_elements(
        coalesce(p_payload->'employees','[]'::jsonb)
      ) duplicate where lower(trim(duplicate.value->>'email'))=
        lower(trim(v_row->>'email'))) > 1 then
      v_errors:=v_errors||jsonb_build_array(jsonb_build_object(
        'sheet','PRACOWNICY','row',v_index+1,'code','DUPLICATE_EMPLOYEE_EMAIL',
        'message','Ten sam adres e-mail występuje w pliku więcej niż raz.'
      ));
    end if;
    if nullif(trim(v_row->>'employeeNo'),'') is not null
      and (select count(*) from jsonb_array_elements(
        coalesce(p_payload->'employees','[]'::jsonb)
      ) duplicate where upper(trim(duplicate.value->>'employeeNo'))=
        upper(trim(v_row->>'employeeNo'))) > 1 then
      v_errors:=v_errors||jsonb_build_array(jsonb_build_object(
        'sheet','PRACOWNICY','row',v_index+1,'code','DUPLICATE_EMPLOYEE_NUMBER',
        'message','Ten sam numer pracownika występuje w pliku więcej niż raz.'
      ));
    end if;
    if nullif(trim(v_row->>'employeeNo'),'') is not null
      and nullif(lower(trim(v_row->>'email')),'') is not null
      and exists(
        select 1
        from public.matrix_employee_profiles_v2 number_profile
        join public.matrix_employee_profiles_v2 email_profile
          on email_profile.matrix_version_id=number_profile.matrix_version_id
          and email_profile.employee_id<>number_profile.employee_id
          and lower(email_profile.email)=lower(trim(v_row->>'email'))
        where number_profile.matrix_version_id=v_matrix
          and upper(number_profile.employee_no)=upper(trim(v_row->>'employeeNo'))
      ) then
      v_errors:=v_errors||jsonb_build_array(jsonb_build_object(
        'sheet','PRACOWNICY','row',v_index+1,'code','EMPLOYEE_IDENTITY_CONFLICT',
        'message','Numer pracownika i adres e-mail wskazują dwie różne osoby.'
      ));
    end if;
    if nullif(trim(v_row->>'primaryRoleCode'),'') is null
      or not exists(select 1 from public.matrix_roles_v2 role_row
        where role_row.matrix_version_id=v_matrix and role_row.active
          and upper(role_row.code)=upper(v_row->>'primaryRoleCode')) then
      v_errors:=v_errors||jsonb_build_array(jsonb_build_object(
        'sheet','PRACOWNICY','row',v_index+1,'code','ROLE_NOT_FOUND',
        'message','Nie znaleziono aktywnej roli z kolumny primaryRoleCode.'
      ));
    end if;
    if jsonb_typeof(coalesce(v_row->'locationCodes','[]'::jsonb))<>'array'
      or jsonb_array_length(coalesce(v_row->'locationCodes','[]'::jsonb))=0 then
      v_errors:=v_errors||jsonb_build_array(jsonb_build_object(
        'sheet','PRACOWNICY','row',v_index+1,'code','LOCATION_REQUIRED',
        'message','Podaj co najmniej jeden zwykły lokal pracy.'
      ));
    elsif exists(
      select 1 from jsonb_array_elements_text(v_row->'locationCodes') code
      where not exists(select 1 from public.matrix_locations_v2 location_row
        where location_row.matrix_version_id=v_matrix and location_row.active
          and upper(location_row.code)=upper(code.value))
    ) then
      v_errors:=v_errors||jsonb_build_array(jsonb_build_object(
        'sheet','PRACOWNICY','row',v_index+1,'code','LOCATION_NOT_FOUND',
        'message','Co najmniej jeden kod lokalu nie istnieje w Matrixie.'
      ));
    end if;
    if nullif(v_row->>'baseRate','') is null then
      v_warnings:=v_warnings||jsonb_build_array(jsonb_build_object(
        'sheet','PRACOWNICY','row',v_index+1,'code','PAY_RATE_MISSING',
        'message','Brak stawki zablokuje późniejszą publikację Matrixa.'
      ));
    elsif (v_row->>'baseRate') !~ '^\d+([.,]\d{1,2})?$' then
      v_errors:=v_errors||jsonb_build_array(jsonb_build_object(
        'sheet','PRACOWNICY','row',v_index+1,'code','INVALID_PAY_RATE',
        'message','Stawka musi być nieujemną liczbą z maksymalnie dwoma miejscami po przecinku.'
      ));
    end if;
    if exists(select 1 from jsonb_each_text(coalesce(
      v_row->'shiftPeriodPreferences','{}'::jsonb
    )) preference where upper(preference.value) not in (
      'INHERIT','PREFERRED','NEUTRAL','AVOIDED','BLOCKED'
    )) then
      v_errors:=v_errors||jsonb_build_array(jsonb_build_object(
        'sheet','PRACOWNICY','row',v_index+1,'code','INVALID_SHIFT_PREFERENCE',
        'message','Preferencja pory musi mieć wartość INHERIT, PREFERRED, NEUTRAL, AVOIDED albo BLOCKED.'
      ));
    end if;
  end loop;

  for v_row,v_index in
    select row.value,row.ordinality::integer
    from jsonb_array_elements(coalesce(p_payload->'shifts','[]'::jsonb))
      with ordinality row(value,ordinality)
  loop
    if nullif(trim(v_row->>'code'),'') is null
      or nullif(trim(v_row->>'name'),'') is null then
      v_errors:=v_errors||jsonb_build_array(jsonb_build_object(
        'sheet','ZMIANY','row',v_index+1,'code','SHIFT_IDENTITY_REQUIRED',
        'message','Podaj kod i nazwę bloku obsady.'
      ));
    end if;
    if upper(coalesce(v_row->>'shiftPeriod',''))
      not in ('MORNING','MIDDLE','EVENING') then
      v_errors:=v_errors||jsonb_build_array(jsonb_build_object(
        'sheet','ZMIANY','row',v_index+1,'code','INVALID_SHIFT_PERIOD',
        'message','Okres zmiany to MORNING, MIDDLE albo EVENING.'
      ));
    end if;
    if coalesce(v_row->>'startsAt','') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
      or coalesce(v_row->>'endsAt','') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' then
      v_errors:=v_errors||jsonb_build_array(jsonb_build_object(
        'sheet','ZMIANY','row',v_index+1,'code','INVALID_SHIFT_TIME',
        'message','Godziny muszą mieć format HH:MM.'
      ));
    end if;
    if not exists(select 1 from public.matrix_locations_v2 location_row
      where location_row.matrix_version_id=v_matrix and location_row.active
        and upper(location_row.code)=upper(coalesce(v_row->>'locationCode',''))) then
      v_errors:=v_errors||jsonb_build_array(jsonb_build_object(
        'sheet','ZMIANY','row',v_index+1,'code','LOCATION_NOT_FOUND',
        'message','Nie znaleziono lokalu dla bloku obsady.'
      ));
    end if;
    if jsonb_typeof(coalesce(v_row->'days','[]'::jsonb))<>'array'
      or jsonb_array_length(coalesce(v_row->'days','[]'::jsonb))=0
      or exists(select 1 from jsonb_array_elements_text(v_row->'days') day_value
        where day_value.value !~ '^[1-7]$') then
      v_errors:=v_errors||jsonb_build_array(jsonb_build_object(
        'sheet','ZMIANY','row',v_index+1,'code','INVALID_SHIFT_DAYS',
        'message','Podaj co najmniej jeden dzień od 1 do 7.'
      ));
    end if;
  end loop;

  for v_row,v_index in
    select row.value,row.ordinality::integer
    from jsonb_array_elements(coalesce(p_payload->'roleDuties','[]'::jsonb))
      with ordinality row(value,ordinality)
  loop
    if not exists(select 1 from public.matrix_roles_v2 role_row
      where role_row.matrix_version_id=v_matrix and role_row.active
        and upper(role_row.code)=upper(coalesce(v_row->>'roleCode',''))) then
      v_errors:=v_errors||jsonb_build_array(jsonb_build_object(
        'sheet','ROLE-OBOWIĄZKI','row',v_index+1,'code','ROLE_NOT_FOUND',
        'message','Nie znaleziono aktywnej roli.'
      ));
    end if;
    if not exists(select 1 from public.matrix_duties_v2 duty_row
      where duty_row.matrix_version_id=v_matrix and duty_row.active
        and upper(duty_row.code)=upper(coalesce(v_row->>'dutyCode',''))) then
      v_errors:=v_errors||jsonb_build_array(jsonb_build_object(
        'sheet','ROLE-OBOWIĄZKI','row',v_index+1,'code','DUTY_NOT_FOUND',
        'message','Nie znaleziono aktywnego obowiązku.'
      ));
    end if;
    if upper(coalesce(v_row->>'assignmentMode','OPTIONAL'))
      not in ('REQUIRED','OPTIONAL','EXTRA') then
      v_errors:=v_errors||jsonb_build_array(jsonb_build_object(
        'sheet','ROLE-OBOWIĄZKI','row',v_index+1,'code','INVALID_ASSIGNMENT_MODE',
        'message','Znaczenie to REQUIRED, OPTIONAL albo EXTRA.'
      ));
    end if;
    if coalesce((v_row->>'shiftObligation')::boolean,false)
      and upper(coalesce(v_row->>'shiftPeriod',''))
        not in ('MORNING','MIDDLE','EVENING') then
      v_errors:=v_errors||jsonb_build_array(jsonb_build_object(
        'sheet','ROLE-OBOWIĄZKI','row',v_index+1,'code','SHIFT_PERIOD_REQUIRED',
        'message','Obowiązek zmianowy wymaga pory MORNING, MIDDLE albo EVENING.'
      ));
    end if;
  end loop;

  for v_row,v_index in
    select row.value,row.ordinality::integer
    from jsonb_array_elements(coalesce(p_payload->'staffingRules','[]'::jsonb))
      with ordinality row(value,ordinality)
  loop
    if upper(coalesce(v_row->>'operation','SET')) not in ('SET','ADD','REMOVE') then
      v_errors:=v_errors||jsonb_build_array(jsonb_build_object(
        'sheet','OBSADA','row',v_index+1,'code','INVALID_OPERATION',
        'message','Import obsady obsługuje SET, ADD albo REMOVE.'
      ));
    end if;
    if upper(coalesce(v_row->>'operation','SET')) in ('SET','ADD')
      and (coalesce(v_row->>'countValue','') !~ '^\d+$'
        or (v_row->>'countValue')::integer<0) then
      v_errors:=v_errors||jsonb_build_array(jsonb_build_object(
        'sheet','OBSADA','row',v_index+1,'code','INVALID_STAFFING_COUNT',
        'message','Liczba osób musi być nieujemną liczbą całkowitą.'
      ));
    end if;
    if not exists(select 1 from public.matrix_scenarios_v2 scenario
      where scenario.matrix_version_id=v_matrix and scenario.active
        and upper(scenario.code)=upper(coalesce(v_row->>'scenarioCode',''))) then
      v_errors:=v_errors||jsonb_build_array(jsonb_build_object(
        'sheet','OBSADA','row',v_index+1,'code','SCENARIO_NOT_FOUND',
        'message','Nie znaleziono scenariusza.'
      ));
    end if;
    if not exists(select 1 from public.matrix_roles_v2 role_row
      where role_row.matrix_version_id=v_matrix and role_row.active
        and upper(role_row.code)=upper(coalesce(v_row->>'roleCode',''))) then
      v_errors:=v_errors||jsonb_build_array(jsonb_build_object(
        'sheet','OBSADA','row',v_index+1,'code','ROLE_NOT_FOUND',
        'message','Nie znaleziono roli.'
      ));
    end if;
    if not exists(select 1 from public.matrix_shift_templates_v2 shift_row
      join public.matrix_locations_v2 location_row on location_row.id=shift_row.location_id
      where shift_row.matrix_version_id=v_matrix and shift_row.active
        and upper(shift_row.code)=upper(coalesce(v_row->>'shiftCode',''))
        and (nullif(v_row->>'locationCode','') is null
          or upper(location_row.code)=upper(v_row->>'locationCode'))) then
      v_errors:=v_errors||jsonb_build_array(jsonb_build_object(
        'sheet','OBSADA','row',v_index+1,'code','SHIFT_NOT_FOUND',
        'message','Nie znaleziono zmiany lub bloku obsady.'
      ));
    end if;
  end loop;

  return jsonb_build_object(
    'valid',jsonb_array_length(v_errors)=0,
    'errors',v_errors,'warnings',v_warnings,
    'summary',jsonb_build_object(
      'employees',jsonb_array_length(coalesce(p_payload->'employees','[]'::jsonb)),
      'shifts',jsonb_array_length(coalesce(p_payload->'shifts','[]'::jsonb)),
      'staffingRules',jsonb_array_length(coalesce(p_payload->'staffingRules','[]'::jsonb)),
      'roleDuties',jsonb_array_length(coalesce(p_payload->'roleDuties','[]'::jsonb)),
      'total',v_total
    ),
    'matrixVersionId',v_matrix
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_import_preview_uat_v2(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_preview jsonb;
  v_errors jsonb;
  v_row jsonb;
  v_index integer;
  v_matrix uuid;
  v_duty_count integer;
begin
  v_preview := public.matrix_v2_import_preview_alpha16(p_payload);
  v_errors := coalesce(v_preview->'errors','[]'::jsonb);
  v_matrix := (v_preview->>'matrixVersionId')::uuid;
  if jsonb_typeof(coalesce(p_payload->'employeeDuties','[]'::jsonb))<>'array' then
    raise exception 'INVALID_EMPLOYEE_DUTIES_IMPORT';
  end if;
  for v_row,v_index in
    select row.value,row.ordinality::integer
    from jsonb_array_elements(coalesce(p_payload->'employeeDuties','[]'::jsonb))
      with ordinality row(value,ordinality)
  loop
    if not exists(
      select 1 from jsonb_array_elements(coalesce(p_payload->'employees','[]'::jsonb)) employee
      where (nullif(lower(trim(v_row->>'email')),'') is not null
          and lower(trim(employee.value->>'email'))=lower(trim(v_row->>'email')))
        or (nullif(trim(v_row->>'employeeNo'),'') is not null
          and upper(trim(employee.value->>'employeeNo'))=upper(trim(v_row->>'employeeNo')))
    ) then
      v_errors:=v_errors||jsonb_build_array(jsonb_build_object(
        'sheet','PRACOWNICY','row',v_index+1,
        'code','EMPLOYEE_DUTY_EMPLOYEE_NOT_FOUND',
        'message','Funkcja pracownika nie wskazuje osoby z sekcji pracowników.'
      ));
    end if;
    if not exists(select 1 from public.matrix_duties_v2 duty
      where duty.matrix_version_id=v_matrix and duty.active
        and upper(duty.code)=upper(coalesce(v_row->>'dutyCode',''))) then
      v_errors:=v_errors||jsonb_build_array(jsonb_build_object(
        'sheet','PRACOWNICY','row',v_index+1,
        'code','EMPLOYEE_DUTY_NOT_FOUND',
        'message','Kolumna funkcji nie odpowiada aktywnemu obowiązkowi w Matrixie.'
      ));
    end if;
  end loop;
  v_duty_count:=jsonb_array_length(coalesce(p_payload->'employeeDuties','[]'::jsonb));
  v_preview:=jsonb_set(v_preview,'{errors}',v_errors,true);
  v_preview:=jsonb_set(v_preview,'{valid}',to_jsonb(jsonb_array_length(v_errors)=0),true);
  v_preview:=jsonb_set(v_preview,'{summary,employeeDuties}',to_jsonb(v_duty_count),true);
  v_preview:=jsonb_set(v_preview,'{summary,total}',to_jsonb(
    coalesce((v_preview->'summary'->>'total')::integer,0)+v_duty_count
  ),true);
  return v_preview;
end;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_import_preview_uat_v3(p_payload jsonb, p_mode text DEFAULT 'UPDATE'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_mode text:=upper(trim(coalesce(p_mode,'UPDATE')));
  v_preview jsonb;
  v_normalized jsonb;
  v_matrix uuid;
  v_updates integer;
  v_creates integer;
  v_archives integer:=0;
  v_archive_rows jsonb:='[]'::jsonb;
  v_errors jsonb;
  v_row jsonb;
  v_index integer;
  v_contract text;
  v_limits_invalid boolean;
  v_employee uuid;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  if not (public.has_app_role('OWNER') or public.has_app_role('ADMIN')) then
    raise exception 'FORBIDDEN';
  end if;
  if v_mode not in ('UPDATE','REPLACE') then raise exception 'INVALID_IMPORT_MODE'; end if;
  v_preview:=public.matrix_v2_import_preview_uat_v2(p_payload);
  v_matrix:=(v_preview->>'matrixVersionId')::uuid;
  v_normalized:=solver_private.matrix_v2_import_normalize_uat_v3(p_payload,v_matrix);
  v_preview:=public.matrix_v2_import_preview_uat_v2(v_normalized);
  v_errors:=coalesce(v_preview->'errors','[]'::jsonb);
  for v_row,v_index in
    select source.value,source.ordinality::integer
    from jsonb_array_elements(coalesce(v_normalized->'employees','[]'::jsonb))
      with ordinality source(value,ordinality)
  loop
    v_contract:=solver_private.normalize_contract_type_v2(v_row->>'contractType');
    if nullif(trim(v_row->>'contractType'),'') is null then
      v_errors:=v_errors||jsonb_build_array(jsonb_build_object(
        'sheet','PRACOWNICY','row',v_index+1,'code','CONTRACT_TYPE_REQUIRED',
        'message','Wybierz formę współpracy. Import nie przypisuje umowy automatycznie.'
      ));
    end if;
    if (v_row ? 'active' and jsonb_typeof(v_row->'active')<>'boolean')
      or (v_row ? 'onlyMorning' and jsonb_typeof(v_row->'onlyMorning')<>'boolean')
      or (v_row ? 'onlyEvening' and jsonb_typeof(v_row->'onlyEvening')<>'boolean')
      or (v_row ? 'noWeekends' and jsonb_typeof(v_row->'noWeekends')<>'boolean') then
      v_errors:=v_errors||jsonb_build_array(jsonb_build_object(
        'sheet','PRACOWNICY','row',v_index+1,'code','INVALID_EMPLOYEE_BOOLEAN',
        'message','Pola aktywności i ograniczeń muszą mieć wartość TAK albo NIE.'
      ));
    elsif coalesce((v_row->>'onlyMorning')::boolean,false)
      and coalesce((v_row->>'onlyEvening')::boolean,false) then
      v_errors:=v_errors||jsonb_build_array(jsonb_build_object(
        'sheet','PRACOWNICY','row',v_index+1,'code','CONFLICTING_SHIFT_LIMITS',
        'message','Pracownik nie może mieć jednocześnie ograniczenia tylko rano i tylko popołudnie.'
      ));
    end if;
    if v_row ? 'locationGrants' then
      if jsonb_typeof(v_row->'locationGrants')<>'array' then
        v_errors:=v_errors||jsonb_build_array(jsonb_build_object(
          'sheet','PRACOWNICY','row',v_index+1,'code','INVALID_LOCATION_GRANTS',
          'message','Uprawnienia lokalowe muszą być listą lokali.'
        ));
      elsif exists(
        select 1 from jsonb_array_elements(v_row->'locationGrants') location_grant
        where jsonb_typeof(location_grant.value)<>'object'
          or nullif(trim(location_grant.value->>'code'),'') is null
          or not exists(select 1 from public.matrix_locations_v2 location_row
            where location_row.matrix_version_id=v_matrix and location_row.active
              and upper(location_row.code)=upper(location_grant.value->>'code'))
          or (location_grant.value ? 'standardAllowed'
            and jsonb_typeof(location_grant.value->'standardAllowed')<>'boolean')
          or (location_grant.value ? 'overtimeAllowed'
            and jsonb_typeof(location_grant.value->'overtimeAllowed')<>'boolean')
          or (location_grant.value ? 'homeLocation'
            and jsonb_typeof(location_grant.value->'homeLocation')<>'boolean')
          or not (
            case when jsonb_typeof(location_grant.value->'standardAllowed')='boolean'
              then (location_grant.value->>'standardAllowed')::boolean else false end
            or case when jsonb_typeof(location_grant.value->'overtimeAllowed')='boolean'
              then (location_grant.value->>'overtimeAllowed')::boolean else false end
            or case when jsonb_typeof(location_grant.value->'homeLocation')='boolean'
              then (location_grant.value->>'homeLocation')::boolean else false end
          )
          or (
            case when jsonb_typeof(location_grant.value->'homeLocation')='boolean'
              then (location_grant.value->>'homeLocation')::boolean else false end
            and not case when jsonb_typeof(location_grant.value->'standardAllowed')='boolean'
              then (location_grant.value->>'standardAllowed')::boolean else false end
          )
      ) or (
        select count(*) from jsonb_array_elements(v_row->'locationGrants') location_grant
        where case when jsonb_typeof(location_grant.value->'homeLocation')='boolean'
          then (location_grant.value->>'homeLocation')::boolean else false end
      )>1 or (
        select count(*) from jsonb_array_elements(v_row->'locationGrants') location_grant
      )<>(
        select count(distinct upper(trim(location_grant.value->>'code')))
        from jsonb_array_elements(v_row->'locationGrants') location_grant
      ) then
        v_errors:=v_errors||jsonb_build_array(jsonb_build_object(
          'sheet','PRACOWNICY','row',v_index+1,'code','INVALID_LOCATION_GRANTS',
          'message','Sprawdź zwykłe, nadgodzinowe i bazowe uprawnienia do lokali. Każdy lokal może wystąpić tylko raz.'
        ));
      end if;
    end if;
    if v_row ? 'dutyCodes' then
      if jsonb_typeof(v_row->'dutyCodes')<>'array' or exists(
        select 1 from jsonb_array_elements_text(v_row->'dutyCodes') duty_code
        where not exists(
          select 1 from public.matrix_duties_v2 duty
          where duty.matrix_version_id=v_matrix and duty.active
            and upper(duty.code)=upper(duty_code.value)
        )
      ) then
        v_errors:=v_errors||jsonb_build_array(jsonb_build_object(
          'sheet','PRACOWNICY','row',v_index+1,'code','INVALID_DUTY_COLUMNS',
          'message','Co najmniej jedna kolumna obowiązku nie odpowiada aktywnemu obowiązkowi w Matrixie.'
        ));
      end if;
    end if;
    if nullif(v_row->>'employmentStart','') is not null
      and not pg_catalog.pg_input_is_valid(v_row->>'employmentStart','date') then
      v_errors:=v_errors||jsonb_build_array(jsonb_build_object(
        'sheet','PRACOWNICY','row',v_index+1,'code','INVALID_EMPLOYMENT_START',
        'message','Data rozpoczęcia zatrudnienia jest nieprawidłowa.'
      ));
    end if;
    if nullif(v_row->>'employmentEnd','') is not null
      and not pg_catalog.pg_input_is_valid(v_row->>'employmentEnd','date') then
      v_errors:=v_errors||jsonb_build_array(jsonb_build_object(
        'sheet','PRACOWNICY','row',v_index+1,'code','INVALID_EMPLOYMENT_END',
        'message','Data zakończenia zatrudnienia jest nieprawidłowa.'
      ));
    elsif nullif(v_row->>'employmentEnd','') is not null
      and nullif(v_row->>'employmentStart','') is null then
      v_errors:=v_errors||jsonb_build_array(jsonb_build_object(
        'sheet','PRACOWNICY','row',v_index+1,'code','EMPLOYMENT_START_REQUIRED',
        'message','Data zakończenia wymaga daty rozpoczęcia zatrudnienia.'
      ));
    elsif nullif(v_row->>'employmentStart','') is not null
      and pg_catalog.pg_input_is_valid(v_row->>'employmentStart','date')
      and nullif(v_row->>'employmentEnd','') is not null
      and pg_catalog.pg_input_is_valid(v_row->>'employmentEnd','date')
      and (v_row->>'employmentEnd')::date<(v_row->>'employmentStart')::date then
      v_errors:=v_errors||jsonb_build_array(jsonb_build_object(
        'sheet','PRACOWNICY','row',v_index+1,'code','INVALID_EMPLOYMENT_DATES',
        'message','Data zakończenia nie może poprzedzać rozpoczęcia zatrudnienia.'
      ));
    end if;
    v_employee:=null;
    if (nullif(v_row->>'employmentStart','') is null
        or pg_catalog.pg_input_is_valid(v_row->>'employmentStart','date'))
      and (nullif(v_row->>'employmentEnd','') is null
        or pg_catalog.pg_input_is_valid(v_row->>'employmentEnd','date')) then
      select profile.employee_id into v_employee
      from public.matrix_employee_profiles_v2 profile
      where profile.matrix_version_id=v_matrix
        and nullif(trim(v_row->>'employeeNo'),'') is not null
        and upper(profile.employee_no)=upper(trim(v_row->>'employeeNo'));
      if v_employee is not null and exists(
        select 1 from public.employee_pay_rates_v2 rate
        where rate.employee_id=v_employee and (
          (nullif(v_row->>'employmentStart','') is not null
            and rate.valid_from<(v_row->>'employmentStart')::date)
          or (nullif(v_row->>'employmentEnd','') is not null and (
            rate.valid_from>(v_row->>'employmentEnd')::date
            or rate.valid_to is null
            or rate.valid_to>(v_row->>'employmentEnd')::date
          ))
        )
      ) then
        v_errors:=v_errors||jsonb_build_array(jsonb_build_object(
          'sheet','PRACOWNICY','row',v_index+1,
          'code','EMPLOYMENT_DATES_CONFLICT_PAY_RATES',
          'message','Okres zatrudnienia jest sprzeczny z zapisaną historią stawek tego pracownika.'
        ));
      end if;
    end if;
    if v_contract in ('UMOWA_O_PRACE','CZESC_ETATU') and (
      nullif(v_row->>'nominalHours','') is null
      or nullif(v_row->>'maximumMonthlyHours','') is null
      or nullif(v_row->>'maximumWeeklyHours','') is null
      or nullif(v_row->>'maximumConsecutiveDays','') is null
    ) then
      v_errors:=v_errors||jsonb_build_array(jsonb_build_object(
        'sheet','PRACOWNICY','row',v_index+1,'code','EMPLOYMENT_LIMITS_REQUIRED',
        'message','Dla umowy o pracę podaj nominał, limit miesięczny, limit tygodniowy i maksymalną liczbę kolejnych dni.'
      ));
    end if;
    v_limits_invalid:=coalesce(v_row->>'nominalHours','') !~ '^\d+([.,]\d+)?$'
      or coalesce(v_row->>'maximumMonthlyHours','') !~ '^\d+([.,]\d+)?$'
      or coalesce(v_row->>'maximumWeeklyHours','') !~ '^\d+([.,]\d+)?$'
      or coalesce(v_row->>'maximumConsecutiveDays','') !~ '^\d+$'
      or coalesce(v_row->>'employmentFraction','') !~ '^\d+([.,]\d+)?$'
      or (nullif(v_row->>'minimumRestHours','') is not null
        and (v_row->>'minimumRestHours') !~ '^\d+([.,]\d+)?$');
    if not v_limits_invalid then
      v_limits_invalid:=replace(v_row->>'maximumMonthlyHours',',','.')::numeric
        <replace(v_row->>'nominalHours',',','.')::numeric
        or replace(v_row->>'nominalHours',',','.')::numeric>744
        or replace(v_row->>'maximumMonthlyHours',',','.')::numeric>744
        or replace(v_row->>'maximumWeeklyHours',',','.')::numeric>168
        or (v_row->>'maximumConsecutiveDays')::integer not between 1 and 31
        or replace(v_row->>'employmentFraction',',','.')::numeric not between .01 and 1
        or (nullif(v_row->>'minimumRestHours','') is not null
          and replace(v_row->>'minimumRestHours',',','.')::numeric>48);
    end if;
    if v_limits_invalid then
      v_errors:=v_errors||jsonb_build_array(jsonb_build_object(
        'sheet','PRACOWNICY','row',v_index+1,'code','INVALID_EMPLOYEE_LIMITS',
        'message','Sprawdź nominał i limity. Limit miesięczny nie może być niższy od nominału.'
      ));
    end if;
    if nullif(v_row->>'preferenceMonth','') is not null
      and not pg_catalog.pg_input_is_valid(v_row->>'preferenceMonth','date') then
      v_errors:=v_errors||jsonb_build_array(jsonb_build_object(
        'sheet','PRACOWNICY','row',v_index+1,'code','INVALID_PREFERENCE_MONTH',
        'message','Miesiąc preferencji ma nieprawidłową datę.'
      ));
    end if;
    if upper(coalesce(v_row->>'workTimePolicy','CONTRACT_DEFAULT'))
      not in ('CONTRACT_DEFAULT','CUSTOM') then
      v_errors:=v_errors||jsonb_build_array(jsonb_build_object(
        'sheet','PRACOWNICY','row',v_index+1,'code','INVALID_WORK_TIME_POLICY',
        'message','Polityka czasu pracy to CONTRACT_DEFAULT albo CUSTOM.'
      ));
    end if;
  end loop;
  v_preview:=jsonb_set(v_preview,'{errors}',v_errors,true);
  v_preview:=jsonb_set(v_preview,'{valid}',to_jsonb(jsonb_array_length(v_errors)=0),true);

  select count(*) into v_updates
  from jsonb_array_elements(coalesce(v_normalized->'employees','[]'::jsonb)) imported
  where exists(select 1 from public.matrix_employee_profiles_v2 profile
    where profile.matrix_version_id=v_matrix and (
      (nullif(trim(imported.value->>'employeeNo'),'') is not null
        and upper(profile.employee_no)=upper(trim(imported.value->>'employeeNo')))
      or (nullif(lower(trim(imported.value->>'email')),'') is not null
        and lower(profile.email)=lower(trim(imported.value->>'email')))
    ));
  v_creates:=jsonb_array_length(coalesce(v_normalized->'employees','[]'::jsonb))-v_updates;
  if v_mode='REPLACE' then
    select count(*),coalesce(jsonb_agg(jsonb_build_object(
      'employeeId',profile.employee_id,'employeeNo',profile.employee_no,
      'employeeName',profile.first_name||' '||profile.last_name,
      'email',coalesce(profile.email,employee.email),
      'reason',case when exists(
        select 1 from jsonb_array_elements(coalesce(v_normalized->'employees','[]'::jsonb)) imported
        where nullif(lower(trim(imported.value->>'email')),'') is not null
          and lower(trim(imported.value->>'email')) in (
            lower(coalesce(profile.email,'')),lower(coalesce(employee.email,''))
          )
      ) then 'DUPLICATE_IDENTITY' else 'NOT_IN_FILE' end
    ) order by profile.employee_no),'[]'::jsonb)
    into v_archives,v_archive_rows
    from public.matrix_employee_profiles_v2 profile
    join public.employees employee on employee.id=profile.employee_id
    where profile.matrix_version_id=v_matrix and profile.active
      and not exists(
        select 1 from jsonb_array_elements(coalesce(v_normalized->'employees','[]'::jsonb)) imported
        where nullif(trim(imported.value->>'employeeNo'),'') is not null
          and upper(profile.employee_no)=upper(trim(imported.value->>'employeeNo'))
      );
  end if;
  v_preview:=jsonb_set(v_preview,'{summary,employeesToUpdate}',to_jsonb(v_updates),true);
  v_preview:=jsonb_set(v_preview,'{summary,employeesToCreate}',to_jsonb(v_creates),true);
  v_preview:=jsonb_set(v_preview,'{summary,employeesToArchive}',to_jsonb(v_archives),true);
  return v_preview||jsonb_build_object(
    'mode',v_mode,'employeesToArchive',v_archive_rows
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_import_preview_uat_v4(p_payload jsonb, p_mode text DEFAULT 'UPDATE'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if to_regprocedure('public.matrix_v2_import_preview_uat_v3(jsonb,text)') is null
    or to_regprocedure('public.matrix_v2_import_apply_uat_v3(jsonb,text)') is null then
    raise exception 'MATRIX_IMPORT_CONTRACT_INCOMPLETE';
  end if;
  return public.matrix_v2_import_preview_uat_v3(p_payload,p_mode);
exception when others then
  if sqlerrm like 'MATRIX_%' or sqlerrm like 'INVALID_%' then raise; end if;
  raise exception 'MATRIX_IMPORT_PREVIEW_FAILED|%|%|%',gen_random_uuid(),sqlstate,sqlerrm;
end;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_import_preview_uat_v5(p_payload jsonb, p_mode text DEFAULT 'UPDATE'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  return public.matrix_v2_import_preview_uat_v4(p_payload,p_mode);
end;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_is_iso_4217_currency(p_currency text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE STRICT
 SET search_path TO ''
AS $function$
  select p_currency ~ '^[A-Z]{3}$' and position(
    ' '||p_currency||' ' in
    ' AED AFN ALL AMD ANG AOA ARS AUD AWG AZN BAM BBD BDT BGN BHD BIF BMD BND BOB BOV BRL BSD BTN BWP BYN BZD CAD CDF CHE CHF CHW CLF CLP CNY COP COU CRC CUC CUP CVE CZK DJF DKK DOP DZD EGP ERN ETB EUR FJD FKP GBP GEL GHS GIP GMD GNF GTQ GYD HKD HNL HTG HUF IDR ILS INR IQD IRR ISK JMD JOD JPY KES KGS KHR KMF KPW KRW KWD KYD KZT LAK LBP LKR LRD LSL LYD MAD MDL MGA MKD MMK MNT MOP MRU MUR MVR MWK MXN MXV MYR MZN NAD NGN NIO NOK NPR NZD OMR PAB PEN PGK PHP PKR PLN PYG QAR RON RSD RUB RWF SAR SBD SCR SDG SEK SGD SHP SLE SLL SOS SRD SSP STN SVC SYP SZL THB TJS TMT TND TOP TRY TTD TWD TZS UAH UGX USD USN UYI UYU UYW UZS VED VES VND VUV WST XAF XAG XAU XBA XBB XBC XBD XCD XDR XOF XPD XPF XPT XSU XTS XUA XXX YER ZAR ZMW ZWG ZWL '
  ) > 0;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_is_supported_objective_config(p_direction text, p_parameters jsonb)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE STRICT
 SET search_path TO ''
AS $function$
  select jsonb_typeof(p_parameters)='object'
    and p_parameters-array['target','targetValue']='{}'::jsonb
    and not (p_parameters ? 'target' and p_parameters ? 'targetValue')
    and (
      not (p_parameters ? 'target' or p_parameters ? 'targetValue')
      or (
        case upper(p_direction)
          when 'MIN' then 'MINIMIZE'
          when 'MAX' then 'MAXIMIZE'
          else upper(p_direction)
        end='MINIMIZE'
        and coalesce(p_parameters->>case
          when p_parameters ? 'targetValue' then 'targetValue'
          else 'target' end,'') ~ '^[0-9]+$'
      )
    );
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_is_supported_pay_condition(p_condition jsonb)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE STRICT
 SET search_path TO ''
AS $function$
  select case
    when jsonb_typeof(p_condition)<>'object'
      or p_condition-array['field','operator','value']<>'{}'::jsonb
      or not (p_condition ? 'field' and p_condition ? 'operator'
        and p_condition ? 'value')
      then false
    when lower(p_condition->>'field') in (
      'role_id','location_id','shift_template_id','scenario_id','employee_id'
    ) then case upper(p_condition->>'operator')
      when 'EQ' then jsonb_typeof(p_condition->'value')='string'
        and (p_condition->>'value')
          ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      when 'NE' then jsonb_typeof(p_condition->'value')='string'
        and (p_condition->>'value')
          ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      when 'IN' then jsonb_typeof(p_condition->'value')='array' and not exists(
        select 1 from jsonb_array_elements(p_condition->'value') item
        where jsonb_typeof(item.value)<>'string'
          or (item.value#>>'{}')
            !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      )
      when 'NOT_IN' then jsonb_typeof(p_condition->'value')='array' and not exists(
        select 1 from jsonb_array_elements(p_condition->'value') item
        where jsonb_typeof(item.value)<>'string'
          or (item.value#>>'{}')
            !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      )
      else false end
    when lower(p_condition->>'field')='duty_ids' then
      case upper(p_condition->>'operator')
        when 'CONTAINS' then jsonb_typeof(p_condition->'value')='string'
          and (p_condition->>'value')
            ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        when 'CONTAINS_ANY' then jsonb_typeof(p_condition->'value')='array'
          and not exists(
            select 1 from jsonb_array_elements(p_condition->'value') item
            where jsonb_typeof(item.value)<>'string'
              or (item.value#>>'{}')
                !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          )
        when 'CONTAINS_ALL' then jsonb_typeof(p_condition->'value')='array'
          and not exists(
            select 1 from jsonb_array_elements(p_condition->'value') item
            where jsonb_typeof(item.value)<>'string'
              or (item.value#>>'{}')
                !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          )
        else false end
    when lower(p_condition->>'field')='contract_code' then
      case upper(p_condition->>'operator')
        when 'EQ' then jsonb_typeof(p_condition->'value')='string'
          and length(p_condition->>'value')>0
        when 'NE' then jsonb_typeof(p_condition->'value')='string'
          and length(p_condition->>'value')>0
        when 'IN' then jsonb_typeof(p_condition->'value')='array'
          and not exists(
            select 1 from jsonb_array_elements(p_condition->'value') item
            where jsonb_typeof(item.value)<>'string'
              or length(item.value#>>'{}')=0
          )
        when 'NOT_IN' then jsonb_typeof(p_condition->'value')='array'
          and not exists(
            select 1 from jsonb_array_elements(p_condition->'value') item
            where jsonb_typeof(item.value)<>'string'
              or length(item.value#>>'{}')=0
          )
        else false end
    when lower(p_condition->>'field') in ('weekday','duration_minutes') then
      case upper(p_condition->>'operator')
        when 'EQ' then jsonb_typeof(p_condition->'value')='number'
          and (p_condition->'value'#>>'{}') ~ '^[0-9]+$'
          and (lower(p_condition->>'field')<>'weekday'
            or (p_condition->>'value')::integer between 1 and 7)
        when 'NE' then jsonb_typeof(p_condition->'value')='number'
          and (p_condition->'value'#>>'{}') ~ '^[0-9]+$'
          and (lower(p_condition->>'field')<>'weekday'
            or (p_condition->>'value')::integer between 1 and 7)
        when 'GTE' then jsonb_typeof(p_condition->'value')='number'
          and (p_condition->'value'#>>'{}') ~ '^[0-9]+$'
          and (lower(p_condition->>'field')<>'weekday'
            or (p_condition->>'value')::integer between 1 and 7)
        when 'LTE' then jsonb_typeof(p_condition->'value')='number'
          and (p_condition->'value'#>>'{}') ~ '^[0-9]+$'
          and (lower(p_condition->>'field')<>'weekday'
            or (p_condition->>'value')::integer between 1 and 7)
        when 'IN' then jsonb_typeof(p_condition->'value')='array'
          and not exists(
            select 1 from jsonb_array_elements(p_condition->'value') item
            where jsonb_typeof(item.value)<>'number'
              or (item.value#>>'{}') !~ '^[0-9]+$'
              or (lower(p_condition->>'field')='weekday'
                and (item.value#>>'{}')::integer not between 1 and 7)
          )
        when 'NOT_IN' then jsonb_typeof(p_condition->'value')='array'
          and not exists(
            select 1 from jsonb_array_elements(p_condition->'value') item
            where jsonb_typeof(item.value)<>'number'
              or (item.value#>>'{}') !~ '^[0-9]+$'
              or (lower(p_condition->>'field')='weekday'
                and (item.value#>>'{}')::integer not between 1 and 7)
          )
        else false end
    when lower(p_condition->>'field')='local_time' then
      upper(p_condition->>'operator')='OVERLAPS_TIME'
      and jsonb_typeof(p_condition->'value')='object'
      and (p_condition->'value')-array['start','end']<>'{}'::jsonb
      and coalesce(p_condition->'value'->>'start','')
        ~ '^([01][0-9]|2[0-3]):[0-5][0-9](:[0-5][0-9])?$'
      and coalesce(p_condition->'value'->>'end','')
        ~ '^([01][0-9]|2[0-3]):[0-5][0-9](:[0-5][0-9])?$'
    else false
  end;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_merge_equivalent_shifts_uat_v2(p_apply boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_matrix uuid; v_groups integer:=0; v_duplicates integer:=0;
  v_blockers jsonb:='[]'::jsonb; v_preview jsonb:='[]'::jsonb;
  group_row record; rule_row public.matrix_staffing_rules_v2%rowtype;
  v_existing public.matrix_staffing_rules_v2%rowtype;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  if not (public.has_app_role('OWNER') or public.has_app_role('ADMIN')) then
    raise exception 'FORBIDDEN';
  end if;
  select version.id into v_matrix from public.matrix_versions version
  where version.status='DRAFT' and version.schema_version>=2
  order by version.version desc limit 1;
  if v_matrix is null then raise exception 'NO_MATRIX_V2_DRAFT'; end if;

  with groups as (
    select min(shift.id::text)::uuid survivor_id,
      array_agg(shift.id order by shift.sort_order,shift.id) ids,
      min(shift.name) name,shift.location_id,
      min(shift.starts_at) starts_at,min(shift.ends_at) ends_at,
      count(*) amount
    from public.matrix_shift_templates_v2 shift
    where shift.matrix_version_id=v_matrix and shift.active
    group by shift.location_id,lower(trim(shift.name)),shift.starts_at,
      shift.ends_at,shift.ends_next_day
    having count(*)>1
  )
  select count(*),coalesce(sum(amount-1),0),coalesce(jsonb_agg(jsonb_build_object(
    'name',name,'locationId',location_id,'startsAt',starts_at,'endsAt',ends_at,
    'entries',amount,'survivorId',survivor_id,'ids',to_jsonb(ids)
  ) order by name),'[]'::jsonb)
  into v_groups,v_duplicates,v_preview from groups;

  with groups as (
    select (array_agg(shift.id order by shift.sort_order,shift.id))[1] survivor_id,
      (array_agg(shift.id order by shift.sort_order,shift.id))[2:] duplicate_ids
    from public.matrix_shift_templates_v2 shift
    where shift.matrix_version_id=v_matrix and shift.active
    group by shift.location_id,lower(trim(shift.name)),shift.starts_at,
      shift.ends_at,shift.ends_next_day having count(*)>1
  ), conflicts as (
    select jsonb_build_object('code','STAFFING_RULE_CONFLICT','message',
      'Powielone zmiany mają różne reguły obsady dla tego samego zakresu.') blocker
    from groups
    join public.matrix_staffing_rules_v2 duplicate
      on duplicate.shift_template_id=any(groups.duplicate_ids)
    join public.matrix_staffing_rules_v2 survivor
      on survivor.shift_template_id=groups.survivor_id
      and survivor.scenario_id=duplicate.scenario_id
      and survivor.role_id=duplicate.role_id
      and survivor.duty_id is not distinct from duplicate.duty_id
    where row(survivor.operation,survivor.count_value,
      survivor.multiplier_basis_points,survivor.active)
      is distinct from row(duplicate.operation,duplicate.count_value,
        duplicate.multiplier_basis_points,duplicate.active)
    union all
    select jsonb_build_object('code','EVENT_DEMAND_REFERENCE','message',
      'Co najmniej jeden powielony wpis jest używany przez aktywny event.')
    from groups join public.workforce_event_demand_v2 demand
      on demand.shift_template_id=any(groups.duplicate_ids)
    join public.workforce_calendar_events_v2 event on event.id=demand.event_id
    where event.status='ACTIVE'
  )
  select coalesce(jsonb_agg(distinct blocker),'[]'::jsonb)
    into v_blockers from conflicts;

  if not p_apply then return jsonb_build_object(
    'matrixVersionId',v_matrix,'groups',v_groups,'duplicates',v_duplicates,
    'items',v_preview,'blockers',v_blockers,'applied',false
  ); end if;
  if jsonb_array_length(v_blockers)>0 then
    raise exception 'SHIFT_MERGE_BLOCKED:%',v_blockers::text;
  end if;
  perform pg_advisory_xact_lock(hashtext('matrix-v2-lifecycle'));

  for group_row in
    select (array_agg(shift.id order by shift.sort_order,shift.id))[1] survivor_id,
      (array_agg(shift.id order by shift.sort_order,shift.id))[2:] duplicate_ids,
      array_agg(distinct day_value order by day_value)::smallint[] merged_days
    from public.matrix_shift_templates_v2 shift
    cross join lateral unnest(shift.day_mask) day_value
    where shift.matrix_version_id=v_matrix and shift.active
    group by shift.location_id,lower(trim(shift.name)),shift.starts_at,
      shift.ends_at,shift.ends_next_day having count(distinct shift.id)>1
  loop
    update public.matrix_shift_templates_v2 set day_mask=group_row.merged_days,
      shift_period=case when extract(hour from starts_at)<12 then 'MORNING'
        when extract(hour from starts_at)<17 then 'MIDDLE' else 'EVENING' end,
      updated_at=now() where id=group_row.survivor_id;

    for rule_row in select * from public.matrix_staffing_rules_v2
      where shift_template_id=any(group_row.duplicate_ids)
    loop
      select * into v_existing from public.matrix_staffing_rules_v2 existing
      where existing.shift_template_id=group_row.survivor_id
        and existing.scenario_id=rule_row.scenario_id
        and existing.role_id=rule_row.role_id
        and existing.duty_id is not distinct from rule_row.duty_id limit 1;
      if v_existing.id is null then
        update public.matrix_staffing_rules_v2
          set shift_template_id=group_row.survivor_id,updated_at=now()
        where id=rule_row.id;
      else
        delete from public.matrix_staffing_rules_v2 where id=rule_row.id;
      end if;
      v_existing:=null;
    end loop;

    insert into public.matrix_pay_rule_shifts_v2(
      matrix_version_id,pay_rule_id,shift_template_id
    ) select distinct mapping.matrix_version_id,mapping.pay_rule_id,
      group_row.survivor_id
    from public.matrix_pay_rule_shifts_v2 mapping
    where mapping.shift_template_id=any(group_row.duplicate_ids)
    on conflict do nothing;
    delete from public.matrix_pay_rule_shifts_v2 mapping
      where mapping.shift_template_id=any(group_row.duplicate_ids);
    update public.matrix_shift_templates_v2 set active=false,updated_at=now()
      where id=any(group_row.duplicate_ids);
  end loop;

  insert into public.audit_log(actor_id,entity_type,entity_id,action,new_data)
  values(auth.uid(),'matrix_v2_shifts',v_matrix::text,'MERGE_EQUIVALENT_SHIFTS',
    jsonb_build_object('groups',v_groups,'duplicates',v_duplicates,'items',v_preview));
  return jsonb_build_object(
    'matrixVersionId',v_matrix,'groups',v_groups,'duplicates',v_duplicates,
    'items',v_preview,'blockers','[]'::jsonb,'applied',true
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_next_employee_no_v2()
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_number integer:=1;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  if not (public.has_app_role('OWNER') or public.has_app_role('ADMIN')
    or public.has_app_role('HR_FINANCE')) then raise exception 'FORBIDDEN'; end if;
  while exists(
    select 1 from public.employees employee
    where upper(employee.employee_no)=upper('GP-'||lpad(v_number::text,3,'0'))
  ) loop
    v_number:=v_number+1;
  end loop;
  return 'GP-'||lpad(v_number::text,3,'0');
end;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_normalize_shift_periods_uat_v2()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_matrix uuid; v_updated integer:=0; v_recognized integer:=0;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  if not (public.has_app_role('OWNER') or public.has_app_role('ADMIN')) then
    raise exception 'FORBIDDEN';
  end if;
  perform pg_advisory_xact_lock(hashtext('matrix-v2-lifecycle'));
  v_matrix:=public.matrix_v2_create_draft(null);
  select count(*) into v_recognized from public.matrix_shift_templates_v2 shift_row
  where shift_row.matrix_version_id=v_matrix and shift_row.active;
  update public.matrix_shift_templates_v2 shift_row set
    shift_period=case when extract(hour from shift_row.starts_at)<12 then 'MORNING'
      when extract(hour from shift_row.starts_at)<17 then 'MIDDLE' else 'EVENING' end,
    updated_at=now()
  where shift_row.matrix_version_id=v_matrix and shift_row.active
    and shift_row.shift_period is distinct from case
      when extract(hour from shift_row.starts_at)<12 then 'MORNING'
      when extract(hour from shift_row.starts_at)<17 then 'MIDDLE' else 'EVENING' end;
  get diagnostics v_updated=row_count;
  insert into public.audit_log(actor_id,entity_type,entity_id,action,new_data)
  values(auth.uid(),'matrix_v2_shift_periods',v_matrix::text,'NORMALIZE_FROM_START_TIME',
    jsonb_build_object('recognized',v_recognized,'updated',v_updated,
      'morningBefore','12:00','middleBefore','17:00'));
  return jsonb_build_object('matrixVersionId',v_matrix,
    'recognized',v_recognized,'updated',v_updated);
end;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_prevent_last_usable_delete_uat_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if old.status in ('DRAFT','ACTIVE') and not exists(
    select 1 from public.matrix_versions mv
    where mv.id<>old.id and mv.status in ('DRAFT','ACTIVE')
  ) then
    raise exception 'MATRIX_LAST_USABLE_VERSION_REQUIRED';
  end if;
  return old;
end;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_publication_readiness_alpha16(p_effective_from date DEFAULT CURRENT_DATE)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_matrix uuid;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  if not (public.has_app_role('OWNER') or public.has_app_role('ADMIN')) then
    raise exception 'FORBIDDEN';
  end if;
  select mv.id into v_matrix from public.matrix_versions mv
  where mv.status='DRAFT' and mv.schema_version>=2
  order by mv.version desc limit 1;
  if v_matrix is null then raise exception 'NO_MATRIX_V2_DRAFT'; end if;
  return jsonb_build_object(
    'ready',not exists(
      select 1 from public.matrix_employee_profiles_v2 profile
      where profile.matrix_version_id=v_matrix and profile.active and (
        not exists(select 1 from public.employee_pay_rates_v2 rate
          where rate.employee_id=profile.employee_id and rate.active
            and rate.valid_from<=p_effective_from
            and (rate.valid_to is null or rate.valid_to>=p_effective_from))
        or not exists(select 1 from public.matrix_employee_roles_v2 role_grant
          where role_grant.matrix_version_id=v_matrix
            and role_grant.employee_id=profile.employee_id and role_grant.active)
        or not exists(select 1 from public.matrix_employee_locations_v2 location_grant
          where location_grant.matrix_version_id=v_matrix
            and location_grant.employee_id=profile.employee_id
            and location_grant.active and location_grant.standard_allowed)
      )
    ),
    'blockers',coalesce((
      select jsonb_agg(blocker order by blocker->>'employeeNo',blocker->>'code')
      from (
        select jsonb_build_object(
          'code','MISSING_PAY_RATE','employeeId',profile.employee_id,
          'employeeNo',profile.employee_no,
          'employeeName',profile.first_name||' '||profile.last_name,
          'message','Brak aktywnej stawki na dzień publikacji.'
        ) blocker
        from public.matrix_employee_profiles_v2 profile
        where profile.matrix_version_id=v_matrix and profile.active
          and not exists(select 1 from public.employee_pay_rates_v2 rate
            where rate.employee_id=profile.employee_id and rate.active
              and rate.valid_from<=p_effective_from
              and (rate.valid_to is null or rate.valid_to>=p_effective_from))
        union all
        select jsonb_build_object(
          'code','MISSING_ROLE','employeeId',profile.employee_id,
          'employeeNo',profile.employee_no,
          'employeeName',profile.first_name||' '||profile.last_name,
          'message','Brak aktywnej roli w Matrixie.'
        )
        from public.matrix_employee_profiles_v2 profile
        where profile.matrix_version_id=v_matrix and profile.active
          and not exists(select 1 from public.matrix_employee_roles_v2 role_grant
            where role_grant.matrix_version_id=v_matrix
              and role_grant.employee_id=profile.employee_id and role_grant.active)
        union all
        select jsonb_build_object(
          'code','MISSING_STANDARD_LOCATION','employeeId',profile.employee_id,
          'employeeNo',profile.employee_no,
          'employeeName',profile.first_name||' '||profile.last_name,
          'message','Brak co najmniej jednego lokalu pracy w zwykłym limicie.'
        )
        from public.matrix_employee_profiles_v2 profile
        where profile.matrix_version_id=v_matrix and profile.active
          and not exists(select 1 from public.matrix_employee_locations_v2 location_grant
            where location_grant.matrix_version_id=v_matrix
              and location_grant.employee_id=profile.employee_id
              and location_grant.active and location_grant.standard_allowed)
      ) problems
    ),'[]'::jsonb),
    'effectiveFrom',p_effective_from,'matrixVersionId',v_matrix
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_publication_readiness_base_uat006(p_effective_from date, p_schedule_month date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_matrix uuid;
  v_month date:=date_trunc('month',coalesce(p_schedule_month,p_effective_from,current_date))::date;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  if not (public.has_app_role('OWNER') or public.has_app_role('ADMIN')) then
    raise exception 'FORBIDDEN';
  end if;
  select mv.id into v_matrix from public.matrix_versions mv
  where mv.status='DRAFT' and mv.schema_version>=2
  order by mv.version desc limit 1;
  if v_matrix is null then raise exception 'NO_MATRIX_V2_DRAFT'; end if;

  return jsonb_build_object(
    'ready',not exists(
      select 1 from public.matrix_employee_profiles_v2 profile
      where profile.matrix_version_id=v_matrix and profile.active
        and coalesce(profile.employment_start,v_month)<v_month+interval '1 month'
        and coalesce(profile.employment_end,v_month)>=v_month
        and (
          not solver_private.employee_pay_rate_covers_period_v2(
            profile.employee_id,
            greatest(v_month,coalesce(profile.employment_start,v_month)),
            least((v_month+interval '1 month'-interval '1 day')::date,
              coalesce(profile.employment_end,(v_month+interval '1 month'-interval '1 day')::date))
          )
          or not exists(select 1 from public.matrix_employee_roles_v2 role_grant
            where role_grant.matrix_version_id=v_matrix
              and role_grant.employee_id=profile.employee_id and role_grant.active)
          or not exists(select 1 from public.matrix_employee_locations_v2 location_grant
            where location_grant.matrix_version_id=v_matrix
              and location_grant.employee_id=profile.employee_id
              and location_grant.active and location_grant.standard_allowed)
        )
    ) and not exists(
      select 1 from public.matrix_shift_templates_v2 shift_row
      where shift_row.matrix_version_id=v_matrix and shift_row.active
        and shift_row.shift_period is distinct from case
          when upper(shift_row.code) like 'RANO%' then 'MORNING'
          when upper(shift_row.code) like 'SRODEK%'
            or upper(shift_row.code) like 'ŚRODEK%' then 'MIDDLE'
          when upper(shift_row.code) like 'WIECZOR%'
            or upper(shift_row.code) like 'WIECZÓR%' then 'EVENING'
          else shift_row.shift_period
        end
    ),
    'blockers',coalesce((
      select jsonb_agg(blocker order by blocker->>'employeeNo',blocker->>'code')
      from (
        select jsonb_build_object(
          'code','MISSING_PAY_RATE','employeeId',profile.employee_id,
          'employeeNo',profile.employee_no,
          'employeeName',profile.first_name||' '||profile.last_name,
          'requiredFrom',greatest(v_month,coalesce(profile.employment_start,v_month)),
          'requiredTo',least((v_month+interval '1 month'-interval '1 day')::date,
            coalesce(profile.employment_end,(v_month+interval '1 month'-interval '1 day')::date)),
          'foundRates',coalesce((
            select jsonb_agg(jsonb_build_object(
              'validFrom',rate.valid_from,'validTo',rate.valid_to,
              'amountMinor',rate.base_rate_minor,'currency',rate.currency
            ) order by rate.valid_from)
            from public.employee_pay_rates_v2 rate
            where rate.employee_id=profile.employee_id and rate.active
          ),'[]'::jsonb),
          'message','Brak ciągłej aktywnej stawki dla całego okresu pracy w miesiącu grafiku.'
        ) blocker
        from public.matrix_employee_profiles_v2 profile
        where profile.matrix_version_id=v_matrix and profile.active
          and coalesce(profile.employment_start,v_month)<v_month+interval '1 month'
          and coalesce(profile.employment_end,v_month)>=v_month
          and not solver_private.employee_pay_rate_covers_period_v2(
            profile.employee_id,
            greatest(v_month,coalesce(profile.employment_start,v_month)),
            least((v_month+interval '1 month'-interval '1 day')::date,
              coalesce(profile.employment_end,(v_month+interval '1 month'-interval '1 day')::date))
          )
        union all
        select jsonb_build_object(
          'code','MISSING_ROLE','employeeId',profile.employee_id,
          'employeeNo',profile.employee_no,
          'employeeName',profile.first_name||' '||profile.last_name,
          'message','Brak aktywnej roli w Matrixie.'
        )
        from public.matrix_employee_profiles_v2 profile
        where profile.matrix_version_id=v_matrix and profile.active
          and coalesce(profile.employment_start,v_month)<v_month+interval '1 month'
          and coalesce(profile.employment_end,v_month)>=v_month
          and not exists(select 1 from public.matrix_employee_roles_v2 role_grant
            where role_grant.matrix_version_id=v_matrix
              and role_grant.employee_id=profile.employee_id and role_grant.active)
        union all
        select jsonb_build_object(
          'code','MISSING_STANDARD_LOCATION','employeeId',profile.employee_id,
          'employeeNo',profile.employee_no,
          'employeeName',profile.first_name||' '||profile.last_name,
          'message','Brak co najmniej jednego zwykłego lokalu pracy.'
        )
        from public.matrix_employee_profiles_v2 profile
        where profile.matrix_version_id=v_matrix and profile.active
          and coalesce(profile.employment_start,v_month)<v_month+interval '1 month'
          and coalesce(profile.employment_end,v_month)>=v_month
          and not exists(select 1 from public.matrix_employee_locations_v2 location_grant
            where location_grant.matrix_version_id=v_matrix
              and location_grant.employee_id=profile.employee_id
              and location_grant.active and location_grant.standard_allowed)
        union all
        select jsonb_build_object(
          'code','SHIFT_PERIOD_MISMATCH','shiftTemplateId',shift_row.id,
          'shiftName',shift_row.name,'shiftCode',shift_row.code,
          'storedPeriod',shift_row.shift_period,
          'expectedPeriod',case
            when upper(shift_row.code) like 'RANO%' then 'MORNING'
            when upper(shift_row.code) like 'SRODEK%'
              or upper(shift_row.code) like 'ŚRODEK%' then 'MIDDLE'
            when upper(shift_row.code) like 'WIECZOR%'
              or upper(shift_row.code) like 'WIECZÓR%' then 'EVENING'
          end,
          'message','Pora zmiany jest niespójna z jej jednoznacznym kodem.'
        )
        from public.matrix_shift_templates_v2 shift_row
        where shift_row.matrix_version_id=v_matrix and shift_row.active
          and shift_row.shift_period is distinct from case
            when upper(shift_row.code) like 'RANO%' then 'MORNING'
            when upper(shift_row.code) like 'SRODEK%'
              or upper(shift_row.code) like 'ŚRODEK%' then 'MIDDLE'
            when upper(shift_row.code) like 'WIECZOR%'
              or upper(shift_row.code) like 'WIECZÓR%' then 'EVENING'
            else shift_row.shift_period
          end
      ) problems
    ),'[]'::jsonb),
    'effectiveFrom',coalesce(p_effective_from,current_date),
    'scheduleMonth',v_month,
    'matrixVersionId',v_matrix
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_publication_readiness_before_b4f115(p_effective_from date, p_schedule_month date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_base jsonb;
  v_matrix uuid;
  v_extra jsonb := '[]'::jsonb;
  v_blockers jsonb := '[]'::jsonb;
begin
  v_base := public.matrix_v2_publication_readiness_before_simple_roles_uat_v1(
    p_effective_from,
    p_schedule_month
  );
  v_matrix := nullif(v_base->>'matrixVersionId','')::uuid;

  select coalesce(jsonb_agg(problem order by employee_no),'[]'::jsonb)
  into v_extra
  from (
    select employee.employee_no,
      jsonb_build_object(
        'code','EMPLOYEE_PRIMARY_ROLE_REQUIRED',
        'employeeId',profile.employee_id,
        'employeeNo',employee.employee_no,
        'employeeName',trim(employee.first_name||' '||employee.last_name),
        'message',format(
          '%s (%s) nie ma dokładnie jednej aktywnej roli podstawowej. Przejdź do Zespół → Role i wybierz rolę podstawową.',
          trim(employee.first_name||' '||employee.last_name),
          employee.employee_no
        )
      ) problem
    from public.matrix_employee_profiles_v2 profile
    join public.employees employee on employee.id = profile.employee_id
    where profile.matrix_version_id = v_matrix
      and profile.active
      and profile.archived_at is null
      and (
        select count(*)
        from public.matrix_employee_roles_v2 role_link
        where role_link.matrix_version_id = profile.matrix_version_id
          and role_link.employee_id = profile.employee_id
          and role_link.active
          and role_link.is_primary
      ) <> 1
  ) invalid_profiles;

  v_blockers := coalesce(v_base->'blockers','[]'::jsonb) || v_extra;
  return v_base || jsonb_build_object(
    'ready',jsonb_array_length(v_blockers) = 0,
    'blockers',v_blockers
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_publication_readiness_before_simple_roles_uat_v1(p_effective_from date, p_schedule_month date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_base jsonb;
  v_matrix uuid;
  v_extra jsonb := '[]'::jsonb;
  v_base_blockers jsonb := '[]'::jsonb;
  v_all_blockers jsonb := '[]'::jsonb;
begin
  v_base := public.matrix_v2_publication_readiness_base_uat006(p_effective_from,p_schedule_month);
  v_matrix := nullif(v_base->>'matrixVersionId','')::uuid;

  select coalesce(jsonb_agg(value),'[]'::jsonb) into v_base_blockers
  from jsonb_array_elements(coalesce(v_base->'blockers','[]'::jsonb))
  where value->>'code' <> 'SHIFT_PERIOD_MISMATCH';

  select coalesce(jsonb_agg(problem),'[]'::jsonb) into v_extra
  from (
    select jsonb_build_object(
      'code','REQUIRED_DUTY_WITH_ZERO_MINIMUM','roleId',link.role_id,
      'dutyId',link.duty_id,'message',
      'Obowiązek wymagany musi mieć minimalną liczbę co najmniej 1.'
    ) problem
    from public.matrix_role_duties_v2 link
    where link.matrix_version_id=v_matrix and link.active
      and link.assignment_mode='REQUIRED' and link.minimum_count<1
    union all
    select jsonb_build_object(
      'code','STAFFING_DUTY_NOT_LINKED_TO_ROLE','roleId',rule.role_id,
      'dutyId',rule.duty_id,'shiftTemplateId',rule.shift_template_id,
      'message','Reguła obsady używa obowiązku nieprzypisanego do tej roli.'
    )
    from public.matrix_staffing_rules_v2 rule
    where rule.matrix_version_id=v_matrix and rule.active and rule.duty_id is not null
      and not exists(select 1 from public.matrix_role_duties_v2 link
        where link.matrix_version_id=rule.matrix_version_id
          and link.role_id=rule.role_id and link.duty_id=rule.duty_id and link.active)
    union all
    select jsonb_build_object(
      'code','INACTIVE_DUTY_HAS_ACTIVE_DEPENDENCIES','dutyId',duty.id,
      'message','Wyłączony obowiązek nadal ma aktywne zależności.'
    )
    from public.matrix_duties_v2 duty
    where duty.matrix_version_id=v_matrix and not duty.active and (
      exists(select 1 from public.matrix_role_duties_v2 link where link.matrix_version_id=v_matrix and link.duty_id=duty.id and link.active)
      or exists(select 1 from public.matrix_employee_duties_v2 link where link.matrix_version_id=v_matrix and link.duty_id=duty.id and link.active)
      or exists(select 1 from public.matrix_staffing_rules_v2 rule where rule.matrix_version_id=v_matrix and rule.duty_id=duty.id and rule.active)
    )
    union all
    select jsonb_build_object(
      'code','SHIFT_PERIOD_FROM_TIME_MISMATCH','shiftTemplateId',shift_row.id,
      'shiftName',shift_row.name,'shiftCode',shift_row.code,
      'message','Automatyczna klasyfikacja zmiany jest niespójna z godziną rozpoczęcia.'
    )
    from public.matrix_shift_templates_v2 shift_row
    where shift_row.matrix_version_id=v_matrix and shift_row.active
      and shift_row.shift_period is distinct from case
        when extract(hour from shift_row.starts_at)<12 then 'MORNING'
        when extract(hour from shift_row.starts_at)<17 then 'MIDDLE'
        else 'EVENING' end
    union all
    select jsonb_build_object(
      'code','SHIFT_OVERNIGHT_FLAG_INCONSISTENT',
      'shiftTemplateId',shift_row.id,'shiftCode',shift_row.code,
      'shiftName',shift_row.name,'locationId',shift_row.location_id,
      'startsAt',to_char(shift_row.starts_at,'HH24:MI'),
      'endsAt',to_char(shift_row.ends_at,'HH24:MI'),
      'endsNextDay',shift_row.ends_next_day,
      'expectedEndsNextDay',(shift_row.ends_at<=shift_row.starts_at),
      'message',format(
        '%s (%s–%s): pole „Następny dzień” powinno mieć wartość %s.',
        shift_row.name,to_char(shift_row.starts_at,'HH24:MI'),
        to_char(shift_row.ends_at,'HH24:MI'),
        case when shift_row.ends_at<=shift_row.starts_at then 'TAK' else 'NIE' end
      )
    )
    from public.matrix_shift_templates_v2 shift_row
    where shift_row.matrix_version_id=v_matrix and shift_row.active
      and shift_row.ends_next_day is distinct from (shift_row.ends_at<=shift_row.starts_at)
  ) problems;

  v_all_blockers:=v_base_blockers||v_extra;
  return v_base||jsonb_build_object(
    'ready',jsonb_array_length(v_all_blockers)=0,
    'blockers',v_all_blockers
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_publication_readiness_uat_v2(p_effective_from date, p_schedule_month date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_base jsonb;
  v_matrix uuid;
  v_default_scenario uuid;
  v_shift_blockers jsonb:='[]'::jsonb;
  v_blockers jsonb:='[]'::jsonb;
begin
  v_base:=public.matrix_v2_publication_readiness_before_b4f115(p_effective_from,p_schedule_month);
  v_matrix:=nullif(v_base->>'matrixVersionId','')::uuid;
  select scenario.id into v_default_scenario
  from public.matrix_scenarios_v2 scenario
  where scenario.matrix_version_id=v_matrix and scenario.active and scenario.is_default
  order by scenario.sort_order,scenario.id limit 1;

  if v_default_scenario is not null then
    select coalesce(jsonb_agg(jsonb_build_object(
      'code','SHIFT_BASE_STAFFING_REQUIRED',
      'shiftTemplateId',shift_row.id,
      'shiftCode',shift_row.code,
      'shiftName',shift_row.name,
      'locationId',shift_row.location_id,
      'startsAt',to_char(shift_row.starts_at,'HH24:MI'),
      'endsAt',to_char(shift_row.ends_at,'HH24:MI'),
      'endsNextDay',shift_row.ends_next_day,
      'message',format('%s • %s • %s–%s: uzupełnij obsadę albo wyłącz zmianę.',location_row.name,shift_row.name,to_char(shift_row.starts_at,'HH24:MI'),to_char(shift_row.ends_at,'HH24:MI'))
    ) order by location_row.sort_order,shift_row.sort_order,shift_row.id),'[]'::jsonb)
    into v_shift_blockers
    from public.matrix_shift_templates_v2 shift_row
    join public.matrix_locations_v2 location_row
      on location_row.id=shift_row.location_id and location_row.matrix_version_id=shift_row.matrix_version_id
    where shift_row.matrix_version_id=v_matrix and shift_row.active
      and not exists(
        select 1 from public.matrix_staffing_rules_v2 staffing
        where staffing.matrix_version_id=v_matrix
          and staffing.scenario_id=v_default_scenario
          and staffing.shift_template_id=shift_row.id
          and staffing.active and staffing.operation='SET'
          and staffing.count_value>=1
      );
  end if;

  v_blockers:=coalesce(v_base->'blockers','[]'::jsonb)||v_shift_blockers;
  return v_base||jsonb_build_object('ready',jsonb_array_length(v_blockers)=0,'blockers',v_blockers);
end;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_publish_draft(p_effective_from date DEFAULT CURRENT_DATE)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_draft public.matrix_versions%rowtype;
  v_active public.matrix_versions%rowtype;
  v_default_count integer;
  v_cycle boolean;
  v_document jsonb;
  v_hash text;
  v_scenario record;
  v_active_strategy_count integer;
begin
  if not (public.has_app_role('OWNER') or public.has_app_role('ADMIN')) then
    raise exception 'FORBIDDEN';
  end if;
  if p_effective_from is null then raise exception 'EFFECTIVE_FROM_REQUIRED'; end if;
  if p_effective_from>current_date then
    raise exception 'FUTURE_MATRIX_ACTIVATION_REQUIRES_SCHEDULER';
  end if;
  perform pg_advisory_xact_lock(hashtext('matrix-v2-lifecycle'));

  select * into v_draft from public.matrix_versions mv
  where mv.status='DRAFT' and mv.schema_version>=2
  order by mv.version desc limit 1 for update;
  if v_draft.id is null then raise exception 'NO_MATRIX_V2_DRAFT'; end if;
  select * into v_active from public.matrix_versions mv
  where mv.status='ACTIVE' order by mv.version desc limit 1 for update;
  if exists(select 1 from public.matrix_versions mv
      where mv.status='ACTIVE' and p_effective_from<mv.effective_from) then
    raise exception 'EFFECTIVE_FROM_PRECEDES_ACTIVE_MATRIX';
  end if;

  select count(*) into v_default_count from public.matrix_scenarios_v2 s
  where s.matrix_version_id=v_draft.id and s.active and s.is_default;
  if v_default_count<>1 then raise exception 'EXACTLY_ONE_ACTIVE_DEFAULT_SCENARIO_REQUIRED'; end if;
  if exists(select 1 from public.matrix_scenarios_v2 s
    where s.matrix_version_id=v_draft.id and s.active and s.is_default
      and s.parent_scenario_id is not null) then
    raise exception 'DEFAULT_SCENARIO_CANNOT_INHERIT';
  end if;

  if not exists(select 1 from public.matrix_roles_v2 x
      where x.matrix_version_id=v_draft.id and x.active)
    or not exists(select 1 from public.matrix_locations_v2 x
      where x.matrix_version_id=v_draft.id and x.active)
    or not exists(select 1 from public.matrix_shift_templates_v2 x
      where x.matrix_version_id=v_draft.id and x.active)
    or not exists(select 1 from public.matrix_strategies_v2 x
      where x.matrix_version_id=v_draft.id and x.active) then
    raise exception 'ACTIVE_ROLE_LOCATION_SHIFT_AND_STRATEGY_REQUIRED';
  end if;

  if exists(select 1 from public.matrix_locations_v2 l
    where l.matrix_version_id=v_draft.id
      and not exists(select 1 from pg_catalog.pg_timezone_names tz
        where tz.name=l.timezone)) then
    raise exception 'INVALID_LOCATION_TIMEZONE';
  end if;
  if exists(
    select 1 from public.matrix_shift_templates_v2 shift_row
    where shift_row.matrix_version_id=v_draft.id and shift_row.active
      and shift_row.ends_next_day is distinct from
        (shift_row.ends_at<=shift_row.starts_at)
  ) then raise exception 'SHIFT_OVERNIGHT_FLAG_INCONSISTENT'; end if;
  if not public.matrix_v2_is_iso_4217_currency(
    upper(coalesce(v_draft.settings->>'currency',''))
  ) then
    raise exception 'INVALID_MATRIX_CURRENCY';
  end if;
  if nullif(v_draft.settings->>'timezone','') is null or not exists(
    select 1 from pg_catalog.pg_timezone_names tz
    where tz.name=v_draft.settings->>'timezone'
  ) then raise exception 'INVALID_MATRIX_TIMEZONE'; end if;
  if coalesce(v_draft.settings->>'minimumRestMinutes','') !~ '^[0-9]+$'
    or (v_draft.settings->>'minimumRestMinutes')::integer<0
    or coalesce(v_draft.settings->>'maximumShiftsPerDay','') !~ '^[0-9]+$'
    or (v_draft.settings->>'maximumShiftsPerDay')::integer not between 1 and 24
    or jsonb_typeof(v_draft.settings->'missingAvailabilityMeansAvailable')<>'boolean'
    or jsonb_typeof(v_draft.settings->'requireOptimal')<>'boolean'
  then raise exception 'INVALID_MATRIX_SETTINGS'; end if;
  if exists(
    select 1 from public.matrix_scenarios_v2 s
    where s.matrix_version_id=v_draft.id and s.active and (
      jsonb_typeof(s.settings_overrides)<>'object'
      or s.settings_overrides-array[
        'timezone','minimumRestMinutes','maximumShiftsPerDay',
        'missingAvailabilityMeansAvailable','requireOptimal',
        'onlyMorningBeforeMinute','onlyEveningAfterMinute','randomSeed'
      ]<>'{}'::jsonb
      or (s.settings_overrides ? 'timezone' and (
        nullif(s.settings_overrides->>'timezone','') is null
        or not exists(select 1 from pg_catalog.pg_timezone_names tz
          where tz.name=s.settings_overrides->>'timezone')
      ))
      or (s.settings_overrides ? 'minimumRestMinutes' and (
        coalesce(s.settings_overrides->>'minimumRestMinutes','') !~ '^[0-9]+$'
        or (s.settings_overrides->>'minimumRestMinutes')::integer<0
      ))
      or (s.settings_overrides ? 'maximumShiftsPerDay' and (
        coalesce(s.settings_overrides->>'maximumShiftsPerDay','') !~ '^[0-9]+$'
        or (s.settings_overrides->>'maximumShiftsPerDay')::integer not between 1 and 24
      ))
      or (s.settings_overrides ? 'missingAvailabilityMeansAvailable'
        and jsonb_typeof(s.settings_overrides->'missingAvailabilityMeansAvailable')<>'boolean')
      or (s.settings_overrides ? 'requireOptimal'
        and jsonb_typeof(s.settings_overrides->'requireOptimal')<>'boolean')
      or (s.settings_overrides ? 'onlyMorningBeforeMinute' and (
        coalesce(s.settings_overrides->>'onlyMorningBeforeMinute','') !~ '^[0-9]+$'
        or (s.settings_overrides->>'onlyMorningBeforeMinute')::integer>2880
      ))
      or (s.settings_overrides ? 'onlyEveningAfterMinute' and (
        coalesce(s.settings_overrides->>'onlyEveningAfterMinute','') !~ '^[0-9]+$'
        or (s.settings_overrides->>'onlyEveningAfterMinute')::integer>2880
      ))
      or (s.settings_overrides ? 'randomSeed' and
        coalesce(s.settings_overrides->>'randomSeed','') !~ '^[0-9]+$')
    )
  ) then raise exception 'INVALID_SCENARIO_SETTINGS_OVERRIDE'; end if;
  if exists(
    select 1 from public.matrix_pay_rules_v2 p
    where p.matrix_version_id=v_draft.id and p.active
      and p.currency<>upper(v_draft.settings->>'currency')
  ) or exists(
    select 1 from public.matrix_scenario_budgets_v2 b
    where b.matrix_version_id=v_draft.id
      and b.currency<>upper(v_draft.settings->>'currency')
  ) or exists(
    select 1 from public.employee_pay_rates_v2 r
    join public.matrix_employee_profiles_v2 profile
      on profile.matrix_version_id=v_draft.id
      and profile.employee_id=r.employee_id and profile.active
    where r.active and r.valid_from<=p_effective_from
      and (r.valid_to is null or r.valid_to>=p_effective_from)
      and r.currency<>upper(v_draft.settings->>'currency')
  ) then raise exception 'MIXED_CURRENCIES_UNSUPPORTED'; end if;
  if exists(
    select 1 from public.matrix_employee_profiles_v2 profile
    where profile.matrix_version_id=v_draft.id and profile.active
      and not exists(
        select 1 from public.employee_pay_rates_v2 rate
        where rate.employee_id=profile.employee_id and rate.active
          and rate.valid_from<=p_effective_from
          and (rate.valid_to is null or rate.valid_to>=p_effective_from)
      )
  ) then raise exception 'ACTIVE_EMPLOYEE_REQUIRES_PAY_RATE'; end if;
  if exists(
    select 1 from public.matrix_pay_rules_v2 p
    where p.matrix_version_id=v_draft.id and p.active and (
      jsonb_typeof(p.condition_expression)<>'object'
      or p.condition_expression-array['conditions']<>'{}'::jsonb
      or (p.condition_expression ? 'conditions'
        and jsonb_typeof(p.condition_expression->'conditions')<>'array')
      or p.formula_expression<>'{}'::jsonb
      or (p.local_start is null)<>(p.local_end is null)
      or (
        case when p.local_start is null then 0 else 1 end
        +(select count(*) from jsonb_array_elements(
          coalesce(p.condition_expression->'conditions','[]'::jsonb)
        ) condition where lower(coalesce(condition.value->>'field',''))='local_time'
          and upper(coalesce(condition.value->>'operator',''))='OVERLAPS_TIME')
      )>1
      or (
        p.calculation_method in (
          'SHIFT_DURATION_THRESHOLD_PER_HOUR','MONTHLY_THRESHOLD_PER_HOUR'
        ) and (
          p.local_start is not null or exists(
            select 1 from jsonb_array_elements(
              coalesce(p.condition_expression->'conditions','[]'::jsonb)
            ) condition where lower(coalesce(condition.value->>'field',''))='local_time'
              and upper(coalesce(condition.value->>'operator',''))='OVERLAPS_TIME'
          )
        )
      )
      or (p.calculation_method='MULTIPLIER'
        and p.multiplier_basis_points<10000)
      or (p.calculation_method='FIXED_PER_SHIFT' and (
        p.rate_minor_per_hour is not null or p.percent_basis_points is not null
        or p.multiplier_basis_points is not null or p.threshold_minutes is not null
      ))
      or (p.calculation_method='PER_HOUR' and (
        p.amount_minor is not null or p.percent_basis_points is not null
        or p.multiplier_basis_points is not null or p.threshold_minutes is not null
      ))
      or (p.calculation_method='PERCENT_BASE' and (
        p.amount_minor is not null or p.rate_minor_per_hour is not null
        or p.multiplier_basis_points is not null or p.threshold_minutes is not null
      ))
      or (p.calculation_method='MULTIPLIER' and (
        p.amount_minor is not null or p.rate_minor_per_hour is not null
        or p.percent_basis_points is not null or p.threshold_minutes is not null
      ))
      or (p.calculation_method in (
        'SHIFT_DURATION_THRESHOLD_PER_HOUR','MONTHLY_THRESHOLD_PER_HOUR'
      ) and (
        p.amount_minor is not null or p.percent_basis_points is not null
        or p.multiplier_basis_points is not null
      ))
    )
  ) then raise exception 'INVALID_PAY_RULE_CONFIGURATION'; end if;
  if exists(
    select 1
    from public.matrix_pay_rules_v2 p
    cross join lateral jsonb_array_elements(
      coalesce(p.condition_expression->'conditions','[]'::jsonb)
    ) condition
    where p.matrix_version_id=v_draft.id and p.active
      and not public.matrix_v2_is_supported_pay_condition(condition.value)
  ) then raise exception 'UNSUPPORTED_PAY_RULE_CONDITION'; end if;
  if exists(
    select 1 from public.matrix_pay_rules_v2 left_rule
    join public.matrix_pay_rules_v2 right_rule
      on right_rule.matrix_version_id=left_rule.matrix_version_id
      and right_rule.id>left_rule.id and right_rule.active
      and coalesce(right_rule.stacking_group,right_rule.id::text)
        =coalesce(left_rule.stacking_group,left_rule.id::text)
      and right_rule.stacking_mode<>left_rule.stacking_mode
    where left_rule.matrix_version_id=v_draft.id and left_rule.active
  ) then raise exception 'INCONSISTENT_PAY_STACKING_GROUP'; end if;
  if exists(
    select 1 from public.matrix_scenario_pay_rule_overrides_v2 override
    join public.matrix_scenarios_v2 scenario
      on scenario.id=override.scenario_id and scenario.active
    join public.matrix_pay_rules_v2 rule
      on rule.id=override.pay_rule_id and rule.active
    where override.matrix_version_id=v_draft.id and (
      coalesce(override.formula_expression,'{}'::jsonb)<>'{}'::jsonb
      or (rule.calculation_method='FIXED_PER_SHIFT' and (
        override.rate_minor_per_hour is not null
        or override.percent_basis_points is not null
        or override.multiplier_basis_points is not null
      ))
      or (rule.calculation_method in (
        'PER_HOUR','SHIFT_DURATION_THRESHOLD_PER_HOUR',
        'MONTHLY_THRESHOLD_PER_HOUR'
      ) and (
        override.amount_minor is not null
        or override.percent_basis_points is not null
        or override.multiplier_basis_points is not null
      ))
      or (rule.calculation_method='PERCENT_BASE' and (
        override.amount_minor is not null or override.rate_minor_per_hour is not null
        or override.multiplier_basis_points is not null
      ))
      or (rule.calculation_method='MULTIPLIER' and (
        override.amount_minor is not null or override.rate_minor_per_hour is not null
        or override.percent_basis_points is not null
        or (override.multiplier_basis_points is not null
          and override.multiplier_basis_points<10000)
      ))
    )
  ) then raise exception 'INVALID_SCENARIO_PAY_RULE_OVERRIDE'; end if;
  if exists(select 1 from public.matrix_shift_templates_v2 s
    where s.matrix_version_id=v_draft.id
      and cardinality(s.day_mask)<>(select count(distinct d) from unnest(s.day_mask) d)) then
    raise exception 'SHIFT_DAY_MASK_CONTAINS_DUPLICATES';
  end if;

  with recursive walk(id,parent_scenario_id,path,cycle) as (
    select s.id,s.parent_scenario_id,array[s.id],false
    from public.matrix_scenarios_v2 s where s.matrix_version_id=v_draft.id
    union all
    select p.id,p.parent_scenario_id,w.path||p.id,p.id=any(w.path)
    from walk w join public.matrix_scenarios_v2 p on p.id=w.parent_scenario_id
    where not w.cycle
  ) select coalesce(bool_or(w.cycle),false) into v_cycle from walk w;
  if v_cycle then raise exception 'SCENARIO_INHERITANCE_CYCLE'; end if;
  if exists(
    with recursive chain as (
      select s.id,s.parent_scenario_id,0 depth
      from public.matrix_scenarios_v2 s
      where s.matrix_version_id=v_draft.id
      union all
      select parent.id,parent.parent_scenario_id,chain.depth+1
      from chain
      join public.matrix_scenarios_v2 parent
        on parent.id=chain.parent_scenario_id
        and parent.matrix_version_id=v_draft.id
      where chain.depth<32
    )
    select 1 from chain
    where chain.depth=32 and chain.parent_scenario_id is not null
  ) then raise exception 'SCENARIO_INHERITANCE_TOO_DEEP'; end if;
  if exists(select 1 from public.matrix_scenarios_v2 s
    join public.matrix_scenarios_v2 p on p.id=s.parent_scenario_id
    where s.matrix_version_id=v_draft.id and s.active and not p.active) then
    raise exception 'ACTIVE_SCENARIO_HAS_INACTIVE_PARENT';
  end if;

  if exists(
    select 1 from public.matrix_strategies_v2 s
    where s.matrix_version_id=v_draft.id and s.active and (
      upper(s.solver_code)<>'CP_SAT'
      or jsonb_typeof(s.solver_options)<>'object'
    )
  ) then raise exception 'UNSUPPORTED_STRATEGY_SOLVER_CONFIGURATION'; end if;
  if exists(
    select 1 from public.matrix_strategies_v2 s
    where s.matrix_version_id=v_draft.id and s.active and (
      s.solver_options-array['maxTimeSeconds','randomSeed']<>'{}'::jsonb
      or (s.solver_options ? 'maxTimeSeconds' and (
        coalesce(s.solver_options->>'maxTimeSeconds','') !~ '^[0-9]+$'
        or (s.solver_options->>'maxTimeSeconds')::integer not between 1 and 86400
      ))
      or (s.solver_options ? 'randomSeed' and (
        coalesce(s.solver_options->>'randomSeed','') !~ '^[0-9]+$'
        or (s.solver_options->>'randomSeed')::numeric>2147483647
      ))
    )
  ) then raise exception 'INVALID_STRATEGY_SOLVER_OPTIONS'; end if;

  if exists(
    select 1 from public.matrix_strategy_objectives_v2 o
    join public.matrix_strategies_v2 s on s.id=o.strategy_id and s.active
    where o.matrix_version_id=v_draft.id and o.active and (
      upper(o.metric_code) not in (
        'UNFILLED','TOTAL_COST','PREFERENCE_VIOLATIONS',
        'HOME_LOCATION_VIOLATIONS','NOMINAL_DEVIATION_MINUTES',
        'OVERTIME_MINUTES','LOAD_SPREAD_MINUTES','WEEKEND_SPREAD',
        'BASELINE_CHANGES','COST','TOTAL_COST_UNITS','PREFERENCES',
        'HOME_LOCATION','NOMINAL_DEVIATION','OVERTIME','LOAD_SPREAD',
        'BASELINE_CHANGES_COUNT','UNFILLED_SEATS','TOTAL_COST_MINOR',
        'WORKLOAD_VARIANCE','WEEKEND_VARIANCE','NON_HOME_LOCATION_COUNT'
      )
      or jsonb_typeof(o.parameters)<>'object'
    )
  ) then raise exception 'UNSUPPORTED_STRATEGY_OBJECTIVE'; end if;
  if exists(
    select 1 from public.matrix_strategy_objectives_v2 o
    join public.matrix_strategies_v2 s on s.id=o.strategy_id and s.active
    where o.matrix_version_id=v_draft.id and o.active and (
      o.parameters-array['target','targetValue']<>'{}'::jsonb
      or (o.parameters ? 'target' and o.parameters ? 'targetValue')
      or ((o.parameters ? 'target' or o.parameters ? 'targetValue') and (
        upper(o.direction)<>'MINIMIZE'
        or coalesce(o.parameters->>case when o.parameters ? 'targetValue'
          then 'targetValue' else 'target' end,'') !~ '^[0-9]+$'
      ))
    )
  ) then raise exception 'INVALID_STRATEGY_OBJECTIVE_PARAMETERS'; end if;

  if exists(
    select 1 from public.matrix_scenario_strategies_v2 ss
    join public.matrix_scenarios_v2 sc on sc.id=ss.scenario_id and sc.active
    join public.matrix_strategies_v2 st on st.id=ss.strategy_id and st.active
    where ss.matrix_version_id=v_draft.id and ss.active and (
      jsonb_typeof(ss.objective_overrides)<>'object'
      or jsonb_typeof(ss.solver_overrides)<>'object'
    )
  ) then raise exception 'INVALID_SCENARIO_STRATEGY_OVERRIDE'; end if;
  if exists(
    select 1
    from public.matrix_scenario_strategies_v2 ss
    join public.matrix_scenarios_v2 sc on sc.id=ss.scenario_id and sc.active
    join public.matrix_strategies_v2 st on st.id=ss.strategy_id and st.active
    cross join lateral jsonb_each(ss.objective_overrides) ov
    left join public.matrix_strategy_objectives_v2 objective
      on objective.strategy_id=ss.strategy_id
      and objective.metric_code=upper(ov.key) and objective.active
    where ss.matrix_version_id=v_draft.id and ss.active and (
      ov.key<>upper(ov.key)
      or objective.id is null
      or jsonb_typeof(ov.value)<>'object'
      or (ov.value ? 'parameters'
        and jsonb_typeof(ov.value->'parameters')<>'object')
    )
  ) then raise exception 'INVALID_SCENARIO_OBJECTIVE_OVERRIDE'; end if;
  if exists(
    select 1
    from public.matrix_scenario_strategies_v2 ss
    join public.matrix_scenarios_v2 sc on sc.id=ss.scenario_id and sc.active
    join public.matrix_strategies_v2 st on st.id=ss.strategy_id and st.active
    cross join lateral jsonb_each(ss.objective_overrides) ov
    join public.matrix_strategy_objectives_v2 objective
      on objective.strategy_id=ss.strategy_id
      and objective.metric_code=upper(ov.key) and objective.active
    where ss.matrix_version_id=v_draft.id and ss.active and (
      ov.value-array['active','tier','weight','direction','tolerance','parameters']
        <>'{}'::jsonb
      or (ov.value ? 'active' and jsonb_typeof(ov.value->'active')<>'boolean')
      or (ov.value ? 'tier' and (
        coalesce(ov.value->>'tier','') !~ '^[0-9]+$'
        or (ov.value->>'tier')::integer not between 1 and 100
      ))
      or (ov.value ? 'weight' and coalesce(ov.value->>'weight','') !~ '^[0-9]+$')
      or (ov.value ? 'tolerance'
        and coalesce(ov.value->>'tolerance','') !~ '^[0-9]+$')
      or (ov.value ? 'direction' and upper(ov.value->>'direction')
        not in ('MIN','MINIMIZE','MAX','MAXIMIZE'))
      or (
        (objective.parameters||coalesce(
          ov.value->'parameters','{}'::jsonb
        ))-array['target','targetValue']<>'{}'::jsonb
        or (
          (objective.parameters||coalesce(
            ov.value->'parameters','{}'::jsonb
          )) ? 'target'
          and (objective.parameters||coalesce(
            ov.value->'parameters','{}'::jsonb
          )) ? 'targetValue'
        )
        or (
          (
            (objective.parameters||coalesce(
              ov.value->'parameters','{}'::jsonb
            )) ? 'target'
            or (objective.parameters||coalesce(
              ov.value->'parameters','{}'::jsonb
            )) ? 'targetValue'
          ) and (
            case upper(coalesce(ov.value->>'direction',objective.direction))
              when 'MIN' then 'MINIMIZE'
              when 'MAX' then 'MAXIMIZE'
              else upper(coalesce(ov.value->>'direction',objective.direction))
            end <> 'MINIMIZE'
            or coalesce(
              (objective.parameters||coalesce(
                ov.value->'parameters','{}'::jsonb
              ))->>case when (objective.parameters||coalesce(
                ov.value->'parameters','{}'::jsonb
              )) ? 'targetValue' then 'targetValue' else 'target' end,
              ''
            ) !~ '^[0-9]+$'
          )
        )
      )
    )
  ) then raise exception 'INVALID_SCENARIO_OBJECTIVE_OVERRIDE'; end if;
  if exists(
    select 1 from public.matrix_scenario_strategies_v2 ss
    join public.matrix_scenarios_v2 sc on sc.id=ss.scenario_id and sc.active
    join public.matrix_strategies_v2 st on st.id=ss.strategy_id and st.active
    where ss.matrix_version_id=v_draft.id and ss.active and (
      ss.solver_overrides-array['maxTimeSeconds','randomSeed']<>'{}'::jsonb
      or (ss.solver_overrides ? 'maxTimeSeconds' and (
        coalesce(ss.solver_overrides->>'maxTimeSeconds','') !~ '^[0-9]+$'
        or (ss.solver_overrides->>'maxTimeSeconds')::integer not between 1 and 86400
      ))
      or (ss.solver_overrides ? 'randomSeed' and (
        coalesce(ss.solver_overrides->>'randomSeed','') !~ '^[0-9]+$'
        or (ss.solver_overrides->>'randomSeed')::numeric>2147483647
      ))
    )
  ) then raise exception 'INVALID_SCENARIO_SOLVER_OVERRIDE'; end if;

  -- Validate the exact inherited configuration emitted by the snapshot, not
  -- just each override row in isolation. A child may override direction while
  -- inheriting a target, or introduce the second target alias; both must fail
  -- at publication rather than in the worker.
  if exists(
    with recursive scenario_chain as (
      select scenario.id root_id,scenario.id,scenario.parent_scenario_id,0 depth
      from public.matrix_scenarios_v2 scenario
      where scenario.matrix_version_id=v_draft.id and scenario.active
      union all
      select chain.root_id,parent.id,parent.parent_scenario_id,chain.depth+1
      from scenario_chain chain
      join public.matrix_scenarios_v2 parent
        on parent.id=chain.parent_scenario_id
        and parent.matrix_version_id=v_draft.id
      where chain.depth<32
    ), raw_links as (
      select chain.root_id,chain.depth,link.id,link.strategy_id,
        link.active,link.objective_overrides
      from scenario_chain chain
      join public.matrix_scenario_strategies_v2 link
        on link.scenario_id=chain.id
        and link.matrix_version_id=v_draft.id
    ), resolved_links as (
      select link.root_id,link.strategy_id,
        (array_agg(link.active order by link.depth,link.id))[1] active,
        solver_private.jsonb_deep_merge_array_v2(array_agg(
          link.objective_overrides order by link.depth desc,link.id
        )) objective_overrides
      from raw_links link
      group by link.root_id,link.strategy_id
    )
    select 1
    from resolved_links resolved
    join public.matrix_strategies_v2 strategy
      on strategy.id=resolved.strategy_id and strategy.active
    join public.matrix_strategy_objectives_v2 objective
      on objective.strategy_id=resolved.strategy_id and objective.active
    cross join lateral (select coalesce(
      resolved.objective_overrides->upper(objective.metric_code),'{}'::jsonb
    ) value) override_config
    where resolved.active
      and coalesce((override_config.value->>'active')::boolean,true)
      and not public.matrix_v2_is_supported_objective_config(
        coalesce(override_config.value->>'direction',objective.direction),
        objective.parameters||coalesce(
          override_config.value->'parameters','{}'::jsonb
        )
      )
  ) then raise exception 'INVALID_RESOLVED_SCENARIO_OBJECTIVE'; end if;

  for v_scenario in
    select s.id from public.matrix_scenarios_v2 s
    where s.matrix_version_id=v_draft.id and s.active
  loop
    with recursive chain as (
      select s.id,s.parent_scenario_id,0 depth
      from public.matrix_scenarios_v2 s where s.id=v_scenario.id
      union all
      select parent.id,parent.parent_scenario_id,chain.depth+1
      from public.matrix_scenarios_v2 parent
      join chain on chain.parent_scenario_id=parent.id
      where parent.matrix_version_id=v_draft.id and chain.depth<32
    ), resolved as (
      select distinct on (ss.strategy_id) ss.strategy_id,ss.active,chain.depth
      from chain join public.matrix_scenario_strategies_v2 ss
        on ss.scenario_id=chain.id and ss.matrix_version_id=v_draft.id
      order by ss.strategy_id,chain.depth,ss.id
    )
    select count(*) into v_active_strategy_count
    from resolved r join public.matrix_strategies_v2 st
      on st.id=r.strategy_id and st.active
    where r.active;
    if v_active_strategy_count=0 then
      raise exception 'ACTIVE_SCENARIO_WITHOUT_ACTIVE_STRATEGY:%',v_scenario.id;
    end if;
  end loop;
  if exists(select 1 from public.matrix_strategies_v2 s
    where s.matrix_version_id=v_draft.id and s.active
      and not exists(select 1 from public.matrix_strategy_objectives_v2 o
        where o.strategy_id=s.id and o.active and o.tier=1 and o.metric_code='UNFILLED')) then
    raise exception 'ACTIVE_STRATEGY_REQUIRES_TIER1_UNFILLED_OBJECTIVE';
  end if;

  if exists(select 1 from public.matrix_staffing_rules_v2 x
    join public.matrix_scenarios_v2 sc on sc.id=x.scenario_id
    join public.matrix_shift_templates_v2 sh on sh.id=x.shift_template_id
    join public.matrix_roles_v2 r on r.id=x.role_id
    left join public.matrix_duties_v2 d on d.id=x.duty_id
    where x.matrix_version_id=v_draft.id and x.active
      and (not sc.active or not sh.active or not r.active
        or (x.duty_id is not null and not d.active))) then
    raise exception 'ACTIVE_STAFFING_RULE_REFERENCES_INACTIVE_SCOPE';
  end if;

  -- Publishing is the fail-closed boundary. Dormant rows may remain in a
  -- draft for editing history, but no active configuration may point at a
  -- role, duty, location or shift that the snapshot itself will omit.
  if exists(
    select 1 from public.matrix_shift_templates_v2 shift_row
    join public.matrix_locations_v2 location on location.id=shift_row.location_id
    where shift_row.matrix_version_id=v_draft.id and shift_row.active
      and not location.active
  ) then raise exception 'ACTIVE_SHIFT_REFERENCES_INACTIVE_LOCATION'; end if;
  if exists(
    select 1 from public.matrix_role_duties_v2 link
    join public.matrix_roles_v2 role on role.id=link.role_id
    join public.matrix_duties_v2 duty on duty.id=link.duty_id
    where link.matrix_version_id=v_draft.id and link.active
      and (not role.active or not duty.active)
  ) then raise exception 'ROLE_DUTY_REFERENCES_INACTIVE_SCOPE'; end if;
  if exists(
    select 1 from public.matrix_employee_roles_v2 grant_row
    join public.matrix_employee_profiles_v2 profile
      on profile.matrix_version_id=grant_row.matrix_version_id
      and profile.employee_id=grant_row.employee_id
    join public.matrix_roles_v2 role on role.id=grant_row.role_id
    where grant_row.matrix_version_id=v_draft.id and profile.active
      and grant_row.active and not role.active
  ) then raise exception 'EMPLOYEE_ROLE_REFERENCES_INACTIVE_ROLE'; end if;
  if exists(
    select 1 from public.matrix_employee_locations_v2 grant_row
    join public.matrix_employee_profiles_v2 profile
      on profile.matrix_version_id=grant_row.matrix_version_id
      and profile.employee_id=grant_row.employee_id
    join public.matrix_locations_v2 location on location.id=grant_row.location_id
    where grant_row.matrix_version_id=v_draft.id and profile.active
      and grant_row.active and not location.active
  ) then raise exception 'EMPLOYEE_LOCATION_REFERENCES_INACTIVE_LOCATION'; end if;
  if exists(
    select 1 from public.matrix_employee_duties_v2 grant_row
    join public.matrix_employee_profiles_v2 profile
      on profile.matrix_version_id=grant_row.matrix_version_id
      and profile.employee_id=grant_row.employee_id
    join public.matrix_duties_v2 duty on duty.id=grant_row.duty_id
    left join public.matrix_roles_v2 role on role.id=grant_row.role_id
    left join public.matrix_locations_v2 location on location.id=grant_row.location_id
    where grant_row.matrix_version_id=v_draft.id and profile.active
      and grant_row.active and (
        not duty.active
        or (grant_row.role_id is not null and not role.active)
        or (grant_row.location_id is not null and not location.active)
      )
  ) then raise exception 'EMPLOYEE_DUTY_REFERENCES_INACTIVE_SCOPE'; end if;
  if exists(
    select 1 from public.matrix_scenario_strategies_v2 link
    join public.matrix_scenarios_v2 scenario on scenario.id=link.scenario_id
    join public.matrix_strategies_v2 strategy on strategy.id=link.strategy_id
    where link.matrix_version_id=v_draft.id and scenario.active
      and link.active and not strategy.active
  ) then raise exception 'SCENARIO_REFERENCES_INACTIVE_STRATEGY'; end if;
  if exists(
    select 1 from public.matrix_pay_rules_v2 rule
    left join public.matrix_pay_rule_roles_v2 role_link on role_link.pay_rule_id=rule.id
    left join public.matrix_roles_v2 role on role.id=role_link.role_id
    left join public.matrix_pay_rule_duties_v2 duty_link on duty_link.pay_rule_id=rule.id
    left join public.matrix_duties_v2 duty on duty.id=duty_link.duty_id
    left join public.matrix_pay_rule_locations_v2 location_link
      on location_link.pay_rule_id=rule.id
    left join public.matrix_locations_v2 location on location.id=location_link.location_id
    left join public.matrix_pay_rule_shifts_v2 shift_link on shift_link.pay_rule_id=rule.id
    left join public.matrix_shift_templates_v2 shift_row
      on shift_row.id=shift_link.shift_template_id
    where rule.matrix_version_id=v_draft.id and rule.active and (
      (role_link.pay_rule_id is not null and not role.active)
      or (duty_link.pay_rule_id is not null and not duty.active)
      or (location_link.pay_rule_id is not null and not location.active)
      or (shift_link.pay_rule_id is not null and not shift_row.active)
    )
  ) then raise exception 'PAY_RULE_REFERENCES_INACTIVE_SCOPE'; end if;
  if exists(
    select 1 from public.matrix_scenario_budgets_v2 budget
    join public.matrix_scenarios_v2 scenario on scenario.id=budget.scenario_id
    left join public.matrix_locations_v2 location on location.id=budget.location_id
    left join public.matrix_roles_v2 role on role.id=budget.role_id
    left join public.matrix_duties_v2 duty on duty.id=budget.duty_id
    where budget.matrix_version_id=v_draft.id and scenario.active and (
      (budget.location_id is not null and not location.active)
      or (budget.role_id is not null and not role.active)
      or (budget.duty_id is not null and not duty.active)
    )
  ) then raise exception 'SCENARIO_BUDGET_REFERENCES_INACTIVE_SCOPE'; end if;

  v_document:=public.matrix_v2_content_document(v_draft.id);
  if v_document is null then raise exception 'MATRIX_V2_CONTENT_NOT_FOUND'; end if;
  v_hash:=encode(extensions.digest(v_document::text,'sha256'),'hex');

  update public.matrix_versions set status='ARCHIVED',
    effective_to=greatest(effective_from,p_effective_from)
  where status='DRAFT' and id<>v_draft.id;
  update public.matrix_versions set status='ARCHIVED',
    effective_to=greatest(effective_from,p_effective_from-1)
  where status='ACTIVE' and id<>v_draft.id;
  update public.matrix_versions set status='ACTIVE',effective_from=p_effective_from,
    effective_to=null,activated_at=now(),published_at=now(),published_by=auth.uid(),
    content_hash=v_hash,schema_version=2
  where id=v_draft.id;

  insert into public.audit_log(actor_id,entity_type,entity_id,action,new_data)
  values(auth.uid(),'matrix_v2',v_draft.id::text,'PUBLISH',jsonb_build_object(
    'version',v_draft.version,'effectiveFrom',p_effective_from,
    'contentHash',v_hash,'solverEngine',(select f.engine
      from public.solver_feature_flags f where f.flag_key='DEFAULT_ENGINE')));
  return v_draft.id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_publish_draft_uat_v2(p_effective_from date DEFAULT NULL::date)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_timezone text;
  v_effective_from date;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  if not (public.has_app_role('OWNER') or public.has_app_role('ADMIN')) then
    raise exception 'FORBIDDEN';
  end if;

  select coalesce(nullif(version.settings->>'timezone',''),'UTC')
    into v_timezone
  from public.matrix_versions version
  where version.status='DRAFT' and version.schema_version>=2
  order by version.version desc
  limit 1;
  if v_timezone is null then raise exception 'NO_MATRIX_V2_DRAFT'; end if;
  if not exists(
    select 1 from pg_catalog.pg_timezone_names timezone_row
    where timezone_row.name=v_timezone
  ) then raise exception 'INVALID_MATRIX_TIMEZONE'; end if;

  perform pg_catalog.set_config('TimeZone',v_timezone,true);
  v_effective_from:=coalesce(
    p_effective_from,
    (pg_catalog.clock_timestamp() at time zone v_timezone)::date
  );
  return public.matrix_v2_publish_draft(v_effective_from);
end;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_revision_history_uat_v2(p_limit integer DEFAULT 250)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_limit integer:=least(greatest(coalesce(p_limit,250),1),1000);
  v_versions jsonb;
  v_audit jsonb;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  if not (public.has_app_role('OWNER') or public.has_app_role('ADMIN')) then
    raise exception 'FORBIDDEN';
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'id',version.id,'version',version.version,'name',version.name,
    'status',version.status,'effectiveFrom',version.effective_from,
    'effectiveTo',version.effective_to,'createdAt',version.created_at,
    'activatedAt',version.activated_at,'publishedAt',version.published_at,
    'baseVersionId',version.base_version_id,'contentHash',version.content_hash,
    'workforceHash',version.workforce_hash,
    'createdBy',coalesce(nullif(trim(coalesce(creator.raw_user_meta_data->>'full_name','')),''),creator.email,'System'),
    'publishedBy',coalesce(nullif(trim(coalesce(publisher.raw_user_meta_data->>'full_name','')),''),publisher.email),
    'counts',jsonb_build_object(
      'employees',(select count(*) from public.matrix_employee_profiles_v2 row_value where row_value.matrix_version_id=version.id and row_value.active),
      'roles',(select count(*) from public.matrix_roles_v2 row_value where row_value.matrix_version_id=version.id and row_value.active),
      'locations',(select count(*) from public.matrix_locations_v2 row_value where row_value.matrix_version_id=version.id and row_value.active),
      'duties',(select count(*) from public.matrix_duties_v2 row_value where row_value.matrix_version_id=version.id and row_value.active),
      'shifts',(select count(*) from public.matrix_shift_templates_v2 row_value where row_value.matrix_version_id=version.id and row_value.active),
      'staffingRules',(select count(*) from public.matrix_staffing_rules_v2 row_value where row_value.matrix_version_id=version.id and row_value.active),
      'scenarios',(select count(*) from public.matrix_scenarios_v2 row_value where row_value.matrix_version_id=version.id and row_value.active),
      'strategies',(select count(*) from public.matrix_strategies_v2 row_value where row_value.matrix_version_id=version.id and row_value.active)
    )
  ) order by version.version desc),'[]'::jsonb)
  into v_versions
  from public.matrix_versions version
  left join auth.users creator on creator.id=version.created_by
  left join auth.users publisher on publisher.id=version.published_by
  where version.schema_version>=2;

  with recent as (
    select log.*,
      coalesce(
        log.new_data->>'matrixVersionId',log.new_data->>'matrix_version_id',
        log.old_data->>'matrixVersionId',log.old_data->>'matrix_version_id',
        case when log.entity_type in ('matrix_v2','matrix_version') then log.entity_id end
      ) matrix_version_id,
      case
        when log.entity_type like '%employee%' then 'Pracownicy i umowy'
        when log.entity_type like '%staffing%' then 'Wymagana obsada'
        when log.entity_type like '%strategy%' or log.entity_type like '%scenario%' then 'Scenariusze i warianty'
        when log.entity_type like '%pay%' or log.entity_type like '%budget%' then 'Finanse'
        when log.entity_type like '%role%' or log.entity_type like '%location%'
          or log.entity_type like '%duty%' or log.entity_type like '%shift%' then 'Role, lokale i zmiany'
        when log.action like '%IMPORT%' or log.entity_type like '%import%' then 'Import Excel'
        when log.action='PUBLISH' then 'Publikacja'
        else 'Ustawienia Matrixa'
      end section
    from public.audit_log log
    where log.entity_type like 'matrix_v2%'
      or log.entity_type='matrix_version'
      or log.entity_type='employee_pay_rate_v2'
    order by log.created_at desc,log.id desc
    limit v_limit
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'id',recent.id,'createdAt',recent.created_at,
    'actorId',recent.actor_id,
    'actor',coalesce(nullif(trim(coalesce(actor.raw_user_meta_data->>'full_name','')),''),actor.email,'System'),
    'matrixVersionId',recent.matrix_version_id,'section',recent.section,
    'entityType',recent.entity_type,'entityId',recent.entity_id,
    'action',recent.action,'oldData',recent.old_data,'newData',recent.new_data
  ) order by recent.created_at desc,recent.id desc),'[]'::jsonb)
  into v_audit
  from recent
  left join auth.users actor on actor.id=recent.actor_id;

  return jsonb_build_object('versions',v_versions,'audit',v_audit);
end;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_scope_allows_resource_for_app_role_uat_v1(p_manager_role public.app_role, p_role_id uuid DEFAULT NULL::uuid, p_location_id uuid DEFAULT NULL::uuid, p_employee_id uuid DEFAULT NULL::uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  with resource as (
    select
      (select role.logical_id from public.matrix_roles_v2 role where role.id=p_role_id) role_logical_id,
      (select location.logical_id from public.matrix_locations_v2 location where location.id=p_location_id) location_logical_id
  )
  select auth.uid() is not null
    and p_manager_role in ('ROLE_MANAGER','LOCATION_MANAGER')
    and public.has_app_role(p_manager_role)
    and exists(
      select 1
      from public.matrix_scope_grants_v2 grant_row
      cross join resource
      where grant_row.auth_user_id=auth.uid()
        and grant_row.active
        and grant_row.app_role=p_manager_role
        and (
          p_manager_role<>'ROLE_MANAGER'
          or (
            grant_row.role_logical_id is not null
            and (
              (p_role_id is not null and resource.role_logical_id=grant_row.role_logical_id)
              or (p_role_id is null and p_employee_id is not null and exists(
                select 1
                from public.matrix_employee_roles_v2 employee_role
                join public.matrix_roles_v2 role on role.id=employee_role.role_id
                join public.matrix_versions matrix on matrix.id=employee_role.matrix_version_id
                where employee_role.employee_id=p_employee_id
                  and employee_role.active and role.active and matrix.status='ACTIVE'
                  and role.logical_id=grant_row.role_logical_id
              ))
            )
          )
        )
        and (
          p_manager_role<>'LOCATION_MANAGER'
          or (
            grant_row.location_logical_id is not null
            and (
              (p_location_id is not null and resource.location_logical_id=grant_row.location_logical_id)
              or (p_location_id is null and p_employee_id is not null and exists(
                select 1
                from public.matrix_employee_locations_v2 employee_location
                join public.matrix_locations_v2 location on location.id=employee_location.location_id
                join public.matrix_versions matrix on matrix.id=employee_location.matrix_version_id
                where employee_location.employee_id=p_employee_id
                  and employee_location.active and location.active and matrix.status='ACTIVE'
                  and location.logical_id=grant_row.location_logical_id
              ))
            )
          )
        )
        and (
          grant_row.role_logical_id is null
          or p_manager_role='ROLE_MANAGER'
          or (p_role_id is not null and resource.role_logical_id=grant_row.role_logical_id)
          or (p_role_id is null and p_employee_id is not null and exists(
            select 1
            from public.matrix_employee_roles_v2 employee_role
            join public.matrix_roles_v2 role on role.id=employee_role.role_id
            join public.matrix_versions matrix on matrix.id=employee_role.matrix_version_id
            where employee_role.employee_id=p_employee_id
              and employee_role.active and role.active and matrix.status='ACTIVE'
              and role.logical_id=grant_row.role_logical_id
          ))
        )
        and (
          grant_row.location_logical_id is null
          or p_manager_role='LOCATION_MANAGER'
          or (p_location_id is not null and resource.location_logical_id=grant_row.location_logical_id)
          or (p_location_id is null and p_employee_id is not null and exists(
            select 1
            from public.matrix_employee_locations_v2 employee_location
            join public.matrix_locations_v2 location on location.id=employee_location.location_id
            join public.matrix_versions matrix on matrix.id=employee_location.matrix_version_id
            where employee_location.employee_id=p_employee_id
              and employee_location.active and location.active and matrix.status='ACTIVE'
              and location.logical_id=grant_row.location_logical_id
          ))
        )
        and (
          grant_row.duty_logical_id is null
          or (p_employee_id is not null and exists(
            select 1
            from public.matrix_employee_duties_v2 employee_duty
            join public.matrix_duties_v2 duty on duty.id=employee_duty.duty_id
            join public.matrix_versions matrix on matrix.id=employee_duty.matrix_version_id
            where employee_duty.employee_id=p_employee_id
              and employee_duty.active and duty.active and matrix.status='ACTIVE'
              and duty.logical_id=grant_row.duty_logical_id
          ))
        )
        and (
          p_employee_id is null
          or (p_manager_role='ROLE_MANAGER' and exists(
            select 1
            from public.matrix_employee_roles_v2 employee_role
            join public.matrix_roles_v2 role on role.id=employee_role.role_id
            join public.matrix_versions matrix on matrix.id=employee_role.matrix_version_id
            where employee_role.employee_id=p_employee_id
              and employee_role.active and role.active and matrix.status='ACTIVE'
              and role.logical_id=grant_row.role_logical_id
          ))
          or (p_manager_role='LOCATION_MANAGER' and exists(
            select 1
            from public.matrix_employee_locations_v2 employee_location
            join public.matrix_locations_v2 location on location.id=employee_location.location_id
            join public.matrix_versions matrix on matrix.id=employee_location.matrix_version_id
            where employee_location.employee_id=p_employee_id
              and employee_location.active and location.active and matrix.status='ACTIVE'
              and location.logical_id=grant_row.location_logical_id
          ))
        )
    );
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_shift_staffing_save_uat_v3(p_scenario_id uuid, p_shift_template_ids uuid[], p_role_id uuid, p_duty_id uuid, p_operation text, p_count_value integer, p_multiplier_basis_points integer, p_active boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_matrix uuid;
  v_shifts uuid[];
  v_source_shift uuid;
  v_target_shift uuid;
  v_target_scenario uuid;
  v_target_role uuid;
  v_target_duty uuid;
  v_existing_rule uuid;
  v_operation text:=upper(trim(coalesce(p_operation,'')));
  v_saved integer:=0;
  v_role_duty_linked boolean:=false;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  if not (public.has_app_role('OWNER') or public.has_app_role('ADMIN')) then
    raise exception 'FORBIDDEN';
  end if;

  select coalesce(array_agg(distinct shift_id),array[]::uuid[])
  into v_shifts
  from unnest(coalesce(p_shift_template_ids,array[]::uuid[])) shift_id;
  if cardinality(v_shifts)<1 then raise exception 'SHIFT_SELECTION_REQUIRED'; end if;
  if cardinality(v_shifts)>100 then raise exception 'TOO_MANY_SHIFTS_SELECTED'; end if;
  if p_scenario_id is null then raise exception 'SCENARIO_REQUIRED'; end if;
  if p_role_id is null then raise exception 'ROLE_REQUIRED'; end if;
  if v_operation not in ('SET','ADD','MULTIPLY','REMOVE') then
    raise exception 'INVALID_STAFFING_OPERATION';
  end if;
  if v_operation='SET' and coalesce(p_active,true) and coalesce(p_count_value,0)<1 then
    raise exception 'STAFFING_REQUIRED_COUNT_MUST_BE_POSITIVE';
  end if;
  if v_operation='ADD' and p_count_value is null then
    raise exception 'STAFFING_COUNT_REQUIRED';
  end if;
  if v_operation='MULTIPLY' and coalesce(p_multiplier_basis_points,-1)<0 then
    raise exception 'INVALID_STAFFING_MULTIPLIER';
  end if;

  perform pg_advisory_xact_lock(hashtext('matrix-v2-lifecycle'));
  v_matrix:=public.matrix_v2_create_draft(null);

  select target.id into v_target_scenario
  from public.matrix_scenarios_v2 source
  join public.matrix_scenarios_v2 target
    on target.matrix_version_id=v_matrix and target.logical_id=source.logical_id
  where source.id=p_scenario_id and target.active;
  if v_target_scenario is null then raise exception 'SCENARIO_NOT_IN_MATRIX_V2'; end if;

  select target.id into v_target_role
  from public.matrix_roles_v2 source
  join public.matrix_roles_v2 target
    on target.matrix_version_id=v_matrix and target.logical_id=source.logical_id
  where source.id=p_role_id and target.active;
  if v_target_role is null then raise exception 'ROLE_NOT_IN_MATRIX_V2'; end if;

  if p_duty_id is not null then
    select target.id into v_target_duty
    from public.matrix_duties_v2 source
    join public.matrix_duties_v2 target
      on target.matrix_version_id=v_matrix and target.logical_id=source.logical_id
    where source.id=p_duty_id and target.active;
    if v_target_duty is null then raise exception 'DUTY_NOT_IN_MATRIX_V2'; end if;

    v_role_duty_linked:=not exists(
      select 1 from public.matrix_role_duties_v2 link
      where link.matrix_version_id=v_matrix
        and link.role_id=v_target_role and link.duty_id=v_target_duty and link.active
    );
    insert into public.matrix_role_duties_v2(
      matrix_version_id,role_id,duty_id,assignment_mode,minimum_count,active
    ) values(v_matrix,v_target_role,v_target_duty,'OPTIONAL',0,true)
    on conflict (matrix_version_id,role_id,duty_id)
    do update set active=true;
  end if;

  foreach v_source_shift in array v_shifts loop
    select target.id into v_target_shift
    from public.matrix_shift_templates_v2 source
    join public.matrix_shift_templates_v2 target
      on target.matrix_version_id=v_matrix and target.logical_id=source.logical_id
    where source.id=v_source_shift and target.active;
    if v_target_shift is null then raise exception 'SHIFT_NOT_IN_MATRIX_V2'; end if;

    select rule.id into v_existing_rule
    from public.matrix_staffing_rules_v2 rule
    where rule.matrix_version_id=v_matrix
      and rule.scenario_id=v_target_scenario
      and rule.shift_template_id=v_target_shift
      and rule.role_id=v_target_role
      and rule.duty_id is not distinct from v_target_duty;

    perform public.matrix_v2_admin_save_alpha16(
      'STAFFING_RULE',v_existing_rule,
      jsonb_build_object(
        'scenarioId',v_target_scenario,
        'shiftTemplateId',v_target_shift,
        'roleId',v_target_role,
        'dutyId',v_target_duty,
        'operation',v_operation,
        'countValue',case when v_operation in ('SET','ADD') then p_count_value else null end,
        'multiplierBasisPoints',case when v_operation='MULTIPLY' then p_multiplier_basis_points else null end,
        'active',coalesce(p_active,true),
        'sourceMetadata',jsonb_build_object('source','UNIFIED_SHIFT_STAFFING_UI')
      )
    );
    v_saved:=v_saved+1;
  end loop;

  insert into public.audit_log(actor_id,entity_type,entity_id,action,new_data)
  values(auth.uid(),'matrix_version',v_matrix::text,'SAVE_UNIFIED_SHIFT_STAFFING',
    jsonb_build_object(
      'scenarioId',v_target_scenario,'shiftTemplateIds',to_jsonb(v_shifts),
      'roleId',v_target_role,'dutyId',v_target_duty,
      'roleDutyLinked',v_role_duty_linked,'operation',v_operation,
      'countValue',p_count_value,'saved',v_saved
    ));

  return jsonb_build_object(
    'matrixVersionId',v_matrix,'saved',v_saved,
    'roleDutyLinked',v_role_duty_linked
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_stable_uuid(p_value text)
 RETURNS uuid
 LANGUAGE sql
 IMMUTABLE STRICT
 SET search_path TO ''
AS $function$
  select (
    substr(md5(p_value),1,8)||'-'||substr(md5(p_value),9,4)||'-'||
    substr(md5(p_value),13,4)||'-'||substr(md5(p_value),17,4)||'-'||
    substr(md5(p_value),21,12)
  )::uuid;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_staffing_bulk_adjust_uat_v2(p_scenario_id uuid, p_location_id uuid DEFAULT NULL::uuid, p_shift_period text DEFAULT NULL::text, p_role_id uuid DEFAULT NULL::uuid, p_delta integer DEFAULT 1)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_matrix uuid;
  v_scenario uuid;
  v_location uuid;
  v_role uuid;
  v_period text:=nullif(upper(trim(coalesce(p_shift_period,''))), '');
  v_matching integer:=0;
  v_eligible integer:=0;
  v_updated integer:=0;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  if not (public.has_app_role('OWNER') or public.has_app_role('ADMIN')) then
    raise exception 'FORBIDDEN';
  end if;
  if p_scenario_id is null then raise exception 'SCENARIO_REQUIRED'; end if;
  if coalesce(p_delta,0)=0 or abs(p_delta)>20 then
    raise exception 'INVALID_STAFFING_BULK_DELTA';
  end if;
  if v_period is not null and v_period not in ('MORNING','MIDDLE','EVENING') then
    raise exception 'INVALID_SHIFT_PERIOD';
  end if;

  v_matrix:=public.matrix_v2_create_draft(null);
  select target.id into v_scenario
  from public.matrix_scenarios_v2 source
  join public.matrix_scenarios_v2 target
    on target.matrix_version_id=v_matrix and target.logical_id=source.logical_id
  where source.id=p_scenario_id;
  if v_scenario is null then raise exception 'SCENARIO_NOT_IN_MATRIX_V2'; end if;

  if p_location_id is not null then
    select target.id into v_location
    from public.matrix_locations_v2 source
    join public.matrix_locations_v2 target
      on target.matrix_version_id=v_matrix and target.logical_id=source.logical_id
    where source.id=p_location_id;
    if v_location is null then raise exception 'LOCATION_NOT_IN_MATRIX_V2'; end if;
  end if;
  if p_role_id is not null then
    select target.id into v_role
    from public.matrix_roles_v2 source
    join public.matrix_roles_v2 target
      on target.matrix_version_id=v_matrix and target.logical_id=source.logical_id
    where source.id=p_role_id;
    if v_role is null then raise exception 'ROLE_NOT_IN_MATRIX_V2'; end if;
  end if;

  -- Lock and validate the complete target set before changing any row.  This
  -- preserves the established staffing contracts: active SET rules require at
  -- least one person and ADD rules cannot carry a negative count.  A single
  -- invalid result aborts the whole bulk operation instead of being clamped.
  perform rule.id
  from public.matrix_staffing_rules_v2 rule
  join public.matrix_shift_templates_v2 shift
    on shift.id=rule.shift_template_id
  where rule.matrix_version_id=v_matrix and rule.scenario_id=v_scenario
    and rule.active and rule.operation in ('SET','ADD')
    and (v_location is null or shift.location_id=v_location)
    and (v_period is null or shift.shift_period=v_period)
    and (v_role is null or rule.role_id=v_role)
  for update of rule;

  select count(*),count(*) filter(where rule.operation in ('SET','ADD'))
  into v_matching,v_eligible
  from public.matrix_staffing_rules_v2 rule
  join public.matrix_shift_templates_v2 shift
    on shift.id=rule.shift_template_id
  where rule.matrix_version_id=v_matrix and rule.scenario_id=v_scenario
    and rule.active
    and (v_location is null or shift.location_id=v_location)
    and (v_period is null or shift.shift_period=v_period)
    and (v_role is null or rule.role_id=v_role);
  if v_eligible<1 then raise exception 'STAFFING_TARGET_NOT_FOUND'; end if;

  if exists(
    select 1
    from public.matrix_staffing_rules_v2 rule
    join public.matrix_shift_templates_v2 shift
      on shift.id=rule.shift_template_id
    where rule.matrix_version_id=v_matrix and rule.scenario_id=v_scenario
      and rule.active and rule.operation in ('SET','ADD')
      and (v_location is null or shift.location_id=v_location)
      and (v_period is null or shift.shift_period=v_period)
      and (v_role is null or rule.role_id=v_role)
      and (
        (rule.operation='SET' and coalesce(rule.count_value,0)+p_delta<1)
        or (rule.operation='ADD' and coalesce(rule.count_value,0)+p_delta<0)
      )
  ) then
    raise exception 'STAFFING_COUNT_BELOW_MINIMUM';
  end if;

  update public.matrix_staffing_rules_v2 rule set
    count_value=coalesce(rule.count_value,0)+p_delta,
    updated_at=now()
  from public.matrix_shift_templates_v2 shift
  where shift.id=rule.shift_template_id
    and rule.matrix_version_id=v_matrix and rule.scenario_id=v_scenario
    and rule.active and rule.operation in ('SET','ADD')
    and (v_location is null or shift.location_id=v_location)
    and (v_period is null or shift.shift_period=v_period)
    and (v_role is null or rule.role_id=v_role);
  get diagnostics v_updated=row_count;

  insert into public.audit_log(actor_id,entity_type,entity_id,action,new_data)
  values(auth.uid(),'matrix_version',v_matrix::text,'BULK_ADJUST_STAFFING',
    jsonb_build_object(
      'scenarioId',v_scenario,'locationId',v_location,'shiftPeriod',v_period,
      'roleId',v_role,'delta',p_delta,'updated',v_updated,
      'skipped',greatest(v_matching-v_updated,0)
    ));
  return jsonb_build_object(
    'matrixVersionId',v_matrix,'updated',v_updated,
    'skipped',greatest(v_matching-v_updated,0)
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_staffing_rules_bulk_save_uat_v2(p_scenario_id uuid, p_shift_template_ids uuid[], p_role_id uuid, p_duty_id uuid, p_operation text, p_count_value integer, p_multiplier_basis_points integer, p_active boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_matrix uuid;
  v_shifts uuid[];
  v_shift uuid;
  v_operation text:=upper(trim(coalesce(p_operation,'')));
  v_saved integer:=0;
  v_target_scenario uuid;
  v_target_role uuid;
  v_target_duty uuid;
  v_target_shift uuid;
  v_existing uuid;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  if not (public.has_app_role('OWNER') or public.has_app_role('ADMIN')) then
    raise exception 'FORBIDDEN';
  end if;

  select coalesce(array_agg(distinct shift_id),array[]::uuid[])
  into v_shifts
  from unnest(coalesce(p_shift_template_ids,array[]::uuid[])) shift_id;
  if cardinality(v_shifts)<1 then raise exception 'SHIFT_SELECTION_REQUIRED'; end if;
  if cardinality(v_shifts)>100 then raise exception 'TOO_MANY_SHIFTS_SELECTED'; end if;
  if p_scenario_id is null then raise exception 'SCENARIO_REQUIRED'; end if;
  if p_role_id is null then raise exception 'ROLE_REQUIRED'; end if;
  if v_operation not in ('SET','ADD','MULTIPLY','REMOVE') then
    raise exception 'INVALID_STAFFING_OPERATION';
  end if;
  if v_operation in ('SET','ADD') and p_count_value is null then
    raise exception 'STAFFING_COUNT_REQUIRED';
  end if;
  if v_operation in ('SET','ADD') and p_count_value<0 then
    raise exception 'STAFFING_COUNT_NEGATIVE';
  end if;
  if v_operation='MULTIPLY' and coalesce(p_multiplier_basis_points,-1)<0 then
    raise exception 'INVALID_STAFFING_MULTIPLIER';
  end if;

  v_matrix:=public.matrix_v2_create_draft(null);

  -- Validate every reference up front.  The following FOREACH loop therefore
  -- cannot partially apply a batch before discovering a bad final selection.
  select target.id into v_target_scenario
    from public.matrix_scenarios_v2 source
    join public.matrix_scenarios_v2 target
      on target.matrix_version_id=v_matrix and target.logical_id=source.logical_id
    where source.id=p_scenario_id and target.active;
  if v_target_scenario is null then raise exception 'SCENARIO_NOT_IN_MATRIX_V2'; end if;
  select target.id into v_target_role
    from public.matrix_roles_v2 source
    join public.matrix_roles_v2 target
      on target.matrix_version_id=v_matrix and target.logical_id=source.logical_id
    where source.id=p_role_id and target.active;
  if v_target_role is null then raise exception 'ROLE_NOT_IN_MATRIX_V2'; end if;
  if p_duty_id is not null then
    select target.id into v_target_duty
      from public.matrix_duties_v2 source
      join public.matrix_duties_v2 target
        on target.matrix_version_id=v_matrix and target.logical_id=source.logical_id
      where source.id=p_duty_id and target.active;
    if v_target_duty is null then raise exception 'DUTY_NOT_IN_MATRIX_V2'; end if;
  end if;
  if (
    select count(distinct selected.shift_id)
    from unnest(v_shifts) selected(shift_id)
    join public.matrix_shift_templates_v2 source on source.id=selected.shift_id
    join public.matrix_shift_templates_v2 target
      on target.matrix_version_id=v_matrix and target.logical_id=source.logical_id
    where target.active
  )<>cardinality(v_shifts) then
    raise exception 'SHIFT_NOT_IN_MATRIX_V2';
  end if;

  foreach v_shift in array v_shifts loop
    select target.id into v_target_shift
    from public.matrix_shift_templates_v2 source
    join public.matrix_shift_templates_v2 target
      on target.matrix_version_id=v_matrix and target.logical_id=source.logical_id
    where source.id=v_shift and target.active;
    if v_target_shift is null then raise exception 'SHIFT_NOT_IN_MATRIX_V2'; end if;
    select rule.id into v_existing
    from public.matrix_staffing_rules_v2 rule
    where rule.matrix_version_id=v_matrix
      and rule.scenario_id=v_target_scenario
      and rule.shift_template_id=v_target_shift
      and rule.role_id=v_target_role
      and rule.duty_id is not distinct from v_target_duty;
    perform public.matrix_v2_admin_save_alpha16(
      'STAFFING_RULE',v_existing,
      jsonb_build_object(
        'scenarioId',v_target_scenario,
        'shiftTemplateId',v_target_shift,
        'roleId',v_target_role,
        'dutyId',v_target_duty,
        'operation',v_operation,
        'countValue',case when v_operation in ('SET','ADD') then p_count_value else null end,
        'multiplierBasisPoints',case when v_operation='MULTIPLY' then p_multiplier_basis_points else null end,
        'active',coalesce(p_active,true),
        'sourceMetadata',jsonb_build_object(
          'source','MATRIX_BULK_UI','batchSize',cardinality(v_shifts)
        )
      )
    );
    v_saved:=v_saved+1;
  end loop;

  insert into public.audit_log(actor_id,entity_type,entity_id,action,new_data)
  values(auth.uid(),'matrix_version',v_matrix::text,'BULK_SAVE_STAFFING',
    jsonb_build_object(
      'scenarioId',v_target_scenario,'roleId',v_target_role,
      'dutyId',v_target_duty,
      'operation',v_operation,'shiftTemplateIds',to_jsonb(v_shifts),'saved',v_saved
    ));
  return jsonb_build_object('matrixVersionId',v_matrix,'saved',v_saved);
end;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_team_import_apply_uat_v1(p_configuration jsonb, p_mode text DEFAULT 'UPDATE'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET statement_timeout TO '180s'
AS $function$
declare
  v_identity jsonb;
  v_result jsonb;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  if not (public.has_app_role('OWNER') or public.has_app_role('ADMIN')) then raise exception 'FORBIDDEN'; end if;
  perform pg_advisory_xact_lock(hashtext('matrix-v2-lifecycle'));
  v_identity:=solver_private.matrix_v2_assert_workbook_identity_uat_v1(p_configuration);
  v_result:=public.matrix_v2_team_import_apply_uat_v1_core_20260824(p_configuration,p_mode);
  return v_result||jsonb_build_object('workbookIdentity',v_identity);
end;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_team_import_apply_uat_v1_core_20260824(p_configuration jsonb, p_mode text DEFAULT 'UPDATE'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET statement_timeout TO '180s'
AS $function$
declare
  v_configuration jsonb:=solver_private.matrix_v2_team_import_configuration_uat_v2(coalesce(p_configuration,'{}'::jsonb));
  v_configuration_without_rates jsonb;
  v_result jsonb;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  if not (public.has_app_role('OWNER') or public.has_app_role('ADMIN')) then raise exception 'FORBIDDEN'; end if;
  if jsonb_typeof(p_configuration)<>'object' then raise exception 'INVALID_TEAM_IMPORT_PAYLOAD'; end if;
  perform pg_advisory_xact_lock(hashtext('matrix-v2-lifecycle'));
  v_configuration_without_rates:=jsonb_set(v_configuration,'{employees}',coalesce((
    select jsonb_agg(value-'baseRate')
    from jsonb_array_elements(coalesce(v_configuration->'employees','[]'::jsonb))
  ),'[]'::jsonb),true);
  perform solver_private.matrix_v2_full_import_phase_uat_v1(v_configuration,'PRE');
  perform solver_private.matrix_v2_seed_import_shifts_uat_v1(v_configuration);
  v_result:=public.matrix_v2_import_apply_uat_v5(v_configuration_without_rates,p_mode);
  perform solver_private.matrix_v2_full_import_phase_uat_v1(v_configuration,'POST');
  return v_result||jsonb_build_object('atomic',true,'scope','TEAM_AND_STRUCTURE','financeDeferred',true,'validationOrder','STRUCTURE_THEN_RELATIONS');
exception when others then
  if sqlerrm like 'MATRIX_%' or sqlerrm like 'INVALID_%'
    or sqlerrm like 'EMPLOYEE_%' or sqlerrm like 'IMPORTED_%'
    or sqlerrm like 'FULL_IMPORT_%' then raise; end if;
  raise exception 'TEAM_IMPORT_APPLY_FAILED|%|%|%',gen_random_uuid(),sqlstate,sqlerrm;
end;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_team_import_preview_uat_v1(p_configuration jsonb, p_mode text DEFAULT 'UPDATE'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET statement_timeout TO '180s'
AS $function$
declare
  v_identity jsonb;
  v_result jsonb;
begin
  v_identity:=solver_private.matrix_v2_assert_workbook_identity_uat_v1(p_configuration);
  v_result:=public.matrix_v2_team_import_preview_uat_v1_core_20260824(p_configuration,p_mode);
  return v_result||jsonb_build_object('workbookIdentity',v_identity);
end;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_team_import_preview_uat_v1_core_20260814(p_configuration jsonb, p_mode text DEFAULT 'UPDATE'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET statement_timeout TO '180s'
AS $function$
declare
  v_configuration jsonb:=solver_private.matrix_v2_team_import_configuration_uat_v2(coalesce(p_configuration,'{}'::jsonb));
  v_configuration_without_rates jsonb;
  v_preview jsonb;
  v_result jsonb;
  v_extra integer;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  if not (public.has_app_role('OWNER') or public.has_app_role('ADMIN')) then raise exception 'FORBIDDEN'; end if;
  if jsonb_typeof(p_configuration)<>'object' then raise exception 'INVALID_TEAM_IMPORT_PAYLOAD'; end if;
  perform pg_advisory_xact_lock(hashtext('matrix-v2-lifecycle'));
  v_configuration_without_rates:=jsonb_set(v_configuration,'{employees}',coalesce((
    select jsonb_agg(value-'baseRate')
    from jsonb_array_elements(coalesce(v_configuration->'employees','[]'::jsonb))
  ),'[]'::jsonb),true);

  begin
    perform solver_private.matrix_v2_full_import_phase_uat_v1(v_configuration,'PRE');
    perform solver_private.matrix_v2_seed_import_shifts_uat_v1(v_configuration);
    v_preview:=public.matrix_v2_import_preview_uat_v5(v_configuration_without_rates,p_mode);
    if coalesce((v_preview->>'valid')::boolean,false) then
      perform public.matrix_v2_import_apply_uat_v5(v_configuration_without_rates,p_mode);
      perform solver_private.matrix_v2_full_import_phase_uat_v1(v_configuration,'POST');
    end if;
    v_preview:=jsonb_set(v_preview,'{warnings}',coalesce((
      select jsonb_agg(case when warning.value->>'code'='PAY_RATE_MISSING'
        then jsonb_set(warning.value,'{message}',to_jsonb('Stawkę uzupełnisz w kroku 2 po nadaniu numeru GP-###; do tego czasu publikacja konfiguracji może być zablokowana.'::text),true)
        else warning.value end order by warning.ordinality)
      from jsonb_array_elements(coalesce(v_preview->'warnings','[]'::jsonb))
        with ordinality warning(value,ordinality)
    ),'[]'::jsonb),true);
    v_extra:=jsonb_array_length(coalesce(v_configuration->'roles','[]'::jsonb))
      +jsonb_array_length(coalesce(v_configuration->'locations','[]'::jsonb))
      +jsonb_array_length(coalesce(v_configuration->'duties','[]'::jsonb))
      +jsonb_array_length(coalesce(v_configuration->'scenarios','[]'::jsonb))
      +jsonb_array_length(coalesce(v_configuration->'strategies','[]'::jsonb))
      +jsonb_array_length(coalesce(v_configuration->'strategyObjectives','[]'::jsonb))
      +jsonb_array_length(coalesce(v_configuration->'scenarioStrategies','[]'::jsonb))
      +jsonb_array_length(coalesce(v_configuration->'employeeRoles','[]'::jsonb))
      +jsonb_array_length(coalesce(v_configuration->'employeeLocationsDetailed','[]'::jsonb))
      +jsonb_array_length(coalesce(v_configuration->'employeeCapabilities','[]'::jsonb))
      +jsonb_array_length(coalesce(v_configuration->'timeConstraints','[]'::jsonb));
    v_result:=jsonb_build_object(
      'valid',coalesce((v_preview->>'valid')::boolean,false),
      'errors',coalesce(v_preview->'errors','[]'::jsonb),
      'warnings',coalesce(v_preview->'warnings','[]'::jsonb),
      'configuration',v_preview,
      'finance',jsonb_build_object('valid',true,'errors','[]'::jsonb,'warnings','[]'::jsonb,
        'normalizedRows','[]'::jsonb,'summary',jsonb_build_object('rows',0,'employees',0,'create',0,'update',0,'deactivate',0,'unchanged',0)),
      'summary',coalesce(v_preview->'summary','{}'::jsonb)||jsonb_build_object(
        'total',coalesce((v_preview#>>'{summary,total}')::integer,0)+v_extra,
        'financeRows',0,'financeEmployees',0,'financeChanges',0,
        'roles',jsonb_array_length(coalesce(v_configuration->'roles','[]'::jsonb)),
        'locations',jsonb_array_length(coalesce(v_configuration->'locations','[]'::jsonb)),
        'duties',jsonb_array_length(coalesce(v_configuration->'duties','[]'::jsonb)),
        'scenarios',jsonb_array_length(coalesce(v_configuration->'scenarios','[]'::jsonb)),
        'strategies',jsonb_array_length(coalesce(v_configuration->'strategies','[]'::jsonb)),
        'timeConstraints',jsonb_array_length(coalesce(v_configuration->'timeConstraints','[]'::jsonb))
      )
    );
    raise sqlstate 'GPQ01' using message='TEAM_IMPORT_DRY_RUN_COMPLETE';
  exception when sqlstate 'GPQ01' then
    return v_result;
  end;
end;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_team_import_preview_uat_v1_core_20260824(p_configuration jsonb, p_mode text DEFAULT 'UPDATE'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET statement_timeout TO '180s'
AS $function$
begin
  return public.matrix_v2_team_import_preview_uat_v1_core_20260814(
    p_configuration,p_mode
  );
exception when others then
  if sqlerrm like 'MATRIX_%' or sqlerrm like 'INVALID_%'
    or sqlerrm like 'EMPLOYEE_%' or sqlerrm like 'IMPORTED_%'
    or sqlerrm like 'FULL_IMPORT_%' or sqlerrm like 'ROLE_%' then
    raise;
  end if;
  raise exception 'TEAM_IMPORT_PREVIEW_FAILED|%|%|%',
    gen_random_uuid(),sqlstate,sqlerrm;
end;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_workspace(p_month date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_payload jsonb;
  v_matrix uuid;
  v_visible_employee_ids uuid[];
  v_employees jsonb;
  v_ad_hoc_workers jsonb;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;

  v_payload := public.matrix_v2_workspace_before_employee_privacy_uat_v1(p_month);
  v_matrix := nullif(v_payload->'matrixVersion'->>'id', '')::uuid;

  select coalesce(array_agg(visible.employee_id order by visible.employee_id), '{}'::uuid[])
  into v_visible_employee_ids
  from authorization_private.matrix_v2_visible_employee_ids_uat_v1() visible;

  select coalesce(jsonb_agg(
    jsonb_build_object(
      'id', employee.id,
      'employeeNo', employee.employee_no,
      'firstName', employee.first_name,
      'lastName', employee.last_name,
      'active', employee.active and employee.archived_at is null
    )
    || coalesce((
      select jsonb_build_object(
        'employmentStage', profile.employment_stage,
        'probationEnd', profile.probation_end
      )
      from public.matrix_employee_profiles_v2 profile
      where profile.matrix_version_id = v_matrix
        and profile.employee_id = employee.id
    ), '{}'::jsonb)
    || jsonb_build_object(
      'overtimePolicy', coalesce((
        select profile.overtime_policy
        from public.matrix_employee_profiles_v2 profile
        where profile.matrix_version_id = v_matrix
          and profile.employee_id = employee.id
      ), 'NEVER')
    )
    order by employee.active desc, employee.last_name, employee.first_name, employee.employee_no
  ), '[]'::jsonb)
  into v_employees
  from public.employees employee
  where employee.id = any(v_visible_employee_ids);
  v_payload := jsonb_set(v_payload, '{employees}', v_employees, true);

  select coalesce(jsonb_agg(item.value order by item.ordinality), '[]'::jsonb)
  into v_employees
  from jsonb_array_elements(coalesce(v_payload->'employeeRoles', '[]'::jsonb))
    with ordinality item(value, ordinality)
  where nullif(item.value->>'employee_id', '')::uuid = any(v_visible_employee_ids);
  v_payload := jsonb_set(v_payload, '{employeeRoles}', v_employees, true);

  select coalesce(jsonb_agg(item.value order by item.ordinality), '[]'::jsonb)
  into v_employees
  from jsonb_array_elements(coalesce(v_payload->'employeeLocations', '[]'::jsonb))
    with ordinality item(value, ordinality)
  where nullif(item.value->>'employee_id', '')::uuid = any(v_visible_employee_ids);
  v_payload := jsonb_set(v_payload, '{employeeLocations}', v_employees, true);

  select coalesce(jsonb_agg(item.value order by item.ordinality), '[]'::jsonb)
  into v_employees
  from jsonb_array_elements(coalesce(v_payload->'employeeDuties', '[]'::jsonb))
    with ordinality item(value, ordinality)
  where nullif(item.value->>'employee_id', '')::uuid = any(v_visible_employee_ids);
  v_payload := jsonb_set(v_payload, '{employeeDuties}', v_employees, true);

  select coalesce(jsonb_agg(item.value order by item.ordinality), '[]'::jsonb)
  into v_employees
  from jsonb_array_elements(coalesce(v_payload->'timeConstraints', '[]'::jsonb))
    with ordinality item(value, ordinality)
  where nullif(item.value->>'employeeId', '')::uuid = any(v_visible_employee_ids);
  v_payload := jsonb_set(v_payload, '{timeConstraints}', v_employees, true);

  select coalesce(jsonb_agg(item.value order by item.ordinality), '[]'::jsonb)
  into v_employees
  from jsonb_array_elements(coalesce(v_payload->'workPatterns', '[]'::jsonb))
    with ordinality item(value, ordinality)
  where nullif(item.value->>'employeeId', '')::uuid = any(v_visible_employee_ids);
  v_payload := jsonb_set(v_payload, '{workPatterns}', v_employees, true);

  select coalesce(jsonb_agg(item.value order by item.ordinality), '[]'::jsonb)
  into v_employees
  from jsonb_array_elements(coalesce(v_payload->'employeePayRates', '[]'::jsonb))
    with ordinality item(value, ordinality)
  where nullif(item.value->>'employee_id', '')::uuid = any(v_visible_employee_ids);
  v_payload := jsonb_set(v_payload, '{employeePayRates}', v_employees, true);

  -- An ad-hoc identity is a recovery resource. A linked employee must be visible
  -- and the recovery role/employee resource must be inside the caller's scope.
  -- A temporary identity has no employee or location relation, so it can only be
  -- resolved through its role scope. HR_FINANCE keeps its pre-existing full
  -- finance/recovery projection; field-level finance redaction already ran in
  -- the wrapped function and remains independent from person visibility.
  select coalesce(jsonb_agg(item.value order by item.ordinality), '[]'::jsonb)
  into v_ad_hoc_workers
  from jsonb_array_elements(coalesce(v_payload->'adHocWorkers', '[]'::jsonb))
    with ordinality item(value, ordinality)
  where (
      nullif(item.value->>'employee_id', '') is null
      or nullif(item.value->>'employee_id', '')::uuid = any(v_visible_employee_ids)
    )
    and (
      public.has_app_role('HR_FINANCE')
      or public.matrix_v2_can_manage_resource_uat_v1(
        nullif(item.value->>'role_id', '')::uuid,
        null,
        nullif(item.value->>'employee_id', '')::uuid
      )
    );
  v_payload := jsonb_set(v_payload, '{adHocWorkers}', v_ad_hoc_workers, true);

  return v_payload;
end;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_workspace_before_ad_hoc_projection_uat_v1(p_month date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_result jsonb;
  v_matrix uuid;
  v_employees jsonb := '[]'::jsonb;
  v_employee jsonb;
  v_locations jsonb := '[]'::jsonb;
  v_location jsonb;
  v_categories jsonb := '[]'::jsonb;
  v_category jsonb;
  v_roles jsonb := '[]'::jsonb;
  v_role jsonb;
begin
  v_result := public.matrix_v2_workspace_before_overtime_uat_v1(p_month);
  v_matrix := nullif(v_result->'matrixVersion'->>'id', '')::uuid;
  for v_employee in
    select value from jsonb_array_elements(coalesce(v_result->'employees', '[]'::jsonb))
  loop
    v_employee := v_employee || jsonb_build_object(
      'overtimePolicy', coalesce((
        select profile.overtime_policy
        from public.matrix_employee_profiles_v2 profile
        where profile.matrix_version_id = v_matrix
          and profile.employee_id = (v_employee->>'id')::uuid
      ), 'NEVER')
    );
    v_employees := v_employees || jsonb_build_array(v_employee);
  end loop;
  v_result := jsonb_set(v_result, '{employees}', v_employees, true);
  for v_location in select value from jsonb_array_elements(coalesce(v_result->'locations','[]'::jsonb)) loop
    v_location := v_location || jsonb_build_object('logicalId',(
      select location_row.logical_id from public.matrix_locations_v2 location_row
      where location_row.id=(v_location->>'id')::uuid
    ));
    v_locations := v_locations || jsonb_build_array(v_location);
  end loop;
  v_result := jsonb_set(v_result, '{locations}', v_locations, true);
  for v_role in select value from jsonb_array_elements(coalesce(v_result->'roles','[]'::jsonb)) loop
    v_role := v_role || jsonb_build_object('logicalId',(
      select role_row.logical_id from public.matrix_roles_v2 role_row
      where role_row.id=(v_role->>'id')::uuid
    ));
    v_roles := v_roles || jsonb_build_array(v_role);
  end loop;
  v_result := jsonb_set(v_result, '{roles}', v_roles, true);
  for v_category in select value from jsonb_array_elements(coalesce(v_result->'roleCategories','[]'::jsonb)) loop
    v_category := v_category || jsonb_build_object('logicalId',(
      select category.logical_id from public.matrix_role_categories_v2 category
      where category.id=(v_category->>'id')::uuid
    ));
    v_categories := v_categories || jsonb_build_array(v_category);
  end loop;
  return jsonb_set(v_result, '{roleCategories}', v_categories, true);
end;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_workspace_before_b4f52_uat_v1(p_month date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_result jsonb;v_month_end date:=(p_month+interval '1 month - 1 day')::date;
begin
  v_result:=public.matrix_v2_workspace_before_b4f91_uat_v1(p_month);
  return v_result||jsonb_build_object('workPatterns',coalesce((select jsonb_agg(jsonb_build_object(
    'id',p.id,'employeeId',p.employee_id,'weekday',p.weekday,'localStart',p.local_start,
    'localEnd',p.local_end,'roleId',p.role_id,'locationId',p.location_id,
    'enforcement',p.enforcement,'validFrom',p.valid_from,'validTo',p.valid_to,
    'revision',p.revision,'reason',p.reason,'active',p.active
  ) order by p.employee_id,p.valid_from,p.weekday,p.local_start)
  from public.employee_weekly_work_patterns_v2 p where p.active and p.valid_from<=v_month_end
    and (p.valid_to is null or p.valid_to>=p_month)),'[]'::jsonb));
end;$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_workspace_before_b4f91_uat_v1(p_month date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_result jsonb;
  v_matrix uuid;
begin
  v_result := public.matrix_v2_workspace_before_ad_hoc_projection_uat_v1(p_month);
  v_matrix := nullif(v_result->'matrixVersion'->>'id', '')::uuid;

  v_result := jsonb_set(
    v_result,
    '{adHocWorkers}',
    coalesce((
      select jsonb_agg(
        (to_jsonb(pool) - 'role_id') || jsonb_build_object(
          'role_id', coalesce(workspace_role.id, pool.role_id),
          'roleCode', coalesce(workspace_role.code, source_role.code)
        )
        order by pool.display_name, pool.id
      )
      from public.recovery_ad_hoc_pool_v2 pool
      join public.matrix_roles_v2 source_role on source_role.id = pool.role_id
      left join public.matrix_roles_v2 workspace_role
        on workspace_role.matrix_version_id = v_matrix
       and workspace_role.logical_id = source_role.logical_id
      where pool.active
    ), '[]'::jsonb),
    true
  );

  return v_result;
end;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_workspace_before_categories_uat_v1(p_month date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_matrix uuid;
  v_month date:=case when p_month is null then null
    else date_trunc('month',p_month)::date end;
  v_timezone text;
  v_finance boolean;
  v_manage boolean;
  v_owner_admin boolean;
  v_result jsonb;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  v_owner_admin:=public.has_app_role('OWNER') or public.has_app_role('ADMIN');
  v_finance:=v_owner_admin or public.has_app_role('HR_FINANCE');
  v_manage:=v_owner_admin or public.has_app_role('HR_FINANCE');

  if v_owner_admin then
    select mv.id into v_matrix from public.matrix_versions mv
    where mv.status='DRAFT' and mv.schema_version>=2
    order by mv.version desc limit 1;
  end if;
  if v_matrix is null then
    select mv.id into v_matrix from public.matrix_versions mv
    where mv.status='ACTIVE' and mv.schema_version>=2
    order by mv.version desc limit 1;
  end if;
  if v_matrix is null then raise exception 'MATRIX_V2_NOT_FOUND'; end if;
  select nullif(mv.settings->>'timezone','') into v_timezone
  from public.matrix_versions mv where mv.id=v_matrix;
  if v_timezone is null or not exists(
    select 1 from pg_catalog.pg_timezone_names tz where tz.name=v_timezone
  ) then raise exception 'INVALID_MATRIX_TIMEZONE'; end if;

  select jsonb_build_object(
    'matrixVersion',to_jsonb(mv),
    'month',v_month,
    'editable',mv.status='DRAFT' and v_owner_admin,
    'financeVisible',v_finance,
    'featureFlag',(select to_jsonb(f) from public.solver_feature_flags f
      where f.flag_key='DEFAULT_ENGINE'),
    'roles',coalesce((select jsonb_agg(to_jsonb(x) order by x.sort_order,x.code)
      from public.matrix_roles_v2 x where x.matrix_version_id=v_matrix),'[]'::jsonb),
    'locations',coalesce((select jsonb_agg(to_jsonb(x) order by x.sort_order,x.code)
      from public.matrix_locations_v2 x where x.matrix_version_id=v_matrix),'[]'::jsonb),
    'duties',coalesce((select jsonb_agg(to_jsonb(x) order by x.sort_order,x.code)
      from public.matrix_duties_v2 x where x.matrix_version_id=v_matrix),'[]'::jsonb),
    'shiftTemplates',coalesce((select jsonb_agg(to_jsonb(x) order by x.sort_order,x.code)
      from public.matrix_shift_templates_v2 x where x.matrix_version_id=v_matrix),'[]'::jsonb),
    'roleDuties',coalesce((select jsonb_agg(to_jsonb(x) order by x.role_id,x.duty_id)
      from public.matrix_role_duties_v2 x where x.matrix_version_id=v_matrix),'[]'::jsonb),
    'scenarios',coalesce((select jsonb_agg(to_jsonb(x) order by x.sort_order,x.code)
      from public.matrix_scenarios_v2 x where x.matrix_version_id=v_matrix),'[]'::jsonb),
    'staffingRules',coalesce((select jsonb_agg(to_jsonb(x)
        order by x.scenario_id,x.shift_template_id,x.role_id,x.duty_id)
      from public.matrix_staffing_rules_v2 x where x.matrix_version_id=v_matrix),'[]'::jsonb),
    'strategies',coalesce((select jsonb_agg(to_jsonb(x) order by x.sort_order,x.code)
      from public.matrix_strategies_v2 x where x.matrix_version_id=v_matrix),'[]'::jsonb),
    'strategyObjectives',coalesce((select jsonb_agg(to_jsonb(x)
        order by x.strategy_id,x.tier,x.sort_order,x.metric_code)
      from public.matrix_strategy_objectives_v2 x where x.matrix_version_id=v_matrix),'[]'::jsonb),
    'scenarioStrategies',coalesce((select jsonb_agg(to_jsonb(x)
        order by x.scenario_id,x.sort_order,x.strategy_id)
      from public.matrix_scenario_strategies_v2 x where x.matrix_version_id=v_matrix),'[]'::jsonb),
    'employees',coalesce((select jsonb_agg(jsonb_build_object(
        'id',e.id,'employeeNo',e.employee_no,'firstName',e.first_name,
        'lastName',e.last_name,'active',e.active and e.archived_at is null
      ) order by e.active desc,e.last_name,e.first_name,e.employee_no)
      from public.employees e
      where v_manage or e.auth_user_id=auth.uid()),'[]'::jsonb),
    'employeeRoles',coalesce((select jsonb_agg(to_jsonb(x) order by x.employee_id,x.role_id)
      from public.matrix_employee_roles_v2 x
      where x.matrix_version_id=v_matrix
        and (v_manage or public.matrix_v2_can_manage_employee(x.employee_id))),
      '[]'::jsonb),
    'employeeLocations',coalesce((select jsonb_agg(to_jsonb(x) order by x.employee_id,x.location_id)
      from public.matrix_employee_locations_v2 x
      where x.matrix_version_id=v_matrix
        and (v_manage or public.matrix_v2_can_manage_employee(x.employee_id))),
      '[]'::jsonb),
    'employeeDuties',coalesce((select jsonb_agg(to_jsonb(x) order by x.employee_id,x.duty_id)
      from public.matrix_employee_duties_v2 x
      where x.matrix_version_id=v_matrix
        and (v_manage or public.matrix_v2_can_manage_employee(x.employee_id))),
      '[]'::jsonb),
    'timeConstraints',coalesce((select jsonb_agg(jsonb_build_object(
        'id',x.id,'employeeId',x.employee_id,'kind',x.constraint_kind,
        'startsAt',lower(x.time_range),'endsAt',upper(x.time_range),
        'source',x.source,'editableByEmployee',x.editable_by_employee,
        'status',x.status,'note',x.note,'createdAt',x.created_at
      ) order by lower(x.time_range),x.id)
      from public.employee_time_constraints_v2 x
      where (v_manage or public.matrix_v2_can_manage_employee(x.employee_id))
        and x.status='ACTIVE'
        and (v_month is null or x.time_range && tstzrange(
          v_month::timestamp at time zone v_timezone,
          (v_month+interval '1 month')::timestamp at time zone v_timezone,'[)'))),'[]'::jsonb),
    'payRules',case when v_finance then coalesce((select jsonb_agg(to_jsonb(x)
        order by x.priority,x.code) from public.matrix_pay_rules_v2 x
      where x.matrix_version_id=v_matrix),'[]'::jsonb) else '[]'::jsonb end,
    'payRuleRoles',case when v_finance then coalesce((select jsonb_agg(to_jsonb(x)
      order by x.pay_rule_id,x.role_id) from public.matrix_pay_rule_roles_v2 x
      where x.matrix_version_id=v_matrix),'[]'::jsonb) else '[]'::jsonb end,
    'payRuleDuties',case when v_finance then coalesce((select jsonb_agg(to_jsonb(x)
      order by x.pay_rule_id,x.duty_id) from public.matrix_pay_rule_duties_v2 x
      where x.matrix_version_id=v_matrix),'[]'::jsonb) else '[]'::jsonb end,
    'payRuleLocations',case when v_finance then coalesce((select jsonb_agg(to_jsonb(x)
      order by x.pay_rule_id,x.location_id) from public.matrix_pay_rule_locations_v2 x
      where x.matrix_version_id=v_matrix),'[]'::jsonb) else '[]'::jsonb end,
    'payRuleShifts',case when v_finance then coalesce((select jsonb_agg(to_jsonb(x)
      order by x.pay_rule_id,x.shift_template_id) from public.matrix_pay_rule_shifts_v2 x
      where x.matrix_version_id=v_matrix),'[]'::jsonb) else '[]'::jsonb end,
    'scenarioPayRuleOverrides',case when v_finance then coalesce((select jsonb_agg(to_jsonb(x)
      order by x.scenario_id,x.pay_rule_id) from public.matrix_scenario_pay_rule_overrides_v2 x
      where x.matrix_version_id=v_matrix),'[]'::jsonb) else '[]'::jsonb end,
    'scenarioBudgets',case when v_finance then coalesce((select jsonb_agg(to_jsonb(x)
      order by x.scenario_id,x.budget_month,x.id) from public.matrix_scenario_budgets_v2 x
      where x.matrix_version_id=v_matrix
        and (v_month is null or x.budget_month is null or x.budget_month=v_month)),
      '[]'::jsonb) else '[]'::jsonb end,
    'employeePayRates',case when v_finance then coalesce((select jsonb_agg(to_jsonb(x)
      order by x.employee_id,x.valid_from desc) from public.employee_pay_rates_v2 x
      where v_month is null or (
        x.valid_from<(v_month+interval '1 month')::date
        and (x.valid_to is null or x.valid_to>=v_month))),
      '[]'::jsonb) else '[]'::jsonb end,
    'scopeGrants',coalesce((select jsonb_agg(to_jsonb(x)
      order by x.auth_user_id,x.app_role,x.id) from public.matrix_scope_grants_v2 x
      where v_owner_admin or x.auth_user_id=auth.uid()),'[]'::jsonb)
  ) into v_result
  from public.matrix_versions mv where mv.id=v_matrix;

  return v_result;
end;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_workspace_before_employee_privacy_uat_v1(p_month date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_payload jsonb:=public.matrix_v2_workspace_before_b4f52_uat_v1(p_month);
  v_visibility text:=public.application_finance_visibility_current_uat_v1();
  v_worker jsonb;
  v_workers jsonb:='[]'::jsonb;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  if v_visibility='FULL' then
    return v_payload||jsonb_build_object('financeVisibility',v_visibility,'financeVisible',true);
  end if;

  for v_worker in
    select value from jsonb_array_elements(coalesce(v_payload->'adHocWorkers','[]'::jsonb))
  loop
    v_workers:=v_workers||jsonb_build_array(
      v_worker-'base_rate_minor'-'rateMinor'-'approved_rate_minor'-'currency'
    );
  end loop;

  v_payload:=jsonb_set(v_payload,'{adHocWorkers}',v_workers,true);
  v_payload:=jsonb_set(v_payload,'{payRules}','[]'::jsonb,true);
  v_payload:=jsonb_set(v_payload,'{payRuleRoles}','[]'::jsonb,true);
  v_payload:=jsonb_set(v_payload,'{payRuleDuties}','[]'::jsonb,true);
  v_payload:=jsonb_set(v_payload,'{payRuleLocations}','[]'::jsonb,true);
  v_payload:=jsonb_set(v_payload,'{payRuleShifts}','[]'::jsonb,true);
  v_payload:=jsonb_set(v_payload,'{scenarioPayRuleOverrides}','[]'::jsonb,true);
  v_payload:=jsonb_set(v_payload,'{scenarioBudgets}','[]'::jsonb,true);
  v_payload:=jsonb_set(v_payload,'{employeePayRates}','[]'::jsonb,true);
  v_payload:=jsonb_set(v_payload,'{financeVisible}','false'::jsonb,true);
  return v_payload||jsonb_build_object('financeVisibility',v_visibility);
end;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_v2_workspace_before_overtime_uat_v1(p_month date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_result jsonb; v_matrix uuid; v_employees jsonb; v_employee jsonb;
begin
  v_result:=public.matrix_v2_workspace_before_categories_uat_v1(p_month);
  v_matrix:=(v_result->'matrixVersion'->>'id')::uuid;
  v_result:=jsonb_set(v_result,'{roleCategories}',coalesce((select jsonb_agg(to_jsonb(category) order by category.sort_order,category.code)
    from public.matrix_role_categories_v2 category where category.matrix_version_id=v_matrix),'[]'::jsonb),true);
  v_result:=jsonb_set(v_result,'{roles}',coalesce((select jsonb_agg(to_jsonb(role_row) order by role_row.sort_order,role_row.code)
    from public.matrix_roles_v2 role_row where role_row.matrix_version_id=v_matrix),'[]'::jsonb),true);
  v_employees:='[]'::jsonb;
  for v_employee in select value from jsonb_array_elements(coalesce(v_result->'employees','[]'::jsonb)) loop
    v_employee:=v_employee||coalesce((select jsonb_build_object(
      'employmentStage',profile.employment_stage,'probationEnd',profile.probation_end
    ) from public.matrix_employee_profiles_v2 profile
      where profile.matrix_version_id=v_matrix and profile.employee_id=(v_employee->>'id')::uuid),'{}'::jsonb);
    v_employees:=v_employees||jsonb_build_array(v_employee);
  end loop;
  v_result:=jsonb_set(v_result,'{employees}',v_employees,true);
  v_result:=jsonb_set(v_result,'{adHocWorkers}',coalesce((select jsonb_agg(to_jsonb(pool) order by pool.display_name,pool.id)
    from public.recovery_ad_hoc_pool_v2 pool where pool.active),'[]'::jsonb),true);
  return v_result;
end;
$function$;

CREATE OR REPLACE FUNCTION public.matrix_workspace(p_month date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
with mv as (select * from matrix_versions where status='ACTIVE' order by version desc limit 1)
select jsonb_build_object(
 'version',(select to_jsonb(mv) from mv),
 'roles',coalesce((select jsonb_agg(to_jsonb(r) order by r.sort_order,r.name) from matrix_roles r join mv on mv.id=r.matrix_version_id),'[]'::jsonb),
 'locations',coalesce((select jsonb_agg(to_jsonb(l) order by l.name) from matrix_locations l join mv on mv.id=l.matrix_version_id),'[]'::jsonb),
 'functions',coalesce((select jsonb_agg(to_jsonb(f) order by f.name) from matrix_functions f join mv on mv.id=f.matrix_version_id),'[]'::jsonb),
 'shifts',coalesce((select jsonb_agg(to_jsonb(s) order by s.sort_order,s.name) from matrix_shift_templates s join mv on mv.id=s.matrix_version_id),'[]'::jsonb),
 'demand',coalesce((select jsonb_agg(to_jsonb(d)) from matrix_demand d join matrix_shift_templates s on s.id=d.shift_template_id join mv on mv.id=s.matrix_version_id),'[]'::jsonb),
 'sections',coalesce((select jsonb_agg(jsonb_build_object('id',rp.id,'month',rp.month,'role_id',rp.role_id,'role_code',r.code,'role_name',r.name,'version',rp.version,'status',rp.status,'name',rp.name,'updated_at',rp.updated_at) order by r.sort_order) from role_plan_sections rp join matrix_roles r on r.id=rp.role_id join mv on mv.id=rp.matrix_version_id where rp.month=coalesce(date_trunc('month',p_month)::date,date_trunc('month',current_date)::date)),'[]'::jsonb),
 'conflicts',coalesce((select jsonb_agg(to_jsonb(c) order by c.severity,c.created_at desc) from matrix_conflicts c where c.status='OPEN'),'[]'::jsonb)
);
$function$;

CREATE OR REPLACE FUNCTION public.message_center_workspace_uat_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_user uuid:=auth.uid();
begin
  if v_user is null then raise exception 'AUTH_REQUIRED'; end if;
  return jsonb_build_object(
    'currentUserId',v_user,
    'contacts',coalesce((
      select jsonb_agg(jsonb_build_object(
        'authUserId',source.auth_user_id,'employeeId',source.employee_id,
        'name',source.display_name,'email',source.email,
        'employeeNo',source.employee_no,'roleName',source.role_name,
        'avatarMode',source.avatar_mode,'catAvatarKey',source.cat_avatar_key
      ) order by source.display_name)
      from (
        select distinct on (directory.auth_user_id) directory.auth_user_id,
          employee.id employee_id,
          coalesce(nullif(trim(profile.display_name),''),
            nullif(trim(employee.first_name||' '||employee.last_name),''),directory.email) display_name,
          directory.email,employee.employee_no,coalesce(role_row.name,directory.app_role::text) role_name,
          coalesce(profile.avatar_mode,'INITIALS') avatar_mode,profile.cat_avatar_key
        from public.application_access_directory_v1 directory
        left join public.employees employee on employee.auth_user_id=directory.auth_user_id
        left join public.user_profiles_v1 profile on profile.auth_user_id=directory.auth_user_id
        left join lateral (
          select role_item.name from public.matrix_employee_roles_v2 employee_role
          join public.matrix_roles_v2 role_item on role_item.id=employee_role.role_id
          where employee_role.employee_id=employee.id and employee_role.active
          order by employee_role.is_primary desc limit 1
        ) role_row on true
        where directory.active and directory.auth_user_id is not null
          and directory.auth_user_id<>v_user
        order by directory.auth_user_id,(employee.id is not null) desc,directory.app_role::text
      ) source
    ),'[]'::jsonb),
    'conversations',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',conversation.id,'subject',conversation.subject,'kind',conversation.kind,
        'contextType',conversation.context_type,'contextId',conversation.context_id,
        'updatedAt',conversation.updated_at,
        'unreadCount',(select count(*) from public.team_messages_v1 unread
          where unread.conversation_id=conversation.id and unread.sender_user_id<>v_user
            and unread.created_at>coalesce(own_member.last_read_at,'epoch'::timestamptz)),
        'lastMessage',(select message.body from public.team_messages_v1 message
          where message.conversation_id=conversation.id order by message.created_at desc limit 1),
        'members',(select coalesce(jsonb_agg(jsonb_build_object(
          'authUserId',member.auth_user_id,
          'name',public.message_display_name_uat_v1(member.auth_user_id),
          'avatarMode',coalesce(profile.avatar_mode,'INITIALS'),
          'catAvatarKey',profile.cat_avatar_key
        ) order by public.message_display_name_uat_v1(member.auth_user_id)),'[]'::jsonb)
          from public.team_conversation_members_v1 member
          left join public.user_profiles_v1 profile on profile.auth_user_id=member.auth_user_id
          where member.conversation_id=conversation.id)
      ) order by conversation.updated_at desc)
      from public.team_conversation_members_v1 own_member
      join public.team_conversations_v1 conversation on conversation.id=own_member.conversation_id
      where own_member.auth_user_id=v_user
    ),'[]'::jsonb),
    'messages',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',message.id,'conversationId',message.conversation_id,
        'senderUserId',message.sender_user_id,
        'senderName',public.message_display_name_uat_v1(message.sender_user_id),
        'senderAvatarMode',coalesce(profile.avatar_mode,'INITIALS'),
        'senderCatAvatarKey',profile.cat_avatar_key,
        'body',message.body,'createdAt',message.created_at
      ) order by message.created_at)
      from public.team_messages_v1 message
      left join public.user_profiles_v1 profile on profile.auth_user_id=message.sender_user_id
      where exists(select 1 from public.team_conversation_members_v1 member
        where member.conversation_id=message.conversation_id and member.auth_user_id=v_user)
    ),'[]'::jsonb)
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.message_conversation_create_uat_v1(p_recipient_auth_user_id uuid, p_subject text, p_message text, p_context_type text DEFAULT NULL::text, p_context_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user uuid:=auth.uid();v_conversation uuid;v_employee uuid;
  v_subject text:=coalesce(nullif(trim(p_subject),''),'Rozmowa zespołu');
begin
  if v_user is null then raise exception 'AUTH_REQUIRED'; end if;
  if p_recipient_auth_user_id is null or p_recipient_auth_user_id=v_user then
    raise exception 'RECIPIENT_NOT_FOUND';
  end if;
  if nullif(trim(p_message),'') is null then raise exception 'EMPTY_MESSAGE'; end if;
  if not exists(select 1 from public.application_access_directory_v1 directory
    where directory.auth_user_id=p_recipient_auth_user_id and directory.active) then
    raise exception 'RECIPIENT_NOT_FOUND';
  end if;
  insert into public.team_conversations_v1(kind,subject,context_type,context_id,created_by)
  values(case when p_context_type='SWAP' then 'SWAP' else 'DIRECT' end,
    v_subject,p_context_type,p_context_id,v_user) returning id into v_conversation;
  select employee.id into v_employee from public.employees employee
    where employee.auth_user_id=v_user limit 1;
  insert into public.team_conversation_members_v1(conversation_id,auth_user_id,employee_id,last_read_at)
  values(v_conversation,v_user,v_employee,now());
  select employee.id into v_employee from public.employees employee
    where employee.auth_user_id=p_recipient_auth_user_id limit 1;
  insert into public.team_conversation_members_v1(conversation_id,auth_user_id,employee_id)
  values(v_conversation,p_recipient_auth_user_id,v_employee);
  insert into public.team_messages_v1(conversation_id,sender_user_id,body)
  values(v_conversation,v_user,trim(p_message));
  insert into public.notifications(
    recipient_id,title,body,kind,context_type,context_id,action_route,action_required
  ) values(
    p_recipient_auth_user_id,
    'Nowa wiadomość od '||public.message_display_name_uat_v1(v_user),
    v_subject||': '||left(trim(p_message),240),'MESSAGE','TEAM_CONVERSATION',
    v_conversation::text,
    public.personal_message_action_route_uat_v1(p_recipient_auth_user_id,v_conversation),false
  );
  return jsonb_build_object('conversationId',v_conversation);
end;
$function$;

CREATE OR REPLACE FUNCTION public.message_display_name_uat_v1(p_auth_user_id uuid)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select coalesce(
    (select nullif(trim(profile.display_name),'') from public.user_profiles_v1 profile
      where profile.auth_user_id=p_auth_user_id),
    (select nullif(trim(employee.first_name||' '||employee.last_name),'')
      from public.employees employee where employee.auth_user_id=p_auth_user_id limit 1),
    (select auth_user.email from auth.users auth_user where auth_user.id=p_auth_user_id),
    'Użytkownik SZAFUNEK'
  );
$function$;

CREATE OR REPLACE FUNCTION public.message_mark_read_uat_v1(p_conversation_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_user uuid:=auth.uid();
begin
  if v_user is null then raise exception 'AUTH_REQUIRED'; end if;
  update public.team_conversation_members_v1 set last_read_at=now()
  where conversation_id=p_conversation_id and auth_user_id=v_user;
  if not found then raise exception 'CONVERSATION_FORBIDDEN'; end if;
  update public.notifications set read_at=coalesce(read_at,now()),resolved_at=now(),resolution='READ'
  where recipient_id=v_user and context_type='TEAM_CONVERSATION'
    and context_id=p_conversation_id::text and resolved_at is null;
  return true;
end;
$function$;

CREATE OR REPLACE FUNCTION public.message_send_uat_v1(p_conversation_id uuid, p_body text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user uuid:=auth.uid();v_message uuid;v_recipient uuid;v_subject text;
begin
  if v_user is null then raise exception 'AUTH_REQUIRED'; end if;
  if nullif(trim(p_body),'') is null then raise exception 'EMPTY_MESSAGE'; end if;
  if not exists(select 1 from public.team_conversation_members_v1 member
    where member.conversation_id=p_conversation_id and member.auth_user_id=v_user) then
    raise exception 'CONVERSATION_FORBIDDEN';
  end if;
  insert into public.team_messages_v1(conversation_id,sender_user_id,body)
  values(p_conversation_id,v_user,trim(p_body)) returning id into v_message;
  update public.team_conversations_v1 set updated_at=now()
    where id=p_conversation_id returning subject into v_subject;
  update public.team_conversation_members_v1 set last_read_at=now()
    where conversation_id=p_conversation_id and auth_user_id=v_user;
  for v_recipient in select member.auth_user_id
    from public.team_conversation_members_v1 member
    where member.conversation_id=p_conversation_id and member.auth_user_id<>v_user
  loop
    update public.notifications set
      title='Nowa wiadomość od '||public.message_display_name_uat_v1(v_user),
      body=v_subject||': '||left(trim(p_body),240),kind='MESSAGE',
      action_route=public.personal_message_action_route_uat_v1(v_recipient,p_conversation_id),
      read_at=null,resolved_at=null,resolution=null,created_at=now()
    where recipient_id=v_recipient and context_type='TEAM_CONVERSATION'
      and context_id=p_conversation_id::text and resolved_at is null;
    if not found then
      insert into public.notifications(
        recipient_id,title,body,kind,context_type,context_id,action_route,action_required
      ) values(v_recipient,
        'Nowa wiadomość od '||public.message_display_name_uat_v1(v_user),
        v_subject||': '||left(trim(p_body),240),'MESSAGE','TEAM_CONVERSATION',
        p_conversation_id::text,
        public.personal_message_action_route_uat_v1(v_recipient,p_conversation_id),false);
    end if;
  end loop;
  return jsonb_build_object('messageId',v_message);
end;
$function$;

CREATE OR REPLACE FUNCTION public.monthly_budgets_get_before_b4f52_uat_v1(p_month date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_revision public.monthly_budget_revisions_v2%rowtype;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  if not (public.has_app_role('OWNER') or public.has_app_role('ADMIN') or public.has_app_role('HR_FINANCE')) then
    raise exception 'BUDGET_VIEW_FORBIDDEN';
  end if;
  select * into v_revision from public.monthly_budget_revisions_v2
    where budget_month = date_trunc('month', p_month)::date and status = 'ACTIVE';
  return jsonb_build_object(
    'month', date_trunc('month', p_month)::date,
    'canEdit', public.has_app_role('OWNER') or public.has_app_role('ADMIN') or public.has_app_role('HR_FINANCE'),
    'revision', case when v_revision.id is null then null else jsonb_build_object(
      'id', v_revision.id, 'number', v_revision.revision, 'note', v_revision.note,
      'createdAt', v_revision.created_at
    ) end,
    'lines', coalesce((select jsonb_agg(jsonb_build_object(
      'id', line.id, 'scopeType', line.scope_type,
      'locationLogicalId', line.location_logical_id,
      'categoryLogicalId', line.category_logical_id, 'roleLogicalId', line.role_logical_id,
      'metricType', line.metric_type, 'enforcement', line.enforcement,
      'limitValue', line.limit_value, 'referenceValue', line.reference_value,
      'currency', line.currency, 'costBasis', line.cost_basis,
      'distributionMode', line.distribution_mode, 'distribution', line.distribution
    ) order by line.scope_type, line.location_logical_id, line.category_logical_id, line.role_logical_id, line.metric_type)
    from public.monthly_budget_lines_v2 line where line.revision_id = v_revision.id), '[]'::jsonb)
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.monthly_budgets_get_uat_v1(p_month date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_payload jsonb:=public.monthly_budgets_get_before_b4f52_uat_v1(p_month);
  v_visibility text:=public.application_finance_visibility_current_uat_v1();
  v_configured boolean:=jsonb_array_length(coalesce(v_payload->'lines','[]'::jsonb))>0;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  if v_visibility in ('FULL','AGGREGATE') then
    return v_payload||jsonb_build_object('financeVisibility',v_visibility);
  end if;
  if v_visibility='BUDGET_ONLY' then
    return jsonb_build_object(
      'month',date_trunc('month',p_month)::date,
      'canEdit',false,
      'revision',null,
      'lines','[]'::jsonb,
      'budgetStatus',jsonb_build_object('configured',v_configured),
      'financeVisibility',v_visibility
    );
  end if;
  return jsonb_build_object(
    'month',date_trunc('month',p_month)::date,
    'canEdit',false,
    'revision',null,
    'lines','[]'::jsonb,
    'financeVisibility','NONE'
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.monthly_budgets_save_uat_v1(p_month date, p_lines jsonb, p_note text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_month date := date_trunc('month', p_month)::date;
  v_revision_id uuid; v_revision integer; v_line jsonb; v_scope text;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  if not (public.has_app_role('OWNER') or public.has_app_role('ADMIN') or public.has_app_role('HR_FINANCE')) then
    raise exception 'BUDGET_EDIT_FORBIDDEN';
  end if;
  if jsonb_typeof(p_lines) <> 'array' then raise exception 'BUDGET_LINES_MUST_BE_ARRAY'; end if;
  perform pg_advisory_xact_lock(hashtext('monthly-budget:' || v_month::text));
  select coalesce(max(revision),0)+1 into v_revision from public.monthly_budget_revisions_v2 where budget_month=v_month;
  update public.monthly_budget_revisions_v2 set status='ARCHIVED', archived_at=now()
    where budget_month=v_month and status='ACTIVE';
  insert into public.monthly_budget_revisions_v2(budget_month,revision,status,note,created_by)
    values(v_month,v_revision,'ACTIVE',nullif(trim(p_note),''),auth.uid()) returning id into v_revision_id;
  for v_line in select value from jsonb_array_elements(p_lines) loop
    v_scope:=upper(coalesce(v_line->>'scopeType',''));
    if v_scope not in ('COMPANY','LOCATION','CATEGORY','LOCATION_CATEGORY','ROLE') then raise exception 'INVALID_BUDGET_SCOPE'; end if;
    insert into public.monthly_budget_lines_v2(
      revision_id,scope_type,location_logical_id,category_logical_id,role_logical_id,
      metric_type,enforcement,limit_value,reference_value,currency,cost_basis,
      distribution_mode,distribution
    ) values(
      v_revision_id,v_scope,coalesce(nullif(v_line->>'locationLogicalId','')::uuid,(
        select location_row.logical_id from public.matrix_locations_v2 location_row
        where location_row.id=nullif(v_line->>'locationId','')::uuid limit 1
      )),coalesce(nullif(v_line->>'categoryLogicalId','')::uuid,(
        select category.logical_id from public.matrix_role_categories_v2 category
        where category.id=nullif(v_line->>'categoryId','')::uuid limit 1
      )),coalesce(nullif(v_line->>'roleLogicalId','')::uuid,(
        select role_row.logical_id from public.matrix_roles_v2 role_row
        where role_row.id=nullif(v_line->>'roleId','')::uuid limit 1
      )),upper(coalesce(nullif(v_line->>'metricType',''),'COST')),
      upper(coalesce(nullif(v_line->>'enforcement',''),'TARGET')),
      coalesce((v_line->>'limitValue')::numeric,0),nullif(v_line->>'referenceValue','')::numeric,
      case when upper(coalesce(nullif(v_line->>'metricType',''),'COST'))='COST'
        then upper(coalesce(nullif(v_line->>'currency',''),'PLN')) else null end,
      case when upper(coalesce(nullif(v_line->>'metricType',''),'COST'))='COST'
        then upper(coalesce(nullif(v_line->>'costBasis',''),'WAGES')) else null end,
      upper(coalesce(nullif(v_line->>'distributionMode',''),'MONTHLY')),
      case when jsonb_typeof(v_line->'distribution')='object' then v_line->'distribution' else null end
    );
  end loop;
  insert into public.audit_log(actor_id,entity_type,entity_id,action,new_data)
    values(auth.uid(),'monthly_budget_revision',v_revision_id::text,'PUBLISH',
      jsonb_build_object('month',v_month,'revision',v_revision,'lineCount',jsonb_array_length(p_lines),'note',p_note));
  return public.monthly_budgets_get_uat_v1(v_month);
end;
$function$;

CREATE OR REPLACE FUNCTION public.operational_program_can_manage_uat_v1()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select auth.uid() is not null and (
    public.has_app_role('OWNER') or public.has_app_role('ADMIN')
    or public.has_app_role('ROLE_MANAGER') or public.has_app_role('LOCATION_MANAGER')
  );
$function$;

CREATE OR REPLACE FUNCTION public.operational_program_cancel_uat_v1(p_event_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid(); v_event public.operational_program_events_v1%rowtype;
begin
  if not public.operational_program_can_manage_uat_v1() then raise exception 'FORBIDDEN'; end if;
  if length(trim(coalesce(p_reason,'')))<3 then raise exception 'CANCELLATION_REASON_REQUIRED'; end if;
  update public.operational_program_events_v1 set status='CANCELLED',cancellation_reason=trim(p_reason),
    cancelled_by=v_actor,cancelled_at=now(),updated_at=now()
    where id=p_event_id and status not in('CANCELLED','COMPLETED') returning * into v_event;
  if v_event.id is null then raise exception 'EVENT_NOT_CANCELLABLE'; end if;
  update public.operational_program_participants_v1 set assignment_status='CANCELLED',updated_at=now()
    where event_id=p_event_id;
  update public.operational_program_inventory_links_v1 set sync_status='CANCELLED',updated_at=now()
    where event_id=p_event_id;
  delete from public.time_records where source='OPERATIONAL_EVENT:'||p_event_id::text and status='OPEN';
  insert into public.notifications(recipient_id,channel,title,body,sent_at)
    select distinct participant.auth_user_id,'IN_APP','Anulowano: '||v_event.title,trim(p_reason),now()
    from public.operational_program_participants_v1 participant
    where participant.event_id=p_event_id and participant.auth_user_id is not null;
  insert into public.operational_program_audit_v1(event_id,actor_id,action,detail)
    values(p_event_id,v_actor,'CANCEL',jsonb_build_object('reason',trim(p_reason)));
  return jsonb_build_object('id',p_event_id,'status','CANCELLED');
end;
$function$;

CREATE OR REPLACE FUNCTION public.operational_program_integration_save_uat_v1(p_base_url text, p_launch_path_template text DEFAULT '/sessions/new?eventId={eventId}'::text, p_active boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid(); v_row public.business_app_integrations_v1%rowtype;
begin
  if v_actor is null or not(public.has_app_role('OWNER') or public.has_app_role('ADMIN')) then
    raise exception 'FORBIDDEN';
  end if;
  if trim(coalesce(p_base_url,'')) !~ '^https?://' then raise exception 'INVALID_INTEGRATION_URL'; end if;
  if position('{eventId}' in coalesce(p_launch_path_template,''))=0 then raise exception 'EVENT_ID_PLACEHOLDER_REQUIRED'; end if;
  update public.business_app_integrations_v1 set base_url=rtrim(trim(p_base_url),'/'),
    launch_path_template=trim(p_launch_path_template),active=p_active,
    connection_status=case when p_active then 'CONFIGURED' else 'DISCONNECTED' end,
    updated_by=v_actor,updated_at=now() where product_code='INVETORY_PRO' returning * into v_row;
  return jsonb_build_object('id',v_row.id,'status',v_row.connection_status,'active',v_row.active,'baseUrl',v_row.base_url);
end;
$function$;

CREATE OR REPLACE FUNCTION public.operational_program_inventory_ack_uat_v1(p_event_id uuid, p_external_session_id text, p_external_session_url text, p_status text DEFAULT 'READY'::text, p_error text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid(); v_status text:=upper(trim(p_status));
begin
  if not public.operational_program_can_manage_uat_v1() then raise exception 'FORBIDDEN'; end if;
  if v_status not in('READY','ERROR','COMPLETED') then raise exception 'INVALID_SYNC_STATUS'; end if;
  update public.operational_program_inventory_links_v1 set
    external_session_id=nullif(trim(p_external_session_id),''),
    external_session_url=coalesce(nullif(trim(p_external_session_url),''),external_session_url),
    sync_status=v_status,last_error=nullif(trim(p_error),''),attempt_count=attempt_count+1,
    last_attempt_at=now(),synced_at=case when v_status in('READY','COMPLETED') then now() else synced_at end,
    updated_at=now() where event_id=p_event_id;
  if not found then raise exception 'INVENTORY_LINK_NOT_FOUND'; end if;
  insert into public.operational_program_audit_v1(event_id,actor_id,action,detail)
    values(p_event_id,v_actor,'INVENTORY_SYNC',jsonb_build_object('status',v_status,'externalSessionId',p_external_session_id,'error',p_error));
  return jsonb_build_object('eventId',p_event_id,'status',v_status);
end;
$function$;

CREATE OR REPLACE FUNCTION public.operational_program_preview_uat_v1(p_month date, p_starts_at timestamp with time zone, p_ends_at timestamp with time zone, p_location_id uuid DEFAULT NULL::uuid, p_category_ids uuid[] DEFAULT '{}'::uuid[], p_role_ids uuid[] DEFAULT '{}'::uuid[], p_employee_ids uuid[] DEFAULT '{}'::uuid[], p_required_count integer DEFAULT 1)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_matrix uuid; v_month date:=date_trunc('month',p_month)::date;
begin
  if not public.operational_program_can_manage_uat_v1() then raise exception 'FORBIDDEN'; end if;
  if p_ends_at<=p_starts_at then raise exception 'INVALID_EVENT_RANGE'; end if;
  select id into v_matrix from public.matrix_versions
    where status in('ACTIVE','ARCHIVED') and schema_version>=2
      and effective_from<=v_month
    order by effective_from desc,version desc limit 1;
  if v_matrix is null then raise exception 'PUBLISHED_CONFIGURATION_NOT_FOUND'; end if;

  return jsonb_build_object(
    'requiredCount',greatest(1,coalesce(p_required_count,1)),
    'candidates',coalesce((
      with scoped as (
        select profile.employee_id,profile.employee_no,profile.first_name,profile.last_name,
          profile.nominal_monthly_minutes,profile.maximum_monthly_minutes,
          profile.maximum_weekly_minutes,coalesce(profile.minimum_rest_minutes,660) minimum_rest_minutes,
          employee.auth_user_id,
          exists(select 1 from public.matrix_employee_locations_v2 location_grant
            where location_grant.matrix_version_id=v_matrix
              and location_grant.employee_id=profile.employee_id and location_grant.active
              and (p_location_id is null or location_grant.location_id=p_location_id)) location_ok
        from public.matrix_employee_profiles_v2 profile
        join public.employees employee on employee.id=profile.employee_id
        where profile.matrix_version_id=v_matrix and profile.active
          and employee.active and employee.archived_at is null
          and (cardinality(p_employee_ids)=0 or profile.employee_id=any(p_employee_ids))
          and (cardinality(p_employee_ids)>0 or (
            cardinality(p_role_ids)=0 or exists(
              select 1 from public.matrix_employee_roles_v2 role_grant
              where role_grant.matrix_version_id=v_matrix and role_grant.employee_id=profile.employee_id
                and role_grant.role_id=any(p_role_ids) and role_grant.active
            )
          ))
          and (cardinality(p_employee_ids)>0 or cardinality(p_category_ids)=0 or exists(
            select 1 from public.matrix_employee_roles_v2 role_grant
            join public.matrix_roles_v2 role_row on role_row.id=role_grant.role_id
            where role_grant.matrix_version_id=v_matrix and role_grant.employee_id=profile.employee_id
              and role_grant.active and role_row.category_id=any(p_category_ids)
          ))
      ), evaluated as (
        select scoped.*,
          exists(select 1 from public.employee_time_constraints_v2 constraint_row
            where constraint_row.employee_id=scoped.employee_id and constraint_row.status='ACTIVE'
              and constraint_row.constraint_kind in('UNAVAILABLE','LEAVE','SICKNESS')
              and constraint_row.time_range && tstzrange(p_starts_at,p_ends_at,'[)')) unavailable,
          exists(select 1 from public.published_schedules_v2 schedule
            join public.published_schedule_variants_v2 link on link.schedule_id=schedule.id
            join public.plan_assignments_v2 assignment on assignment.variant_id=link.variant_id
            join public.plan_shifts_v2 shift_row on shift_row.id=assignment.shift_id
            where schedule.month=v_month and schedule.status='PUBLISHED'
              and assignment.employee_id=scoped.employee_id
              and tstzrange(shift_row.starts_at,shift_row.ends_at,'[)') && tstzrange(p_starts_at,p_ends_at,'[)')) overlaps_shift,
          exists(select 1 from public.published_schedules_v2 schedule
            join public.published_schedule_variants_v2 link on link.schedule_id=schedule.id
            join public.plan_assignments_v2 assignment on assignment.variant_id=link.variant_id
            join public.plan_shifts_v2 shift_row on shift_row.id=assignment.shift_id
            where schedule.month=v_month and schedule.status='PUBLISHED'
              and assignment.employee_id=scoped.employee_id
              and not (shift_row.ends_at<=p_starts_at-scoped.minimum_rest_minutes*interval '1 minute'
                or shift_row.starts_at>=p_ends_at+scoped.minimum_rest_minutes*interval '1 minute')) rest_risk,
          coalesce((select round(sum(extract(epoch from (shift_row.ends_at-shift_row.starts_at))/60))::integer
            from public.published_schedules_v2 schedule
            join public.published_schedule_variants_v2 link on link.schedule_id=schedule.id
            join public.plan_assignments_v2 assignment on assignment.variant_id=link.variant_id
            join public.plan_shifts_v2 shift_row on shift_row.id=assignment.shift_id
            where schedule.month=v_month and schedule.status='PUBLISHED'
              and assignment.employee_id=scoped.employee_id),0) planned_minutes
        from scoped
      )
      select jsonb_agg(jsonb_build_object(
        'employeeId',employee_id,'employeeNo',employee_no,
        'name',first_name||' '||last_name,'authUserId',auth_user_id,
        'status',case when unavailable or overlaps_shift then 'BLOCKED'
          when not location_ok or rest_risk then 'WARNING' else 'SAFE' end,
        'reasons',to_jsonb(array_remove(array[
          case when unavailable then 'Twarda niedostępność, urlop albo L4' end,
          case when overlaps_shift then 'Ma już zmianę w tych godzinach' end,
          case when not location_ok then 'Brak przypisania do wybranego lokalu' end,
          case when rest_risk and not overlaps_shift then 'Ryzyko naruszenia odpoczynku' end
        ],null)),
        'plannedMinutes',planned_minutes,'nominalMinutes',nominal_monthly_minutes,
        'maximumMinutes',maximum_monthly_minutes
      ) order by
        case when unavailable or overlaps_shift then 3 when not location_ok or rest_risk then 2 else 1 end,
        abs(nominal_monthly_minutes-planned_minutes),last_name,first_name)
      from evaluated
    ),'[]'::jsonb)
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.operational_program_save_uat_v1(p_event jsonb, p_audience jsonb DEFAULT '[]'::jsonb, p_checklist jsonb DEFAULT '[]'::jsonb, p_participant_ids uuid[] DEFAULT '{}'::uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid(); v_id uuid; v_item jsonb; v_preview jsonb; v_candidate jsonb;
  v_employee uuid; v_integration public.business_app_integrations_v1%rowtype; v_path text; v_url text;
  v_event public.operational_program_events_v1%rowtype;
begin
  if not public.operational_program_can_manage_uat_v1() then raise exception 'FORBIDDEN'; end if;
  if upper(coalesce(p_event->>'status','DRAFT')) not in('DRAFT','ANALYSIS','PUBLISHED') then
    raise exception 'INVALID_EVENT_STATUS';
  end if;
  insert into public.operational_program_events_v1(
    event_type,title,description,location_id,starts_at,ends_at,status,audience_mode,
    required_count,inventory_type,inventory_groups,private_note,published_note,agenda,
    created_by,published_by,published_at
  ) values(
    upper(trim(p_event->>'type')),trim(p_event->>'title'),nullif(trim(p_event->>'description'),''),
    nullif(p_event->>'locationId','')::uuid,(p_event->>'startsAt')::timestamptz,(p_event->>'endsAt')::timestamptz,
    upper(coalesce(p_event->>'status','DRAFT')),upper(coalesce(p_event->>'audienceMode','NEED_COUNT')),
    nullif(p_event->>'requiredCount','')::integer,
    case when upper(trim(p_event->>'type'))='INVENTORY' then upper(coalesce(p_event->>'inventoryType','FULL')) else null end,
    coalesce(array(select jsonb_array_elements_text(coalesce(p_event->'inventoryGroups','[]'::jsonb))),'{}'),
    nullif(p_event->>'privateNote',''),nullif(p_event->>'publishedNote',''),nullif(p_event->>'agenda',''),v_actor,
    case when upper(coalesce(p_event->>'status','DRAFT'))='PUBLISHED' then v_actor end,
    case when upper(coalesce(p_event->>'status','DRAFT'))='PUBLISHED' then now() end
  ) returning * into v_event;
  v_id:=v_event.id;

  for v_item in select value from jsonb_array_elements(coalesce(p_audience,'[]'::jsonb)) loop
    insert into public.operational_program_audience_rules_v1(
      event_id,rule_mode,scope_type,scope_uuid,scope_code
    ) values(v_id,upper(coalesce(v_item->>'mode','INCLUDE')),upper(v_item->>'type'),
      nullif(v_item->>'id','')::uuid,nullif(v_item->>'code',''));
  end loop;
  for v_item in select value from jsonb_array_elements(coalesce(p_checklist,'[]'::jsonb)) loop
    insert into public.operational_program_checklist_items_v1(event_id,item_order,label,visibility,visible_to)
    values(v_id,coalesce(nullif(v_item->>'order','')::integer,0),trim(v_item->>'label'),
      upper(coalesce(v_item->>'visibility','ALL')),coalesce(v_item->'visibleTo','[]'::jsonb));
  end loop;

  if cardinality(p_participant_ids)>0 then
    v_preview:=public.operational_program_preview_uat_v1(
      date_trunc('month',v_event.starts_at)::date,v_event.starts_at,v_event.ends_at,v_event.location_id,
      coalesce(array(select (x->>'id')::uuid from jsonb_array_elements(p_audience) x where upper(x->>'type')='CATEGORY' and upper(coalesce(x->>'mode','INCLUDE'))='INCLUDE'),'{}'),
      coalesce(array(select (x->>'id')::uuid from jsonb_array_elements(p_audience) x where upper(x->>'type')='ROLE' and upper(coalesce(x->>'mode','INCLUDE'))='INCLUDE'),'{}'),
      p_participant_ids,coalesce(v_event.required_count,cardinality(p_participant_ids)));
    foreach v_employee in array p_participant_ids loop
      select value into v_candidate from jsonb_array_elements(v_preview->'candidates')
        where value->>'employeeId'=v_employee::text limit 1;
      if v_candidate is null then raise exception 'PARTICIPANT_NOT_IN_ACTIVE_CONFIGURATION|%',v_employee; end if;
      if v_candidate->>'status'='BLOCKED' then raise exception 'PARTICIPANT_HARD_BLOCK|%|%',v_employee,v_candidate->'reasons'; end if;
      if v_candidate->>'status'='WARNING' and length(trim(coalesce(p_event->>'overrideReason','')))<5 then
        raise exception 'PARTICIPANT_WARNING_REQUIRES_REASON|%|%',v_employee,v_candidate->'reasons';
      end if;
      insert into public.operational_program_participants_v1(
        event_id,employee_id,auth_user_id,selection_source,candidate_status,reasons,
        assignment_status,override_reason
      ) select v_id,v_employee,employee.auth_user_id,
        case when upper(coalesce(p_event->>'audienceMode','NEED_COUNT'))='ALL_SCOPE' then 'SCOPE' else 'MANAGER' end,
        v_candidate->>'status',coalesce(array(select jsonb_array_elements_text(v_candidate->'reasons')),'{}'),
        'CONFIRMED',case when v_candidate->>'status'='WARNING' then trim(p_event->>'overrideReason') end
      from public.employees employee where employee.id=v_employee;
    end loop;
  end if;
  if v_event.audience_mode='NEED_COUNT' and cardinality(p_participant_ids)<coalesce(v_event.required_count,1)
    and v_event.status='PUBLISHED' then raise exception 'NOT_ENOUGH_PARTICIPANTS'; end if;

  if v_event.status='PUBLISHED' then
    insert into public.notifications(recipient_id,channel,title,body,sent_at)
    select distinct participant.auth_user_id,'IN_APP','Nowe wydarzenie: '||v_event.title,
      to_char(v_event.starts_at at time zone 'Europe/Warsaw','DD.MM.YYYY HH24:MI')||
        coalesce(' • '||v_event.published_note,''),now()
    from public.operational_program_participants_v1 participant
    where participant.event_id=v_id and participant.auth_user_id is not null;

    insert into public.time_records(employee_id,work_date,planned_start,planned_end,source,status)
    select participant.employee_id,(v_event.starts_at at time zone 'Europe/Warsaw')::date,
      v_event.starts_at,v_event.ends_at,'OPERATIONAL_EVENT:'||v_id::text,'OPEN'
    from public.operational_program_participants_v1 participant
    where participant.event_id=v_id and participant.employee_id is not null
    on conflict(employee_id,work_date,planned_start) do update set
      planned_end=excluded.planned_end,source=excluded.source;

    if v_event.event_type='INVENTORY' then
      select * into v_integration from public.business_app_integrations_v1 where product_code='INVETORY_PRO';
      v_path:=replace(v_integration.launch_path_template,'{eventId}',v_id::text);
      v_url:=case when v_integration.active and v_integration.base_url is not null
        then rtrim(v_integration.base_url,'/')||'/'||ltrim(v_path,'/') end;
      insert into public.operational_program_inventory_links_v1(
        event_id,integration_id,external_session_url,sync_status,payload,payload_hash
      ) values(v_id,v_integration.id,v_url,
        case when v_url is null then 'WAITING_CONFIGURATION' else 'QUEUED' end,
        jsonb_build_object('eventId',v_id,'title',v_event.title,'type',v_event.inventory_type,
          'groups',v_event.inventory_groups,'startsAt',v_event.starts_at,'endsAt',v_event.ends_at,
          'locationId',v_event.location_id,'participants',to_jsonb(p_participant_ids)),
        encode(extensions.digest((jsonb_build_object('eventId',v_id,'version',v_event.version_no))::text,'sha256'),'hex'));
    end if;
  end if;
  insert into public.operational_program_audit_v1(event_id,actor_id,action,detail)
    values(v_id,v_actor,case when v_event.status='PUBLISHED' then 'PUBLISH' else 'SAVE_DRAFT' end,
      jsonb_build_object('status',v_event.status,'participantCount',cardinality(p_participant_ids)));
  return jsonb_build_object('id',v_id,'status',v_event.status,'participantCount',cardinality(p_participant_ids));
end;
$function$;

CREATE OR REPLACE FUNCTION public.operational_program_workspace_uat_v1(p_month date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid(); v_month date:=date_trunc('month',p_month)::date;
  v_matrix uuid; v_can_manage boolean; v_employee uuid;
begin
  if v_actor is null then raise exception 'AUTH_REQUIRED'; end if;
  v_can_manage:=public.operational_program_can_manage_uat_v1();
  select id into v_matrix from public.matrix_versions
    where status in('ACTIVE','ARCHIVED') and schema_version>=2 and effective_from<=v_month
    order by effective_from desc,version desc limit 1;
  select id into v_employee from public.employees where auth_user_id=v_actor and active and archived_at is null limit 1;
  return jsonb_build_object(
    'canManage',v_can_manage,
    'canConfigureIntegration',public.has_app_role('OWNER') or public.has_app_role('ADMIN'),
    'integration',coalesce((select jsonb_build_object(
      'id',integration.id,'productCode',integration.product_code,'displayName',integration.display_name,
      'baseUrl',integration.base_url,'launchPathTemplate',integration.launch_path_template,
      'status',integration.connection_status,'active',integration.active
    ) from public.business_app_integrations_v1 integration where integration.product_code='INVETORY_PRO'),'null'::jsonb),
    'categories',coalesce((select jsonb_agg(jsonb_build_object(
      'id',category.id,'code',category.code,'name',category.name,'color',category.color
    ) order by category.sort_order,category.name) from public.matrix_role_categories_v2 category
      where category.matrix_version_id=v_matrix and category.active),'[]'::jsonb),
    'roles',coalesce((select jsonb_agg(jsonb_build_object(
      'id',role_row.id,'code',role_row.code,'name',role_row.name,'categoryId',role_row.category_id,'color',role_row.color
    ) order by role_row.sort_order,role_row.name) from public.matrix_roles_v2 role_row
      where role_row.matrix_version_id=v_matrix and role_row.active),'[]'::jsonb),
    'locations',coalesce((select jsonb_agg(jsonb_build_object(
      'id',location_row.id,'code',location_row.code,'name',location_row.name
    ) order by location_row.sort_order,location_row.name) from public.matrix_locations_v2 location_row
      where location_row.matrix_version_id=v_matrix and location_row.active),'[]'::jsonb),
    'employees',case when v_can_manage then coalesce((select jsonb_agg(jsonb_build_object(
      'id',profile.employee_id,'employeeNo',profile.employee_no,'name',profile.first_name||' '||profile.last_name,
      'email',profile.email
    ) order by profile.last_name,profile.first_name) from public.matrix_employee_profiles_v2 profile
      where profile.matrix_version_id=v_matrix and profile.active),'[]'::jsonb) else '[]'::jsonb end,
    'events',coalesce((select jsonb_agg(jsonb_build_object(
      'id',event_row.id,'type',event_row.event_type,'title',event_row.title,
      'description',event_row.description,'startsAt',event_row.starts_at,'endsAt',event_row.ends_at,
      'status',event_row.status,'audienceMode',event_row.audience_mode,'requiredCount',event_row.required_count,
      'locationId',event_row.location_id,'locationName',location_row.name,
      'publishedNote',event_row.published_note,'agenda',event_row.agenda,
      'inventoryType',event_row.inventory_type,'inventoryGroups',event_row.inventory_groups,
      'participants',coalesce((select jsonb_agg(jsonb_build_object(
        'employeeId',participant.employee_id,'name',coalesce(profile.first_name||' '||profile.last_name,user_row.email),
        'candidateStatus',participant.candidate_status,'status',participant.assignment_status,
        'reasons',participant.reasons
      ) order by coalesce(profile.last_name,user_row.email))
        from public.operational_program_participants_v1 participant
        left join public.matrix_employee_profiles_v2 profile on profile.matrix_version_id=v_matrix and profile.employee_id=participant.employee_id
        left join auth.users user_row on user_row.id=participant.auth_user_id
        where participant.event_id=event_row.id),'[]'::jsonb),
      'checklist',coalesce((select jsonb_agg(jsonb_build_object(
        'id',check_item.id,'label',check_item.label,'visibility',check_item.visibility,
        'completed',check_item.completed
      ) order by check_item.item_order,check_item.id)
        from public.operational_program_checklist_items_v1 check_item where check_item.event_id=event_row.id),'[]'::jsonb),
      'inventoryLink',(select jsonb_build_object(
        'status',inventory_link.sync_status,'url',inventory_link.external_session_url,
        'externalSessionId',inventory_link.external_session_id,'lastError',inventory_link.last_error
      ) from public.operational_program_inventory_links_v1 inventory_link where inventory_link.event_id=event_row.id)
    ) order by event_row.starts_at,event_row.title)
      from public.operational_program_events_v1 event_row
      left join public.matrix_locations_v2 location_row on location_row.id=event_row.location_id
      where event_row.starts_at>=v_month::timestamptz
        and event_row.starts_at<(v_month+interval '1 month')
        and (v_can_manage or exists(select 1 from public.operational_program_participants_v1 participant
          where participant.event_id=event_row.id and (participant.employee_id=v_employee or participant.auth_user_id=v_actor)))
    ),'[]'::jsonb)
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.optimizer_abort_finalize_v4(p_run_id uuid, p_error text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r public.optimization_runs; v_plan_ids uuid[];
begin
  if not public.can_manage_plans() then raise exception 'FORBIDDEN'; end if;
  select * into r from public.optimization_runs
    where id=p_run_id and requested_by=auth.uid() for update;
  if r.id is null then return jsonb_build_object('runId',p_run_id,'aborted',false); end if;
  if r.status<>'RUNNING' then
    return jsonb_build_object('runId',r.id,'aborted',false,'status',r.status);
  end if;
  select coalesce(array_agg(plan_id) filter(where plan_id is not null),'{}'::uuid[])
    into v_plan_ids from public.optimization_candidates where run_id=r.id;
  delete from public.optimization_candidates where run_id=r.id;
  delete from public.plans where id=any(v_plan_ids);
  update public.optimization_runs set
    status='FAILED',finished_at=now(),heartbeat_at=now(),
    failure_message=left(coalesce(p_error,'UNKNOWN_ERROR'),2000),
    result_summary=result_summary||jsonb_build_object('phase','FAILED','progress',100)
  where id=r.id and status='RUNNING';
  return jsonb_build_object('runId',r.id,'aborted',true,'plansRemoved',cardinality(v_plan_ids));
end $function$;

CREATE OR REPLACE FUNCTION public.optimizer_active_workspace_v2(p_month date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_engine text;
  v_schedule_id uuid;
  v_month date:=date_trunc('month',p_month)::date;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  if p_month is null then raise exception 'MONTH_REQUIRED'; end if;
  select f.engine into v_engine
  from public.solver_feature_flags f
  where f.flag_key='DEFAULT_ENGINE' and f.enabled;
  if v_engine is null then raise exception 'SOLVER_ENGINE_CONFIGURATION_MISSING'; end if;
  if v_engine not in ('ALPHA15','SHADOW','ORTOOLS_V2') then
    raise exception 'SOLVER_ENGINE_CONFIGURATION_INVALID';
  end if;
  if v_engine<>'ORTOOLS_V2' then return null; end if;
  if not (
    public.has_app_role('OWNER') or public.has_app_role('ADMIN')
    or public.has_app_role('HR_FINANCE') or public.has_app_role('VERIFIER')
  ) then raise exception 'FORBIDDEN'; end if;
  select s.id into v_schedule_id
  from public.published_schedules_v2 s
  where s.month=v_month and s.status='PUBLISHED'
  order by s.published_at desc,s.id desc limit 1;
  if v_schedule_id is null then
    return jsonb_build_object(
      'engine','ORTOOLS_V2',
      'context',jsonb_build_object(
        'type','PUBLISHED_SCHEDULE','status','EMPTY','month',v_month,
        'name','Brak opublikowanego grafiku'
      ),
      'variants','[]'::jsonb,'shifts','[]'::jsonb,
      'issues','[]'::jsonb,'finance',null
    );
  end if;
  return public.optimizer_published_schedule_v2(v_schedule_id)
    ||jsonb_build_object('engine','ORTOOLS_V2');
end;
$function$;

CREATE OR REPLACE FUNCTION public.optimizer_begin_finalize_v4(p_run_id uuid, p_name text, p_candidates jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  r public.optimization_runs;
  v_baseline jsonb;
  v_best jsonb;
begin
  if not public.can_manage_plans() then raise exception 'FORBIDDEN'; end if;
  select * into r from public.optimization_runs
    where id=p_run_id and requested_by=auth.uid() for update;
  if r.id is null or r.status<>'RUNNING' then raise exception 'OPTIMIZATION_RUN_NOT_WRITABLE'; end if;
  if r.result_summary->>'phase'='FINALIZING' then
    return jsonb_build_object('runId',r.id,'finalizing',true,
      'finalizeCursor',coalesce((r.checkpoint->>'finalizeCursor')::integer,0),'finalizeTarget',3);
  end if;
  if r.current_generation<r.target_generations then raise exception 'GENERATIONS_INCOMPLETE'; end if;
  if jsonb_array_length(coalesce(p_candidates,'[]'::jsonb))<>3 then raise exception 'THREE_VARIANTS_REQUIRED'; end if;
  if (select array_agg((x->>'rank')::integer order by (x->>'rank')::integer)
      from jsonb_array_elements(p_candidates) x)<>array[1,2,3]
    or exists(select 1 from jsonb_array_elements(p_candidates) x
      where coalesce((x->>'hardViolations')::integer,0)<>0)
    or (select count(distinct md5(coalesce(x->'assignments','[]'::jsonb)::text))
      from jsonb_array_elements(p_candidates) x)<>3
  then raise exception 'THREE_DISTINCT_HARD_VALID_VARIANTS_REQUIRED'; end if;
  v_baseline:=r.checkpoint->'baselineRanking';
  select x->'metrics'->'ranking' into v_best
  from jsonb_array_elements(p_candidates) x where (x->>'rank')::integer=1;
  if v_baseline is not null and (
    coalesce((v_best->>0)::numeric,0)>coalesce((v_baseline->>0)::numeric,0)
    or (coalesce((v_best->>0)::numeric,0)=coalesce((v_baseline->>0)::numeric,0)
      and coalesce((v_best->>1)::numeric,0)>coalesce((v_baseline->>1)::numeric,0))
    or (coalesce((v_best->>0)::numeric,0)=coalesce((v_baseline->>0)::numeric,0)
      and coalesce((v_best->>1)::numeric,0)=coalesce((v_baseline->>1)::numeric,0)
      and coalesce((v_best->>2)::numeric,0)>coalesce((v_baseline->>2)::numeric,0))
  ) then raise exception 'NO_REGRESSION_GUARD'; end if;
  delete from public.optimization_candidates where run_id=r.id;
  insert into public.optimization_candidates(
    run_id,rank,score,hard_violations,metrics,assignments,selected
  )
  select r.id,(x->>'rank')::integer,(x->>'score')::numeric,
    coalesce((x->>'hardViolations')::integer,0),coalesce(x->'metrics','{}'::jsonb),
    coalesce(x->'assignments','[]'::jsonb),(x->>'rank')::integer=1
  from jsonb_array_elements(p_candidates) x;
  update public.optimization_runs set
    checkpoint=checkpoint||jsonb_build_object(
      'finalizeCursor',0,'finalizeTarget',3,
      'finalizeName',coalesce(nullif(trim(p_name),''),'Plan optymalny'),
      'finalCandidates',p_candidates),
    heartbeat_at=now(),
    result_summary=result_summary||jsonb_build_object(
      'phase','FINALIZING','progress',90,'engineVersion','ALPHA_15_V4')
  where id=r.id;
  return jsonb_build_object('runId',r.id,'finalizing',true,'finalizeCursor',0,'finalizeTarget',3);
end $function$;

CREATE OR REPLACE FUNCTION public.optimizer_candidate_diagnostics_alpha16(p_schedule_id uuid, p_issue_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_payload jsonb;
  v_candidates jsonb:='[]'::jsonb;
  v_candidate jsonb;
  v_hard text[];
  v_classification text;
  v_summary jsonb;
begin
  v_payload:=public.optimizer_candidate_diagnostics_before_role_scope_alpha16(
    p_schedule_id,p_issue_id
  );
  for v_candidate in
    select candidate.value
    from jsonb_array_elements(coalesce(v_payload->'candidates','[]'::jsonb)) candidate
  loop
    select coalesce(array_agg(reason),array[]::text[]) into v_hard
    from jsonb_array_elements_text(coalesce(v_candidate->'hardReasons','[]'::jsonb)) reason;
    if 'ROLE_REQUIRED'=any(v_hard) then
      v_hard:=array_remove(v_hard,'STANDBY_TIER_1_RESERVED');
      v_hard:=array_remove(v_hard,'STANDBY_TIER_2_RESERVED');
    end if;
    v_classification:=case
      when cardinality(v_hard)>0 then 'BLOCKED'
      when jsonb_array_length(coalesce(v_candidate->'softReasons','[]'::jsonb))>0 then 'WARNING'
      else 'ELIGIBLE'
    end;
    v_candidate:=jsonb_set(v_candidate,'{hardReasons}',to_jsonb(v_hard),true);
    v_candidate:=jsonb_set(v_candidate,'{classification}',to_jsonb(v_classification),true);
    v_candidates:=v_candidates||jsonb_build_array(v_candidate);
  end loop;
  select jsonb_build_object(
    'considered',jsonb_array_length(v_candidates),
    'eligible',count(*) filter(where candidate.value->>'classification'='ELIGIBLE'),
    'warning',count(*) filter(where candidate.value->>'classification'='WARNING'),
    'blocked',count(*) filter(where candidate.value->>'classification'='BLOCKED')
  ) into v_summary
  from jsonb_array_elements(v_candidates) candidate;
  return jsonb_set(
    jsonb_set(v_payload,'{candidates}',v_candidates,true),
    '{summary}',v_summary,true
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.optimizer_candidate_diagnostics_before_primary_rules_alpha16(p_schedule_id uuid, p_issue_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_schedule public.published_schedules_v2%rowtype;
  v_issue public.plan_issues_v2%rowtype;
  v_shift public.plan_shifts_v2%rowtype;
  v_shift_period text;
  v_timezone text;
  v_minimum_rest integer;
  v_candidates jsonb;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  if not solver_private.alpha16_can_manage_schedule_v2(p_schedule_id) then
    raise exception 'FORBIDDEN';
  end if;
  select * into v_schedule from public.published_schedules_v2 schedule
  where schedule.id=p_schedule_id and schedule.status='PUBLISHED';
  if v_schedule.id is null then raise exception 'PUBLISHED_SCHEDULE_NOT_FOUND'; end if;
  select issue.* into v_issue
  from public.plan_issues_v2 issue
  join public.published_schedule_variants_v2 link
    on link.schedule_id=v_schedule.id and link.variant_id=issue.variant_id
  where issue.id=p_issue_id and issue.issue_code='UNFILLED_SLOT';
  if v_issue.id is null then raise exception 'UNFILLED_ISSUE_NOT_FOUND'; end if;
  select shift_row.* into v_shift from public.plan_shifts_v2 shift_row
  where shift_row.id=v_issue.shift_id;
  if v_shift.id is null then raise exception 'SHIFT_NOT_FOUND'; end if;
  select template.shift_period,location.timezone into v_shift_period,v_timezone
  from public.matrix_shift_templates_v2 template
  join public.matrix_locations_v2 location on location.id=template.location_id
  where template.id=v_shift.shift_template_id;
  select coalesce((matrix.settings->>'minimumRestMinutes')::integer,660)
  into v_minimum_rest
  from public.matrix_versions matrix where matrix.id=v_schedule.matrix_version_id;

  with schedule_variants as (
    select link.variant_id
    from public.published_schedule_variants_v2 link
    where link.schedule_id=v_schedule.id
  ), scheduled as (
    select assignment.employee_id,shift_row.starts_at,shift_row.ends_at,
      shift_row.shift_date
    from public.plan_assignments_v2 assignment
    join schedule_variants variant on variant.variant_id=assignment.variant_id
    join public.plan_shifts_v2 shift_row on shift_row.id=assignment.shift_id
    union all
    select override_row.employee_id,shift_row.starts_at,shift_row.ends_at,
      shift_row.shift_date
    from public.operational_assignment_overrides_v2 override_row
    join public.plan_shifts_v2 shift_row on shift_row.id=override_row.shift_id
    where override_row.schedule_id=v_schedule.id and override_row.status='ACTIVE'
  ), profiles as (
    select profile.*,
      coalesce(profile.minimum_rest_minutes,v_minimum_rest) rest_minutes
    from public.matrix_employee_profiles_v2 profile
    where profile.matrix_version_id=v_schedule.matrix_version_id
      and profile.active and profile.archived_at is null
      and (profile.employment_start is null
        or profile.employment_start<=v_shift.shift_date)
      and (profile.employment_end is null
        or profile.employment_end>=v_shift.shift_date)
  ), candidate_base as (
    select profile.*,
      exists(select 1 from public.matrix_employee_roles_v2 grant_row
        where grant_row.matrix_version_id=v_schedule.matrix_version_id
          and grant_row.employee_id=profile.employee_id
          and grant_row.role_id=v_issue.role_id and grant_row.active
          and (grant_row.valid_from is null or grant_row.valid_from<=v_shift.shift_date)
          and (grant_row.valid_to is null or grant_row.valid_to>=v_shift.shift_date)
      ) role_ok,
      exists(select 1 from public.matrix_employee_locations_v2 grant_row
        where grant_row.matrix_version_id=v_schedule.matrix_version_id
          and grant_row.employee_id=profile.employee_id
          and grant_row.location_id=v_shift.location_id and grant_row.active
          and grant_row.standard_allowed
          and (grant_row.valid_from is null or grant_row.valid_from<=v_shift.shift_date)
          and (grant_row.valid_to is null or grant_row.valid_to>=v_shift.shift_date)
      ) location_ok,
      v_issue.duty_id is null or exists(
        select 1 from public.matrix_employee_duties_v2 grant_row
        where grant_row.matrix_version_id=v_schedule.matrix_version_id
          and grant_row.employee_id=profile.employee_id
          and grant_row.duty_id=v_issue.duty_id and grant_row.active
          and (grant_row.role_id is null or grant_row.role_id=v_issue.role_id)
          and (grant_row.location_id is null or grant_row.location_id=v_shift.location_id)
          and (grant_row.valid_from is null or grant_row.valid_from<=v_shift.shift_date)
          and (grant_row.valid_to is null or grant_row.valid_to>=v_shift.shift_date)
      ) duty_ok,
      exists(select 1 from scheduled assignment
        where assignment.employee_id=profile.employee_id
          and tstzrange(assignment.starts_at,assignment.ends_at,'[)')
            && tstzrange(v_shift.starts_at,v_shift.ends_at,'[)')) overlap,
      exists(select 1 from public.employee_time_constraints_v2 constraint_row
        where constraint_row.employee_id=profile.employee_id
          and constraint_row.status='ACTIVE'
          and constraint_row.constraint_kind in ('UNAVAILABLE','LEAVE','SICKNESS')
          and constraint_row.time_range
            && tstzrange(v_shift.starts_at,v_shift.ends_at,'[)')) blocked_time,
      (
        exists(select 1 from public.employee_time_constraints_v2 constraint_row
          where constraint_row.employee_id=profile.employee_id
            and constraint_row.status='ACTIVE'
            and constraint_row.constraint_kind='AVAILABLE_WINDOW'
            and lower(constraint_row.time_range)<(v_shift.shift_date+1)::timestamp
              at time zone v_timezone
            and upper(constraint_row.time_range)>v_shift.shift_date::timestamp
              at time zone v_timezone)
        and not exists(select 1 from public.employee_time_constraints_v2 constraint_row
          where constraint_row.employee_id=profile.employee_id
            and constraint_row.status='ACTIVE'
            and constraint_row.constraint_kind='AVAILABLE_WINDOW'
            and lower(constraint_row.time_range)<=v_shift.starts_at
            and upper(constraint_row.time_range)>=v_shift.ends_at)
      ) outside_available_window,
      coalesce(solver_private.alpha16_preference_level_v2(
        profile.employee_id,v_schedule.matrix_version_id,v_schedule.month,v_shift_period
      ),case
        when profile.only_morning and v_shift_period<>'MORNING' then 'BLOCKED'
        when profile.only_evening and v_shift_period<>'EVENING' then 'BLOCKED'
        else 'NEUTRAL' end) preference_level,
      coalesce((select sum(extract(epoch from
        (assignment.ends_at-assignment.starts_at))/60)::integer
        from scheduled assignment
        where assignment.employee_id=profile.employee_id
          and assignment.shift_date>=v_schedule.month
          and assignment.shift_date<(v_schedule.month+interval '1 month')::date),0)
        monthly_minutes,
      coalesce((select count(*) from scheduled assignment
        where assignment.employee_id=profile.employee_id
          and assignment.shift_date>=v_schedule.month
          and assignment.shift_date<(v_schedule.month+interval '1 month')::date),0)
        monthly_shifts,
      coalesce((select sum(extract(epoch from
        (assignment.ends_at-assignment.starts_at))/60)::integer
        from scheduled assignment
        where assignment.employee_id=profile.employee_id
          and assignment.shift_date>=date_trunc('week',v_shift.shift_date)::date
          and assignment.shift_date<date_trunc('week',v_shift.shift_date)::date+7),0)
        weekly_minutes,
      (select jsonb_build_object('date',assignment.shift_date,
          'startsAt',assignment.starts_at,'endsAt',assignment.ends_at)
        from scheduled assignment
        where assignment.employee_id=profile.employee_id
          and assignment.ends_at<=v_shift.starts_at
        order by assignment.ends_at desc limit 1) previous_shift,
      (select jsonb_build_object('date',assignment.shift_date,
          'startsAt',assignment.starts_at,'endsAt',assignment.ends_at)
        from scheduled assignment
        where assignment.employee_id=profile.employee_id
          and assignment.starts_at>=v_shift.ends_at
        order by assignment.starts_at limit 1) next_shift,
      exists(select 1 from scheduled assignment
        where assignment.employee_id=profile.employee_id
          and assignment.shift_date=v_shift.shift_date-1) works_previous_day,
      exists(select 1 from scheduled assignment
        where assignment.employee_id=profile.employee_id
          and assignment.shift_date=v_shift.shift_date+1) works_next_day,
      coalesce((select min(day_offset.value)-1
        from generate_series(1,31) day_offset(value)
        where not exists(select 1 from scheduled assignment
          where assignment.employee_id=profile.employee_id
            and assignment.shift_date=v_shift.shift_date-day_offset.value)),31)
        consecutive_days_before,
      coalesce((select min(day_offset.value)-1
        from generate_series(1,31) day_offset(value)
        where not exists(select 1 from scheduled assignment
          where assignment.employee_id=profile.employee_id
            and assignment.shift_date=v_shift.shift_date+day_offset.value)),31)
        consecutive_days_after
    from profiles profile
  ), evaluated as (
    select candidate.*,
      extract(epoch from (v_shift.ends_at-v_shift.starts_at))/60 target_minutes,
      candidate.consecutive_days_before+1+candidate.consecutive_days_after
        projected_consecutive_days,
      candidate.previous_shift is not null and
        extract(epoch from (v_shift.starts_at-
          (candidate.previous_shift->>'endsAt')::timestamptz))/60
          <candidate.rest_minutes previous_rest_conflict,
      candidate.next_shift is not null and
        extract(epoch from ((candidate.next_shift->>'startsAt')::timestamptz-
          v_shift.ends_at))/60<candidate.rest_minutes next_rest_conflict
    from candidate_base candidate
  ), classified as (
    select candidate.*,
      array_remove(array[
        case when not candidate.role_ok then 'ROLE_REQUIRED' end,
        case when not candidate.location_ok then 'LOCATION_NOT_ALLOWED' end,
        case when not candidate.duty_ok then 'DUTY_REQUIRED' end,
        case when candidate.overlap then 'SHIFT_OVERLAP' end,
        case when candidate.blocked_time then 'DECLARED_UNAVAILABLE' end,
        case when candidate.outside_available_window then 'OUTSIDE_AVAILABILITY_WINDOW' end,
        case when candidate.previous_rest_conflict then 'REST_AFTER_PREVIOUS_SHIFT' end,
        case when candidate.next_rest_conflict then 'REST_BEFORE_NEXT_SHIFT' end,
        case when candidate.monthly_minutes+candidate.target_minutes>
          candidate.maximum_monthly_minutes then 'MONTHLY_LIMIT' end,
        case when candidate.weekly_minutes+candidate.target_minutes>
          candidate.maximum_weekly_minutes then 'WEEKLY_LIMIT' end,
        case when candidate.projected_consecutive_days>
          candidate.maximum_consecutive_days then 'MAX_CONSECUTIVE_DAYS' end,
        case when candidate.preference_level='BLOCKED' then 'MANAGER_SHIFT_BLOCK' end
      ]::text[],null) hard_reasons,
      array_remove(array[
        case when candidate.preference_level='AVOIDED' then 'SHIFT_PREFERENCE_AVOIDED' end,
        case when candidate.monthly_minutes+candidate.target_minutes>
          candidate.nominal_monthly_minutes then 'OVERTIME_AFTER_ASSIGNMENT' end
      ]::text[],null) soft_reasons
    from evaluated candidate
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'employeeId',candidate.employee_id,
    'employeeNo',candidate.employee_no,
    'name',candidate.first_name||' '||candidate.last_name,
    'classification',case
      when cardinality(candidate.hard_reasons)>0 then 'BLOCKED'
      when cardinality(candidate.soft_reasons)>0 then 'WARNING'
      else 'ELIGIBLE' end,
    'hardReasons',to_jsonb(candidate.hard_reasons),
    'softReasons',to_jsonb(candidate.soft_reasons),
    'preferenceLevel',candidate.preference_level,
    'monthlyShifts',candidate.monthly_shifts,
    'monthlyMinutes',candidate.monthly_minutes,
    'nominalMonthlyMinutes',candidate.nominal_monthly_minutes,
    'maximumMonthlyMinutes',candidate.maximum_monthly_minutes,
    'weeklyMinutes',candidate.weekly_minutes,
    'maximumWeeklyMinutes',candidate.maximum_weekly_minutes,
    'consecutiveDaysBefore',candidate.consecutive_days_before,
    'consecutiveDaysAfter',candidate.consecutive_days_after,
    'projectedConsecutiveDays',candidate.projected_consecutive_days,
    'maximumConsecutiveDays',candidate.maximum_consecutive_days,
    'declaredUnavailable',candidate.blocked_time,
    'outsideAvailableWindow',candidate.outside_available_window,
    'worksPreviousDay',candidate.works_previous_day,
    'worksNextDay',candidate.works_next_day,
    'previousShift',candidate.previous_shift,
    'nextShift',candidate.next_shift
  ) order by
    case when cardinality(candidate.hard_reasons)=0
      and cardinality(candidate.soft_reasons)=0 then 0
      when cardinality(candidate.hard_reasons)=0 then 1 else 2 end,
    candidate.monthly_minutes,candidate.last_name,candidate.first_name
  ),'[]'::jsonb) into v_candidates
  from classified candidate;

  return jsonb_build_object(
    'scheduleId',v_schedule.id,
    'issue',jsonb_build_object(
      'id',v_issue.id,'code',v_issue.issue_code,'message',v_issue.message,
      'slotKey',v_issue.slot_key,'roleId',v_issue.role_id,'dutyId',v_issue.duty_id
    ),
    'shift',jsonb_build_object(
      'id',v_shift.id,'slotGroupKey',v_shift.slot_group_key,
      'date',v_shift.shift_date,'startsAt',v_shift.starts_at,
      'endsAt',v_shift.ends_at,'locationId',v_shift.location_id,
      'shiftTemplateId',v_shift.shift_template_id,'shiftPeriod',v_shift_period
    ),
    'candidates',v_candidates,
    'summary',jsonb_build_object(
      'considered',jsonb_array_length(v_candidates),
      'eligible',(select count(*) from jsonb_array_elements(v_candidates) row
        where row.value->>'classification'='ELIGIBLE'),
      'warning',(select count(*) from jsonb_array_elements(v_candidates) row
        where row.value->>'classification'='WARNING'),
      'blocked',(select count(*) from jsonb_array_elements(v_candidates) row
        where row.value->>'classification'='BLOCKED')
    )
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.optimizer_candidate_diagnostics_before_role_scope_alpha16(p_schedule_id uuid, p_issue_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_payload jsonb;
  v_candidates jsonb:='[]'::jsonb;
  v_candidate jsonb;
  v_hard text[];
  v_soft text[];
  v_extra text[];
  v_shift_id uuid;
  v_matrix_version_id uuid;
  v_contract text;
  v_policy text;
  v_classification text;
  v_summary jsonb;
begin
  v_payload:=public.optimizer_candidate_diagnostics_before_primary_rules_alpha16(
    p_schedule_id,p_issue_id
  );
  select issue.shift_id,schedule.matrix_version_id
  into v_shift_id,v_matrix_version_id
  from public.plan_issues_v2 issue
  join public.published_schedules_v2 schedule on schedule.id=p_schedule_id
  where issue.id=p_issue_id;

  for v_candidate in
    select candidate.value
    from jsonb_array_elements(coalesce(v_payload->'candidates','[]'::jsonb)) candidate
  loop
    select coalesce(array_agg(reason),array[]::text[]) into v_hard
    from jsonb_array_elements_text(coalesce(v_candidate->'hardReasons','[]'::jsonb)) reason;
    select coalesce(array_agg(reason),array[]::text[]) into v_soft
    from jsonb_array_elements_text(coalesce(v_candidate->'softReasons','[]'::jsonb)) reason;
    select coalesce(hr.contract_type,'INNE'),coalesce(profile.work_time_policy,'CONTRACT_DEFAULT')
    into v_contract,v_policy
    from public.matrix_employee_profiles_v2 profile
    left join public.employee_hr_profiles hr on hr.employee_id=profile.employee_id
    where profile.matrix_version_id=v_matrix_version_id
      and profile.employee_id=(v_candidate->>'employeeId')::uuid;
    if v_contract in ('ZLECENIE','B2B') and v_policy<>'CUSTOM' then
      v_hard:=array_remove(v_hard,'MONTHLY_LIMIT');
      v_hard:=array_remove(v_hard,'WEEKLY_LIMIT');
      v_hard:=array_remove(v_hard,'MAX_CONSECUTIVE_DAYS');
      v_hard:=array_remove(v_hard,'REST_AFTER_PREVIOUS_SHIFT');
      v_hard:=array_remove(v_hard,'REST_BEFORE_NEXT_SHIFT');
      v_soft:=array_remove(v_soft,'OVERTIME_AFTER_ASSIGNMENT');
    end if;
    v_extra:=solver_private.schedule_primary_conflict_reasons_uat_v2(
      p_schedule_id,(v_candidate->>'employeeId')::uuid,v_shift_id
    );
    if 'ONE_PRIMARY_SHIFT_PER_DAY'=any(v_extra) then
      v_hard:=array_remove(v_hard,'SHIFT_OVERLAP');
    end if;
    select coalesce(array_agg(distinct reason order by reason),array[]::text[])
    into v_hard from unnest(v_hard||v_extra) reason;
    v_classification:=case
      when cardinality(v_hard)>0 then 'BLOCKED'
      when cardinality(v_soft)>0 then 'WARNING'
      else 'ELIGIBLE'
    end;
    v_candidate:=jsonb_set(v_candidate,'{hardReasons}',to_jsonb(v_hard),true);
    v_candidate:=jsonb_set(v_candidate,'{softReasons}',to_jsonb(v_soft),true);
    v_candidate:=jsonb_set(v_candidate,'{classification}',to_jsonb(v_classification),true);
    v_candidates:=v_candidates||jsonb_build_array(v_candidate);
  end loop;

  select jsonb_build_object(
    'considered',jsonb_array_length(v_candidates),
    'eligible',count(*) filter(where candidate.value->>'classification'='ELIGIBLE'),
    'warning',count(*) filter(where candidate.value->>'classification'='WARNING'),
    'blocked',count(*) filter(where candidate.value->>'classification'='BLOCKED')
  ) into v_summary
  from jsonb_array_elements(v_candidates) candidate;

  return jsonb_set(
    jsonb_set(v_payload,'{candidates}',v_candidates,true),
    '{summary}',v_summary,true
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.optimizer_checkpoint_v2(p_run_id uuid, p_expected_generation integer, p_checkpoint jsonb, p_metrics jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_generation integer;
begin
  if not public.can_manage_plans() then raise exception 'FORBIDDEN'; end if;
  update public.optimization_runs set
    checkpoint=coalesce(p_checkpoint,'{}'::jsonb),
    current_generation=current_generation+1,
    heartbeat_at=now(),
    result_summary=coalesce(result_summary,'{}'::jsonb)||coalesce(p_metrics,'{}'::jsonb)
      ||jsonb_build_object('phase','OPTIMIZING','progress',least(99,round(100.0*(current_generation+1)/greatest(target_generations,1))))
  where id=p_run_id and requested_by=auth.uid() and status='RUNNING'
    and current_generation=p_expected_generation
  returning current_generation into v_generation;
  if v_generation is null then raise exception 'STALE_OR_FORBIDDEN_CHECKPOINT'; end if;
  return jsonb_build_object('runId',p_run_id,'generation',v_generation);
end $function$;

CREATE OR REPLACE FUNCTION public.optimizer_commit(p_run_id uuid, p_name text, p_candidates jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r public.optimization_runs; best jsonb; c jsonb; a jsonb; plan_id uuid; shift_id uuid;
  plan_version integer; start_at timestamptz; end_at timestamptz; emp public.employees; loc public.locations;
  total_cost numeric:=0; assignment_count integer:=0; issue_count integer:=0; hard_count integer:=0;
begin
  if not public.can_manage_plans() then raise exception 'FORBIDDEN'; end if;
  select * into r from public.optimization_runs where id=p_run_id and requested_by=auth.uid() for update;
  if r.id is null or r.status<>'RUNNING' then raise exception 'OPTIMIZATION_RUN_NOT_WRITABLE'; end if;
  if jsonb_array_length(coalesce(p_candidates,'[]'::jsonb))=0 then raise exception 'NO_CANDIDATES'; end if;
  best:=p_candidates->0;
  if coalesce((best->>'hardViolations')::integer,0)>0 then raise exception 'BEST_CANDIDATE_HAS_HARD_VIOLATIONS'; end if;
  select coalesce(max(version),0)+1 into plan_version from public.plans where month=r.month;
  insert into public.plans(month,name,scenario_code,optimization_mode,staffing_level,status,version,score,total_cost,generated_at,created_by)
  values(r.month,coalesce(nullif(trim(p_name),''),'Plan optymalny '||to_char(r.month,'YYYY-MM')),r.scenario_code,
    (select code from public.optimizer_profiles where id=r.profile_id),'OPTIMAL','GENERATING',plan_version,
    (best->>'score')::numeric,0,now(),auth.uid()) returning id into plan_id;

  for a in select value from jsonb_array_elements(coalesce(best->'assignments','[]'::jsonb)) loop
    select * into emp from public.employees where id=(a->>'employeeId')::uuid and active and archived_at is null;
    select * into loc from public.locations where id=(a->>'locationId')::uuid and active;
    if emp.id is null or loc.id is null then raise exception 'INVALID_EMPLOYEE_OR_LOCATION'; end if;
    start_at:=(a->>'startsAt')::timestamptz; end_at:=(a->>'endsAt')::timestamptz;
    if end_at<=start_at or not exists(select 1 from public.employee_locations el where el.employee_id=emp.id and el.location_id=loc.id and (el.standard_allowed or el.overtime_allowed)) then raise exception 'HARD_CONSTRAINT_LOCATION_OR_TIME'; end if;
    if ((emp.employment_start is not null and (a->>'date')::date<emp.employment_start) or (emp.employment_end is not null and (a->>'date')::date>emp.employment_end)
      or (emp.no_weekends and extract(isodow from (a->>'date')::date) in (6,7))
      or (emp.only_morning and start_at::time>=time '15:00') or (emp.only_evening and start_at::time<time '14:00')) then raise exception 'HARD_CONSTRAINT_EMPLOYMENT_PATTERN'; end if;
    if not (emp.primary_role::text=a->>'role' or exists(select 1 from public.matrix_employee_roles mer join public.matrix_roles mr on mr.id=mer.role_id where mer.matrix_version_id=r.matrix_version_id and mer.employee_id=emp.id and mr.code=a->>'role')) then raise exception 'HARD_CONSTRAINT_ROLE'; end if;
    if nullif(a->>'function','') is not null and not exists(select 1 from public.employee_capabilities ec where ec.employee_id=emp.id and ec.active and ec.capability=a->>'function' and (ec.scope_role is null or ec.scope_role::text=a->>'role') and (ec.scope_location is null or ec.scope_location::text=loc.code::text)) then raise exception 'HARD_CONSTRAINT_CAPABILITY'; end if;
    if exists(select 1 from public.employee_availability av where av.employee_id=emp.id and av.work_date=(a->>'date')::date and (not av.available or (av.earliest_start is not null and start_at::time<av.earliest_start) or (av.latest_end is not null and end_at::time>av.latest_end))) then raise exception 'HARD_CONSTRAINT_AVAILABILITY'; end if;
    if exists(select 1 from public.assignments ax join public.shifts sx on sx.id=ax.shift_id where sx.plan_id=plan_id and ax.employee_id=emp.id and tstzrange(sx.starts_at,sx.ends_at,'[)') && tstzrange(start_at,end_at,'[)')) then raise exception 'HARD_CONSTRAINT_OVERLAP'; end if;
    if exists(select 1 from public.assignments ax join public.shifts sx on sx.id=ax.shift_id where sx.plan_id=plan_id and ax.employee_id=emp.id and tstzrange(sx.starts_at-coalesce(emp.minimum_rest_minutes,660)*interval '1 minute',sx.ends_at+coalesce(emp.minimum_rest_minutes,660)*interval '1 minute','[)') && tstzrange(start_at,end_at,'[)')) then raise exception 'HARD_CONSTRAINT_REST'; end if;
    if coalesce((select sum(public.shift_minutes(sx.starts_at,sx.ends_at)) from public.assignments ax join public.shifts sx on sx.id=ax.shift_id where sx.plan_id=plan_id and ax.employee_id=emp.id),0)+public.shift_minutes(start_at,end_at)>coalesce(emp.max_monthly_minutes,emp.monthly_nominal_minutes) then raise exception 'HARD_CONSTRAINT_MONTHLY_LIMIT'; end if;
    if coalesce((select sum(public.shift_minutes(sx.starts_at,sx.ends_at)) from public.assignments ax join public.shifts sx on sx.id=ax.shift_id where sx.plan_id=plan_id and ax.employee_id=emp.id and date_trunc('week',sx.shift_date::timestamp)=date_trunc('week',(a->>'date')::date::timestamp)),0)+public.shift_minutes(start_at,end_at)>emp.max_weekly_minutes then raise exception 'HARD_CONSTRAINT_WEEKLY_LIMIT'; end if;
    select s.id into shift_id from public.shifts s where s.plan_id=plan_id and s.location_id=loc.id and s.shift_date=(a->>'date')::date and s.shift_code=a->>'shiftCode';
    if shift_id is null then insert into public.shifts(plan_id,location_id,shift_date,shift_code,starts_at,ends_at,status) values(plan_id,loc.id,(a->>'date')::date,a->>'shiftCode',start_at,end_at,'PLANNED') returning id into shift_id; end if;
    insert into public.assignments(shift_id,employee_id,assigned_role,assigned_capability,cost,explanation)
    values(shift_id,emp.id,(a->>'role')::public.employee_role,nullif(a->>'function',''),round(emp.hourly_rate*public.shift_minutes(start_at,end_at)/60,2),jsonb_build_object('engine','ALPHA_13_GA','runId',r.id,'slotId',a->>'slotId'));
    total_cost:=total_cost+round(emp.hourly_rate*public.shift_minutes(start_at,end_at)/60,2); assignment_count:=assignment_count+1;
  end loop;

  for c in select value from jsonb_array_elements(p_candidates) loop
    insert into public.optimization_candidates(run_id,rank,score,hard_violations,metrics,assignments,selected)
    values(r.id,(c->>'rank')::integer,(c->>'score')::numeric,coalesce((c->>'hardViolations')::integer,0),coalesce(c->'metrics','{}'::jsonb),coalesce(c->'assignments','[]'::jsonb),(c->>'rank')::integer=1);
  end loop;
  for c in select value from jsonb_array_elements(coalesce(best->'unfilled','[]'::jsonb)) loop
    insert into public.plan_issues(plan_id,issue_type,severity,role,capability,required_count,assigned_count,message)
    values(plan_id,case when nullif(c->>'function','') is null then 'SHORTAGE' else 'CAPABILITY_MISSING' end,'CRITICAL',(c->>'role')::public.employee_role,nullif(c->>'function',''),1,0,
      'Nierozwiązywalny brak: '||(c->>'role')||coalesce(' / '||nullif(c->>'function',''),'')||' • '||(c->>'date')||' • '||(c->>'shiftCode'));
    issue_count:=issue_count+1;
  end loop;
  update public.plans set status='READY',total_cost=total_cost,generated_at=now() where id=plan_id;
  update public.optimization_runs set status=case when issue_count=0 then 'SUCCEEDED' else 'INFEASIBLE' end,finished_at=now(),
    result_summary=jsonb_build_object('planId',plan_id,'score',best->'score','assignments',assignment_count,'unfilled',issue_count,'alternatives',jsonb_array_length(p_candidates),'cost',total_cost)
    where id=r.id;
  insert into public.audit_log(actor_id,entity_type,entity_id,action,new_data) values(auth.uid(),'optimization_run',r.id::text,'COMMIT',(select result_summary from public.optimization_runs where id=r.id));
  return jsonb_build_object('plan_id',plan_id,'run_id',r.id,'status',case when issue_count=0 then 'READY' else 'READY_WITH_EXCEPTIONS' end,'assignments',assignment_count,'issues',issue_count,'total_cost',total_cost,'score',best->'score','alternatives',jsonb_array_length(p_candidates));
exception when others then
  if r.id is not null then update public.optimization_runs set status='FAILED',finished_at=now(),failure_message=sqlerrm where id=r.id; end if;
  raise;
end $function$;

CREATE OR REPLACE FUNCTION public.optimizer_complete_finalize_v4(p_run_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  r public.optimization_runs;
  v_variants jsonb;
  v_winner jsonb;
  v_status text;
begin
  if not public.can_manage_plans() then raise exception 'FORBIDDEN'; end if;
  select * into r from public.optimization_runs
    where id=p_run_id and requested_by=auth.uid() for update;
  if r.id is null or r.status<>'RUNNING' or r.result_summary->>'phase'<>'FINALIZING'
    or coalesce((r.checkpoint->>'finalizeCursor')::integer,0)<>3
    or (select count(*) from public.optimization_candidates c
      where c.run_id=r.id and c.plan_id is not null)<>3
  then raise exception 'FINALIZATION_INCOMPLETE'; end if;

  update public.plans p set status='READY',generated_at=now()
  where p.id in (select c.plan_id from public.optimization_candidates c where c.run_id=r.id);

  select jsonb_agg(jsonb_build_object(
    'planId',p.id,'rank',c.rank,'score',c.score,
    'assignments',jsonb_array_length(c.assignments),
    'unfilled',coalesce((c.metrics->>'unfilled')::integer,0),
    'alertGroups',(select count(*) from public.plan_issues pi where pi.plan_id=p.id and pi.resolved_at is null),
    'totalCost',p.total_cost,'metrics',c.metrics
  ) order by c.rank) into v_variants
  from public.optimization_candidates c join public.plans p on p.id=c.plan_id
  where c.run_id=r.id;
  select x into v_winner from jsonb_array_elements(v_variants) x where (x->>'rank')::integer=1;
  v_status:=case when coalesce((v_winner->>'unfilled')::integer,0)=0 then 'SUCCEEDED' else 'INFEASIBLE' end;

  update public.optimization_runs set
    status=v_status,finished_at=now(),heartbeat_at=now(),
    result_summary=jsonb_build_object(
      'phase','DONE','progress',100,'ranking','LEXICOGRAPHIC','engineVersion','ALPHA_15_V4',
      'planId',v_winner->'planId','score',v_winner->'score',
      'assignments',v_winner->'assignments','unfilled',v_winner->'unfilled',
      'alertGroups',v_winner->'alertGroups','alternatives',3,
      'cost',v_winner->'totalCost','variants',v_variants,
      'baselineRanking',r.checkpoint->'baselineRanking')
  where id=r.id;
  insert into public.audit_log(actor_id,entity_type,entity_id,action,new_data)
  values(auth.uid(),'optimization_run',r.id::text,'COMMIT_V4',
    (select result_summary from public.optimization_runs where id=r.id));

  return jsonb_build_object(
    'plan_id',v_winner->'planId','run_id',r.id,
    'status',case when v_status='SUCCEEDED' then 'READY' else 'READY_WITH_EXCEPTIONS' end,
    'assignments',v_winner->'assignments','issues',v_winner->'unfilled',
    'alerts',v_winner->'alertGroups','total_cost',v_winner->'totalCost',
    'score',v_winner->'score','alternatives',3,'variants',v_variants,
    'engineVersion','ALPHA_15_V4','baselineRanking',r.checkpoint->'baselineRanking');
end $function$;

CREATE OR REPLACE FUNCTION public.optimizer_configuration_v2(p_month date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_month date:=date_trunc('month',p_month)::date;
  v_period_end date:=(date_trunc('month',p_month)+interval '1 month - 1 day')::date;
  v_engine text;
  v_enabled boolean;
  v_solver_version text;
  v_matrix public.matrix_versions%rowtype;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  if p_month is null then raise exception 'MONTH_REQUIRED'; end if;
  select flag.engine,flag.enabled,nullif(trim(flag.config->>'solverVersion'),'')
  into v_engine,v_enabled,v_solver_version
  from public.solver_feature_flags flag
  where flag.flag_key='DEFAULT_ENGINE';
  if v_engine is null then raise exception 'SOLVER_ENGINE_CONFIGURATION_MISSING'; end if;
  if not coalesce(v_enabled,false) then raise exception 'SOLVER_DISABLED'; end if;
  if v_engine not in ('ALPHA15','SHADOW','ORTOOLS_V2') then
    raise exception 'SOLVER_ENGINE_CONFIGURATION_INVALID';
  end if;
  if v_engine='ALPHA15' then
    return jsonb_build_object('engine',v_engine,'enabled',true);
  end if;
  if length(coalesce(v_solver_version,'')) not between 1 and 200 then
    raise exception 'SOLVER_VERSION_CONFIGURATION_REQUIRED';
  end if;

  select * into v_matrix
  from public.matrix_versions matrix_version
  where matrix_version.status in ('ACTIVE','ARCHIVED')
    and matrix_version.schema_version>=2
    and solver_private.matrix_covers_planning_month_uat_v1(matrix_version.effective_from,v_month)
    and coalesce(matrix_version.content_hash,'') ~ '^[0-9a-f]{64}$'
    and coalesce(matrix_version.workforce_hash,'') ~ '^[0-9a-f]{64}$'
  order by matrix_version.effective_from desc,matrix_version.version desc
  limit 1;
  if v_matrix.id is null then raise exception 'MATRIX_V2_FOR_MONTH_NOT_FOUND'; end if;

  return jsonb_build_object(
    'engine',v_engine,'enabled',true,'solverVersion',v_solver_version,
    'matrixVersion',jsonb_build_object(
      'id',v_matrix.id,'schemaVersion',v_matrix.schema_version,
      'effectiveFrom',v_matrix.effective_from,'settings',v_matrix.settings,
      'contentHash',v_matrix.content_hash,'workforceHash',v_matrix.workforce_hash
    ),
    'scenarios',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',scenario.id,'code',scenario.code,'name',scenario.name,
        'description',scenario.description,'isDefault',scenario.is_default,
        'sortOrder',scenario.sort_order,'parentScenarioId',scenario.parent_scenario_id,
        'available',(
          (scenario.valid_from is null or scenario.valid_from<=v_period_end)
          and (scenario.valid_to is null or scenario.valid_to>=v_month)
        )
      ) order by scenario.sort_order,scenario.name)
      from public.matrix_scenarios_v2 scenario
      where scenario.matrix_version_id=v_matrix.id and scenario.active
    ),'[]'::jsonb),
    'roles',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',role_row.id,'code',role_row.code,'name',role_row.name,
        'sortOrder',role_row.sort_order
      ) order by role_row.sort_order,role_row.name)
      from public.matrix_roles_v2 role_row
      where role_row.matrix_version_id=v_matrix.id and role_row.active
    ),'[]'::jsonb),
    'locations',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',location_row.id,'code',location_row.code,'name',location_row.name,
        'sortOrder',location_row.sort_order,'timezone',location_row.timezone
      ) order by location_row.sort_order,location_row.name)
      from public.matrix_locations_v2 location_row
      where location_row.matrix_version_id=v_matrix.id and location_row.active
    ),'[]'::jsonb),
    'strategies',coalesce((
      select jsonb_agg(jsonb_build_object('id',strategy.id) order by strategy.id)
      from public.matrix_strategies_v2 strategy
      where strategy.matrix_version_id=v_matrix.id and strategy.active
    ),'[]'::jsonb),
    'scenarioStrategies',coalesce((
      select jsonb_agg(jsonb_build_object(
        'scenarioId',link.scenario_id,'strategyId',link.strategy_id,
        'active',link.active
      ) order by link.scenario_id,link.sort_order,link.id)
      from public.matrix_scenario_strategies_v2 link
      where link.matrix_version_id=v_matrix.id
    ),'[]'::jsonb)
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.optimizer_create_leader_variant_uat_v1(p_run_id uuid, p_source_variant_id uuid, p_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid:=auth.uid();
  v_source public.plan_variants_v2%rowtype;
  v_run public.optimization_runs_v2%rowtype;
  v_id uuid:=gen_random_uuid();
  v_name text:=trim(coalesce(p_name,''));
begin
  if v_actor is null then raise exception 'AUTH_REQUIRED'; end if;
  if length(v_name) not between 1 and 200 then raise exception 'INVALID_PLAN_NAME'; end if;
  perform pg_advisory_xact_lock(hashtextextended('leader-copy:'||p_run_id::text,0));
  select * into v_run from public.optimization_runs_v2 where id=p_run_id for update;
  select * into v_source from public.plan_variants_v2
    where id=p_source_variant_id and run_id=p_run_id and variant_kind='GENERATED'
    for update;
  if v_run.id is null or v_source.id is null then raise exception 'VARIANT_NOT_FOUND'; end if;
  if v_run.status<>'READY' or v_source.status not in ('READY','SELECTED','PUBLISHED')
    or v_source.hard_violations<>0 then raise exception 'VALID_GENERATED_VARIANT_REQUIRED'; end if;
  if not (
    public.has_app_role('OWNER') or public.has_app_role('ADMIN')
    or (v_run.scope_type='ROLE' and exists(
      select 1 from public.matrix_scope_grants_v2 grant_row
      join public.matrix_roles_v2 role on role.id=v_run.scope_role_id
      where grant_row.auth_user_id=v_actor and grant_row.active
        and grant_row.app_role='ROLE_MANAGER'
        and (grant_row.role_logical_id is null or grant_row.role_logical_id=role.logical_id)
    ))
  ) then raise exception 'LEADER_VARIANT_FORBIDDEN'; end if;

  update public.plan_variants_v2
    set status='ARCHIVED',selected=false
    where run_id=p_run_id and variant_kind='LEADER_COPY'
      and status in ('READY','SELECTED');
  update public.plan_variants_v2
    set selected=false,status=case when status='SELECTED' then 'READY' else status end
    where run_id=p_run_id and variant_kind='GENERATED';

  insert into public.plan_variants_v2(
    id,run_id,run_strategy_id,strategy_id,name,status,hard_violations,
    assignment_count,unfilled_count,solver_status,solution_hash,objective_bound,
    metrics,recommended,selected,equivalent_to_variant_id,snapshot_hash,
    selected_at,selected_by,variant_kind,source_variant_id,revision,last_edited_at,last_edited_by
  ) values(
    v_id,v_source.run_id,v_source.run_strategy_id,v_source.strategy_id,v_name,
    'SELECTED',0,v_source.assignment_count,v_source.unfilled_count,
    v_source.solver_status,v_source.solution_hash,v_source.objective_bound,
    v_source.metrics||jsonb_build_object('leaderCopy',true),false,true,
    v_source.equivalent_to_variant_id,v_source.snapshot_hash,now(),v_actor,
    'LEADER_COPY',v_source.id,0,now(),v_actor
  );

  insert into public.plan_shifts_v2(
    id,variant_id,slot_group_key,shift_template_id,location_id,shift_date,
    starts_at,ends_at,source_type,source_id,created_at
  )
  select public.matrix_v2_stable_uuid('LEADER_SHIFT:'||v_id::text||':'||source.id::text),
    v_id,source.slot_group_key,source.shift_template_id,source.location_id,
    source.shift_date,source.starts_at,source.ends_at,source.source_type,
    source.source_id,now()
  from public.plan_shifts_v2 source where source.variant_id=v_source.id;

  insert into public.plan_assignments_v2(
    id,variant_id,shift_id,slot_key,employee_id,role_id,locked,explanation,created_at
  )
  select public.matrix_v2_stable_uuid('LEADER_ASSIGNMENT:'||v_id::text||':'||source.id::text),
    v_id,public.matrix_v2_stable_uuid('LEADER_SHIFT:'||v_id::text||':'||source.shift_id::text),
    source.slot_key,source.employee_id,source.role_id,source.locked,
    coalesce(source.explanation,'{}'::jsonb)||jsonb_build_object(
      'sourceVariantId',v_source.id,'sourceAssignmentId',source.id,'edited',false
    ),now()
  from public.plan_assignments_v2 source where source.variant_id=v_source.id;

  insert into public.plan_assignment_duties_v2(assignment_id,duty_id)
  select public.matrix_v2_stable_uuid('LEADER_ASSIGNMENT:'||v_id::text||':'||source.id::text),duty.duty_id
  from public.plan_assignments_v2 source
  join public.plan_assignment_duties_v2 duty on duty.assignment_id=source.id
  where source.variant_id=v_source.id;

  insert into public.plan_issues_v2(
    variant_id,shift_id,slot_key,issue_code,severity,role_id,duty_id,
    required_count,assigned_count,message,metadata,created_at
  )
  select v_id,
    case when source.shift_id is null then null else
      public.matrix_v2_stable_uuid('LEADER_SHIFT:'||v_id::text||':'||source.shift_id::text) end,
    source.slot_key,source.issue_code,source.severity,source.role_id,source.duty_id,
    source.required_count,source.assigned_count,source.message,
    coalesce(source.metadata,'{}'::jsonb)||jsonb_build_object('sourceIssueId',source.id),now()
  from public.plan_issues_v2 source where source.variant_id=v_source.id;

  insert into solver_private.plan_assignment_cost_components_v2(
    assignment_id,pay_rule_id,component_code,amount_minor,quantity_minutes,
    calculation_basis,created_at
  )
  select public.matrix_v2_stable_uuid('LEADER_ASSIGNMENT:'||v_id::text||':'||assignment.id::text),
    component.pay_rule_id,component.component_code,component.amount_minor,
    component.quantity_minutes,component.calculation_basis,now()
  from public.plan_assignments_v2 assignment
  join solver_private.plan_assignment_cost_components_v2 component
    on component.assignment_id=assignment.id
  where assignment.variant_id=v_source.id;

  insert into solver_private.plan_variant_finance_v2(
    variant_id,base_cost_units,additions_cost_units,total_cost_units,
    base_cost_minor,additions_cost_minor,total_cost_minor,currency,budget_minor,
    hard_budget_exceeded,breakdown
  )
  select v_id,finance.base_cost_units,finance.additions_cost_units,finance.total_cost_units,
    finance.base_cost_minor,finance.additions_cost_minor,finance.total_cost_minor,
    finance.currency,finance.budget_minor,finance.hard_budget_exceeded,
    finance.breakdown||jsonb_build_object('sourceVariantId',v_source.id)
  from solver_private.plan_variant_finance_v2 finance where finance.variant_id=v_source.id;

  insert into public.audit_log(actor_id,entity_type,entity_id,action,new_data)
  values(v_actor,'plan_variant_v2',v_id::text,'CREATE_LEADER_COPY',
    jsonb_build_object('runId',p_run_id,'sourceVariantId',v_source.id,'name',v_name));
  return jsonb_build_object('variantId',v_id,'sourceVariantId',v_source.id,
    'name',v_name,'revision',0,'variantKind','LEADER_COPY');
end;
$function$;

CREATE OR REPLACE FUNCTION public.optimizer_create_manual_leader_studio_uat_v1(p_month date, p_scenario_id uuid, p_scope_type text, p_scope_role_id uuid, p_name text, p_solver_version text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid();v_month date:=date_trunc('month',p_month)::date;v_matrix_id uuid;v_run_id uuid:=gen_random_uuid();v_variant_id uuid:=gen_random_uuid();v_snapshot jsonb;v_snapshot_hash text;v_solution_hash text;v_strategy_id uuid;v_run_strategy_id uuid;v_name text:=trim(coalesce(p_name,''));v_unfilled integer;v_currency text;
begin
if v_actor is null then raise exception 'AUTH_REQUIRED';end if;
if p_scope_type not in ('COMPANY','ROLE') then raise exception 'INVALID_SCOPE_TYPE';end if;
if (p_scope_type='ROLE') is distinct from (p_scope_role_id is not null) then raise exception 'INVALID_SCOPE_ROLE';end if;
if length(v_name) not between 1 and 200 then raise exception 'INVALID_PLAN_NAME';end if;
if length(trim(coalesce(p_solver_version,''))) not between 1 and 200 then raise exception 'INVALID_SOLVER_VERSION';end if;
select version.id into v_matrix_id from public.matrix_versions version where version.status in ('ACTIVE','ARCHIVED') and version.schema_version>=2 and version.effective_from<=v_month and coalesce(version.content_hash,'')~'^[0-9a-f]{64}$' and coalesce(version.workforce_hash,'')~'^[0-9a-f]{64}$' order by version.effective_from desc,version.version desc limit 1;
if v_matrix_id is null then raise exception 'MATRIX_V2_FOR_MONTH_NOT_FOUND';end if;
if not exists(select 1 from public.matrix_scenarios_v2 scenario where scenario.id=p_scenario_id and scenario.matrix_version_id=v_matrix_id and scenario.active) then raise exception 'SCENARIO_NOT_FOUND';end if;
if p_scope_type='COMPANY' and not(public.has_app_role('OWNER') or public.has_app_role('ADMIN')) then raise exception 'COMPANY_SCOPE_FORBIDDEN';end if;
if p_scope_type='ROLE' and not(public.has_app_role('OWNER') or public.has_app_role('ADMIN') or exists(select 1 from public.matrix_scope_grants_v2 grant_row join public.matrix_roles_v2 role on role.id=p_scope_role_id where grant_row.auth_user_id=v_actor and grant_row.active and grant_row.app_role='ROLE_MANAGER' and(grant_row.role_logical_id is null or grant_row.role_logical_id=role.logical_id))) then raise exception 'ROLE_SCOPE_FORBIDDEN';end if;
v_snapshot:=solver_private.build_snapshot_payload_v2(v_run_id,v_month,v_matrix_id,p_scenario_id,p_scope_type,p_scope_role_id);
select(strategy.value->>'id')::uuid into v_strategy_id from jsonb_array_elements(coalesce(v_snapshot->'strategies','[]'::jsonb)) with ordinality strategy(value,ordinality) order by strategy.ordinality limit 1;
if v_strategy_id is null then raise exception 'SNAPSHOT_HAS_NO_STRATEGIES';end if;
v_unfilled:=jsonb_array_length(coalesce(v_snapshot->'slots','[]'::jsonb));v_currency:=coalesce(nullif(v_snapshot->>'currency',''),'PLN');
v_snapshot_hash:=encode(extensions.digest(convert_to(solver_private.canonical_json_v2(v_snapshot),'UTF8'),'sha256'),'hex');
v_solution_hash:=encode(extensions.digest(convert_to(solver_private.canonical_json_v2(jsonb_build_object('assignments','[]'::jsonb,'unfilledSlotIds',coalesce((select jsonb_agg(slot.value->>'slotId' order by slot.ordinality) from jsonb_array_elements(coalesce(v_snapshot->'slots','[]'::jsonb)) with ordinality slot(value,ordinality)),'[]'::jsonb))),'UTF8'),'sha256'),'hex');
insert into public.optimization_runs_v2(id,idempotency_key,month,matrix_version_id,scenario_id,scope_type,scope_role_id,name,status,phase,progress,requested_by,snapshot_hash,request_engine,solver_version,finished_at) values(v_run_id,'manual-studio-'||v_run_id::text,v_month,v_matrix_id,p_scenario_id,p_scope_type,p_scope_role_id,v_name,'READY','MANUAL_STUDIO',100,v_actor,v_snapshot_hash,'ORTOOLS_V2',trim(p_solver_version),now());
insert into public.optimization_run_strategies_v2(run_id,strategy_id,ordinal,status,phase,progress,metrics,started_at,finished_at) values(v_run_id,v_strategy_id,1,'READY','MANUAL_STUDIO',100,jsonb_build_object('manualStudio',true),now(),now()) returning id into v_run_strategy_id;
insert into solver_private.optimization_snapshots_v2(run_id,schema_version,snapshot_hash,snapshot) values(v_run_id,2,v_snapshot_hash,v_snapshot);
insert into public.plan_variants_v2(id,run_id,run_strategy_id,strategy_id,name,status,hard_violations,assignment_count,unfilled_count,solver_status,solution_hash,metrics,recommended,selected,snapshot_hash,selected_at,selected_by,variant_kind,revision,last_edited_at,last_edited_by) values(v_variant_id,v_run_id,v_run_strategy_id,v_strategy_id,v_name,'SELECTED',0,0,v_unfilled,'FEASIBLE',v_solution_hash,jsonb_build_object('manualStudio',true,'UNFILLED',v_unfilled),false,true,v_snapshot_hash,now(),v_actor,'LEADER_COPY',0,now(),v_actor);
insert into public.plan_shifts_v2(variant_id,slot_group_key,shift_template_id,location_id,shift_date,starts_at,ends_at,source_type,source_id) select distinct on(slot.value->>'occurrenceId') v_variant_id,slot.value->>'occurrenceId',(slot.value->>'shiftTemplateId')::uuid,(slot.value->>'locationId')::uuid,(slot.value->>'date')::date,(slot.value->>'start')::timestamptz,(slot.value->>'end')::timestamptz,'MATRIX',nullif(slot.value->>'demandId','')::uuid from jsonb_array_elements(coalesce(v_snapshot->'slots','[]'::jsonb)) slot(value) order by slot.value->>'occurrenceId',slot.value->>'slotId';
insert into public.plan_issues_v2(variant_id,shift_id,slot_key,issue_code,severity,role_id,duty_id,required_count,assigned_count,message,metadata) select v_variant_id,shift.id,slot.value->>'slotId','UNFILLED_SLOT','WARNING',(slot.value->>'roleId')::uuid,case when jsonb_array_length(coalesce(slot.value->'dutyIds','[]'::jsonb))=1 then(slot.value->'dutyIds'->>0)::uuid else null end,1,0,'Miejsce oczekuje na ręczną obsadę w Studio lidera.',jsonb_build_object('manualStudio',true,'demandId',slot.value->>'demandId') from jsonb_array_elements(coalesce(v_snapshot->'slots','[]'::jsonb)) slot(value) join public.plan_shifts_v2 shift on shift.variant_id=v_variant_id and shift.slot_group_key=slot.value->>'occurrenceId';
insert into solver_private.plan_variant_finance_v2(variant_id,base_cost_units,additions_cost_units,total_cost_units,base_cost_minor,additions_cost_minor,total_cost_minor,currency,budget_minor,hard_budget_exceeded,breakdown) values(v_variant_id,0,0,0,0,0,0,v_currency,null,false,jsonb_build_object('manualStudio',true,'currency',v_currency));
insert into public.audit_log(actor_id,entity_type,entity_id,action,new_data) values(v_actor,'plan_variant_v2',v_variant_id::text,'CREATE_MANUAL_LEADER_STUDIO',jsonb_build_object('runId',v_run_id,'month',v_month,'scopeType',p_scope_type,'scopeRoleId',p_scope_role_id,'scenarioId',p_scenario_id,'unfilledCount',v_unfilled));
return jsonb_build_object('runId',v_run_id,'variantId',v_variant_id,'name',v_name,'revision',0,'assignmentCount',0,'unfilledCount',v_unfilled);
end;$function$;

CREATE OR REPLACE FUNCTION public.optimizer_demand_profiles_uat_v1(p_month date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_month date:=date_trunc('month',p_month)::date;
  v_matrix_id uuid;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  select matrix_version.id into v_matrix_id
  from public.matrix_versions matrix_version
  where matrix_version.status in ('ACTIVE','ARCHIVED')
    and matrix_version.schema_version>=2
    and solver_private.matrix_covers_planning_month_uat_v1(matrix_version.effective_from,v_month)
    and coalesce(matrix_version.content_hash,'') ~ '^[0-9a-f]{64}$'
    and coalesce(matrix_version.workforce_hash,'') ~ '^[0-9a-f]{64}$'
  order by matrix_version.effective_from desc,matrix_version.version desc limit 1;
  if v_matrix_id is null then raise exception 'MATRIX_V2_FOR_MONTH_NOT_FOUND'; end if;
  return jsonb_build_object('matrixVersionId',v_matrix_id,'profiles',coalesce((
    select jsonb_agg(jsonb_build_object(
      'id',scenario.id,'validFrom',scenario.valid_from,'validTo',scenario.valid_to,
      'profileMode',case
        when scenario.is_default then 'BASELINE'
        when scenario.valid_from is not null or scenario.valid_to is not null then 'PERIOD'
        else 'UNDATED_LEGACY' end
    ) order by scenario.sort_order,scenario.name)
    from public.matrix_scenarios_v2 scenario
    where scenario.matrix_version_id=v_matrix_id and scenario.active
  ),'[]'::jsonb));
end;
$function$;

CREATE OR REPLACE FUNCTION public.optimizer_emergency_assign_alpha16(p_schedule_id uuid, p_issue_id bigint, p_employee_id uuid, p_allow_soft boolean DEFAULT false, p_reason text DEFAULT NULL::text, p_notify boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_diagnostics jsonb;
  v_candidate jsonb;
  v_issue public.plan_issues_v2%rowtype;
  v_id uuid;
  v_class text;
  v_auth_user uuid;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  if not solver_private.alpha16_can_manage_schedule_v2(p_schedule_id) then
    raise exception 'FORBIDDEN';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(
    'operational-v2:'||p_schedule_id::text||':'||p_issue_id::text,0
  ));
  v_diagnostics:=public.optimizer_candidate_diagnostics_alpha16(
    p_schedule_id,p_issue_id
  );
  select candidate.value into v_candidate
  from jsonb_array_elements(v_diagnostics->'candidates') candidate
  where candidate.value->>'employeeId'=p_employee_id::text;
  if v_candidate is null then raise exception 'CANDIDATE_NOT_FOUND'; end if;
  v_class:=v_candidate->>'classification';
  if v_class='BLOCKED' then
    raise exception 'EMERGENCY_ASSIGNMENT_HARD_BLOCK:%',
      coalesce(v_candidate->'hardReasons','[]'::jsonb)::text;
  end if;
  if v_class='WARNING' and (
    not coalesce(p_allow_soft,false)
    or length(trim(coalesce(p_reason,'')))<3
  ) then raise exception 'SOFT_OVERRIDE_REASON_REQUIRED'; end if;
  select issue.* into v_issue from public.plan_issues_v2 issue
  where issue.id=p_issue_id;
  if exists(select 1 from public.operational_assignment_overrides_v2 existing
    where existing.schedule_id=p_schedule_id and existing.slot_key=v_issue.slot_key
      and existing.status='ACTIVE') then raise exception 'SLOT_ALREADY_FILLED'; end if;
  insert into public.operational_assignment_overrides_v2(
    schedule_id,issue_id,shift_id,slot_key,employee_id,role_id,
    assignment_class,override_reason,notify_employee,created_by
  ) values(
    p_schedule_id,p_issue_id,v_issue.shift_id,v_issue.slot_key,p_employee_id,
    v_issue.role_id,case when v_class='WARNING' then 'SOFT_OVERRIDE' else 'ELIGIBLE' end,
    case when v_class='WARNING' then trim(p_reason) else null end,
    coalesce(p_notify,false),auth.uid()
  ) returning id into v_id;
  select employee.auth_user_id into v_auth_user
  from public.employees employee where employee.id=p_employee_id;
  if coalesce(p_notify,false) and v_auth_user is not null then
    insert into public.notifications(recipient_id,channel,title,body)
    values(v_auth_user,'IN_APP','Awaryjna zmiana',
      'Dopisano Cię do zmiany dnia '||
      (v_diagnostics->'shift'->>'date')||'.');
  end if;
  insert into public.audit_log(actor_id,entity_type,entity_id,action,new_data)
  values(auth.uid(),'operational_assignment_override_v2',v_id::text,'CREATE',
    jsonb_build_object(
      'scheduleId',p_schedule_id,'issueId',p_issue_id,
      'employeeId',p_employee_id,'classification',v_class,
      'reason',case when v_class='WARNING' then trim(p_reason) else null end,
      'notified',coalesce(p_notify,false) and v_auth_user is not null
    ));
  return jsonb_build_object(
    'id',v_id,'scheduleId',p_schedule_id,'issueId',p_issue_id,
    'employeeId',p_employee_id,'classification',v_class,
    'notified',coalesce(p_notify,false) and v_auth_user is not null
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.optimizer_employee_availability_month_uat_v1(p_variant_id uuid, p_employee_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_run public.optimization_runs_v2%rowtype;v_default_available boolean:=true;
  v_timezone text;
begin
  select run.* into v_run from public.plan_variants_v2 variant
    join public.optimization_runs_v2 run on run.id=variant.run_id where variant.id=p_variant_id;
  if v_run.id is null or not solver_private.can_access_run_v2(v_run.id) then raise exception 'VARIANT_NOT_FOUND'; end if;
  if coalesce(array_length(p_employee_ids,1),0)=0 or array_length(p_employee_ids,1)>2 then
    raise exception 'ONE_OR_TWO_EMPLOYEES_REQUIRED';end if;
  select coalesce((settings->>'missingAvailabilityMeansAvailable')::boolean,true),
    coalesce(nullif(settings->>'timezone',''),'UTC')
    into v_default_available,v_timezone from public.matrix_versions where id=v_run.matrix_version_id;
  return coalesce((select jsonb_agg(jsonb_build_object(
    'employeeId',employee.id,'date',day_value.day_date::date,'scheduled',exists(
      select 1 from public.plan_assignments_v2 assignment join public.plan_shifts_v2 shift on shift.id=assignment.shift_id
      where assignment.variant_id=p_variant_id and assignment.employee_id=employee.id and shift.shift_date=day_value.day_date),
    'status',case
      when exists(select 1 from public.employee_time_constraints_v2 constraint_row
        where constraint_row.employee_id=employee.id and constraint_row.status='ACTIVE'
          and constraint_row.constraint_kind in ('UNAVAILABLE','LEAVE','SICKNESS')
          and (lower(constraint_row.time_range) at time zone v_timezone)::date<=day_value.day_date
          and ((upper(constraint_row.time_range)-interval '1 microsecond') at time zone v_timezone)::date>=day_value.day_date) then 'HARD_UNAVAILABLE'
      when exists(select 1 from public.employee_time_constraints_v2 constraint_row
        where constraint_row.employee_id=employee.id and constraint_row.status='ACTIVE'
          and constraint_row.constraint_kind='PREFER_NOT_TO_WORK'
          and (lower(constraint_row.time_range) at time zone v_timezone)::date<=day_value.day_date
          and ((upper(constraint_row.time_range)-interval '1 microsecond') at time zone v_timezone)::date>=day_value.day_date) then 'SOFT_AVOID'
      when exists(select 1 from public.employee_time_constraints_v2 constraint_row
        where constraint_row.employee_id=employee.id and constraint_row.status='ACTIVE'
          and constraint_row.constraint_kind='AVAILABLE_WINDOW'
          and (lower(constraint_row.time_range) at time zone v_timezone)::date<=day_value.day_date
          and ((upper(constraint_row.time_range)-interval '1 microsecond') at time zone v_timezone)::date>=day_value.day_date) then 'AVAILABLE_WINDOW'
      when v_default_available then 'DEFAULT_AVAILABLE' else 'NO_AVAILABLE_WINDOW' end,
    'label',case
      when exists(select 1 from public.employee_time_constraints_v2 constraint_row
        where constraint_row.employee_id=employee.id and constraint_row.status='ACTIVE'
          and constraint_row.constraint_kind in ('UNAVAILABLE','LEAVE','SICKNESS')
          and (lower(constraint_row.time_range) at time zone v_timezone)::date<=day_value.day_date
          and ((upper(constraint_row.time_range)-interval '1 microsecond') at time zone v_timezone)::date>=day_value.day_date) then 'Nie może pracować'
      when exists(select 1 from public.employee_time_constraints_v2 constraint_row
        where constraint_row.employee_id=employee.id and constraint_row.status='ACTIVE'
          and constraint_row.constraint_kind='PREFER_NOT_TO_WORK'
          and (lower(constraint_row.time_range) at time zone v_timezone)::date<=day_value.day_date
          and ((upper(constraint_row.time_range)-interval '1 microsecond') at time zone v_timezone)::date>=day_value.day_date) then 'Woli nie pracować'
      when exists(select 1 from public.employee_time_constraints_v2 constraint_row
        where constraint_row.employee_id=employee.id and constraint_row.status='ACTIVE'
          and constraint_row.constraint_kind='AVAILABLE_WINDOW'
          and (lower(constraint_row.time_range) at time zone v_timezone)::date<=day_value.day_date
          and ((upper(constraint_row.time_range)-interval '1 microsecond') at time zone v_timezone)::date>=day_value.day_date) then 'Dostępny w podanych godzinach'
      when v_default_available then 'Dostępny domyślnie' else 'Brak zgłoszonego okna' end
  ) order by employee.id,day_value.day_date) from public.employees employee
  cross join lateral generate_series(v_run.month,(v_run.month+interval '1 month'-interval '1 day')::date,interval '1 day') day_value(day_date)
  where employee.id=any(p_employee_ids)),'[]'::jsonb);
end;
$function$;

CREATE OR REPLACE FUNCTION public.optimizer_employee_published_schedule_v2(p_month date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_engine text;
  v_employee_id uuid;
  v_schedule_id uuid;
  v_matrix_version_id uuid;
  v_month date:=date_trunc('month',p_month)::date;
  v_assignments jsonb;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  if p_month is null then raise exception 'MONTH_REQUIRED'; end if;
  select flag.engine into v_engine
  from public.solver_feature_flags flag
  where flag.flag_key='DEFAULT_ENGINE' and flag.enabled;
  if v_engine is null then raise exception 'SOLVER_ENGINE_CONFIGURATION_MISSING'; end if;
  if v_engine not in ('ALPHA15','SHADOW','ORTOOLS_V2') then
    raise exception 'SOLVER_ENGINE_CONFIGURATION_INVALID';
  end if;
  if v_engine<>'ORTOOLS_V2' then return null; end if;
  select employee.id into v_employee_id
  from public.employees employee
  where employee.auth_user_id=auth.uid()
    and employee.active and employee.archived_at is null
  order by employee.employee_no limit 1;
  if v_employee_id is null then
    raise exception 'EMPLOYEE_ACCOUNT_NOT_LINKED';
  end if;
  select schedule.id,schedule.matrix_version_id
  into v_schedule_id,v_matrix_version_id
  from public.published_schedules_v2 schedule
  where schedule.month=v_month and schedule.status='PUBLISHED'
  order by schedule.published_at desc,schedule.id desc limit 1;
  if v_schedule_id is null then
    return jsonb_build_object(
      'engine','ORTOOLS_V2','scheduleId',null,'assignments','[]'::jsonb
    );
  end if;

  with own_assignments as (
    select assignment.id,assignment.employee_id,assignment.role_id,
      assignment.shift_id,shift.slot_group_key,shift.shift_date,
      shift.starts_at,shift.ends_at,shift.location_id,
      shift.shift_template_id
    from public.published_schedule_variants_v2 link
    join public.plan_assignments_v2 assignment
      on assignment.variant_id=link.variant_id
    join public.plan_shifts_v2 shift on shift.id=assignment.shift_id
    where link.schedule_id=v_schedule_id
      and assignment.employee_id=v_employee_id
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'id',own.id,
    'shiftId',own.slot_group_key,
    'date',own.shift_date,
    'startsAt',own.starts_at,
    'endsAt',own.ends_at,
    'shiftCode',shift_template.code,
    'shiftName',shift_template.name,
    'location',location.name,
    'locationCode',location.code,
    'locationTimezone',location.timezone,
    'role',role.name,
    'roleCode',role.code,
    'capability',coalesce((
      select string_agg(duty.name,', ' order by duty.sort_order,duty.name)
      from public.plan_assignment_duties_v2 assignment_duty
      join public.matrix_duties_v2 duty
        on duty.id=assignment_duty.duty_id
      where assignment_duty.assignment_id=own.id
    ),''),
    'coworkers',coalesce((
      select jsonb_agg(jsonb_build_object(
        'name',coworker.first_name||' '||coworker.last_name,
        'role',coworker_role.name,
        'capability',coalesce((
          select string_agg(
            duty.name,', ' order by duty.sort_order,duty.name
          )
          from public.plan_assignment_duties_v2 assignment_duty
          join public.matrix_duties_v2 duty
            on duty.id=assignment_duty.duty_id
          where assignment_duty.assignment_id=coworker_assignment.id
        ),'')
      ) order by coworker.last_name,coworker.first_name,
        coworker_assignment.id)
      from public.published_schedule_variants_v2 coworker_link
      join public.plan_assignments_v2 coworker_assignment
        on coworker_assignment.variant_id=coworker_link.variant_id
      join public.plan_shifts_v2 coworker_shift
        on coworker_shift.id=coworker_assignment.shift_id
      join public.matrix_employee_profiles_v2 coworker
        on coworker.matrix_version_id=v_matrix_version_id
        and coworker.employee_id=coworker_assignment.employee_id
      join public.matrix_roles_v2 coworker_role
        on coworker_role.id=coworker_assignment.role_id
      where coworker_link.schedule_id=v_schedule_id
        and coworker_assignment.employee_id<>v_employee_id
        and coworker_shift.slot_group_key=own.slot_group_key
        and coworker_shift.location_id=own.location_id
        and coworker_shift.starts_at=own.starts_at
        and coworker_shift.ends_at=own.ends_at
    ),'[]'::jsonb)
  ) order by own.starts_at,own.id),'[]'::jsonb)
  into v_assignments
  from own_assignments own
  join public.matrix_locations_v2 location
    on location.id=own.location_id
    and location.matrix_version_id=v_matrix_version_id
  join public.matrix_shift_templates_v2 shift_template
    on shift_template.id=own.shift_template_id
  join public.matrix_roles_v2 role on role.id=own.role_id;

  return jsonb_build_object(
    'engine','ORTOOLS_V2','scheduleId',v_schedule_id,
    'assignments',v_assignments
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.optimizer_employee_schedule_uat_v2(p_month date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 v_engine text; v_employee_id uuid; v_schedule_id uuid;
 v_month date:=date_trunc('month',p_month)::date; v_variant_ids uuid[];
 v_role_schedule_ids jsonb:='[]'::jsonb; v_source_type text; v_assignments jsonb;
begin
 if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
 if p_month is null then raise exception 'MONTH_REQUIRED'; end if;
 select flag.engine into v_engine from public.solver_feature_flags flag
  where flag.flag_key='DEFAULT_ENGINE' and flag.enabled;
 if v_engine is null then raise exception 'SOLVER_ENGINE_CONFIGURATION_MISSING'; end if;
 if v_engine not in ('ALPHA15','SHADOW','ORTOOLS_V2') then raise exception 'SOLVER_ENGINE_CONFIGURATION_INVALID'; end if;
 if v_engine<>'ORTOOLS_V2' then return null; end if;
 select employee.id into v_employee_id from public.employees employee
  where employee.auth_user_id=auth.uid() and employee.active and employee.archived_at is null
  order by employee.employee_no limit 1;
 if v_employee_id is null then raise exception 'EMPLOYEE_ACCOUNT_NOT_LINKED'; end if;
 select array_agg(distinct publication.variant_id order by publication.variant_id),
  jsonb_agg(distinct to_jsonb(publication.id))
 into v_variant_ids,v_role_schedule_ids
 from public.published_role_schedules_v2 publication
 where publication.month=v_month and publication.status='PUBLISHED'
  and exists(select 1 from public.plan_assignments_v2 assignment
   where assignment.variant_id=publication.variant_id and assignment.employee_id=v_employee_id);
 if coalesce(cardinality(v_variant_ids),0)>0 then v_source_type:='ROLE';
 else
  select schedule.id into v_schedule_id from public.published_schedules_v2 schedule
   where schedule.month=v_month and schedule.status='PUBLISHED'
   order by schedule.published_at desc,schedule.id desc limit 1;
  if v_schedule_id is not null then
   select array_agg(link.variant_id order by link.ordinal) into v_variant_ids
   from public.published_schedule_variants_v2 link where link.schedule_id=v_schedule_id;
   v_source_type:='COMPANY';
  end if;
 end if;
 if coalesce(cardinality(v_variant_ids),0)=0 then
  return jsonb_build_object('engine','ORTOOLS_V2','sourceType',null,'scheduleId',null,
   'roleScheduleIds','[]'::jsonb,'assignments','[]'::jsonb);
 end if;
 with own_assignments as (
  select assignment.id,assignment.employee_id,assignment.role_id,assignment.shift_id,
   shift.slot_group_key,shift.shift_date,shift.starts_at,shift.ends_at,shift.location_id,
   shift.shift_template_id
  from public.plan_assignments_v2 assignment
  join public.plan_shifts_v2 shift on shift.id=assignment.shift_id
  where assignment.variant_id=any(v_variant_ids) and assignment.employee_id=v_employee_id
 )
 select coalesce(jsonb_agg(jsonb_build_object(
  'id',own.id,'shiftId',own.slot_group_key,'date',own.shift_date,
  'startsAt',own.starts_at,'endsAt',own.ends_at,
  'shiftCode',shift_template.code,'shiftName',shift_template.name,
  'location',location.name,'locationCode',location.code,
  'locationTimezone',location.timezone,'role',role.name,'roleCode',role.code,
  'capability',coalesce((select string_agg(duty.name,', ' order by duty.sort_order,duty.name)
   from public.plan_assignment_duties_v2 assignment_duty
   join public.matrix_duties_v2 duty on duty.id=assignment_duty.duty_id
   where assignment_duty.assignment_id=own.id),''),
  'coworkers',coalesce((select jsonb_agg(jsonb_build_object(
    'name',coworker.first_name||' '||coworker.last_name,'role',coworker_role.name,
    'capability',coalesce((select string_agg(duty.name,', ' order by duty.sort_order,duty.name)
     from public.plan_assignment_duties_v2 assignment_duty
     join public.matrix_duties_v2 duty on duty.id=assignment_duty.duty_id
     where assignment_duty.assignment_id=coworker_assignment.id),'')
   ) order by coworker.last_name,coworker.first_name,coworker_assignment.id)
   from public.plan_assignments_v2 coworker_assignment
   join public.plan_shifts_v2 coworker_shift on coworker_shift.id=coworker_assignment.shift_id
   join public.employees coworker on coworker.id=coworker_assignment.employee_id
   join public.matrix_roles_v2 coworker_role on coworker_role.id=coworker_assignment.role_id
   where coworker_assignment.variant_id=any(v_variant_ids)
    and coworker_assignment.employee_id<>v_employee_id
    and coworker_shift.slot_group_key=own.slot_group_key
    and coworker_shift.location_id=own.location_id
    and coworker_shift.starts_at=own.starts_at and coworker_shift.ends_at=own.ends_at
  ),'[]'::jsonb)
 ) order by own.starts_at,own.id),'[]'::jsonb)
 into v_assignments
 from own_assignments own
 join public.matrix_locations_v2 location on location.id=own.location_id
 join public.matrix_shift_templates_v2 shift_template on shift_template.id=own.shift_template_id
 join public.matrix_roles_v2 role on role.id=own.role_id;
 return jsonb_build_object('engine','ORTOOLS_V2','sourceType',v_source_type,
  'scheduleId',v_schedule_id,'roleScheduleIds',v_role_schedule_ids,'assignments',v_assignments);
end;$function$;

CREATE OR REPLACE FUNCTION public.optimizer_employee_schedule_uat_v3(p_month date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_status jsonb;
  v_result jsonb;
  v_employee uuid;
  v_month date:=date_trunc('month',p_month)::date;
  v_assignments jsonb;
  v_replacements jsonb;
begin
  v_status:=public.schedule_publication_status_uat_v2(v_month);
  if coalesce((v_status->>'conflict')::boolean,false) then
    raise exception 'SCHEDULE_PUBLICATION_CONFLICT_REQUIRES_OWNER_RESOLUTION';
  end if;
  select employee.id into v_employee from public.employees employee
  where employee.auth_user_id=auth.uid() and employee.active
  order by employee.employee_no limit 1;
  v_result:=public.optimizer_employee_schedule_uat_v2(v_month);
  v_assignments:=coalesce(v_result->'assignments','[]'::jsonb);
  select coalesce(jsonb_agg(item.value),'[]'::jsonb) into v_assignments
  from jsonb_array_elements(v_assignments) item
  where not exists(select 1 from public.operational_assignment_replacements_v2 replacement
    where replacement.original_assignment_id=(item.value->>'id')::uuid
      and replacement.status='ACTIVE');
  select coalesce(jsonb_agg(original.value||jsonb_build_object(
    'id',replacement.id,'replacementOfAssignmentId',replacement.original_assignment_id,
    'isReplacement',true
  ) order by original.value->>'startsAt'),'[]'::jsonb) into v_replacements
  from public.operational_assignment_replacements_v2 replacement
  cross join lateral jsonb_array_elements(
    public.optimizer_employee_schedule_uat_v2(v_month)->'assignments'
  ) original(value)
  where replacement.month=v_month and replacement.status='ACTIVE'
    and replacement.replacement_employee_id=v_employee
    and original.value->>'id'=replacement.original_assignment_id::text;
  return jsonb_set(
    jsonb_set(v_result,'{assignments}',v_assignments||v_replacements,true),
    '{standby}',coalesce((select jsonb_agg(jsonb_build_object(
      'id',standby.id,'date',standby.standby_date,'tier',standby.tier,
      'status',standby.status,'roleId',standby.role_id,'roleName',role.name,
      'activatedShiftId',standby.activated_shift_id
    ) order by standby.standby_date,standby.tier)
      from public.published_standby_assignments_v2 standby
      join public.matrix_roles_v2 role on role.id=standby.role_id
      where standby.employee_id=v_employee and standby.month=v_month
        and standby.status in ('PLANNED','ACTIVATED','DECLINED')
    ),'[]'::jsonb),true
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.optimizer_fail_v3(p_run_id uuid, p_error text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_changed integer;
begin
  if not public.can_manage_plans() then raise exception 'FORBIDDEN'; end if;
  update public.optimization_runs set
    status='FAILED', finished_at=now(), heartbeat_at=now(),
    failure_message=left(coalesce(p_error,'UNKNOWN_ERROR'),2000),
    result_summary=coalesce(result_summary,'{}'::jsonb)||jsonb_build_object('phase','FAILED','progress',100)
  where id=p_run_id and requested_by=auth.uid() and status='RUNNING';
  get diagnostics v_changed=row_count;
  return jsonb_build_object('runId',p_run_id,'failed',v_changed=1);
end $function$;

CREATE OR REPLACE FUNCTION public.optimizer_finalize_v2(p_run_id uuid, p_name text, p_candidates jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_result jsonb; v_plan uuid;
begin
  if not public.can_manage_plans() then raise exception 'FORBIDDEN'; end if;
  if exists(select 1 from jsonb_array_elements(coalesce(p_candidates,'[]'::jsonb)) c
    where coalesce((c->>'hardViolations')::integer,0)<>0) then
    raise exception 'HARD_CONSTRAINT_VALIDATION_FAILED';
  end if;
  -- optimizer_commit performs a second database-side hard validation of every
  -- assignment. Candidates remain independently stored with their own metrics.
  v_result:=public.optimizer_commit(p_run_id,p_name,p_candidates);
  v_plan:=(v_result->>'plan_id')::uuid;

  -- One alert represents one staffing requirement group, not one empty seat.
  -- required_count preserves the actual number of missing people.
  delete from public.plan_issues where plan_id=v_plan
    and issue_type in ('SHORTAGE','CAPABILITY_MISSING');
  insert into public.plan_issues(plan_id,shift_id,issue_type,severity,role,capability,required_count,assigned_count,message)
  select v_plan,s.id,
    case when nullif(x.function_code,'') is null then 'SHORTAGE' else 'CAPABILITY_MISSING' end,
    'CRITICAL',x.role_code::public.employee_role,nullif(x.function_code,''),x.missing,0,
    'Brak obsady: '||x.missing||' os. • '||x.role_code||coalesce(' / '||nullif(x.function_code,''),'')||' • '||x.work_date||' • '||x.shift_code
  from (
    select u->>'date' work_date,u->>'shiftCode' shift_code,u->>'locationId' location_id,
      u->>'role' role_code,coalesce(u->>'fn','') function_code,count(*)::integer missing
    from jsonb_array_elements(coalesce(p_candidates->0->'unfilled','[]'::jsonb)) u
    group by 1,2,3,4,5
  ) x
  left join public.shifts s on s.plan_id=v_plan and s.shift_date=x.work_date::date
    and s.shift_code=x.shift_code and s.location_id=x.location_id::uuid;

  update public.optimization_runs set result_summary=result_summary||jsonb_build_object(
    'phase','DONE','progress',100,'ranking','LEXICOGRAPHIC','engineVersion','ALPHA_14_V2',
    'alertGroups',(select count(*) from public.plan_issues where plan_id=v_plan and resolved_at is null))
  where id=p_run_id;
  return v_result||jsonb_build_object('engineVersion','ALPHA_14_V2',
    'alerts',(select count(*) from public.plan_issues where plan_id=v_plan and resolved_at is null));
end $function$;

CREATE OR REPLACE FUNCTION public.optimizer_finalize_v3(p_run_id uuid, p_name text, p_candidates jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  r public.optimization_runs;
  c jsonb;
  v_materialized jsonb;
  v_winner jsonb;
  v_variants jsonb:='[]'::jsonb;
  v_baseline jsonb;
  v_best jsonb;
  v_status text;
begin
  if not public.can_manage_plans() then raise exception 'FORBIDDEN'; end if;
  select * into r from public.optimization_runs
    where id=p_run_id and requested_by=auth.uid() for update;
  if r.id is null or r.status<>'RUNNING' then raise exception 'OPTIMIZATION_RUN_NOT_WRITABLE'; end if;
  if jsonb_array_length(coalesce(p_candidates,'[]'::jsonb))<>3 then
    raise exception 'THREE_VARIANTS_REQUIRED';
  end if;
  if (select array_agg((x->>'rank')::integer order by (x->>'rank')::integer)
      from jsonb_array_elements(p_candidates) x)<>array[1,2,3] then
    raise exception 'VARIANT_RANKS_MUST_BE_1_2_3';
  end if;
  if (select count(distinct md5(coalesce(x->'assignments','[]'::jsonb)::text))
      from jsonb_array_elements(p_candidates) x)<>3 then
    raise exception 'THREE_DISTINCT_VARIANTS_REQUIRED';
  end if;
  if exists(select 1 from jsonb_array_elements(p_candidates) x
    where coalesce((x->>'hardViolations')::integer,0)<>0) then
    raise exception 'HARD_CONSTRAINT_VALIDATION_FAILED';
  end if;

  v_baseline:=r.checkpoint->'baselineRanking';
  select x->'metrics'->'ranking' into v_best
  from jsonb_array_elements(p_candidates) x where (x->>'rank')::integer=1;
  if v_baseline is not null and (
    coalesce((v_best->>0)::numeric,0)>coalesce((v_baseline->>0)::numeric,0)
    or (coalesce((v_best->>0)::numeric,0)=coalesce((v_baseline->>0)::numeric,0)
      and coalesce((v_best->>1)::numeric,0)>coalesce((v_baseline->>1)::numeric,0))
    or (coalesce((v_best->>0)::numeric,0)=coalesce((v_baseline->>0)::numeric,0)
      and coalesce((v_best->>1)::numeric,0)=coalesce((v_baseline->>1)::numeric,0)
      and coalesce((v_best->>2)::numeric,0)>coalesce((v_baseline->>2)::numeric,0))
  ) then raise exception 'NO_REGRESSION_GUARD'; end if;

  -- Serialize plan version allocation for this month while the three variants
  -- are materialized in one transaction.
  perform pg_advisory_xact_lock(hashtext('optimizer-plan-version:'||r.month::text));

  -- Reverse order makes rank 1 the newest plan/version and therefore the
  -- default plan returned by the existing workspace RPC.
  for c in
    select value from jsonb_array_elements(p_candidates)
    order by (value->>'rank')::integer desc
  loop
    v_materialized:=public.optimizer_materialize_candidate_v3(p_run_id,p_name,c);
    insert into public.optimization_candidates(
      run_id,plan_id,rank,score,hard_violations,metrics,assignments,selected
    ) values(
      r.id,(v_materialized->>'planId')::uuid,(c->>'rank')::integer,(c->>'score')::numeric,
      coalesce((c->>'hardViolations')::integer,0),coalesce(c->'metrics','{}'::jsonb),
      coalesce(c->'assignments','[]'::jsonb),(c->>'rank')::integer=1
    );
    v_variants:=v_variants||jsonb_build_array(v_materialized);
    if (c->>'rank')::integer=1 then v_winner:=v_materialized; end if;
  end loop;

  select coalesce(jsonb_agg(x order by (x->>'rank')::integer),'[]'::jsonb)
    into v_variants from jsonb_array_elements(v_variants) x;
  v_status:=case when coalesce((v_winner->>'unfilled')::integer,0)=0
    then 'SUCCEEDED' else 'INFEASIBLE' end;

  update public.optimization_runs set
    status=v_status,finished_at=now(),heartbeat_at=now(),
    result_summary=jsonb_build_object(
      'phase','DONE','progress',100,'ranking','LEXICOGRAPHIC','engineVersion','ALPHA_15_V3',
      'planId',v_winner->'planId','score',v_winner->'score',
      'assignments',v_winner->'assignments','unfilled',v_winner->'unfilled',
      'alertGroups',v_winner->'alertGroups','alternatives',3,
      'cost',v_winner->'totalCost','variants',v_variants,
      'baselineRanking',v_baseline)
  where id=r.id;

  insert into public.audit_log(actor_id,entity_type,entity_id,action,new_data)
  values(auth.uid(),'optimization_run',r.id::text,'COMMIT_V3',
    (select result_summary from public.optimization_runs where id=r.id));

  return jsonb_build_object(
    'plan_id',v_winner->'planId','run_id',r.id,
    'status',case when v_status='SUCCEEDED' then 'READY' else 'READY_WITH_EXCEPTIONS' end,
    'assignments',v_winner->'assignments','issues',v_winner->'unfilled',
    'alerts',v_winner->'alertGroups','total_cost',v_winner->'totalCost',
    'score',v_winner->'score','alternatives',3,'variants',v_variants,
    'engineVersion','ALPHA_15_V3','baselineRanking',v_baseline
  );
end $function$;

CREATE OR REPLACE FUNCTION public.optimizer_generation_quota_uat_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_user uuid:=auth.uid(); v_count integer; v_limit integer;
begin
  if v_user is null then raise exception 'AUTH_REQUIRED'; end if;
  select generation_quota_per_user_hour into v_limit
  from solver_private.solver_job_runtime_config_uat_v1 where singleton;
  select count(*) into v_count from public.optimization_runs_v2
  where requested_by=v_user and created_at>=now()-interval '1 hour';
  return jsonb_build_object(
    'requestsLastHour',v_count,'limit',v_limit,
    'level',case
      when v_count>=v_limit then 'HARD_STOP'
      when v_count>=greatest(v_limit-3,1) then 'ANOMALY'
      when v_count>=ceil(v_limit*0.60) then 'WARNING'
      else 'NORMAL' end
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.optimizer_job_status_uat_v1(p_run_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_item solver_private.solver_job_dispatch_outbox_uat_v1%rowtype;
begin
  if not solver_private.can_access_run_v2(p_run_id) then
    raise exception 'RUN_NOT_FOUND';
  end if;
  select * into v_item
  from solver_private.solver_job_dispatch_outbox_uat_v1 where run_id=p_run_id;
  if v_item.run_id is null then
    return jsonb_build_object('runId',p_run_id,'executionMode','SERVICE');
  end if;
  return jsonb_build_object(
    'runId',p_run_id,'executionMode','JOB',
    'dispatchStatus',v_item.dispatch_status,
    'dispatchAttempt',v_item.dispatch_attempt,
    'solverRetryCount',v_item.solver_retry_count,
    'northflankRunId',v_item.northflank_run_id,
    'requestedAt',v_item.requested_at,
    'dispatchStartedAt',v_item.dispatch_started_at,
    'northflankAcceptedAt',v_item.northflank_accepted_at,
    'containerStartedAt',v_item.container_started_at,
    'workerClaimedAt',v_item.worker_claimed_at,
    'solverStartedAt',v_item.solver_started_at,
    'solverFinishedAt',v_item.solver_finished_at,
    'resultSavedAt',v_item.result_saved_at,
    'readyAt',v_item.ready_at,
    'jobFinishedAt',v_item.job_finished_at,
    'configuredVcpu',v_item.configured_vcpu,
    'configuredRamMb',v_item.configured_ram_mb,
    'peakRssMb',v_item.peak_rss_mb,
    'averageRssMb',v_item.average_rss_mb,
    'peakCpuPercent',v_item.peak_cpu_percent,
    'billableSeconds',v_item.billable_seconds,
    'estimatedComputeCostUsd',v_item.estimated_compute_cost_usd,
    'lastErrorCode',v_item.last_error_code,
    'durationsMs',jsonb_build_object(
      'requestToDispatch',case when v_item.dispatch_started_at is null then null
        else round(extract(epoch from(v_item.dispatch_started_at-v_item.requested_at))*1000) end,
      'dispatchToAccept',case when v_item.northflank_accepted_at is null then null
        else round(extract(epoch from(v_item.northflank_accepted_at-v_item.dispatch_started_at))*1000) end,
      'acceptToContainer',case when v_item.container_started_at is null then null
        else round(extract(epoch from(v_item.container_started_at-v_item.northflank_accepted_at))*1000) end,
      'containerToClaim',case when v_item.worker_claimed_at is null then null
        else round(extract(epoch from(v_item.worker_claimed_at-v_item.container_started_at))*1000) end,
      'claimToSolver',case when v_item.solver_started_at is null then null
        else round(extract(epoch from(v_item.solver_started_at-v_item.worker_claimed_at))*1000) end,
      'solverRuntime',case when v_item.solver_finished_at is null then null
        else round(extract(epoch from(v_item.solver_finished_at-v_item.solver_started_at))*1000) end,
      'postprocess',case when v_item.result_saved_at is null then null
        else round(extract(epoch from(v_item.result_saved_at-v_item.solver_finished_at))*1000) end,
      'resultToReady',case when v_item.ready_at is null then null
        else round(extract(epoch from(v_item.ready_at-v_item.result_saved_at))*1000) end,
      'total',case when coalesce(v_item.job_finished_at,v_item.ready_at) is null then null
        else round(extract(epoch from(coalesce(v_item.job_finished_at,v_item.ready_at)-v_item.requested_at))*1000) end
    )
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.optimizer_kadromierz_export_v2(p_month date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_engine text;
  v_schedule_id uuid;
  v_matrix_version_id uuid;
  v_month date:=date_trunc('month',p_month)::date;
  v_result jsonb;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  if p_month is null then raise exception 'MONTH_REQUIRED'; end if;
  select f.engine into v_engine
  from public.solver_feature_flags f
  where f.flag_key='DEFAULT_ENGINE' and f.enabled;
  if v_engine is null then raise exception 'SOLVER_ENGINE_CONFIGURATION_MISSING'; end if;
  if v_engine not in ('ALPHA15','SHADOW','ORTOOLS_V2') then
    raise exception 'SOLVER_ENGINE_CONFIGURATION_INVALID';
  end if;
  if v_engine<>'ORTOOLS_V2' then return null; end if;
  if not (
    public.has_app_role('OWNER') or public.has_app_role('ADMIN')
    or public.has_app_role('HR_FINANCE')
  ) then raise exception 'FORBIDDEN'; end if;
  select s.id,s.matrix_version_id into v_schedule_id,v_matrix_version_id
  from public.published_schedules_v2 s
  where s.month=v_month and s.status='PUBLISHED'
  order by s.published_at desc,s.id desc limit 1;
  if v_schedule_id is null then return '[]'::jsonb; end if;
  select coalesce(jsonb_agg(jsonb_build_object(
    'numer_pracownika',employee.employee_no,
    'pracownik',employee.first_name||' '||employee.last_name,
    'data',shift.shift_date,'lokal',location.code,
    'zmiana',template.code,'od',shift.starts_at,'do',shift.ends_at,
    'rola',role.code,
    'obowiazki',coalesce((
      select string_agg(duty.code,',' order by duty.sort_order,duty.code)
      from public.plan_assignment_duties_v2 assignment_duty
      join public.matrix_duties_v2 duty on duty.id=assignment_duty.duty_id
      where assignment_duty.assignment_id=assignment.id
    ),'')
  ) order by shift.starts_at,employee.employee_no,assignment.id),'[]'::jsonb)
  into v_result
  from public.published_schedule_variants_v2 link
  join public.plan_assignments_v2 assignment on assignment.variant_id=link.variant_id
  join public.plan_shifts_v2 shift on shift.id=assignment.shift_id
  join public.matrix_employee_profiles_v2 employee
    on employee.matrix_version_id=v_matrix_version_id
    and employee.employee_id=assignment.employee_id
  join public.matrix_locations_v2 location on location.id=shift.location_id
  join public.matrix_shift_templates_v2 template on template.id=shift.shift_template_id
  join public.matrix_roles_v2 role on role.id=assignment.role_id
  where link.schedule_id=v_schedule_id;
  return v_result;
end;
$function$;

CREATE OR REPLACE FUNCTION public.optimizer_leader_assignment_context_before_b4_details_uat_v1(p_variant_id uuid, p_assignment_id uuid DEFAULT NULL::uuid, p_issue_id bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_variant public.plan_variants_v2%rowtype;
  v_run public.optimization_runs_v2%rowtype;
  v_shift public.plan_shifts_v2%rowtype;
  v_assignment public.plan_assignments_v2%rowtype;
  v_issue public.plan_issues_v2%rowtype;
  v_role_id uuid;
  v_slot_key text;
  v_duty_id uuid;
begin
  if (p_assignment_id is null)=(p_issue_id is null) then
    raise exception 'ASSIGNMENT_OR_ISSUE_REQUIRED';
  end if;
  if not solver_private.can_edit_leader_variant_uat_v1(p_variant_id) then
    raise exception 'LEADER_VARIANT_NOT_EDITABLE';
  end if;
  select * into v_variant from public.plan_variants_v2 where id=p_variant_id;
  select * into v_run from public.optimization_runs_v2 where id=v_variant.run_id;
  if p_assignment_id is not null then
    select * into v_assignment from public.plan_assignments_v2
      where id=p_assignment_id and variant_id=p_variant_id;
    if v_assignment.id is null then raise exception 'ASSIGNMENT_NOT_FOUND'; end if;
    select * into v_shift from public.plan_shifts_v2 where id=v_assignment.shift_id;
    v_role_id:=v_assignment.role_id; v_slot_key:=v_assignment.slot_key;
    select duty_id into v_duty_id from public.plan_assignment_duties_v2
      where assignment_id=v_assignment.id order by duty_id limit 1;
  else
    select * into v_issue from public.plan_issues_v2
      where id=p_issue_id and variant_id=p_variant_id and issue_code='UNFILLED_SLOT';
    if v_issue.id is null then raise exception 'UNFILLED_ISSUE_NOT_FOUND'; end if;
    select * into v_shift from public.plan_shifts_v2 where id=v_issue.shift_id;
    v_role_id:=v_issue.role_id; v_slot_key:=v_issue.slot_key; v_duty_id:=v_issue.duty_id;
  end if;
  return jsonb_build_object(
    'variantId',p_variant_id,'assignmentId',p_assignment_id,'issueId',p_issue_id,
    'slotKey',v_slot_key,'currentEmployeeId',v_assignment.employee_id,
    'role',jsonb_build_object('id',role.id,'name',role.name),
    'shift',jsonb_build_object('id',v_shift.id,'date',v_shift.shift_date,
      'startsAt',v_shift.starts_at,'endsAt',v_shift.ends_at,
      'locationId',v_shift.location_id,'locationName',location.name,
      'shiftName',template.name),
    'candidates',coalesce((
      select jsonb_agg(jsonb_build_object(
        'employeeId',employee.id,'employeeNo',employee.employee_no,
        'employeeName',trim(employee.first_name||' '||employee.last_name),
        'current',employee.id=v_assignment.employee_id
      ) order by employee.last_name,employee.first_name)
      from public.employees employee
      where employee.active
        and (employee.employment_start is null or employee.employment_start<=v_shift.shift_date)
        and (employee.employment_end is null or employee.employment_end>=v_shift.shift_date)
        and exists(select 1 from public.matrix_employee_roles_v2 er
          where er.matrix_version_id=v_run.matrix_version_id and er.employee_id=employee.id
            and er.role_id=v_role_id and er.active
            and (er.valid_from is null or er.valid_from<=v_shift.shift_date)
            and (er.valid_to is null or er.valid_to>=v_shift.shift_date))
        and exists(select 1 from public.matrix_employee_locations_v2 el
          where el.matrix_version_id=v_run.matrix_version_id and el.employee_id=employee.id
            and el.location_id=v_shift.location_id and el.active and el.standard_allowed
            and (el.valid_from is null or el.valid_from<=v_shift.shift_date)
            and (el.valid_to is null or el.valid_to>=v_shift.shift_date))
        and (v_duty_id is null or exists(select 1 from public.matrix_employee_duties_v2 ed
          where ed.matrix_version_id=v_run.matrix_version_id and ed.employee_id=employee.id
            and ed.duty_id=v_duty_id and ed.active
            and (ed.role_id is null or ed.role_id=v_role_id)
            and (ed.location_id is null or ed.location_id=v_shift.location_id)
            and (ed.valid_from is null or ed.valid_from<=v_shift.shift_date)
            and (ed.valid_to is null or ed.valid_to>=v_shift.shift_date)))
    ),'[]'::jsonb)
  )
  from public.matrix_roles_v2 role,public.matrix_locations_v2 location,
    public.matrix_shift_templates_v2 template
  where role.id=v_role_id and location.id=v_shift.location_id
    and template.id=v_shift.shift_template_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.optimizer_leader_assignment_context_before_daily_limit_uat_v2(p_variant_id uuid, p_assignment_id uuid DEFAULT NULL::uuid, p_issue_id bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_variant public.plan_variants_v2%rowtype; v_run public.optimization_runs_v2%rowtype;
  v_shift public.plan_shifts_v2%rowtype; v_assignment public.plan_assignments_v2%rowtype;
  v_issue public.plan_issues_v2%rowtype; v_role_id uuid; v_slot_key text; v_duty_id uuid;
  v_default_available boolean:=true;
begin
  if (p_assignment_id is null)=(p_issue_id is null) then raise exception 'ASSIGNMENT_OR_ISSUE_REQUIRED'; end if;
  if not solver_private.can_edit_leader_variant_uat_v1(p_variant_id) then raise exception 'LEADER_VARIANT_NOT_EDITABLE'; end if;
  select * into v_variant from public.plan_variants_v2 where id=p_variant_id;
  select * into v_run from public.optimization_runs_v2 where id=v_variant.run_id;
  select coalesce((settings->>'missingAvailabilityMeansAvailable')::boolean,true)
    into v_default_available from public.matrix_versions where id=v_run.matrix_version_id;
  if p_assignment_id is not null then
    select * into v_assignment from public.plan_assignments_v2 where id=p_assignment_id and variant_id=p_variant_id;
    if v_assignment.id is null then raise exception 'ASSIGNMENT_NOT_FOUND'; end if;
    select * into v_shift from public.plan_shifts_v2 where id=v_assignment.shift_id;
    v_role_id:=v_assignment.role_id;v_slot_key:=v_assignment.slot_key;
    select duty_id into v_duty_id from public.plan_assignment_duties_v2
      where assignment_id=v_assignment.id order by duty_id limit 1;
  else
    select * into v_issue from public.plan_issues_v2
      where id=p_issue_id and variant_id=p_variant_id and issue_code='UNFILLED_SLOT';
    if v_issue.id is null then raise exception 'UNFILLED_ISSUE_NOT_FOUND'; end if;
    select * into v_shift from public.plan_shifts_v2 where id=v_issue.shift_id;
    v_role_id:=v_issue.role_id;v_slot_key:=v_issue.slot_key;v_duty_id:=v_issue.duty_id;
  end if;
  return jsonb_build_object(
    'variantId',p_variant_id,'assignmentId',p_assignment_id,'issueId',p_issue_id,
    'slotKey',v_slot_key,'currentEmployeeId',v_assignment.employee_id,
    'role',jsonb_build_object('id',role.id,'name',role.name),
    'duty',case when duty.id is null then null else jsonb_build_object('id',duty.id,'name',duty.name) end,
    'shift',jsonb_build_object('id',v_shift.id,'date',v_shift.shift_date,'startsAt',v_shift.starts_at,
      'endsAt',v_shift.ends_at,'locationId',v_shift.location_id,'locationName',location.name,'shiftName',template.name),
    'candidates',coalesce((select jsonb_agg(jsonb_build_object(
      'employeeId',candidate.employee_id,'employeeNo',candidate.employee_no,'employeeName',candidate.employee_name,
      'current',candidate.employee_id=v_assignment.employee_id,'roleName',role.name,'locationName',location.name,
      'dutyName',case when candidate.duty_match then duty.name else null end,
      'dutyMatch',candidate.duty_match,'dutyCoverageMode',case when v_duty_id is null or candidate.duty_match then 'DIRECT'
        when transfer.assignment_id is not null then 'TRANSFER' else 'NOT_COVERED' end,
      'dutyTransferAssignmentId',transfer.assignment_id,'dutyTransferEmployeeId',transfer.employee_id,
      'dutyTransferEmployeeName',transfer.employee_name,
      'availabilityStatus',candidate.availability_status,
      'suggestionEligible',candidate.availability_status in ('AVAILABLE','SOFT_AVOID')
        and (v_duty_id is null or candidate.duty_match or transfer.assignment_id is not null)
    ) order by (candidate.availability_status in ('AVAILABLE','SOFT_AVOID')
        and (v_duty_id is null or candidate.duty_match or transfer.assignment_id is not null)) desc,
      candidate.last_name,candidate.first_name,candidate.employee_no)
      from (
        select employee.id employee_id,employee.employee_no,employee.first_name,employee.last_name,
          trim(employee.first_name||' '||employee.last_name) employee_name,
          (v_duty_id is null or exists(select 1 from public.matrix_employee_duties_v2 grant_row
            where grant_row.matrix_version_id=v_run.matrix_version_id and grant_row.employee_id=employee.id
              and grant_row.duty_id=v_duty_id and grant_row.active
              and (grant_row.role_id is null or grant_row.role_id=v_role_id)
              and (grant_row.location_id is null or grant_row.location_id=v_shift.location_id)
              and (grant_row.valid_from is null or grant_row.valid_from<=v_shift.shift_date)
              and (grant_row.valid_to is null or grant_row.valid_to>=v_shift.shift_date))) duty_match,
          case
            when exists(select 1 from public.employee_time_constraints_v2 constraint_row
              where constraint_row.employee_id=employee.id and constraint_row.status='ACTIVE'
                and constraint_row.constraint_kind in ('UNAVAILABLE','LEAVE','SICKNESS')
                and constraint_row.time_range&&tstzrange(v_shift.starts_at,v_shift.ends_at,'[)')) then 'HARD_UNAVAILABLE'
            when exists(select 1 from public.plan_assignments_v2 occupied
              join public.plan_shifts_v2 occupied_shift on occupied_shift.id=occupied.shift_id
              where occupied.variant_id=p_variant_id and occupied.employee_id=employee.id
                and occupied.id is distinct from p_assignment_id
                and tstzrange(occupied_shift.starts_at,occupied_shift.ends_at,'[)')
                  &&tstzrange(v_shift.starts_at,v_shift.ends_at,'[)')) then 'SHIFT_CONFLICT'
            when not v_default_available and not exists(select 1 from public.employee_time_constraints_v2 window_row
              where window_row.employee_id=employee.id and window_row.status='ACTIVE'
                and window_row.constraint_kind='AVAILABLE_WINDOW'
                and lower(window_row.time_range)<=v_shift.starts_at and upper(window_row.time_range)>=v_shift.ends_at) then 'OUTSIDE_AVAILABLE_WINDOW'
            when exists(select 1 from public.employee_time_constraints_v2 preference
              where preference.employee_id=employee.id and preference.status='ACTIVE'
                and preference.constraint_kind='PREFER_NOT_TO_WORK'
                and preference.time_range&&tstzrange(v_shift.starts_at,v_shift.ends_at,'[)')) then 'SOFT_AVOID'
            else 'AVAILABLE' end availability_status
        from public.employees employee
        where employee.active and employee.archived_at is null
          and (employee.employment_start is null or employee.employment_start<=v_shift.shift_date)
          and (employee.employment_end is null or employee.employment_end>=v_shift.shift_date)
          and exists(select 1 from public.matrix_employee_roles_v2 grant_row
            where grant_row.matrix_version_id=v_run.matrix_version_id and grant_row.employee_id=employee.id
              and grant_row.role_id=v_role_id and grant_row.active
              and (grant_row.valid_from is null or grant_row.valid_from<=v_shift.shift_date)
              and (grant_row.valid_to is null or grant_row.valid_to>=v_shift.shift_date))
          and exists(select 1 from public.matrix_employee_locations_v2 grant_row
            where grant_row.matrix_version_id=v_run.matrix_version_id and grant_row.employee_id=employee.id
              and grant_row.location_id=v_shift.location_id and grant_row.active and grant_row.standard_allowed
              and (grant_row.valid_from is null or grant_row.valid_from<=v_shift.shift_date)
              and (grant_row.valid_to is null or grant_row.valid_to>=v_shift.shift_date))
      ) candidate
      left join lateral (
        select transfer_assignment.id assignment_id,transfer_employee.id employee_id,
          trim(transfer_employee.first_name||' '||transfer_employee.last_name) employee_name
        from public.plan_assignments_v2 transfer_assignment
        join public.employees transfer_employee on transfer_employee.id=transfer_assignment.employee_id
        where v_duty_id is not null and not candidate.duty_match
          and transfer_assignment.variant_id=p_variant_id and transfer_assignment.shift_id=v_shift.id
          and transfer_assignment.id is distinct from p_assignment_id and transfer_assignment.role_id=v_role_id
          and transfer_assignment.employee_id<>candidate.employee_id
          and exists(select 1 from public.matrix_employee_duties_v2 grant_row
            where grant_row.matrix_version_id=v_run.matrix_version_id
              and grant_row.employee_id=transfer_assignment.employee_id and grant_row.duty_id=v_duty_id
              and grant_row.active and (grant_row.role_id is null or grant_row.role_id=v_role_id)
              and (grant_row.location_id is null or grant_row.location_id=v_shift.location_id)
              and (grant_row.valid_from is null or grant_row.valid_from<=v_shift.shift_date)
              and (grant_row.valid_to is null or grant_row.valid_to>=v_shift.shift_date))
          and not exists(select 1 from public.plan_assignment_duties_v2 transfer_duty
            where transfer_duty.assignment_id=transfer_assignment.id and not exists(
              select 1 from public.matrix_employee_duties_v2 candidate_grant
              where candidate_grant.matrix_version_id=v_run.matrix_version_id
                and candidate_grant.employee_id=candidate.employee_id and candidate_grant.duty_id=transfer_duty.duty_id
                and candidate_grant.active
                and (candidate_grant.role_id is null or candidate_grant.role_id=transfer_assignment.role_id)
                and (candidate_grant.location_id is null or candidate_grant.location_id=v_shift.location_id)))
        order by transfer_employee.last_name,transfer_employee.first_name,transfer_assignment.id limit 1
      ) transfer on true),'[]'::jsonb),
    'suggestionContract',jsonb_build_object('availabilityChecked',true,'dutyTransferChecked',true,'fullMonthCheckedOnSave',true)
  )
  from public.matrix_roles_v2 role
  join public.matrix_locations_v2 location on location.id=v_shift.location_id
  join public.matrix_shift_templates_v2 template on template.id=v_shift.shift_template_id
  left join public.matrix_duties_v2 duty on duty.id=v_duty_id
  where role.id=v_role_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.optimizer_leader_assignment_context_uat_v1(p_variant_id uuid, p_assignment_id uuid DEFAULT NULL::uuid, p_issue_id bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_payload jsonb; v_duty_id uuid; v_duty_name text; v_candidates jsonb;
begin
  v_payload:=public.optimizer_leader_assignment_context_before_b4_details_uat_v1(p_variant_id,p_assignment_id,p_issue_id);
  if p_issue_id is not null then
    select issue.duty_id into v_duty_id from public.plan_issues_v2 issue where issue.id=p_issue_id and issue.variant_id=p_variant_id;
  else
    select duty.duty_id into v_duty_id from public.plan_assignment_duties_v2 duty where duty.assignment_id=p_assignment_id order by duty.duty_id limit 1;
  end if;
  select duty.name into v_duty_name from public.matrix_duties_v2 duty where duty.id=v_duty_id;
  select coalesce(jsonb_agg(candidate.value||jsonb_build_object(
    'roleName',v_payload#>>'{role,name}','locationName',v_payload#>>'{shift,locationName}','dutyName',v_duty_name
  )),'[]'::jsonb) into v_candidates
  from jsonb_array_elements(coalesce(v_payload->'candidates','[]'::jsonb)) candidate(value);
  v_payload:=jsonb_set(v_payload,'{candidates}',v_candidates,true);
  return v_payload||jsonb_build_object('duty',case when v_duty_id is null then null else jsonb_build_object('id',v_duty_id,'name',v_duty_name) end);
end;
$function$;

CREATE OR REPLACE FUNCTION public.optimizer_leader_assignment_context_uat_v2(p_variant_id uuid, p_assignment_id uuid DEFAULT NULL::uuid, p_issue_id bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_payload jsonb;v_matrix_version_id uuid;v_shift_date date;
  v_daily_limit integer:=1;v_candidates jsonb:='[]'::jsonb;
begin
  v_payload:=public.optimizer_leader_assignment_context_before_daily_limit_uat_v2(
    p_variant_id,p_assignment_id,p_issue_id);
  select run.matrix_version_id into v_matrix_version_id
  from public.plan_variants_v2 variant
  join public.optimization_runs_v2 run on run.id=variant.run_id
  where variant.id=p_variant_id;
  v_shift_date:=(v_payload#>>'{shift,date}')::date;
  select greatest(1,coalesce(nullif(settings->>'maximumShiftsPerDay','')::integer,1))
    into v_daily_limit from public.matrix_versions where id=v_matrix_version_id;
  select coalesce(jsonb_agg(case when candidate.value->>'availabilityStatus' in ('AVAILABLE','SOFT_AVOID')
      and (select count(*) from public.plan_assignments_v2 occupied
        join public.plan_shifts_v2 occupied_shift on occupied_shift.id=occupied.shift_id
        where occupied.variant_id=p_variant_id
          and occupied.employee_id=(candidate.value->>'employeeId')::uuid
          and occupied.id is distinct from p_assignment_id
          and occupied_shift.shift_date=v_shift_date)>=v_daily_limit
    then candidate.value||jsonb_build_object(
      'availabilityStatus','DAILY_LIMIT','suggestionEligible',false)
    else candidate.value end order by candidate.ordinality),'[]'::jsonb)
    into v_candidates
  from jsonb_array_elements(coalesce(v_payload->'candidates','[]'::jsonb))
    with ordinality candidate(value,ordinality);
  return jsonb_set(v_payload,'{candidates}',v_candidates,true);
end;
$function$;

CREATE OR REPLACE FUNCTION public.optimizer_leader_assignment_context_uat_v3(p_variant_id uuid, p_assignment_id uuid DEFAULT NULL::uuid, p_issue_id bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_payload jsonb;
  v_candidates jsonb := '[]'::jsonb;
  v_candidate jsonb;
  v_overtime jsonb;
begin
  v_payload := public.optimizer_leader_assignment_context_uat_v2(
    p_variant_id, p_assignment_id, p_issue_id
  );
  for v_candidate in
    select candidate.value
    from jsonb_array_elements(coalesce(v_payload->'candidates', '[]'::jsonb)) candidate(value)
  loop
    v_overtime := solver_private.leader_overtime_candidate_uat_v1(
      p_variant_id, p_assignment_id, p_issue_id, (v_candidate->>'employeeId')::uuid
    );
    v_candidate := v_candidate || v_overtime || jsonb_build_object(
      'suggestionEligible', coalesce((v_candidate->>'suggestionEligible')::boolean, false)
        and not coalesce((v_overtime->>'overtimeBlocked')::boolean, false)
    );
    v_candidates := v_candidates || jsonb_build_array(v_candidate);
  end loop;
  return jsonb_set(v_payload, '{candidates}', v_candidates, true);
end;
$function$;

CREATE OR REPLACE FUNCTION public.optimizer_leader_assignment_context_uat_v4(p_variant_id uuid, p_assignment_id uuid DEFAULT NULL::uuid, p_issue_id bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_payload jsonb:=public.optimizer_leader_assignment_context_uat_v3(p_variant_id,p_assignment_id,p_issue_id);
  v_candidates jsonb:='[]'::jsonb;v_candidate jsonb;v_allowed boolean;v_timezone text;
begin
  select coalesce(version.settings->>'timezone','Europe/Warsaw') into v_timezone
  from public.plan_variants_v2 variant join public.optimization_runs_v2 run on run.id=variant.run_id
  join public.matrix_versions version on version.id=run.matrix_version_id where variant.id=p_variant_id;
  for v_candidate in select value from jsonb_array_elements(coalesce(v_payload->'candidates','[]'::jsonb)) loop
    v_allowed:=solver_private.employee_weekly_pattern_allows_uat_v1(
      (v_candidate->>'employeeId')::uuid,(v_payload#>>'{shift,date}')::date,
      (v_payload#>>'{shift,startsAt}')::timestamptz,(v_payload#>>'{shift,endsAt}')::timestamptz,
      (v_payload#>>'{role,id}')::uuid,(v_payload#>>'{shift,locationId}')::uuid,v_timezone);
    v_candidate:=v_candidate||jsonb_build_object(
      'workPatternAllowed',v_allowed,
      'availabilityStatus',case when v_allowed then v_candidate->>'availabilityStatus' else 'PERMANENT_WORK_PATTERN' end,
      'suggestionEligible',coalesce((v_candidate->>'suggestionEligible')::boolean,false) and v_allowed);
    v_candidates:=v_candidates||jsonb_build_array(v_candidate);
  end loop;
  return jsonb_set(v_payload,'{candidates}',v_candidates,true)
    ||jsonb_build_object('workPatternsChecked',true);
end;$function$;

CREATE OR REPLACE FUNCTION public.optimizer_leader_assignment_drag_preview_uat_v1(p_variant_id uuid, p_source_assignment_id uuid, p_target_assignment_id uuid DEFAULT NULL::uuid, p_target_issue_id bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_result jsonb;
  v_detail text;
  v_error text;
begin
  begin
    v_result:=public.optimizer_leader_assignment_drag_uat_v1(
      p_variant_id,
      p_source_assignment_id,
      p_target_assignment_id,
      p_target_issue_id,
      'Niemutująca kontrola przeciągnięcia w Studio lidera'
    );
    raise exception 'LEADER_DRAG_PREVIEW_ROLLBACK' using detail=v_result::text;
  exception when others then
    get stacked diagnostics v_error=message_text,v_detail=pg_exception_detail;
    if v_error='LEADER_DRAG_PREVIEW_ROLLBACK' then
      return coalesce(v_detail,'{}')::jsonb||jsonb_build_object('valid',true);
    end if;
    return jsonb_build_object('valid',false,'errorCode',v_error);
  end;
end;
$function$;

CREATE OR REPLACE FUNCTION public.optimizer_leader_assignment_drag_uat_v1(p_variant_id uuid, p_source_assignment_id uuid, p_target_assignment_id uuid DEFAULT NULL::uuid, p_target_issue_id bigint DEFAULT NULL::bigint, p_reason text DEFAULT 'Przeciągnięcie w Studio lidera'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid:=auth.uid();
  v_reason text:=trim(coalesce(p_reason,''));
  v_source public.plan_assignments_v2%rowtype;
  v_target public.plan_assignments_v2%rowtype;
  v_issue public.plan_issues_v2%rowtype;
  v_source_context jsonb;v_target_context jsonb;v_candidate jsonb;
  v_snapshot jsonb;v_slot jsonb;v_new_assignment_id uuid;v_source_duty_id uuid;
begin
  if length(v_reason)<3 then raise exception 'EDIT_REASON_REQUIRED'; end if;
  if (p_target_assignment_id is null)=(p_target_issue_id is null) then
    raise exception 'DRAG_TARGET_REQUIRED';
  end if;
  if not solver_private.can_edit_leader_variant_uat_v1(p_variant_id) then
    raise exception 'LEADER_VARIANT_NOT_EDITABLE';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('leader-edit:'||p_variant_id::text,0));
  select * into v_source from public.plan_assignments_v2
    where id=p_source_assignment_id and variant_id=p_variant_id for update;
  if v_source.id is null then raise exception 'ASSIGNMENT_NOT_FOUND'; end if;
  if v_source.locked then raise exception 'LOCKED_ASSIGNMENT_CANNOT_BE_REMOVED'; end if;

  if p_target_assignment_id is not null then
    if p_target_assignment_id=p_source_assignment_id then raise exception 'DRAG_TARGET_UNCHANGED'; end if;
    select * into v_target from public.plan_assignments_v2
      where id=p_target_assignment_id and variant_id=p_variant_id for update;
    if v_target.id is null then raise exception 'ASSIGNMENT_NOT_FOUND'; end if;
    if v_target.locked then raise exception 'LOCKED_ASSIGNMENT_CANNOT_BE_REMOVED'; end if;
    v_target_context:=public.optimizer_leader_assignment_context_uat_v4(
      p_variant_id,p_target_assignment_id,null);
    select value into v_candidate from jsonb_array_elements(coalesce(v_target_context->'candidates','[]'::jsonb))
      where value->>'employeeId'=v_source.employee_id::text;
    if v_candidate is null or not coalesce((v_candidate->>'workPatternAllowed')::boolean,false)
      or coalesce(v_candidate->>'dutyCoverageMode','NOT_COVERED')<>'DIRECT' then
      raise exception 'VARIANT_EMPLOYEE_ELIGIBILITY_INVALID';
    end if;
    v_source_context:=public.optimizer_leader_assignment_context_uat_v4(
      p_variant_id,p_source_assignment_id,null);
    select value into v_candidate from jsonb_array_elements(coalesce(v_source_context->'candidates','[]'::jsonb))
      where value->>'employeeId'=v_target.employee_id::text;
    if v_candidate is null or not coalesce((v_candidate->>'workPatternAllowed')::boolean,false)
      or coalesce(v_candidate->>'dutyCoverageMode','NOT_COVERED')<>'DIRECT' then
      raise exception 'VARIANT_EMPLOYEE_ELIGIBILITY_INVALID';
    end if;
    update public.plan_assignments_v2 set employee_id=v_target.employee_id,
      explanation=coalesce(explanation,'{}'::jsonb)||jsonb_build_object(
        'edited',true,'editedBy',v_actor,'editedAt',now(),'reason',v_reason,
        'dragOperation','SWAP','pairedAssignmentId',v_target.id)
      where id=v_source.id;
    update public.plan_assignments_v2 set employee_id=v_source.employee_id,
      explanation=coalesce(explanation,'{}'::jsonb)||jsonb_build_object(
        'edited',true,'editedBy',v_actor,'editedAt',now(),'reason',v_reason,
        'dragOperation','SWAP','pairedAssignmentId',v_source.id)
      where id=v_target.id;
  else
    select * into v_issue from public.plan_issues_v2
      where id=p_target_issue_id and variant_id=p_variant_id and issue_code='UNFILLED_SLOT' for update;
    if v_issue.id is null then raise exception 'UNFILLED_ISSUE_NOT_FOUND'; end if;
    v_target_context:=public.optimizer_leader_assignment_context_uat_v4(
      p_variant_id,null,p_target_issue_id);
    select value into v_candidate from jsonb_array_elements(coalesce(v_target_context->'candidates','[]'::jsonb))
      where value->>'employeeId'=v_source.employee_id::text;
    if v_candidate is null or not coalesce((v_candidate->>'workPatternAllowed')::boolean,false)
      or coalesce(v_candidate->>'dutyCoverageMode','NOT_COVERED')<>'DIRECT' then
      raise exception 'VARIANT_EMPLOYEE_ELIGIBILITY_INVALID';
    end if;
    select snapshot into v_snapshot from solver_private.optimization_snapshots_v2 snapshot
      join public.plan_variants_v2 variant on variant.run_id=snapshot.run_id where variant.id=p_variant_id;
    insert into public.plan_assignments_v2(variant_id,shift_id,slot_key,employee_id,role_id,locked,explanation)
    values(p_variant_id,v_issue.shift_id,v_issue.slot_key,v_source.employee_id,v_issue.role_id,false,
      jsonb_build_object('edited',true,'editedBy',v_actor,'editedAt',now(),'reason',v_reason,
        'dragOperation','MOVE','sourceAssignmentId',v_source.id,'filledIssueId',v_issue.id))
    returning id into v_new_assignment_id;
    select slot.value into v_slot from jsonb_array_elements(coalesce(v_snapshot->'slots','[]'::jsonb)) slot
      where slot.value->>'slotId'=v_issue.slot_key;
    insert into public.plan_assignment_duties_v2(assignment_id,duty_id)
    select v_new_assignment_id,(duty.value#>>'{}')::uuid
      from jsonb_array_elements(coalesce(v_slot->'dutyIds','[]'::jsonb)) duty;
    delete from public.plan_issues_v2 where id=v_issue.id;
    select duty_id into v_source_duty_id from public.plan_assignment_duties_v2
      where assignment_id=v_source.id order by duty_id limit 1;
    insert into public.plan_issues_v2(variant_id,shift_id,slot_key,issue_code,severity,role_id,duty_id,
      required_count,assigned_count,message,metadata)
    values(p_variant_id,v_source.shift_id,v_source.slot_key,'UNFILLED_SLOT','WARNING',v_source.role_id,
      v_source_duty_id,1,0,'Miejsce zwolnione przez przeniesienie w Studio lidera.',
      jsonb_build_object('movedAssignmentId',v_source.id,'reason',v_reason));
    delete from public.plan_assignments_v2 where id=v_source.id;
  end if;
  return solver_private.refresh_leader_variant_uat_v1(p_variant_id,v_actor,v_reason)
    ||jsonb_build_object('operation',case when p_target_assignment_id is null then 'MOVE' else 'SWAP' end,
      'sourceAssignmentId',p_source_assignment_id,'targetAssignmentId',p_target_assignment_id,
      'targetIssueId',p_target_issue_id,'newAssignmentId',v_new_assignment_id);
end;
$function$;

CREATE OR REPLACE FUNCTION public.optimizer_leader_assignment_lock_uat_v1(p_variant_id uuid, p_assignment_id uuid, p_locked boolean, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid();v_assignment public.plan_assignments_v2%rowtype;
  v_reason text:=trim(coalesce(p_reason,''));v_result jsonb;
begin
  if length(v_reason)<3 then raise exception 'EDIT_REASON_REQUIRED'; end if;
  if not solver_private.can_edit_leader_variant_uat_v1(p_variant_id) then
    raise exception 'LEADER_VARIANT_NOT_EDITABLE';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('leader-edit:'||p_variant_id::text,0));
  select * into v_assignment from public.plan_assignments_v2
    where id=p_assignment_id and variant_id=p_variant_id for update;
  if v_assignment.id is null then raise exception 'ASSIGNMENT_NOT_FOUND'; end if;
  update public.plan_assignments_v2 set locked=p_locked,
    explanation=coalesce(explanation,'{}'::jsonb)||jsonb_build_object(
      'edited',true,'editedBy',v_actor,'editedAt',now(),'reason',v_reason,
      'leaderLocked',p_locked)
    where id=p_assignment_id;
  v_result:=solver_private.refresh_leader_variant_uat_v1(p_variant_id,v_actor,v_reason);
  insert into public.audit_log(actor_id,entity_type,entity_id,action,new_data)
  values(v_actor,'plan_assignment_v2',p_assignment_id::text,
    case when p_locked then 'LEADER_LOCK' else 'LEADER_UNLOCK' end,
    jsonb_build_object('variantId',p_variant_id,'reason',v_reason));
  return v_result||jsonb_build_object('assignmentId',p_assignment_id,'locked',p_locked);
end;
$function$;

CREATE OR REPLACE FUNCTION public.optimizer_leader_assignment_remove_uat_v1(p_variant_id uuid, p_assignment_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid:=auth.uid();
  v_assignment public.plan_assignments_v2%rowtype;
  v_duty_id uuid;
  v_reason text:=trim(coalesce(p_reason,''));
begin
  if length(v_reason)<3 then raise exception 'EDIT_REASON_REQUIRED'; end if;
  if not solver_private.can_edit_leader_variant_uat_v1(p_variant_id) then
    raise exception 'LEADER_VARIANT_NOT_EDITABLE';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('leader-edit:'||p_variant_id::text,0));
  select * into v_assignment from public.plan_assignments_v2
    where id=p_assignment_id and variant_id=p_variant_id for update;
  if v_assignment.id is null then raise exception 'ASSIGNMENT_NOT_FOUND'; end if;
  if v_assignment.locked then raise exception 'LOCKED_ASSIGNMENT_CANNOT_BE_REMOVED'; end if;
  select duty_id into v_duty_id from public.plan_assignment_duties_v2
    where assignment_id=v_assignment.id order by duty_id limit 1;
  insert into public.plan_issues_v2(
    variant_id,shift_id,slot_key,issue_code,severity,role_id,duty_id,
